        "A Porcine of Interest" -> "{\"n\":\"A Porcine of Interest\",\"items\":[\"Rope\",\"A knife or slash weapon\",\"Combat gear\"],\"rec\":[\"Teleport to north Draynor\",\"Teleport to Falador Farm\"],\"enemies\":[\"Sourhog (level 37)\"],\"rewards\":[\"1 Quest point\",\"1,000 Slayer XP\",\"5000 x Coins\",\"30 Slayer Points\",\"Access to Sourhog Cave\",\"Sourhogs can be assigned as a slayer task by Spria\"],\"sec\":[{\"n\":\"Helping Sarah\",\"st\":[{\"t\":\"Read the notice board in Draynor Village.\",\"s\":[\"Yes.\"]},{\"t\":\"Talk to Sarah in the South Falador Farm.\",\"s\":[\"Talk about the bounty.\"]},{\"t\":\"Use a rope on the Strange Hole east of Draynor Manor.\",\"s\":[\"I think that'll be all for now.\"],\"i\":[\"Rope\"]},{\"t\":\"Climb down into the Strange Hole east of Draynor Manor.\"},{\"t\":\"Go to the end of the cave and investigate the skeleton there.\"},{\"t\":\"Talk to Spria in Draynor Village.\"},{\"t\":\"Climb down into the Strange Hole east of Draynor Manor. Be prepared to fight Sourhog (level 37)\",\"i\":[\"Reinforced goggles\",\"A knife or slash weapon\",\"Combat gear\"]},{\"t\":\"Kill Sourhog.\",\"s\":[\"Yes\"],\"i\":[\"Reinforced goggles\"]},{\"t\":\"Cut off Sourhog's foot.\",\"i\":[\"A knife or slash weapon\"]},{\"t\":\"Return to Sarah in the South Falador Farm.\",\"s\":[\"Talk about the bounty.\"],\"i\":[\"Sourhog foot\"]},{\"t\":\"Return to Spria in Draynor Village.\"}],\"i\":[\"Rope\",\"A knife or slash weapon\",\"Combat gear\"],\"c\":1,\"e\":[\"Sourhog (level 37)\"]}]}"
        "A Soul's Bane" -> "{\"n\":\"A Soul's Bane\",\"items\":[\"Rope\",\"Combat gear + food\"],\"rec\":[\"Digsite Teleport\",\"Antipoison (or equivalent)\"],\"enemies\":[\"Multiple level 40-46 enemies\"],\"rewards\":[\"1 Quest point\",\"500 Defence XP\",\"500 Hitpoints XP\",\"500 x Coins\",\"Access to the Dungeon of Tolna\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Talk to Launa east of Varrock.\",\"s\":[\"Yes.\",\"Would you like me to go down to look for your husband and son?\"]},{\"t\":\"Use a rope on the rift.\",\"i\":[\"Rope\"]},{\"t\":\"Enter the rift.\",\"i\":[\"Combat gear + food\"]}],\"i\":[\"Rope\",\"Combat gear + food\"],\"c\":1},{\"n\":\"Anger room\",\"st\":[{\"t\":\"Take a weapon from the weapon rack. Kill the angry monsters with the appropriate weapon:\"},{\"t\":\"Go to the next room.\"}],\"i\":[\"Combat gear + food\"],\"c\":1},{\"n\":\"Fear room\",\"st\":[{\"t\":\"Look inside the Dark Holes to cause fear reapers to appear. Kill 5 of them. You cannot search the same hole over and over again.\"},{\"t\":\"Continue to the next room.\"}],\"i\":[\"Combat gear + food\"],\"c\":1},{\"n\":\"Confusion room\",\"st\":[{\"t\":\"Attack the confusion beasts until you find one which takes damage, and kill it. The others will take 8 hits to die.\"},{\"t\":\"Leave the room through the confusing door.\"}],\"i\":[\"Combat gear + food\"],\"c\":1},{\"n\":\"Hopelessness room\",\"st\":[{\"t\":\"Kill each hopeless creature 3 times.\"},{\"t\":\"Continue through the exit of the room.\"}],\"i\":[\"Combat gear + food\"],\"c\":1},{\"n\":\"Save Tolna\",\"st\":[{\"t\":\"Kill all three of Tolna's heads.\"},{\"t\":\"Talk to Tolna.\"},{\"t\":\"Talk to Tolna outside the rift.\"}],\"i\":[\"Combat gear + food\"],\"c\":1}]}"
        "A Tail of Two Cats" -> "{\"n\":\"A Tail of Two Cats\",\"items\":[\"A cat\",\"Catspeak amulet\",\"Death runes (5)\",\"Chocolate cake\",\"Logs\",\"Tinderbox\",\"Bucket of milk\",\"Shears\",\"Potato seeds (4)\",\"Rake\",\"Seed dibber\",\"Vial of water\",\"Desert shirt\",\"Desert robe\"],\"rec\":[],\"enemies\":[],\"rewards\":[\"2 Quest points\",\"2 x 2,500 Experience Lamps (Any skill over level 30).\",\"A Doctors hat\",\"A Nurse hat\",\"A Mouse Toy\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Talk to Unferth in north east Burthorpe.\",\"s\":[\"I'll help you.\",\"Yes.\"],\"i\":[\"A cat\",\"Catspeak amulet\"]},{\"t\":\"Talk to Hild in the house north east of Unferth.\",\"i\":[\"Death runes (5)\",\"Catspeak amulet\"]},{\"t\":\"Operate the catspeak amulet (e) to locate Bob the Cat. He's often in Catherby Archery Shop or at the Varrock Anvil.\",\"i\":[\"Catspeak amulet (e)\"]},{\"t\":\"Talk to Bob the Cat.\",\"i\":[\"A cat\",\"Catspeak amulet (e)\"]}],\"i\":[\"A cat\",\"Catspeak amulet\",\"Death runes (5)\"],\"c\":0},{\"n\":\"Bob's past\",\"st\":[{\"t\":\"Talk to Gertrude west of Varrock.\",\"s\":[\"Ask about Bob's parents.\"],\"i\":[\"A cat\",\"Catspeak amulet (e)\"]},{\"t\":\"Talk to Reldo in the Varrock Castle's library.\",\"s\":[\"I have a cat related question.\",\"Ask about Robert the Strong.\"],\"i\":[\"A cat\",\"Catspeak amulet (e)\"]},{\"t\":\"Use the catspeak amulet (e) again to locate Bob the Cat.\",\"i\":[\"Catspeak amulet (e)\"]},{\"t\":\"Talk to Bob the Cat again.\",\"i\":[\"A cat\",\"Catspeak amulet (e)\"]},{\"t\":\"Talk to the Sphinx in Sophanem.\",\"s\":[\"Ask the Sphinx for help for Bob.\"],\"i\":[\"A cat\",\"Catspeak amulet (e)\"]}],\"i\":[\"A cat\"],\"c\":0},{\"n\":\"Helping Unferth\",\"st\":[{\"t\":\"Rake Unferth's patch\",\"i\":[\"Rake\"]},{\"t\":\"Plant 4 potato seeds in Unferth's patch. These can take 15-35 minutes to grow.\",\"i\":[\"Seed dibber\",\"Potato seeds (4)\"]},{\"t\":\"Make Unferth's bed.\"},{\"t\":\"Use logs on Unferth's fi