        "A Taste of Hope" -> "{\"n\":\"A Taste of Hope\",\"items\":[\"Coins (1000)\",\"Vial of water\",\"Rod of Ivandis\",\"Emerald\",\"Chisel\",\"Runes or tablet for Enchant Emerald\",\"Combat gear\"],\"rec\":[\"Any pickaxe\"],\"enemies\":[\"Abomination (level 149, safespottable)\",\"Ranis Drakan (level 233, melee only)\"],\"rewards\":[\"1 Quest point\",\"Ivandis Flail\",\"Drakan's Medallion\",\"3 x 2,500 Experience Tomes (Any skill over level 35).\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Talk to Garth outside the Theatre of Blood.\",\"s\":[\"Yes.\"]},{\"t\":\"Enter the Meiyerditch Myreque base. The easiest way to get there is to have a Vyrewatch take you to the mines, escape by mining 15 rocks, then head south from there.\"},{\"t\":\"Talk to Safalaan in the north room.\"}]},{\"n\":\"Spying\",\"st\":[{\"t\":\"Return to the Theatre of Blood and attempt to climb rubble in its south west corner.\"},{\"t\":\"Talk to Harpert near the rubble.\",\"s\":[\"Fine, here's the money.\"],\"i\":[\"Coins (1000)\"]},{\"t\":\"Attempt to climb the rubble again.\"},{\"t\":\"Climb the vent to the north when the steam stops coming out.\"},{\"t\":\"Jump off the roof to the north.\"},{\"t\":\"Climb the vent to the north when steam stops coming out.\"},{\"t\":\"Climb the roof to the east.\"},{\"t\":\"Climb down to the east.\"},{\"t\":\"Look through the window at the end of the path.\"}],\"i\":[\"Coins (1000)\"]},{\"n\":\"Investigating\",\"st\":[{\"t\":\"Return to the Meiyerditch Myreque base. The easiest way to get there is to have a Vyrewatch take you to the mines, escape by mining 15 rocks, then head south from there.\"},{\"t\":\"Talk to Safalaan in the north room.\",\"s\":[\"I do.\"]},{\"t\":\"Talk to Flaygian.\",\"s\":[\"Anything to report?\",\"Why?\"]},{\"t\":\"Talk to Safalaan again.\"},{\"t\":\"Enter Serafina's house in west Meiyerditch.\"},{\"t\":\"Talk to Safalaan.\"},{\"t\":\"Work out how to open the door in the room.\"},{\"t\":\"Search the chest for some notes.\"},{\