        "Alfred Grimhand's Barcrawl" -> "{\"n\":\"Alfred Grimhand's Barcrawl\",\"items\":[\"Coins (208)\"],\"rec\":[\"Games necklace\",\"Varrock teleport\",\"Lumberyard teleport\",\"Falador teleport\",\"Amulet of Glory\",\"Ardougne teleport\",\"Camelot teleport\",\"Ring of dueling\"],\"enemies\":[],\"rewards\":[\"Access to Barbarian Outpost Agility Course\",\"Speak to the Barbarian Guard to learn how to smash empty vials automatically.\"],\"sec\":[{\"n\":\"Getting started\",\"st\":[{\"t\":\"Talk to a barbarian guard outside the Barbarian Agility Course at the Barbarian Outpost to learn about Alfred Grimhand's Barcrawl.\",\"s\":[\"I want to come through this gate.\",\"Looks can be deceiving, I am in fact a barbarian.\"]}],\"c\":0},{\"n\":\"Drinking\",\"st\":[{\"t\":\"Talk to the bartender in the Blue Moon Inn in Varrock.\",\"s\":[\"I'm doing Alfred Grimhand's Barcrawl.\"],\"i\":[\"Coins (50)\"]},{\"t\":\"Talk to the bartender in the Jolly Boar Inn north east of Varrock.\",\"s\":[\"I'm doing Alfred Grimhands Barcrawl.\"],\"i\":[\"Coins (10)\"]},{\"t\":\"Talk to a bartender in the Rising Sun Inn in Falador.\",\"s\":[\"I'm doing Alfred Grimhand's barcrawl.\"],\"i\":[\"Coins (70)\"]},{\"t\":\"Talk to the bartender in the Rusty Anchor in Port Sarim.\",\"s\":[\"I'm doing Alfred Grimhand's Barcrawl.\"],\"i\":[\"Coins (8)\"]},{\"t\":\"Talk to Zembo in the Karamja Spirits Bar on Musa Point.\",\"s\":[\"I'm doing Alfred Grimhand's barcrawl.\"],\"i\":[\"Coins (7)\"]},{\"t\":\"Talk to the bartender in the Dead Man's Chest in Brimhaven.\",\"s\":[\"I'm doing Alfred Grimhand's Barcrawl.\"],\"i\":[\"Coins (15)\"]},{\"t\":\"Talk to the bartender in the Flying Horse Inn in Ardougne.\",\"s\":[\"I'm doing Alfred Grimhand's Barcrawl.\"],\"i\":[\"Coins (8)\"]},{\"t\":\"Talk to the bartender in the Forester's Arms in Seers' Village.\",\"s\":[\"I'm doing Alfred Grimhand's Barcrawl.\"],\"i\":[\"Coins (18)\"]},{\"t\":\"Talk to Blurberry in the Grand Tree.\",\"i\":[\"Coins (10)\"]},{\"t\":\"Talk to the bartender in Dragon Inn in Yanille.\",\"s\":[\"I'm doing Alfred Grimhand's Barcrawl.\"],\"i\":[\"Coins (12)\"]},{\"t\":\"Return to the barbarian guards outside the Barbarian Agility Course.\"}],\"i\":[\"Barcrawl card\",\"Coins (208)\"],\"c\":0}]}"
        "Animal Magnetism" -> "{\"n\":\"Animal Magnetism\",\"items\":[\"Mithril Axe\",\"Iron Bar (5)\",\"Ghostspeak amulet\",\"Ecto-token (20)\",\"Hammer\",\"Hard Leather\",\"Holy Symbol\",\"Polished Buttons\"],\"rec\":[\"Teleport to Draynor (5)\",\"Teleport to Burthorpe\",\"Teleport to Port Phasmatys\"],\"enemies\":[],\"rewards\":[\"1 Quest point\",\"1,000 Crafting XP\",\"1,000 Fletching XP\",\"1,000 Slayer XP\",\"2,500 Woodcutting XP\",\"Ava's Attractor\",\"Ability to purchase Ava's Devices\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Talk to Ava to begin the quest.\",\"s\":[\"I would be happy to make your home a better place.\"]}],\"c\":0},{\"n\":\"Undead Chickens\",\"st\":[{\"t\":\"Talk to Malcolm at the farm west of the Ectofuntus.\",\"i\":[\"Ghostspeak amulet\"]},{\"t\":\"Talk to Alice.\",\"s\":[\"I'm here about a quest.\"]},{\"t\":\"Talk to Malcolm again.\",\"i\":[\"Ghostspeak amulet\"]},{\"t\":\"Talk to Alice again.\",\"s\":[\"I'm here about a quest.\"]},{\"t\":\"Talk to the Old crone just east of the Slayer Tower twice.\",\"s\":[\"I'm here about the farmers east of here.\"],\"i\":[\"Ghostspeak amulet\"]},{\"t\":\"Give the Crone-made amulet to Malcolm.\",\"s\":[\"Okay, you need it more than I do, I suppose.\"],\"i\":[\"Ghostspeak amulet\",\"Crone-made amulet\"]},{\"t\":\"Talk to Malcolm again to watch a cutscene.\",\"i\":[\"Ghostspeak amulet\"]},{\"t\":\"Buy two undead chickens from Malcolm. You can acquire ecto-tokens using the Ectofuntus to the east.\",\"s\":[\"Could I buy those chickens now, then?\",\"Could I buy 2 chickens?\"],\"i\":[\"Ghostspeak amulet\",\"Ecto-token (20)\"]},{\"t\":\"Give the two Undead chickens to Ava.\",\"i\":[\"Undead chicken (2)\"]}],\"i\":[\"Ghostspeak amulet\",\"Ecto-token (20)\"],\"c\":0},{\"n\":\"Magnet\",\"st\":[{\"t\":\"Talk to the witch in the manor twice.\",\"i\":[\"Iron Bar (5)\"]},{\"t\":\"Go to the iron mine in Rimmington northeast of the house portal.\",\"i\":[\"Hammer\",\"Selected Iron\"]},{\"t\":\"While looking north, use the hammer on the Selected iron.\",\"i\":[\"Hammer\",\"Selected Iron\"]},{\"t\":\"Give the Bar magnet to Ava.\",\"i\":[\"Bar magnet\"]}],\"i\":[\"Iron Bar (5)\",\"Hammer\"],\"c\":0},{\"n\":\"Undead twigs\",\"st\":[{\"t\":\"Try to chop an undead tree outside Draynor manor.\",\"i\":[\"Mithril Axe\"]},{\"t\":\"Talk to Turael in Burthorpe twice, giving him the Mithril axe and Holy symbol.\",\"s\":[\"I'm here about a quest.\",\"Hello, I'm here about those trees again.\",\"I'd love one, thanks.\"],\"i\":[\"Mithril Axe\",\"Holy Symbol\"]},{\"t\":\"Try to chop an undead tree outside Draynor manor with the Blessed axe until you receive undead twigs.\",\"i\":[\"Blessed axe\"]},{\"t\":\"Give the Undead twigs to Ava.\",\"i\":[\"Undead twigs\"]},{\"t\":\"Talk to Ava to receive the research notes.\"},{\"t\":\"Translate the research notes.\"},{\"t\":\"Give Ava the translated research notes.\",\"i\":[\"Translated notes\"]},{\"t\":\"Combine Hard leather and Polished buttons with the pattern.\",\"i\":[\"A pattern\",\"Hard Leather\",\"Polished Buttons\"]},{\"t\":\"Give Ava the container.\",\"i\":[\"A container\"]}],\"i\":[\"Mithril Axe\",\"Polished Buttons\",\"Hard Leather\",\"Holy Symbol\"],\"c\":0}]}"
        "Another Slice of H.A.M." -> "{\"n\":\"Another Slice of H.A.M.\",\"items\":[\"A light source\",\"Tinderbox\",\"Magic or ranged combat gear\",\"Rope\"],\"rec\":[\"Lumbridge teleports (3)\"],\"enemies\":[\"H.A.M. Archer (level 30)\",\"H.A.M. Mage (level 30)\",\"Sigmund (level 64)\"],\"rewards\":[\"1 Quest point\",\"3,000 Mining XP\",\"3,000 Prayer XP\",\"An Ancient Mace\",\"Dorgeshuun Train Access.\",\"Ability to buy Goblin Village Teleport Spheres\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Travel to Dorgesh-Kaan under Lumbridge, and talk to Ur-tag there.\",\"s\":[\"What are you arguing about?\",\"I'd love to help!\"]},{\"t\":\"Talk to Tegdak through the doorway in south-west Dorgesh-Kaan.\"},{\"t\":\"Dig up the 6 artefacts in the railway tunnel, clean them, and show them to Tegdak.\"},{\"t\":\"Talk to Zanik in the railway, and then go talk to the Goblin Scribe in the north of Dorgesh-Kaan with her.\",\"s\":[\"Yes\"]}],\"i\":[\"A light source\"]},{\"n\":\"To Goblin Village\",\"st\":[{\"t\":\"Talk to Oldak in the north west of Dorgesh-Kaan with Zanik.\",\"s\":[\"Yes\"]},{\"t\":\"Talk to General Wartface and General Bentnoze in Goblin Village.\",\"i\":[\"Magic or ranged combat gear\"]},{\"t\":\"Make your way to the tower to the south, using the buildings as cover, and climb up the ladder.\"},{\"t\":\"Kill the H.A.M. Mage and H.A.M. Archer with a ranged/magic weapon.\",\"i\":[\"Magic or ranged combat gear\"]},{\"t\":\"Talk to General Wartface and General Bentnoze in Goblin Village again.\"}],\"i\":[\"Magic or ranged combat gear\"],\"c\":1,\"e\":[\"H.A.M. Archer (level 30)\",\"H.A.M. Mage (level 30)\"]},{\"n\":\"Saving Zanik\",\"st\":[{\"t\":\"Talk to the Sergeants in Lumbridge Swamp.\",\"i\":[\"Combat gear\",\"Ancient mace\",\"A light source\"]},{\"t\":\"Enter the Lumbridge Swamp Caves.\",\"i\":[\"Combat gear\",\"Ancient mace\",\"A light source\",\"Rope\"]},{\"t\":\"Climb down the ladder to the secret H.A.M. base.\"},{\"t\":\"Work out how to avoid all t