        "At First Light" -> "{\"n\":\"At First Light\",\"items\":[\"2 Jerboa tails, or a box trap to get some\",\"Hammer\",\"Needle or Costume needle\"],\"rec\":[\"Stamina potions\"],\"enemies\":[],\"rewards\":[\"1 Quest point\",\"4,500 Hunter XP\",\"800 Construction XP\",\"500 Herblore XP\",\"Access to Master Tier Hunters' Rumours\"],\"sec\":[{\"n\":\"Helping out\",\"st\":[{\"t\":\"Talk to Guildmaster Apatura in the Hunter Guild, south-west of Civitas illa Fortis.\",\"s\":[\"Can I help you with anything?\",\"Yes.\"]},{\"t\":\"Go down the stairs in the tree in the guild.\"},{\"t\":\"Talk to Guild Scribe Verity behind the bar.\"},{\"t\":\"Talk to Guild Hunter Wolf (Master), next to the bar.\"},{\"t\":\"Wind up a toy mouse.\",\"i\":[\"Toy mouse\"]},{\"t\":\"Use the wound up toy mouse on Guild Hunter Kiko near the bar.\",\"i\":[\"Toy mouse (wound)\"]},{\"t\":\"Check the cat's bed.\"},{\"t\":\"Return to Guild Hunter Wolf (Master), next to the bar.\"}],\"c\":0},{\"n\":\"On the hunt\",\"st\":[{\"t\":\"Go back up the stairs.\"},{\"t\":\"Get a box trap. You can buy one from Imia in the north of the Hunter Guild's surface for 41gp.\"},{\"t\":\"Talk to Guild Hunter Fox near the crevice south-east of the Hunter Guild.\"},{\"t\":\"Search the leafy bush south of the crevice for a smooth leaf.\"},{\"t\":\"Search the rough-looking bush on the west side of the Locus Oasis.\"},{\"t\":\"Catch two Embertailed Jerboa for their tails.\",\"i\":[\"Box trap\"]},{\"t\":\"Use the tails on the leaves.\",\"i\":[\"Jerboa tail\",\"Smooth leaf\"]},{\"t\":\"Bring the poultice back to Guild Hunter Fox near the crevice.\",\"i\":[\"Makeshift poultice\"]},{\"t\":\"Talk to Guild Hunter Fox.\"}],\"i\":[\"Jerboa tail, or a box trap to get some\"],\"c\":0},{\"n\":\"Bed repairs\",\"st\":[{\"t\":\"Talk to Atza in one of the buildings outside Civitas illa Fortis' south wall, west of the general store.\",\"i\":[\"Fur sample\"]},{\"t\":\"Take a hammer from the house north of Atza.\",\"i\":[\"Hammer\"]},{\"t\":\"Set-up the pile of equipment next to Atza.\",\"i\":[\"Hammer\"]},{\"t\":\"Talk to Atza again for some trimmed fur.\"},{\"t\":\"Return to Guild Hunter Fox near the crevice south-east of the Hunter Guild to get his report.\",\"i\":[\"Trimmed fur\"]},{\"t\":\"Take the needle in the Hunter Guild's surface area, in its south-east corner.\",\"i\":[\"Needle\"]},{\"t\":\"Go down the stairs in the tree in the Hunters Guild.\",\"i\":[\"Fox's report\",\"Trimmed fur\",\"Jerboa tail\",\"Needle or Costume needle\"]},{\"t\":\"Talk to Guild Scribe Verity behind the bar again.\"},{\"t\":\"Use a jerboa tail on the cat bed.\",\"i\":[\"Jerboa tail\",\"Trimmed fur\",\"Needle or Costume needle\"]},{\"t\":\"Go back up the stairs and talk to Guildmaster Apatura to finish the quest.\"}],\"i\":[\"Hammer\",\"Needle or Costume needle\",\"Jerboa tail\"],\"c\":0}]}"
        "Barbarian Training" -> "{\"n\":\"Barbarian Training\",\"items\":[\"Any seed that can be planted directly\",\"Any sapling you can plant\",\"Spade\",\"Any bow\",\"Oak logs\",\"Tinderbox\",\"Any axe\",\"Feathers\",\"Knife\",\"Hammer\",\"Bronze bar (2)\",\"Logs (3)\",\"Attack potion (2)\",\"Roe\",\"Anti-dragon shield or DFS\",\"Combat gear\"],\"rec\":[\"Games necklace (5)\",\"Catherby teleport for fishing\"],\"enemies\":[\"Mithril Dragon (level 304)\"],\"rewards\":[],\"sec\":[{\"n\":\"Barbarian Fishing\",\"st\":[{\"t\":\"Talk to Otto in his hut north-west of Baxtorian Falls about fishing.\",\"s\":[\"You think so?\",\"What can I learn about the use of a fishing rod?\"]},{\"t\":\"Search the bed in Otto's hut.\"},{\"t\":\"Fish from one of the fishing spots near Otto's hut.\",\"i\":[\"Barbarian rod\",\"Feathers\"]},{\"t\":\"Return to Otto and tell him about your success.\",\"s\":[\"I've fished with a barbarian rod!\"]}],\"i\":[\"Feathers\"],\"tr\":[\"Games necklace\",\"Catherby teleport for fishing\"]},{\"n\":\"Barbarian Herblore\",\"st\":[{\"t\":\"Talk to Otto in his hut north-west of Baxtorian Falls about herblore.\",\"s\":[\"What was that secret knowledge of herblore we talked of?\"]},{\"t\":\"Fish from one of the fishing spots near Otto's hut.\",\"i\":[\"Barbarian rod\"]},{\"t\":\"Dissect the fish with a knife until you get some roe.\",\"i\":[\"Knife\",\"Leaping trout/salmon/sturgeon\"]},{\"t\":\"Use roe on an attack potion (2).\",\"i\":[\"Roe\",\"Attack potion (2)\"]},{\"t\":\"Talk to Otto in his hut north-west of Baxtorian Falls.\",\"s\":[\"I've made a barbarian potion!\"],\"i\":[\"Attack mix (2)\"]}],\"i\":[\"Attack potion (2)\",\"Knife\",\"Barbarian rod\",\"Feathers\"]},{\"n\":\"Barbarian Harpooning\",\"st\":[{\"t\":\"Talk to Otto in his hut north-west of Baxtorian Falls about barehand fishing.\",\"s\":[\"You think so?\",\"Please teach me of your cunning with harpoons.\"]},{\"t\":\"Fish in a fishing spot which requires a harpoon WITHOUT a harpoon.\"},{\"t\":\"Return to Otto in his hut north-west of Baxtorian Falls.\",\"s\":[\"Barbarian Outpost.\",\"I've fished with my hands!\"]}]},{\"n\":\"Barbarian Planting\",\"st\":[{\"t\":\"Talk to Otto in his hut north-west of Baxtorian Falls about farming.\",\"s\":[\"You think so?\",\"How can I use my strength in the ways of agriculture?\"]},{\"t\":\"Plant a seed in a patch WITHOUT a dibber. This can fail, so bring multiple and preferably use cheap seeds.\",\"i\":[\"Any seed that can be planted directly (9)\"]},{\"t\":\"Return to Otto in his hut north-west of Baxtorian Falls.\",\"s\":[\"I've planted seeds with my fists!\"]}],\"i\":[\"Any seed that can be planted directly\"]},{\"n\":\"Barb Plant Pot Smashing\",\"st\":[{\"t\":\"Talk to Otto in his hut north-west of Baxtorian Falls about advanced farming.\",\"s\":[\"Are there any other fist related farming activities I can learn?\"]},{\"t\":\"Plant a sapling in a tree or fruit tree patch.\",\"i\":[\"Any sapling you can plant\",\"Spade\"]},{\"t\":\"Return to Otto in his hut north-west of Baxtorian Falls.\",\"s\":[\"I've smashed a pot whilst farming!\"]}],\"i\":[\"Any sapling you can plant\",\"Spade\"]},{\"n\":\"Barbarian Firemaking\",\"st\":[{\"t\":\"Talk to Otto in his hut north-west of Baxtorian Falls about firemaking.\",\"s\":[\"You think so?\",\"I'm ready for your firemaking wisdom. Please instruct me.\"]},{\"t\":\"Use a bow on some oak logs to light it.\",\"i\":[\"Any bow\",\"Oak logs\"]},{\"t\":\"Return to Otto in his hut north-west of Baxtorian Falls.\",\"s\":[\"I've set fire to logs with a bow!\"]}],\"i\":[\"Any bow\",\"Oak logs\"]},{\"n\":\"Barbarian Smithing\",\"st\":[{\"t\":\"Talk to Otto in his hut north-west of Baxtorian Falls about spears.\",\"s\":[\"Tell me more about the use of spears.\"]},{\"t\":\"Make a bronze spear on the anvil south of Otto.\",\"i\":[\"Bronze bar\",\"Logs\",\"Hammer\"]},{\"t\":\"Talk to Otto in his hut north-west of Baxtorian Falls.\",\"s\":[\"I've created a spear!\"]},{\"t\":\"Talk to Otto in his hut north-west of Baxtorian Falls about hastae.\",\"s\":[\"Tell me more about the use of spears.\"]},{\"t\":\"Make a bronze hasta on the anvil south of Otto.\",\"i\":[\"Bronze bar\",\"Logs\",\"Hammer\"]}],\"i\":[\"Hammer\",\"Bronze bar (2)\",\"Logs (2)\"]},{\"n\":\"Barbarian Pyremaking\",\"st\":[{\"t\":\"Talk to Otto in his hut north-west of Baxtorian Falls about advanced firemaking.\",\"s\":[\"I have completed firemaking with a bow. What follows this?\"]},{\"t\":\"Jump into the whirlpool north of Otto. Be prepared to fight mithril dragons.\",\"i\":[\"Combat gear\",\"Anti-dragon shield or DFS\"]},{\"t\":\"Climb down the stairs. There are brutal green dragons there, so have antifire protection and Protect from Magic on!\"},{\"t\":\"Climb up the stairs to the south-east. Be ready to fight the mithril dragons!\"},{\"t\":\"Kill mithril dragons until you get some chewed bones.\"},{\"t\":\"Pick up the chewed bones.\",\"i\":[\"Chewed bones\"]},{\"t\":\"Construct a pyre on the lake near Otto.\",\"i\":[\"Logs\",\"Chewed bones\",\"Tinderbox\",\"Any axe\"]},{\"t\":\"Return to Otto and tell him about the succesful pyre-making.\",\"s\":[\"I've created a pyre ship!\"]}],\"i\":[\"Logs\",\"Tinderbox\",\"Any axe\",\"Combat gear\",\"Anti-dragon shield or DFS\"],\"c\":1,\"e\":[\"Mithril Dragon (level 304)\"]}]}"
        "Bear Your Soul" -> "{\"n\":\"Bear Your Soul\",\"items\":[\"Spade\",\"Dusty key, or another way to get into the deep Taverley Dungeon\"],\"rec\":[],\"enemies\":[],\"rewards\":[\"A Soul Bearer\"],\"sec\":[{\"n\":\"Find the Soul journey book\",\"st\":[{\"t\":\"Go to the Arceuus library and find The Soul journey book in one of the bookcases, then read it. You can ask Biblia for help locating it, or make use of the Runelite Kourend Library plugin.\"}],\"c\":0},{\"n\":\"Talk to Aretha\",\"st\":[{\"t\":\"Talk to Aretha at the Soul Altar.\",\"s\":[\"I've been reading your book...\",\"Yes please.\"]}],\"c\":0},{\"n\":\"Dig up the Soul Bearer\",\"st\":[{\"t\":\"Go to the Arceuus church and dig for the Damaged soul bearer.\"}],\"i\":[\"Spade\"],\"c\":0},{\"n\":\"Have the Soul Bearer repaired\",\"st\":[{\"t\":\"Go to Taverley Dungeon, or teleport to the Key Master directly.\",\"i\":[\"Damaged soul bearer\",\"Dusty key, or another way to get into the deep Taverley Dungeon\"]},{\"t\":\"Enter the cave to the Key Master.\",\"i\":[\"Damaged soul bearer\",\"Dusty key, or another way to get into the deep Taverley Dungeon\"]},{\"t\":\"Talk to Key Master in the Cerberus' Lair.\",\"i\":[\"Damaged soul bearer\"]}],\"i\":[\"Dusty key, or another way to get into the deep Taverley Dungeon\"],\"c\":0}]}"
        "Below Ice Mountain" -> "{\"n\":\"Below Ice Mountain\",\"items\":[\"Cooked Meat\",\"Bread\",\"Knife\",\"Coins (3)\"],\"rec\":[\"A teleport to near Ice Mountain\",\"Falador teleport\",\"Varrock teleport\",\"Combat gear or a pickaxe if you don't want to fight\"],\"enemies\":[\"Ancient Guardian (level 25), or 10 mining + a pickaxe\"],\"rewards\":[\"1 Quest point\",\"2000 x Coins\",\"Access to the Ruins of Camdozaal.\",\"Flex Emote\",\"The ability to make a steak sandwich\"],\"sec\":[{\"n\":\"Starting Off\",\"st\":[{\"t\":\"Talk to Willow outside Falador, south of the Ice Mountain dwarves.\",\"s\":[\"Yes.\"]}]},{\"n\":\"Recruit Checkal\",\"st\":[{\"t\":\"Attempt to recruit Checkal to your team in Barbarian Village.\"},{\"t\":\"Speak to Atlas in the Barbarian Village Inn to learn how to Flex. Pick up a cooked meat if you need one.\",\"s\":[\"Yes.\"],\"i\":[\"Cooked Meat\"]},{\"t\":\"Talk to Checkal and flex your muscles to prove your worth.\"}]},{\"n\":\"Recruit Marley\",\"st\":[{\"t\":\"Speak to Marley in the Edgeville Ruins. Pick up the cooked meat from the Barbarian longhall if you don't have it already.\"},{\"t\":\"Ask the Cook at the Blue Moon Inn for a steak sandwich.\",\"s\":[\"I was wondering if you'd be able to make me a Steak sandwich?\"]},{\"t\":\"Collect meat, bread and a knife to make a steak sandwich.\",\"i\":[\"Cooked Meat\",\"Bread\",\"Knife\"]},{\"t\":\"Use the knife on the bread to make a steak sandwich. Be careful not to eat it!\",\"i\":[\"Knife\",\"Bread\"]},{\"t\":\"Return to Marley and give him the steak sandwich. Be careful not to eat it!\",\"i\":[\"Steak Sandwich\"]}],\"i\":[\"Cooked Meat\",\"Bread\",\"Knife\"]},{\"n\":\"Recruit Burntof\",\"st\":[{\"t\":\"Talk to Burntof in the Falador Inn.\"},{\"t\":\"Buy an Asgarnian Ale for Burntof.\",\"s\":[\"What ales are you serving?\",\"One Asgarnian Ale, please.\"],\"i\":[\"Coins (3)\"]},{\"t\":\"Give Burntof the Asgarnian Ale.\",\"i\":[\"Asgarnian Ale\"]},{\"t\":\"Beat Burntof in a match of Rock-Paper-Scissors. Your choices of Rock, Paper and Scissors do not matter.\",\"s\":[\"Rock.\"]}],\"i\":[\"Coins (3)\"]},{\"n\":\"Excavation!\",\"st\":[{\"t\":\"Talk with Willow at the dungeon entrance on the west side of Ice Mountain.\",\"s\":[\"Yes.\"]},{\"t\":\"Defeat the Lvl-25 Ancient Guardian. Alternatively, with Level 10 Mining, mine the 4 pillars in the corners.\"},{\"t\":\"Watch the cutscene to finish the quest.\",\"s\":[\"Yes.\"]}],\"i\":[\"Combat gear or a pickaxe if you don't want to fight\"],\"c\":1,\"e\":[\"Ancient Guardian (level 25), or 10 mining + a pickaxe\"]}]}"
        "Beneath Cursed Sands" -> "{\"n\":\"Beneath Cursed Sands\",\"items\":[\"Coal\",\"Tinderbox\",\"Iron bar\",\"Spade\",\"Any cooked or raw meat\"],\"rec\":[\"Waterskin(s)\",\"Antipoison\",\"Access to Fairy Rings\",\"Pharaoh's sceptre\",\"Melee combat gear\",\"Ranged combat gear\",\"Food\",\"Stamina Potions\",\"Nardah Teleport\"],\"enemies\":[\"Head Menaphite Guard (lvl 174) without protection prayers\",\"Two Scabarite Mages (lvl 119)\",\"Champion of Scabaras (lvl 379)\",\"Menaphite Akh (lvl 351)\"],\"rewards\":[\"2 Quest points\",\"50,000 Agility XP\",\"A Keris Partisan\",\"A Circlet of Water\",\"Access to the Tombs of Amascut.\",\"Ability to unlock the Jaltevas teleport option on the Pharaoh's sceptre\",\"Access to fairy ring code A.K.P (a small island south-west of Necropolis)\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Talk to Jamila in Sophanem to start the quest.\",\"s\":[\"What's this special item?\",\"Yes.\"]},{\"t\":\"Read the message.\",\"i\":[\"Message\"]}],\"i\":[\"Waterskin(s)\"]},{\"n\":\"Entranced Menaphites\",\"st\":[{\"t\":\"Talk to Maisa at the campsite east of Sophanem, and investigate the excavation.\",\"s\":[\"Let's go.\"]},{\"t\":\"Inspect the blocked entry at the Jaltevas Pyramid.\"},{\"t\":\"Prepare to fight the Head Menaphite Guard, and talk to either a citizen or Menaphite Guard to start the fight.\"},{\"t\":\"Fight the Head Menaphite Guard. This boss uses melee, and can hit up to 16. DO NOT USE ANY OVERHEAD PROTECTION PRAYERS, OR YOU WILL GET HIT FOR 1/3RD OF YOUR HITPOINTS\",\"i\":[\"Melee combat gear\",\"Food\"]},{\"t\":\"Talk to Maisa to continue the quest.\"}],\"i\":[\"Melee combat gear\"],\"r\":[\"Waterskin(s)\",\"Food\"],\"c\":1,\"e\":[\"Head Menaphite Guard (lvl 174) without protection prayers\"]},{\"n\":\"The Ruins of Ullek\",\"st\":[{\"t\":\"Go back to Maisa's camp and talk to her.\"},{\"t\":\"From the campsite, head south and then to the east, around the cliffs, where you will find a set of stairs to the Ruins of Ullek.\"},{\"t\":\"Work out how to unlock the underground entrance west of the obelisk in Ullek.\"},{\"t\":\"Enter the dungeon.\",\"i\":[\"Melee combat gear\",\"Food\"]},{\"t\":\"Use Protect from Magic and defeat the two Scarab Mages.\",\"i\":[\"Melee combat gear\",\"Food\",\"Antipoison\"]},{\"t\":\"Climb down the stairs.\"},{\"t\":\"Avoid the projectiles, run west to the junction, run south, follow the corridor, and pull the lever at the end.\",\"i\":[\"Food\",\"Stamina Potions\"]},{\"t\":\"As fast as possible, run back to the juncture, then run north and pull the second lever.\",\"i\":[\"Food\",\"Stamina Potions\"]},{\"t\":\"With the traps disabled, go through the door west of the juncture.\"}],\"i\":[\"Melee combat gear\",\"Coal\",\"Tinderbox\",\"Spade\",\"Iron bar\"],\"r\":[\"Food\",\"Antipoison\",\"Waterskin(s)\"],\"c\":1},{\"n\":\"Riddle of the Tomb\",\"st\":[{\"t\":\"Solve the tomb riddle.\"},{\"t\":\"Enter the tomb.\"},{\"t\":\"Speak to the Spirit.\"},{\"t\":\"Take the rusty key from the urn in the back of the room.\"}]},{\"n\":\"The Champion of Scabaras\",\"st\":[{\"t\":\"Prepare to fight the Champion of Scabaras, and unlock the door to start the fight.\",\"i\":[\"Ranged combat gear\",\"Food\",\"Antipoison\",\"Stamina Potions\",\"Prayer potions\",\"Rusty key\"]},{\"t\":\"Fight the Champion of Scabaras.\",\"i\":[\"Ranged combat gear\",\"Food\",\"Antipoison\",\"Stamina Potions\",\"Prayer potions\"]},{\"t\":\"Talk to the High Priest of Scabaras.\"}],\"i\":[\"Ranged combat gear\",\"Food\",\"Rusty key\"],\"r\":[\"Antipoison\"],\"c\":1,\"e\":[\"Champion of Scabaras (lvl 379)\"]},{\"n\":\"Cure for the Pox\",\"st\":[{\"t\":\"Talk to Maisa or Zahur in Nardah.\"},{\"t\":\"Purchase some meat from the General Store.\",\"i\":[\"Coins (5)\"]},{\"t\":\"Head west and attempt to jump to the stepping stones over the River Elid.\",\"s\":[\"Yes.\"],\"i\":[\"Any cooked or raw meat\"]},{\"t\":\"Attempt to cross the stepping stones again, and pick the Lily of the Elid.\"},{\"t\":\"Go back to Zahur in Nardah.\",\"i\":[\"Lily of the Elid\"]},{\"t\":\"Talk to Zahur in Nardah.\"},{\"t\":\"Warm up Zahur's Chemistry Equipment.\"},{\"t\":\"Bring the cure crate to the High Priest in Sophanem.\",\"i\":[\"Cure crate\"]}],\"i\":[\"Any cooked or raw meat\",\"Waterskin(s)\"]},{\"n\":\"Fight with the Menaphite Akh\",\"st\":[{\"t\":\"Prepare to fight the Menaphite Akh (lvl 351), and talk to Maisa in Necropolis when ready.\",\"i\":[\"Melee combat gear\",\"Waterskin(s)\"]},{\"t\":\"Defeat the Menaphite Akh. This boss uses melee, and will occasionally cast lightning in front of her, so be prepared to walk behind her to avoid this attack. Whenever a shadow version of them appears, kill them quickly as they'll deal a lot of damage.\",\"i\":[\"Melee combat gear\",\"Waterskin(s)\"]},{\"t\":\"Talk to Maisa or the High Priest in Sophanem to finish the quest.\"}],\"i\":[\"Melee combat gear\",\"Waterskin(s)\"],\"c\":1,\"e\":[\"Menaphite Akh (lvl 351)\"]}]}"
        "Between a Rock..." -> "{\"n\":\"Between a Rock...\",\"items\":[\"Any pickaxe\",\"Gold bars (4)\",\"Hammer\",\"Ammo mould\",\"Coins for travelling (1000)\"],\"rec\":[\"Teleport to Ice Mountain\"],\"enemies\":[\"Scorpion (level 14)\",\"Arzinian Being of Bordanzan (level 75 - 125)\"],\"rewards\":[\"2 Quest points\",\"5,000 Defence XP\",\"5,000 Mining XP\",\"5,000 Smithing XP\",\"A Rune Pickaxe.\",\"Ability to Teleport to Dondakan's Rock using a Ring of Wealth.\",\"Access to Arzinian Mine.\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Talk to Dondakan in the north of the mine.\",\"s\":[\"Why are you firing a cannon at a wall?\",\"So why were you trying to get through the rock again?\",\"Sounds interesting!\",\"Yes.\"]}]},{\"n\":\"Research\",\"st\":[{\"t\":\"Talk to the Dwarven Engineer in west Keldagrim.\"},{\"t\":\"Talk to Rolad at the Ice Mountain entrance to the Dwarven Mine. If you don't have an ammo mould, buy one from Nulodion whilst you're here.\",\"s\":[\"I'll be back later.\"],\"i\":[\"Any pickaxe\"]},{\"t\":\"Enter the Dwarven Mine.\",\"i\":[\"Any pickaxe\"]},{\"t\":\"Search the mine carts for a page.\"},{\"t\":\"Kill scorpions for a page.\"},{\"t\":\"Mine low level rocks for a page.\",\"i\":[\"Any pickaxe\"]},{\"t\":\"Talk to Rolad again.\",\"i\":[\"Pages\"]},{\"t\":\"Read the entire dwarven lore book.\",\"i\":[\"Dwarven lore\"]}],\"i\":[\"Coins (5)\",\"Any pickaxe\"],\"tr\":[\"Teleport to Ice Mountain\"],\"c\":1,\"e\":[\"Scorpion (level 14)\"]},{\"n\":\"Experiment\",\"st\":[{\"t\":\"Return to Dondakan with the book and a gold bar.\",\"i\":[\"Gold bar\",\"Dwarven lore\"]},{\"t\":\"Use a gold bar on Dondakan.\",\"i\":[\"Gold bar\"]},{\"t\":\"Use a gold bar on a furnace to make a gold cannonball.\",\"i\":[\"Gold bar\",\"Ammo mould\"]},{\"t\":\"Use a gold cannon ball on Dondakan.\",\"s\":[\"Yes, I'm sure this will crack open the rock.\"],\"i\":[\"Cannon ball\"]}],\"i\":[\"Ammo mould\",\"Gold bar\"]},{\"n\":\"Solving the schematic\",\"st\":[{\"t\":\"Read the last page of the dwarven lore book again for a base schematic.\",\"s\":[\"Yes.\"],\"i\":[\"Dwarven lore\"]},{\"t\":\"Talk to the Dwarven Engineer in west Keldagrim.\",\"i\":[\"Schematic\",\"Base schematics\"]},{\"t\":\"Use 3 gold bars on an anvil to make a gold helmet.\",\"s\":[\"Golden helmet.\",\"Yes.\"],\"i\":[\"Gold bars (3)\",\"Hammer\"]},{\"t\":\"Talk to Khorvak under White Wolf Mountain.\",\"s\":[\"No, I've had enough of buying drinks for people!\"]},{\"t\":\"Assemble the schematics.\"}],\"i\":[\"Gold bars (3)\",\"Hammer\"]},{\"n\":\"Into the hard place\",\"st\":[{\"t\":\"Prepare for a fight, then return to Dondakan.\",\"s\":[\"You may fire when ready!\"],\"i\":[\"Coins (5)\",\"Gold helmet\",\"Schematic\",\"Any pickaxe\",\"Combat gear\",\"Food\"]},{\"t\":\"Mine 6 gold ores. If you want the Avatar to be level 75 vs 125, get 15. Keep these in your inventory for the boss fight. Do not remove your gold helmet.\",\"i\":[\"Any pickaxe\",\"Gold helmet\"]},{\"t\":\"TALK to the central wall of flame.\",\"i\":[\"Gold helmet\"]},{\"t\":\"Kill the avatar. Make sure to keep the gold ores in your inventory.\",\"i\":[\"Gold helmet\"]},{\"t\":\"Talk to Dondakan to finish the quest.\"}],\"i\":[\"Gold helmet\",\"Schematic\",\"Coins (5)\",\"Any pickaxe\",\"Combat gear\",\"Food\"],\"c\":1}]}"
        "Big Chompy Bird Hunting" -> "{\"n\":\"Big Chompy Bird Hunting\",\"items\":[\"Any axe\",\"Feathers (100)\",\"Knife\",\"Chisel\",\"Wolf bones (4)\",\"Cabbage\",\"Tomato\",\"Onion\",\"Potato\",\"Equa leaves\",\"Doogle leaves\"],\"rec\":[],\"enemies\":[\"Chompy\"],\"rewards\":[\"2 Quest points\",\"262 Fletching XP\",\"1,470 Cooking XP\",\"735 Ranged XP\",\"An Ogre Bow\",\"The ability to fletch Ogre Arrows.\",\"The ability to hunt and cook Chompy Birds.\"],\"sec\":[{\"n\":\"Getting Rantz Arrows\",\"st\":[{\"t\":\"Talk to Rantz in the east of Feldip Hills.\",\"s\":[\"Yes.\",\"Ok, I'll make you some 'stabbers'.\"]},{\"t\":\"Get some achey tree logs near Rantz.\",\"i\":[\"Any axe\"]},{\"t\":\"Use your knife on the achey logs to make arrow shafts.\",\"i\":[\"Knife\",\"Achey tree logs\"]},{\"t\":\"Use the feathers on the arrow shafts.\",\"i\":[\"Feathers\",\"Ogre arrow shafts (make more for later) (6)\"]},{\"t\":\"Use a chisel on some wolf bones.\",\"i\":[\"Chisel\",\"Wolf bones\"]},{\"t\":\"Add the bone arrow tips to the flighted ogre arrows.\",\"i\":[\"Wolfbone arrowtips\",\"Flighted ogre arrow\"]},{\"t\":\"Use at least 6 ogre arrows on Rantz.\",\"i\":[\"Ogre arrow (6)\"]}],\"i\":[\"Any axe\",\"Knife\",\"Feathers (100)\",\"Chisel\",\"Wolf bones (4)\"]},{\"n\":\"Making Bloated Toads\",\"st\":[{\"t\":\"Ask Rantz all the available questions.\",\"s\":[\"How do we make the chompys come?\"]},{\"t\":\"Enter Rantz's cave.\"},{\"t\":\"Open the chest in the cave for some ogre bellows.\"},{\"t\":\"Leave the cave.\"},{\"t\":\"Fill the bellows on swamp bubbles.\",\"i\":[\"Ogre bellows (empty)\"]},{\"t\":\"Inflate 3 toads near the swamp.\",\"i\":[\"Ogre bellows\"]},{\"t\":\"Bring the toads to Rantz.\",\"i\":[\"Bloated toad\"]}]},{\"n\":\"Hunting Chompy\",\"st\":[{\"t\":\"Drop the bloated toad in the clearing south of Rantz.\"},{\"t\":\"Wait for a chompy to spawn. If the frog despawns, you'll need to place another one in the clearing south of Rantz.\"},{\"t\":\"Talk to Rantz again for an ogre bow.\",\"s\":[\"Come on, let me have a go...\",\"I'm actually quite strong... please let me try.\"]},{\"t\":\"Drop another bloated toad in the clearing south of Rantz, and wait for a chompy to come.\",\"i\":[\"Ogre bow\",\"Ogre arrow\"]},{\"t\":\"Kill the chompy. You can only hurt it with an ogre bow + ogre arrows.\",\"i\":[\"Ogre bow\",\"Ogre arrow\"]},{\"t\":\"Talk to Rantz in the east of Feldip Hills.\",\"i\":[\"Raw chompy\"]}],\"c\":1,\"e\":[\"Chompy\"]},{\"n\":\"Cooking Chompy\",\"st\":[{\"t\":\"Enter Rantz's cave.\"},{\"t\":\"Talk to Bugs.\"},{\"t\":\"Talk to Fycie.\"},{\"t\":\"Leave the cave.\"},{\"t\":\"Collect the ingredients Rantz and his children want for the chompy.\"},{\"t\":\"Cook the chompy on Rantz's spit-roast.\",\"i\":[\"Raw chompy\"]},{\"t\":\"Bring Rantz the seasoned chompy to finish the quest.\",\"i\":[\"Seasoned chompy\"]}],\"c\":1,\"e\":[\"Chompy\"]}]}"
        "Biohazard" -> "{\"n\":\"Biohazard\",\"items\":[\"Gas mask\"],\"rec\":[\"Teleport to Ardougne (3)\",\"Teleport to Rimmington\",\"Teleport to Varrock\",\"Coins (30)\"],\"enemies\":[\"Mourner (level 13)\"],\"rewards\":[\"3 Quest points\",\"1,250 Thieving XP\",\"Full West Ardougne Access\",\"Combat Training Camp Access\"],\"sec\":[{\"n\":\"Start the quest\",\"st\":[{\"t\":\"Talk to Elena in her house west of the northern Ardougne bank.\",\"s\":[\"Yes.\"]}],\"i\":[\"Gas mask\"]},{\"n\":\"Getting back into West Ardougne\",\"st\":[{\"t\":\"Talk to Jerico in his house south of the northern Ardougne bank\"},{\"t\":\"Get bird feed from the cupboard in Jerico's house.\"},{\"t\":\"Get a pigeon cage from behind Jerico's house.\",\"i\":[\"Pigeon cage\"]},{\"t\":\"Investigate the watchtower near the entrance to West Ardougne.\",\"i\":[\"Bird feed\",\"Pigeon cage\"]},{\"t\":\"Open the Pigeon cage next to the watchtower.\",\"i\":[\"Pigeon cage\"]},{\"t\":\"Talk to Omart, south of the watchtower, to enter West Ardougne.\",\"s\":[\"Okay, lets do it.\",\"Okay, let's do it.\"],\"i\":[\"Gas mask\"]}]},{\"n\":\"Getting the Distillator\",\"st\":[{\"t\":\"Squeeze through the fence to enter the Mourner's Headquarters yard in the north east of West Ardougne.\"},{\"t\":\"Pick up the rotten apple in the yard.\",\"i\":[\"Rotten apple\"]},{\"t\":\"Use the rotten apple on the cauldron.\",\"i\":[\"Rotten apple\"]},{\"t\":\"Search the cupboard in Sarah's house south-west of the West Ardougne church for a disguise.\"},{\"t\":\"Enter the Mourners' Headquarters whilst wearing the medical gown.\",\"i\":[\"Medical gown\"]},{\"t\":\"Go upstairs and kill the mourner.\"},{\"t\":\"Search the crate in the caged area for Elena's Distillator.\"},{\"t\":\"Return to Elena.\",\"i\":[\"Distillator\"]}],\"c\":1,\"e\":[\"Mourner (level 13)\"]},{\"n\":\"Testing the plague sample\",\"st\":[{\"t\":\"Take the Plague Sample to the Chemist in Rimmington. You can take a boat from Ardougne Dock to Rimmington for 30gp.\",\"s\":[\"Your quest.\"],\"i\":[\"Plague sample\",\"Liquid honey\",\"Sulphuric broline\",\"Ethenea\"]}],\"i\":[\"Plague sample\",\"Liquid honey\",\"Ethenea\",\"Sulphuric broline\",\"Touch paper\"]},{\"n\":\"Revealing the truth\",\"st\":[{\"t\":\"Return to Elena and inform her that the plague is a hoax.\"},{\"t\":\"Tell King Lathas that the Plague is a hoax.\"}]}]}"
        "Black Knights' Fortress" -> "{\"n\":\"Black Knights' Fortress\",\"items\":[\"Bronze med helm\",\"Iron chainbody\",\"Cabbage (NOT from Draynor Manor)\"],\"rec\":[\"Teleport to Falador\",\"Food\",\"Armour\"],\"enemies\":[\"Able to survive being attacked by multiple level 33 Black Knights\"],\"rewards\":[\"3 Quest points\",\"2500 x Coins\"],\"sec\":[{\"n\":\"Talk to Sir Amik Varze\",\"st\":[{\"t\":\"Speak to Sir Amik Varze on the 2nd floor of Falador Castle.\",\"s\":[\"I seek a quest!\",\"I laugh in the face of danger!\",\"Yes.\"]}]},{\"n\":\"Infiltrate the fortress\",\"st\":[{\"t\":\"Enter the Black Knights' Fortress. Be prepared for multiple level 33 Black Knights to attack you.\",\"i\":[\"Iron chainbody\",\"Bronze med helm\",\"Cabbage (NOT from Draynor Manor)\"]},{\"t\":\"Push the wall to enter a secret room.\"},{\"t\":\"Climb up the ladder.\"},{\"t\":\"Climb up the next ladder.\"},{\"t\":\"Climb down the ladder south of you.\"},{\"t\":\"Climb up the ladder east of you.\"},{\"t\":\"Climb down the next ladder east of you.\"},{\"t\":\"Climb down the ladder west of you.\"},{\"t\":\"Listen at the grill.\"}],\"i\":[\"Bronze med helm\",\"Iron chainbody\",\"Cabbage (NOT from Draynor Manor)\"]},{\"n\":\"Sabotage the potion\",\"st\":[{\"t\":\"Climb back up the ladder from the listening room.\",\"i\":[\"Cabbage (NOT from Draynor Manor)\"]},{\"t\":\"Climb up the ladder in the chapel room east of you.\",\"i\":[\"Cabbage (NOT from Draynor Manor)\"]},{\"t\":\"Climb down the ladder west of you.\",\"i\":[\"Cabbage (NOT from Draynor Manor)\"]},{\"t\":\"Climb up the ladder west of you.\",\"i\":[\"Cabbage (NOT from Draynor Manor)\"]},{\"t\":\"Climb down the ladder north of you.\",\"i\":[\"Cabbage (NOT from Draynor Manor)\"]},{\"t\":\"Climb down the next ladder.\",\"i\":[\"Cabbage (NOT from Draynor Manor)\"]},{\"t\":\"Go into the east room and climb the ladder there. When trying to go through the door to the room, you'll have to go through some dialog. Select option 2.\",\"s\"