        "Bone Voyage" -> "{\"n\":\"Bone Voyage\",\"items\":[\"Vodka (2)\",\"Marrentill potion (unf)\"],\"rec\":[\"Teleports to the Digsite (4)\",\"Teleport to the Woodcutting Guild\",\"Varrock teleport\",\"Port Sarim teleport\",\"Lumberyard teleport (2)\",\"Hammer\",\"Iron bar\",\"Oak plank (2)\",\"Nails (5)\"],\"enemies\":[],\"rewards\":[\"1 Quest point\",\"Access to Fossil Island\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Talk to Curator Haig in the Varrock Museum.\",\"s\":[\"Have you any interesting news?\",\"Sign me up!\",\"Yes.\"]}],\"c\":0},{\"n\":\"Securing materials\",\"st\":[{\"t\":\"Talk to the Barge Foreman north of the Dig Site.\"},{\"t\":\"Talk to the Sawmill Operator north east of Varrock.\",\"s\":[\"I'm here on behalf of the museum archaeological team.\"]},{\"t\":\"Return to the Sawmill Operator north east of Varrock.\",\"s\":[\"I'm here on behalf of the museum archaeological team.\"],\"i\":[\"Sawmill agreement\"]},{\"t\":\"Return to the Barge Foreman north of the Dig Site.\"}],\"c\":0},{\"n\":\"Lucky charms\",\"st\":[{\"t\":\"Board the barge.\",\"s\":[\"Can I go onto the barge?\"]},{\"t\":\"Talk to the Lead Navigator.\",\"s\":[\"Yep, that would be me.\",\"No, what happened?\"]},{\"t\":\"Talk to Jack Seagull in the Port Sarim Pub.\",\"s\":[\"Ever made any cursed voyages?\"]},{\"t\":\"Return to the barge.\",\"s\":[\"Can I go onto the barge?\"]},{\"t\":\"Talk to the Lead Navigator again.\"},{\"t\":\"Talk to the Odd Old Man north of the Dig Site.\",\"s\":[\"Talk about lucky charms.\",\"I'm making a cursed voyage.\"]},{\"t\":\"Talk to the Apothecary in south west Varrock.\",\"s\":[\"Talk about something else.\",\"Talk about Bone Voyage.\"],\"i\":[\"Marrentill potion (unf)\",\"Vodka (2)\"]},{\"t\":\"Talk to the Apothecary again.\",\"s\":[\"Talk about something else.\",\"Talk about Bone Voyage.\"],\"i\":[\"Marrentill potion (unf)\",\"Vodka (2)\"]},{\"t\":\"Give the Junior Navigator the bone charm.\",\"i\":[\"Bone charm\"]},{\"t\":\"Give the Lead Navigator the potion.\",\"i\":[\"Potion of sealegs\"]}],\"i\":[\"Marrentill potion (unf)\",\"Vodka (2)\"],\"c\":0},{\"n\":\"The voyage\",\"st\":[{\"t\":\"Talk to the Lead Navigator to set sail. Navigate the ship by keeping the arrow in the middle. Raise the sails to go faster.\",\"s\":[\"I'm ready, let's go.\"]}],\"c\":0}]}"
        "Cabin Fever" -> "{\"n\":\"Cabin Fever\",\"items\":[],\"rec\":[\"Food\"],\"enemies\":[\"Able to survive multiple pirates (level 57) attacking you\"],\"rewards\":[\"2 Quest points\",\"7,000 Smithing XP\",\"7,000 Crafting XP\",\"7,000 Agility XP\",\"10000 x Coins\",\"The Book o' Piracy\",\"Access to Mos Le'Harmless\",\"Access to Cave Horrors and the ability to receive them as a Slayer Task.\",\"Charter Ship prices are now halved.\",\"Ability to play the Trouble Brewing minigame.\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Talk to Bill Teach in Port Phasmatys.\",\"s\":[\"Yes.\",\"Yes, I've always wanted to be a pirate!\",\"Yes, I am a woman of my word.\",\"Yes, I am a man of my word.\"]},{\"t\":\"Talk to Bill Teach on his boat in Port Phasmatys.\",\"s\":[\"Let's go Cap'n!\"]}]},{\"n\":\"Sabotage\",\"st\":[{\"t\":\"Search the repair locker for 4 ropes.\",\"i\":[\"Rope (4)\"]},{\"t\":\"Search the gun locker for 1 fuse.\",\"i\":[\"Fuse\"]},{\"t\":\"Pick up the tinderbox nearby.\",\"i\":[\"Tinderbox\"]},{\"t\":\"Go up to the deck.\"},{\"t\":\"Climb the climbing net.\"},{\"t\":\"Use a rope on the hoisted sail.\",\"i\":[\"Rope\"]},{\"t\":\"Use the fuse on the pirate's powder barrel.\",\"i\":[\"Fuse\"]},{\"t\":\"Use the tinderbox on the fuse.\",\"i\":[\"Tinderbox\"]},{\"t\":\"Talk to Bill Teach.\"}]},{\"n\":\"Repair\",\"st\":[{\"t\":\"Enter the ship's hull.\"},{\"t\":\"Search the repair locker for repair items.\",\"i\":[\"Hammer\",\"Repair plank (6)\",\"Tacks (30)\",\"Swamp paste (3)\"]},{\"t\":\"Repair the holes.\",\"i\":[\"Hammer\",\"Repair plank (2)\",\"Tacks (10)\"]},{\"t\":\"Waterproof the hole.\",\"i\":[\"Swamp paste\"]},{\"t\":\"Go up to the deck.\"},{\"t\":\"Talk to Bill Teach.\"}]},{\"n\":\"Plunder the pirates\",\"st\":[{\"t\":\"Climb the climbing net.\"},{\"t\":\"Use a rope on the hoisted sail.\",\"i\":[\"Rope\"]},{\"t\":\"Enter the ship's hull to loot it.\"},{\"t\":\"Plunder the chest, loot the crate and ransack the barrel for 10 plunder. Switch world after looting to make plunder respawn instantly.\",\"i\":[\"Plunder (10)\"]},{\"t\":\"Return the plunder to the chest in Bill's hull.\"},{\"t\":\"Add the plunder to the plunder storage.\",\"i\":[\"Plunder\"]},{\"t\":\"Go up to the deck.\"},{\"t\":\"Talk to Bill Teach.\"}]},{\"n\":\"Repair the cannon\",\"st\":[{\"t\":\"Search the gun locker for a cannon barrel.\",\"i\":[\"Cannon barrel\"]},{\"t\":\"Go up to the deck and repair the cannon.\"},{\"t\":\"Repair the cannon.\",\"i\":[\"Cannon barrel\"]},{\"t\":\"Talk to Bill Teach.\"}]},{\"n\":\"Fire canisters\",\"st\":[{\"t\":\"Search the gun locker for a ram rod, 3 fuses, and canisters.\",\"i\":[\"Ramrod\",\"Fuse\",\"A few canister\"]},{\"t\":\"Go up to the deck to fire the cannon.\"},{\"t\":\"Get some gunpowder.\"},{\"t\":\"Use the gunpowder on the cannon.\",\"i\":[\"Gunpowder\"]},{\"t\":\"Use the ramrod on the cannon.\",\"i\":[\"Ramrod\"]},{\"t\":\"Use the canister on the cannon.\",\"i\":[\"Canister\"]},{\"t\":\"Use the fuse on the cannon.\",\"i\":[\"Fuse\"]},{\"t\":\"Fire the cannon!\",\"i\":[\"Tinderbox\"]},{\"t\":\"Repeat this 3-4 times until indicated to stop.\"},{\"t\":\"Talk to Bill Teach.\"}]},{\"n\":\"Fire cannon balls\",\"st\":[{\"t\":\"Search the gun locker for a ram rod, and a few fuses and cannon balls.\"},{\"t\":\"Search the gun locker for a ram rod, 3 fuses, and cannon balls.\",\"i\":[\"Ramrod\",\"A few fuses\",\"A few Cannon balls\"]},{\"t\":\"Go up to the deck to fire the cannon.\"},{\"t\":\"Get some gunpowder.\"},{\"t\":\"Use the gunpowder on the cannon.\",\"i\":[\"Gunpowder\"]},{\"t\":\"Use the ramrod on the cannon.\",\"i\":[\"Ramrod\"]},{\"t\":\"Use the cannon ball on the cannon.\",\"i\":[\"Cannon ball\"]},{\"t\":\"Use the fuse on the cannon.\",\"i\":[\"Fuse\"]},{\"t\":\"Fire the cannon!\",\"i\":[\"Tinderbox\"]},{\"t\":\"Keep firing cannonballs until Bill tells you to stop. Quest completed!\"}]}]}"
        "Children of the Sun" -> "{\"n\":\"Children of the Sun\",\"items\":[],\"rec\":[],\"enemies\":[],\"rewards\":[\"1 Quest point\",\"Access to Varlamore to the east of Varrock with a Quetzal.\"],\"sec\":[{\"n\":\"Intrigue\",\"st\":[{\"t\":\"Talk to Alina east of Varrock Square.\",\"s\":[\"When will this delegation arrive?\",\"Yes.\"]},{\"t\":\"Follow the guard, keeping out of sight whilst also not letting them get too far away.\"},{\"t\":\"Attempt to enter the house in the south-east of Varrock, north of the Zamorak Temple, and watch the cutscene.\"},{\"t\":\"Talk to Sergeant Tobyn in Varrock Square.\"},{\"t\":\"Mark the suspect guards.\"},{\"t\":\"Report back to Sergeant Tobyn.\"},{\"t\":\"Talk to Tobyn on the Varrock Castle's roof to finish the quest.\"}],\"c\":0}]}"
        "Client of Kourend" -> "{\"n\":\"Client of Kourend\",\"items\":[\"Feather\"],\"rec\":[\"Games necklace\",\"Coins (100)\"],\"enemies\":[],\"rewards\":[\"1 Quest point\",\"2 x 500 Experience Lamps (Any Skill)\",\"Kharedst's Memoirs\",\"Ability to use the Kourend Castle Teleport spell\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Talk to Veos on the Port Piscarilius docks. You can travel to him by talking to Veos in Port Sarim.\",\"s\":[\"Sounds interesting! How can I help?\",\"Can you take me to Great Kourend?\",\"Have you got any quests for me?\",\"Let's talk about your client...\",\"I've lost something you've given me.\",\"Yes.\"]},{\"t\":\"Use a feather on the Enchanted Scroll.\",\"i\":[\"Feather\",\"Enchanted scroll\"]}],\"i\":[\"Feather\"],\"c\":0},{\"n\":\"Learn about Kourend\",\"st\":[{\"t\":\"Talk to Leenz in Port Piscarilius general store.\",\"s\":[\"Can I ask you about Port Piscarilius?\",\"What is there to do in Port Piscarilius?\"],\"i\":[\"Enchanted scroll\",\"Enchanted quill\"]},{\"t\":\"Talk to Regath in Arceuus general store.\",\"s\":[\"Can I ask you about Arceuus?\",\"What is there to do in Arceuus?\"],\"i\":[\"Enchanted scroll\",\"Enchanted quill\"]},{\"t\":\"Talk to Munty in Lovakengj general store. You can run south towards Kingstown and use the Lovakengj Minecart Network to Lovakengj.\",\"s\":[\"Can I ask you about Lovakengj?\",\"What is there to do in Lovakengj?\"],\"i\":[\"Enchanted scroll\",\"Enchanted quill\"]},{\"t\":\"Talk to Jennifer in Shayzien general store. You can run west towards the bank and use the Lovakengj Minecart Network to Shayzien East.\",\"s\":[\"Can I ask you about Shayzien?\",\"What is there to do in Shayzien?\"],\"i\":[\"Enchanted scroll\",\"Enchanted quill\"]},{\"t\":\"Talk to Horace in the Hosidius general store. You can take the Lovakengj Minecart Network to Hosidius South.\",\"s\":[\"Can I ask you about Hosidius?\",\"What is there to do in Hosidius?\"],\"i\":[\"Enchanted scroll\",\"Enchanted quill\"]},{\"t\":\"Return to Veos on Piscarilius docks.\",\"s\":[\"Let's talk about your client...\",\"I've lost something you've given me.\"]}],\"c\":0},{\"n\":\"The Dark Altar\",\"st\":[{\"t\":\"Activate the mysterious orb at the Dark Altar. You can either run there through Arceuus, teleport to Wintertodt with the Games Necklace and run south, teleport straight there on the Arceuus spellbook, or use the Lovakengj Minecart Network to travel to Arceuus.\",\"i\":[\"Mysterious orb\"]},{\"t\":\"Return to Veos on Piscarilius docks. You can take the Lovakengj Minecart Network from Arceuus to Port Piscarilius and run south-east.\",\"s\":[\"Let's talk about your client...\"]}],\"c\":0}]}"
        "Clock Tower" -> "{\"n\":\"Clock Tower\",\"items\":[\"Bucket of Water or a pair of ice gloves or smiths gloves(i)\"],\"rec\":[\"Stamina Potions\",\"Ardougne Cloak to teleport to monastery\"],\"enemies\":[\"Able to survive a hit or 2 from an Ogre (level 53)\"],\"rewards\":[\"1 Quest point\",\"500 x Coins\"],\"sec\":[{\"n\":\"Getting Started\",\"st\":[{\"t\":\"Talk to Brother Kojo in the Clock Tower to start the quest.\",\"s\":[\"Yes.\"]},{\"t\":\"Open your Quest Journal to sync your current state.\"}]},{\"n\":\"Obtaining the red cog\",\"st\":[{\"t\":\"Enter the Clock Tower basement for the red cog.\"},{\"t\":\"Go through the south east door and pick up the red cog.\",\"i\":[\"Red Cog\"]}]},{\"n\":\"Obtaining the blue cog\",\"st\":[{\"t\":\"Get the bucket next to Brother Cedric, north of the monastery, and fill it up on the well next to it for the Black cog step. If you have other plans for the black cog, you can ignore this step by going down the nearby ladder.\",\"i\":[\"Bucket\"]},{\"t\":\"Climb down the ladder to the east of the Clock Tower, next to Brother Cedric.\"},{\"t\":\"Follow the tunnel and push the wall at the end.\"},{\"t\":\"Pick up the blue cog.\",\"i\":[\"Blue Cog\"]},{\"t\":\"Place the blue cog on the peg on the first floor.\"}],\"i\":[\"There's a bucket and a well and just next to brother cedric for the black cog\"]},{\"n\":\"Obtaining the black cog\",\"st\":[{\"t\":\"Enter the Clock Tower basement for the black cog.\"},{\"t\":\"Enter the north east door, and pick up the black cog with a bucket of water, alternatively you can equip ice gloves or smith gloves(i).\",\"i\":[\"Bucket of Water or a pair of ice gloves or smiths gloves(i)\",\"Black Cog\"]},{\"t\":\"Place the black cog on the peg in the basement.\"}],\"i\":[\"Bucket of Water or a pair of ice gloves or smiths gloves(i)\"]},{\"n\":\"Obtaining the white cog\",\"st\":[{\"t\":\"Enter the Clock Tower basement for the white cog.\"},{\"t\":\"Pick up the rat poison in the north west of the dungeon.\",\"i\":[\"Rat Poison\"]},{\"t\":\"Pull the marked lever up.\"},{\"t\":\"Use the rat poison on the food trough. Wait till the rats have died.\",\"i\":[\"Rat Poison\"]},{\"t\":\"Go through the gate.\"},{\"t\":\"Pick up the white cog.\",\"i\":[\"White Cog\"]},{\"t\":\"Place the white cog on the peg on the second floor.\"}]}]}"
        "Cold War" -> "{\"n\":\"Cold War\",\"items\":[\"Oak Planks (unnoted) (10)\",\"Steel Nails (10)\",\"Hammer\",\"Spade\",\"Clockwork or Steel Bar\",\"Normal Plank\",\"Silk\",\"Raw Cod\",\"Swamp Tar\",\"Feathers (5)\",\"Mahogany Plank\",\"Leather\"],\"rec\":[\"Teleport to Ardougne (4)\",\"Teleport to PoH with a clockwork table\",\"Teleports to Lumbridge (2)\",\"Combat gear and food\"],\"enemies\":[\"1-3 Icelords (level 51)\"],\"rewards\":[\"1 Quest point\",\"2,000 Crafting XP\",\"5,000 Agility XP\",\"1,500 Construction XP\",\"40 Attack XP\",\"Ability to create Penguin Suits\",\"Ability to use the Penguin Agility Course\",\"Abillity to make Bongo Drums\"],\"sec\":[{\"n\":\"Larry's Story\",\"st\":[{\"t\":\"Talk to Larry at the Ardougne Zoo.\",\"s\":[\"Yes.\",\"Okay, why not!\"]},{\"t\":\"Talk to Larry again.\",\"s\":[\"Yes, I have all the materials.\",\"Yes\"],\"i\":[\"Oak Planks (unnoted) (10)\",\"Steel Nails (10)\",\"Hammer\",\"Spade\"]}],\"i\":[\"Oak Planks (unnoted) (10)\",\"Steel Nails (10)\",\"Hammer\",\"Spade\"]},{\"n\":\"Penguin Stake-out\",\"st\":[{\"t\":\"Use an oak plank on the firm snow patch.\",\"i\":[\"Oak Plank\"]},{\"t\":\"Use a spade on the bird hide to cover it in snow.\",\"i\":[\"Spade\"]},{\"t\":\"Talk to Larry on the iceberg to enter the bird hide.\"},{\"t\":\"Talk to Larry again.\",\"s\":[\"That's crazy!\"]},{\"t\":\"Click the boat to return to Relleka.\"}],\"i\":[\"Oak Planks (unnoted) (10)\",\"Steel Nails (10)\",\"Hammer\",\"Spade\"]},{\"n\":\"A Clockwork Penguin\",\"st\":[{\"t\":\"Talk to Larry in Relleka.\"},{\"t\":\"Travel to your POH or another POH with a Crafting table 3 or 4.\",\"i\":[\"Clockwork or Steel Bar\",\"Normal Plank\",\"Silk\"]},{\"t\":\"Craft a steel bar into a clockwork at a crafting table 3.\",\"s\":[\"Clockwork mechanism\"],\"i\":[\"Steel Bar\"]},{\"t\":\"Craft a clockwork penguin at a crafting table 3 or 4.\",\"s\":[\"Clockwork toy\",\"Clockwork penguin\"],\"i\":[\"Clockwork\",\"Normal Plank\",\"Silk\"]},{\"t\":\"Talk to Larry back in the Ardougne Zoo.\",\"s\":[\"Yes, I have it.\",\"Yes\"]},{\"t\":\"Talk to Larry on the iceberg.\",\"s\":[\"It looks like a warning message to keep us away.\",\"Yes\"]}],\"i\":[\"Normal Plank\",\"Clockwork or Steel Bar\",\"Silk\"]},{\"n\":\"Ardougne Mission Report\",\"st\":[{\"t\":\"Unequip cape and weapons and right-click Tuxedo-time Larry at the Ardougne Zoo.\",\"s\":[\"Yes\"]},{\"t\":\"Enter the penguin pen.\"},{\"t\":\"Talk to the zoo penguin.\"},{\"t\":\"Talk to Larry about the mission report, then travel to the sheep farm in Lumbridge.\"}],\"i\":[\"Clockwork suit\"]},{\"n\":\"Lumbridge Mission Report\",\"st\":[{\"t\":\"Tuxedo-time Larry in the Lumbridge sheep farm.\"},{\"t\":\"Talk to the penguins disguised as a sheep in the Lumbridge sheep farm. You will need to use the same 3 emotes as the penguin from the bird hide cutscene.\"},{\"t\":\"Return to the Ardougne Zoo penguin with either a raw cod, or wearing the ring of charos.\",\"s\":[\"I need that phrase!\",\"The penguins in Lumbridge refuse to talk to me.\",\"I must have left the outpost before they gave out the phrase.\",\"Sure!\"],\"i\":[\"Raw Cod\"]},{\"t\":\"Speak to the sheep-penguins again in the Lumbridge sheep farm.\",\"i\":[\"Clockwork suit\"]},{\"t\":\"Talk to Fred the Farmer without the penguin suit.\",\"s\":[\"I need to talk to you about penguins.\",\"Bully Fred\"]},{\"t\":\"Steal a cowbell from a dairy cow.\"},{\"t\":\"Speak to the sheep-penguins once again in the Lumbridge sheep farm to learn about the outpost.\",\"s\":[\"The Farmer is harmless.\"],\"i\":[\"Clockwork suit\"]}],\"i\":[\"Clockwork suit\",\"Raw Cod\",\"Feathers (5)\",\"Swamp Tar\",\"Mahogany Plank\",\"Leather\",\"Combat gear and food\"],\"c\":1},{\"n\":\"Penguin Outpost\",\"st\":[{\"t\":\"Tell Larry about the outpost and travel back to the iceberg.\",\"s\":[\"Yes\"],\"i\":[\"Swamp Tar\",\"Feathers (5)\",\"Lumbridge mission report\"]},{\"t\":\"Jump in the penguin suit and talk to the KGP Agent on the north west portion of the iceberg.\"},{\"t\":\"Talk to Noodle.\"},{\"t\":\"Give Noodle the swamp tar to get an ID card and a mission report.\",\"s\":[\"Yeah, I got it.\"],\"i\":[\"Swamp Tar\",\"Feathers (5)\"]},{\"t\":\"Talk to the KGP Agent again.\",\"i\":[\"Kgp id card\"]},{\"t\":\"Enter the avalanche.\"}],\"i\":[\"Clockwork suit\",\"Feathers (5)\",\"Swamp Tar\",\"Mahogany Plank\",\"Leather\",\"Combat gear and food\"],\"c\":1},{\"n\":\"Briefing and Agility\",\"st\":[{\"t\":\"Talk to the KGP Agent in the first room to the west of the entrance.\"},{\"t\":\"Enter the door to the west of the KGP Agent to begin the agility course.\"},{\"t\":\"Return to Larry to tell him about the penguin army. You can quickly return to him by removing the penguin suit.\"}],\"i\":[\"Clockwork suit\",\"Mahogany Plank\",\"Leather\",\"Combat gear and food\"],\"c\":1},{\"n\":\"Musical Penguins\",\"st\":[{\"t\":\"Talk to Ping or Pong in the room to the east.\"},{\"t\":\"Use the mahogany plank on the leather to make bongos.\",\"i\":[\"Mahogany Plank\",\"Leather\"]},{\"t\":\"Return to Ping or Pong to give them the bongos and cowbells.\",\"s\":[\"Yes.\"],\"i\":[\"Penguin bongos\",\"Cowbell\"]}],\"i\":[\"Clockwork suit\",\"Mahogany Plank\",\"Leather\",\"Combat gear and food\"],\"c\":1},{\"n\":\"The War Room\",\"st\":[{\"t\":\"Open the control room doors via the control panel.\"},{\"t\":\"Enter the war room and walk a few steps in to be captured.\"},{\"t\":\"Kill icelords until you are able to leave through the door to the west. May take up to 3 kills.\"},{\"t\":\"Use the chasm to exit the cave.\"},{\"t\":\"Return to Larry to finish the quest.\"}],\"i\":[\"Clockwork suit\",\"Combat gear and food\"],\"c\":1}]}"
        "Contact!" -> "{\"n\":\"Contact!\",\"items\":[\"A light source\",\"Tinderbox\",\"Combat gear, preferably magic/ranged\",\"Food\",\"Prayer potions\"],\"rec\":[\"Coins for carpet rides (1000)\",\"Amulet of glory for getting to Osman\",\"Antipoisons\",\"Waterskins for desert travel\"],\"enemies\":[\"Giant Scarab (level 191)\"],\"rewards\":[\"1 Quest point\",\"7,000 Thieving XP\",\"2 x 7,000 Experience Lamps (Combat Skills)\",\"Keris\",\"Access to Sophanem's Bank\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Talk to the High Priest in Sophanem.\",\"s\":[\"Yes.\",\"Sounds like a quest for me; I can't turn that down!\",\"Is there any way into Menaphos from below?\"]},{\"t\":\"Talk to Jex in the building in north east Sophanem.\"}],\"i\":[\"A light source\",\"Tinderbox\",\"Antipoisons\"]},{\"n\":\"Explore the dungeon\",\"st\":[{\"t\":\"Go down the ladder east of Jex.\",\"i\":[\"A light source\"]},{\"t\":\"Go down the trapdoor.\",\"i\":[\"A light source\"]},{\"t\":\"Be careful of traps, and follow the path to the south west ladder. Disarm traps where the path breaks, and use protection prayers against the monsters.\"},{\"t\":\"Follow the path along, and search Kaleef's corpse there.\"},{\"t\":\"Read the parchment\",\"i\":[\"Parchment\"]},{\"t\":\"Talk to Maisa on the west side of the chasm.\",\"s\":[\"Draynor Village.\",\"Leela.\"]},{\"t\":\"Talk to Osman in Al Kharid.\",\"s\":[\"I want to talk to you about Sophanem.\",\"It could drive a wedge between the Menaphite cities.\"]}],\"i\":[\"A light source\",\"Tinderbox\",\"Antipoisons\"]},{\"n\":\"Help Osman\",\"st\":[{\"t\":\"Talk to Osman north of Sophanem.\",\"s\":[\"I know of a secret entrance to the north.\"]},{\"t\":\"Prepare to fight a level 191 Giant Scarab. Go down the ladder east of Jex.\",\"i\":[\"A light source\",\"Combat gear, preferably magic/ranged\"]},{\"t\":\"Go down the trapdoor.\",\"i\":[\"A light source\"]},{\"t\":\"Be careful of traps, and follow the path to the south west ladder. Disarm traps where the path breaks, and use protection prayers against the monsters.\"},{\"t\":\"Kill the Giant Scarab near the chasm. It can extinguish your light source and poison you, so be careful. Pray melee if you are meleeing it, range if you are attacking it from a distance.\"},{\"t\":\"Talk to Osman in the chasm.\"},{\"t\":\"Pick up the Keris.\",\"i\":[\"Keris\"]},{\"t\":\"Report back to the High Priest in Sophanem.\"}],\"i\":[\"Combat gear, preferably magic/ranged\",\"Food\",\"Prayer potions\",\"A light source\",\"Tinderbox\",\"Antipoisons\"],\"c\":1,\"e\":[\"Giant Scarab (level 191)\"]}]}"
        "Cook's Assistant" -> "{\"n\":\"Cook's Assistant\",\"items\":[\"Egg\",\"Pot of flour\",\"Bucket of milk\"],\"rec\":[\"Coins (3)\"],\"enemies\":[],\"rewards\":[\"1 Quest point\",\"300 Cooking XP\",\"Permission to use The Cook's range.\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Purchase a bucket from the Lumbridge General Store.\",\"i\":[\"Coins (2)\"]},{\"t\":\"Purchase a pot from the Lumbridge General Store.\",\"i\":[\"Coins\"]}],\"i\":[\"Coins (3)\"],\"c\":0},{\"n\":\"Getting the Egg\",\"st\":[{\"t\":\"Grab an egg from the farm north of Lumbridge.\",\"i\":[\"Egg\"]}],\"c\":0},{\"n\":\"Getting the Flour\",\"st\":[{\"t\":\"Pick some wheat north of Lumbridge.\"},{\"t\":\"Climb up the ladder in the Mill north of Lumbridge to the top floor.\",\"i\":[\"Pot\",\"Grain\"]},{\"t\":\"Fill the hopper with your grain.\",\"i\":[\"Pot\",\"Grain\"]},{\"t\":\"Operate the hopper controls.\",\"i\":[\"Pot\"]},{\"t\":\"Climb down the ladder in the Mill to the ground floor.\",\"i\":[\"Pot\"]},{\"t\":\"Collect the flour in the bin.\",\"i\":[\"Pot\"]}],\"i\":[\"Pot\"],\"c\":0},{\"n\":\"Getting the Milk\",\"st\":[{\"t\":\"Milk the dairy cow north of Lumbridge.\",\"i\":[\"Bucket\"]}],\"i\":[\"Bucket\"],\"c\":0},{\"n\":\"Finishing up\",\"st\":[{\"t\":\"Give the Cook in Lumbridge Castle's kitchen the required items to finish the quest.\",\"s\":[\"What's wrong?\",\"Can I help?\",\"Yes.\"],\"i\":[\"Egg\",\"Bucket of milk\",\"Pot of flour\"]}],\"i\":[\"Egg\",\"Pot of flour\",\"Bucket of milk\"],\"c\":0}]}"
        "Creature of Fenkenstrain" -> "{\"n\":\"Creature of Fenkenstrain\",\"items\":[\"Hammer\",\"Ghostspeak amulet\",\"Silver bar\",\"Bronze wire (3)\",\"Needle\",\"Thread (5)\",\"Spade\",\"Coins at least (100)\",\"33 Magic and runes to cast telegrab, or 50 coins\",\"Armour and weapons defeat a level 51 monster and run past level 72 monsters\"],\"rec\":[\"Fenkenstrain's Castle Teleport (2)\",\"Teleport to any furnace such as glory for Edgeville teleport, Ectophial to Port Phasmatys or a Falador teleport\",\"Stamina potions\"],\"enemies\":[\"Able to defeat an experiment (level 51)\"],\"rewards\":[\"2 Quest points\",\"1,000 Thieving XP\",\"Ring of Charos\",\"Access to the Werewolf Agility Course\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Head to the Canifis bar and either buy the pickled brain for 50 coins, or telegrab it.\",\"s\":[\"I'll buy one.\"],\"i\":[\"33 Magic and runes to cast telegrab, or 50 coins\"]},{\"t\":\"Talk to Dr. Fenkenstrain to start the quest.\",\"s\":[\"Yes.\",\"Braindead\",\"Grave-digging\"]}],\"i\":[\"33 Magic and runes to cast telegrab, or 50 coins\"]},{\"n\":\"Graverobbing\",\"st\":[{\"t\":\"Go up the staircase to grab the items you will need.\"},{\"t\":\"Search the nearby bookcase for Handy Maggot Avoidance Techniques.\",\"s\":[\"Handy Maggot Avoidance Techniques\"]},{\"t\":\"Search the west bookcase for The Joy of Grave Digging.\",\"s\":[\"The Joy of Gravedigging\"]},{\"t\":\"Combine the two amulet by using one on the other.\",\"i\":[\"Marble Amulet\",\"Obsidian Amulet\"]},{\"t\":\"Go back to the ground floor.\"},{\"t\":\"Talk to the Gardener Ghost while wearing your Ghostspeak amulet.\",\"s\":[\"What happened to your head?\"],\"i\":[\"Ghostspeak amulet\"]},{\"t\":\"Go to the grave of the gardener and dig for his head.\"},{\"t\":\"Use the decapitated head on the pickled brain to create a decapitated head.\",\"i\":[\"Decapitated Head\",\"Pickled Brain\"]},{\"t\":\"Use the Star Amulet on the memorial and push it to go in the caves.\",\"i\":[\"Star Amulet\"]},{\"t\":\"Push the memorial south east of the castle.\"},{\"t\":\"Kill the level 51 Experiment north-west of the ladder to get a key.\"},{\"t\":\"Leave the caves by going north-west, be sure to pick up the key from the level 51 experiment.\"},{\"t\":\"Use your spade on this tile to get the torso.\"},{\"t\":\"Use your spade on this tile to get arms.\"},{\"t\":\"Use your spade on this tile to get legs.\"},{\"t\":\"Deliver the body parts to Dr. Fenkenstrain, use a teleport to Fenkenstrain's castle or run back through the caves.\",\"s\":[\"I have some body parts for you.\"]}],\"i\":[\"Ghostspeak amulet\",\"Spade\",\"Armour and weapons defeat a level 51 monster and run past level 72 monsters\",\"Needle\",\"Thread (5)\"],\"c\":1},{\"n\":\"Getting tools\",\"st\":[{\"t\":\"Get a needle and 5 threads and deliver them to Dr. Fenkenstrain.\",\"i\":[\"Needle\",\"Thread (5)\"]}],\"i\":[\"Ghostspeak amulet\",\"Needle\",\"Thread (5)\"]},{\"n\":\"Attracting lightning\",\"st\":[{\"t\":\"Talk to the Gardener Ghost and ask for the shed key.\",\"s\":[\"Do you know where the key to the shed is?\"],\"i\":[\"Ghostspeak amulet\",\"Bronze wire (3)\",\"Silver bar\"]},{\"t\":\"Open the cupboard and search it for a brush.\",\"i\":[\"Bronze wire (3)\",\"Silver bar\"]},{\"t\":\"Grab 3 canes from the pile.\",\"i\":[\"Bronze wire (3)\",\"Silver bar\"]},{\"t\":\"Use 3 canes on the brush one at a time.\",\"i\":[\"Garden Cane\",\"Brush\",\"Bronze wire (3)\",\"Silver bar\"]},{\"t\":\"Go up to the second floor of the castle.\"},{\"t\":\"Use the extended brush on the fireplace to get the conductor mould.\",\"i\":[\"Extended Brush\"]},{\"t\":\"Go to any furnace make a lightning rod.\",\"i\":[\"Silver bar\",\"Conductor Mold\"]},{\"t\":\"Return to the castle and go upstairs.\"},{\"t\":\"Go up to the third floor using the ladder in the middle of the castle.\"},{\"t\":\"Repair the lightning Conductor.\"},{\"t\":\"Go back to the first floor of the castle and talk to Dr. Fenkenstrain.\"}],\"i\":[\"Ghostspeak amulet\",\"Bronze wire (3)\",\"Silver bar\",\"Hammer\"]},{\"n\":\"Facing the monster\",\"st\":[{\"t\":\"Go up to the second floor to confront Fenkenstrain's monster.\"},{\"t\":\"Use the Tower Key on the door.\"},{\"t\":\"Go up the ladder.\"},{\"t\":\"Talk to Fenkenstrain's monster.\"}]},{\"n\":\"Finishing off\",\"st\":[{\"t\":\"Go back to Dr. Fenkenstrain, instead of talking to him right click and pickpocket him.\"}]}]}"
        "Current Affairs" -> "{\"n\":\"Current Affairs\",\"items\":[\"Charcoal\",\"Coins (50)\"],\"rec\":[],\"enemies\":[],\"rewards\":[\"1 Quest point\",\"1,400 Sailing XP\",\"1,000 Fishing XP\",\"Current Duck\",\"Mayor of Catherby\",\"25 x Sawmill Coupon (oak plank)\",\"Access to charting currents\"],\"sec\":[{\"n\":\"Arhein's employee\",\"st\":[{\"t\":\"Talk to Arhein on the northern part of the Catherby Docks to start the quest.\",\"s\":[\"What's with the duck?\",\"Yes.\"]},{\"t\":\"Talk to Councillor Catherine in the north-east of Catherby.\"},{\"t\":\"Fill form cr-4p. The answers you provide do not matter.\",\"s\":[\"Pleasure.\",\"Trade.\",\"Piracy.\",\"0\",\"1\",\"2+\",\"Cargo spillage.\",\"Theft.\",\"Both.\",\"No.\",\"Yes.\",\"Partial.\",\"Partial.\",\"No.\",\"Yes.\",\"Yes.\",\"Partial.\",\"No.\",\"Less than a month.\",\"Less than a year.\",\"A year or more.\",\"Varrock.\",\"Falador.\",\"Edgeville.\"],\"i\":[\"Form cr-4p\",\"Charcoal\"]},{\"t\":\"Hand over the filled form to Councillor Catherine.\",\"s\":[\"Yes, I have it here.\"],\"i\":[\"Form cr-4p\"]},{\"t\":\"Finish talking to Councillor Catherine in the north-east of Catherby.\"}],\"i\":[\"Charcoal\"],\"c\":0},{\"n\":\"A new mayor\",\"st\":[{\"t\":\"Talk to Arhein on the docks about the mayor.\",\"s\":[\"I need to find the Mayor of Catherby.\"]},{\"t\":\"Talk to Harry in the fish shop in south-east Catherby about a new mayor.\",\"s\":[\"I'm here about the mayor.\",\"Yes.\"],\"i\":[\"Coins (50)\"]},{\"t\":\"Fish a new mayor from the aquarium.\",\"i\":[\"Tiny net\",\"Mayoral fishbowl\"]},{\"t\":\"Introduce Arhein on the Catherby docks to the new Mayor of Catherby.\",\"s\":[\"About the mayor...\"],\"i\":[\"Mayor of Catherby\"]},{\"t\":\"Talk to Councillor Catherine about changing the by-laws.\",\"s\":[\"Yes, I have it here.\"],\"i\":[\"Mayor of Catherby\"]},{\"t\":\"Talk to Councillor Catherine to complete the audit.\"},{\"t\":\"Talk to Councillor Catherine in the north-east of Catherby to receive a new form 7r4-5h.\"},{\"t\":\"Use form 7r4-5h on the Mayor of Catherby.\",\"i\":[\"Form 7r4-5h\",\"Mayor of Catherby\"]},{\"t\":\"Show Councillor Catherine the signed form.\",\"i\":[\"Form 7r4-5h\"]},{\"t\":\"Give Arhein on the Catherby docks the good news.\",\"s\":[\"The by-law has been changed!\"]}],\"i\":[\"Coins (50)\"],\"c\":0},{\"n\":\"Map the currents!\",\"st\":[{\"t\":\"Get a new duck from Arhein on the Catherby docks, or from your ship's cargo hold.\",\"s\":[\"About that duck...\"]},{\"t\":\"Sail to the small island east of Catherby, then release the Current duck.\",\"i\":[\"Current Duck\"]},{\"t\":\"Release the Current duck.\",\"i\":[\"Current Duck\"]},{\"t\":\"Follow the Current duck! It'll end up south-west of Entrana.\"},{\"t\":\"Collect your Current duck.\"},{\"t\":\"Share what you've learned with Arhein on the Catherby docks.\",\"s\":[\"I've charted the currents!\"]}],\"i\":[\"Current Duck\"],\"c\":0}]}"
        "Curse of the Empty Lord" -> "{\"n\":\"Curse of the Empty Lord\",\"items\":[\"Ring of visibility\",\"Ghostspeak amulet or Morytania legs 2 or better\",\"Knife\"],\"rec\":[],\"enemies\":[],\"rewards\":[\"10,000 Experience Lamp (Any skill over level 50).\",\"A Set of Ghostly Robes\"],\"sec\":[{\"n\":\"Learn about the Empty Lord\",\"st\":[{\"t\":\"Talk to the Mysterious Ghost outside Glarial's Tomb.\",\"s\":[\"Tell me your story\"],\"i\":[\"Ghostspeak amulet or Morytania legs 2 or better\",\"Ring of visibility\"]},{\"t\":\"Talk to the Mysterious Ghost Rennard.\",\"s\":[\"Tell me your story\"],\"i\":[\"Ghostspeak amulet or Morytania legs 2 or better\",\"Ring of visibility\"]},{\"t\":\"Talk to the Mysterious Ghost Kharrim.\",\"s\":[\"Tell me your story\"],\"i\":[\"Ghostspeak amulet or Morytania legs 2 or better\",\"Ring of visibility\"]},{\"t\":\"Talk to the Mysterious Ghost Lennissa.\",\"s\":[\"Tell me your story\"],\"i\":[\"Ghostspeak amulet or Morytania legs 2 or better\",\"Ring of visibility\"]},{\"t\":\"Talk to the Mysterious Ghost Dhalak.\",\"s\":[\"Tell me your story\"],\"i\":[\"Ghostspeak amulet or Morytania legs 2 or better\",\"Ring of visibility\"]},{\"t\":\"Talk to the Mysterious Ghost Viggora.\",\"s\":[\"Tell me your story\"],\"i\":[\"Ghostspeak amulet or Morytania legs 2 or better\",\"Ring of visibility\"]}],\"i\":[\"Ghostspeak amulet or Morytania legs 2 or better\",\"Ring of visibility\",\"Knife\"],\"c\":0}]}"
        "Daddy's Home" -> "{\"n\":\"Daddy's Home\",\"items\":[\"Plank (10)\",\"Nails (bring more in case you fail with some) (14)\",\"Bolt of cloth (5)\",\"Saw\",\"Hammer\"],\"rec\":[\"Lumberyard Teleport\",\"Varrock Teleports (3)\"],\"enemies\":[],\"rewards\":[\"400 Construction XP\",\"25 x Planks\",\"10 x Oak Planks\",\"50 x Mithril Nails\",\"5 x Steel Bars\",\"8 x Bolt of Cloth\",\"5 x House Teleport Tablets\",\"Falador Teleport Tablet\",\"POH in Rimmington or 1,000 Coins\"],\"sec\":[{\"n\":\"Helping Yarlo & Marlo\",\"st\":[{\"t\":\"Talk to Marlo in north-east Varrock.\",\"s\":[\"What kind of favour do you want me to do?\",\"Tell me more about the job.\",\"Tell me where he lives, and I'll do the job.\"]},{\"t\":\"Talk to Old Man Yarlo in south-east Varrock, west of Aubury's Rune Shop.\"},{\"t\":\"Remove the broken furniture in Old Man Yarlo's house.\"},{\"t\":\"Talk to Old Man Yarlo again after removing all the broken furniture.\",\"s\":[\"Skip Yarlo's lecture. He'll offer it later if you like.\"]},{\"t\":\"Rebuild the furniture in Old Man Yarlo's house.\",\"i\":[\"Plank (3)\",\"Nails (4)\",\"Saw\",\"Hammer\"]},{\"t\":\"Search the crates in Old Man Yarlo's house for waxwood logs.\"},{\"t\":\"Talk to the Sawmill operator north-east of Varrock to make waxwood planks.\",\"s\":[\"I need some waxwood planks for Old Man Yarlo.\"],\"i\":[\"Waxwood log (3)\"]},{\"t\":\"Build the waxwood bed in Old Man Yarlo's house.\",\"i\":[\"Waxwood plank (3)\",\"Bolt of cloth (2)\",\"Hammer\",\"Saw\"]},{\"t\":\"Talk to Old Man Yarlo again after rebuilding the furniture.\"},{\"t\":\"Talk to Marlo in north-east Varrock to complete the quest.\",\"s\":[\"Yeah, what have you got for me?\"]}],\"i\":[\"Plank (10)\",\"Nails (bring more in case you fail with some) (14)\",\"Bolt of cloth (5)\",\"Hammer\",\"Saw\"],\"c\":0}]}"
        "Darkness of Hallowvale" -> "{\"n\":\"Darkness of Hallowvale\",\"items\":[\"Hammer\",\"Plank (2)\",\"Nails (8)\",\"Knife\"],\"rec\":[\"Law rune\",\"Air rune\",\"Any pickaxe\"],\"enemies\":[\"Able to survive 5 hits from Vanstrom Klause (level 169) or use Protect from Melee to negate all his damage.\"],\"rewards\":[\"2 Quest points\",\"7,000 Agility XP\",\"6,000 Thieving XP\",\"2,000 Construction XP\",\"3 x 2,000 Experience Tomes (Any skill over level 30).\"],\"sec\":[{\"n\":\"Infiltrating Meiyerditch\",\"st\":[{\"t\":\"Talk to Veliaf in the Myreque base under Burgh de Rott.\"},{\"t\":\"Leave the Myreque base.\"},{\"t\":\"Fix the boat in south Burgh de Rott.\",\"s\":[\"Yes.\"],\"i\":[\"Hammer\",\"Plank (2)\",\"Nails (8)\"]},{\"t\":\"Fix the boat chute.\",\"s\":[\"Yes.\"],\"i\":[\"Hammer\",\"Plank\",\"Nails (4)\"]},{\"t\":\"Push the boat.\"},{\"t\":\"Board the boat.\"},{\"t\":\"Climb up the walls and search the marked floor.\",\"s\":[\"Yes.\"]},{\"t\":\"Climb down the floorboard.\"},{\"t\":\"Talk to a Meiyerditch citizen.\",\"s\":[\"(whisper) Do you know about the Myreque?\",\"(whisper) I really need to meet the Myreque.\",\"How can Old Man Ral help me?\"]},{\"t\":\"Talk to Old Man Ral in south western Meiyerditch.\",\"s\":[\"Someone said you could help me.\",\"Old Man Ral, the sage of Sanguinesti.\"]},{\"t\":\"Follow the path to the Meiyerditch Myreque base.\"},{\"t\":\"Press the decorated wall.\"},{\"t\":\"Open the rug and enter the trapdoor.\"},{\"t\":\"Talk to Vertida in the north room.\"},{\"t\":\"Bring the message to Veliaf in the Myreque base under Burgh de Rott.\",\"s\":[\"What should I do now?\"]}],\"i\":[\"Hammer\",\"Plank (2)\",\"Nails (8)\",\"Knife\"]},{\"n\":\"Murder at Paterdomus\",\"st\":[{\"t\":\"Talk to Drezel under the Paterdomus Temple.\"},{\"t\":\"Search the bushes west of Paterdomus.\"},{\"t\":\"Return to Drezel.\"},{\"t\":\"Talk to King Roald in Varrock Castle.\",\"s\":[\"I must speak with you on a matter of grave importance.\",\"Talk to the king about Morytania.\",\"What should I do now?\",\"Yes thanks. I'll accept the free teleport.\"]},{\"t\":\"Return to Veliaf in the Myreque base under Burgh de Rott.\"}]},{\"n\":\"Mapping Castle Drakan\",\"st\":[{\"t\":\"Return to the Meiyerditch Myreque base.\"},{\"t\":\"Climb along the western wall until you reach Safalaan.\",\"s\":[\"Okay, lead the way.\"]},{\"t\":\"Sketch the north side of Castle Drakan by using the charcoal on some papyrus.\"},{\"t\":\"Sketch the west side of Castle Drakan by using the charcoal on some papyrus.\"},{\"t\":\"Sketch the south side of Castle Drakan. Be prepared to tank some hits from Vanstrom Klause.\"},{\"t\":\"Tank Vanstrom for 5 hits or use Protect from Melee.\"},{\"t\":\"Talk to Sarius on the walls around Castle Drakan.\"},{\"t\":\"Finish sketching the south side of Castle Drakan.\"},{\"t\":\"Go use a knife on the fireplace near the Meiyerditch Myreque base.\"},{\"t\":\"Use a knife on the portrait south of the fireplace.\"},{\"t\":\"Read the message.\",\"i\":[\"Message\"]},{\"t\":\"Return to Safalaan in the Meiyerditch Myreque base.\"}],\"i\":[\"Knife\"]},{\"n\":\"Investigate the lab\",\"st\":[{\"t\":\"Slash the tapestry in the building in north east Meiyerditch.\",\"i\":[\"Knife\"]},{\"t\":\"Use the ornate key on the nearby statue.\",\"i\":[\"Large ornate key\"]},{\"t\":\"Go down the staircase to the lab.\"},{\"t\":\"Telegrab the Haemalchemy book.\",\"i\":[\"Haemalchemy volume 1\",\"Law rune\",\"Air rune\"]},{\"t\":\"Return to Safalaan with the Haemalchemy book.\"},{\"t\":\"Bring the letter to Veliaf in the Myreque base under Burgh de Rott to complete the quest.\"}],\"i\":[\"Knife\",\"Law rune\",\"Air rune\"]}]}"
        "Death Plateau" -> "{\"n\":\"Death Plateau\",\"items\":[\"Coins (60)\",\"Premade blurb' sp.\",\"Iron bar\",\"Bread (UNNOTED) (10)\",\"Trout (UNNOTED) (10)\"],\"rec\":[\"Games necklace\"],\"enemies\":[],\"rewards\":[\"1 Quest point\",\"3,000 Attack XP\",\"A pair of Steel Claws\",\"The ability to craft claws.\",\"The ability to purchase and equip Climbing Boots.\"],\"sec\":[{\"n\":\"The equipment room\",\"st\":[{\"t\":\"Talk to Denulth in Burthorpe. You can get there with the Burthorpe minigame teleport or a games necklace.\"},{\"t\":\"Ask Eohric, upstairs in Burthorpe castle, about the guard that was on duty last night.\"},{\"t\":\"Talk to Harold, upstairs in the bar in Burthorpe.\"},{\"t\":\"Talk to Eohric.\"},{\"t\":\"Take an Asgarnian ale from the bar.\",\"i\":[\"Coins (60)\",\"Asgarnian ale\",\"Premade blurb' sp.\"]},{\"t\":\"Talk to Harold.\",\"i\":[\"Coins (60)\",\"Asgarnian ale\",\"Premade blurb' sp.\"]},{\"t\":\"Talk to Harold to give him a Blurberry Special.\",\"i\":[\"Coins (60)\",\"Premade blurb' sp.\"]},{\"t\":\"Gamble with Harold (101 coins to immediately bankrupt him).\",\"i\":[\"Coins (60)\"]},{\"t\":\"Read the IOU, and then keep the Combination for the end of the quest.\",\"i\":[\"IOU\"]},{\"t\":\"Go back to Burthorpe castle, and place the coloured stone balls in the correct spots on the mechanism.\"}],\"i\":[\"Coins (60)\",\"Premade blurb' sp.\"],\"c\":0},{\"n\":\"Get spiked boots\",\"st\":[{\"t\":\"Enter the cave north west of Burthorpe.\"},{\"t\":\"Talk to Saba.\",\"s\":[\"Do you know of another way up Death Plateau?\"]},{\"t\":\"Go northwest of Burthorpe, then south at the fork, and talk to Tenzing.\"},{\"t\":\"Talk to Dunstan at the anvil in Burthorpe, then talk to Denulth, where you started the quest.\",\"i\":[\"Climbing boots\"]},{\"t\":\"Talk to Dunstan to exchange the climbing boots for spiked boots.\",\"i\":[\"Climbing boots\",\"Certificate\",\"Iron bar\"]}],\"i\":[\"Iron bar\"],\"c\":0},{\"n\":\"The secret path\",\"st\":[{\"t\":\"Bring the spiked boots, along with (unnoted) 10 bread and 10 trout to Tenzing.\",\"i\":[\"Spiked boots\",\"Bread (UNNOTED) (10)\",\"Trout (UNNOTED) (10)\"]},{\"t\":\"Exit Tenzing's house into the backyard THROUGH THE NORTH DOOR and OVER THE STILE. Continue north past the Death Plateau warning, and around to the east until you stop and say you've gone far enough.\",\"i\":[\"Secret way map\"]},{\"t\":\"Go back and talk to Denulth, giving him the secret map and Combination.\",\"i\":[\"Secret way map\",\"Combination\"]}],\"i\":[\"Bread (UNNOTED) (10)\",\"Trout (UNNOTED) (10)\"],\"c\":0}]}"
        "Death on the Isle" -> "{\"n\":\"Death on the Isle\",\"items\":[],\"rec\":[],\"enemies\":[\"2 unlosable fights\"],\"rewards\":[\"2 Quest points\",\"10,000 Thieving XP\",\"7,500 Agility XP\",\"5,000 Crafting XP\",\"The ability to use a Costume Needle (obtainable by speaking to the Costumer)\",\"The ability to unlock the North Aldarin teleport destination via the pendant of ates\"],\"sec\":[{\"n\":\"Getting the right fit\",\"st\":[{\"t\":\"Talk to Patzi at the entrance to Villa Lucens on the island of Aldarin to start the quest.\",\"s\":[\"Yes.\"]},{\"t\":\"Enter the house north of Patzi through the window to steal a butler's uniform. If the Wandering Guard bothers you, wait until he steps away before entering.\"},{\"t\":\"Steal the butler's uniform from the wardrobe.\"},{\"t\":\"Leave the house with the butler's uniform.\",\"i\":[\"Butler's uniform\"]},{\"t\":\"Return to Patzi after stealing the butler's uniform.\",\"i\":[\"Butler's uniform\"]},{\"t\":\"Equip the Butler's uniform pieces and talk to the Head Butler up the stone stairs and to the south.\",\"s\":[\"I am.\"],\"i\":[\"Butler's uniform\"]}]},{\"n\":\"Inside Villa Lucens\",\"st\":[{\"t\":\"Head inside the villa and talk to Patzi.\"},{\"t\":\"Introduce yourself to Constantinius.\"},{\"t\":\"Introduce yourself to Cozyac.\"},{\"t\":\"Introduce yourself to Pavo.\"},{\"t\":\"Introduce yourself to Xocotla.\"},{\"t\":\"Return to Patzi with the information you've gathered.\"},{\"t\":\"Investigate the Antique wine in the southern part of the cellar.\"},{\"t\":\"Check on the man in the south-eastern part of the cellar.\"},{\"t\":\"Explain your innocence to the guards Stradius and Hutza.\"}],\"i\":[\"Butler's uniform shirt\",\"Butler's uniform pants\"]},{\"n\":\"Playing detective\",\"st\":[{\"t\":\"Enter the cellar again to begin your investigation.\"},{\"t\":\"Investigate the Jug by the entrance stairs.\"},{\"t\":\"Investigate the Small box in the south room.\"},{\"t\":\"Investigate the Broken stool in the south room.\"},{\"t\":\"Investigate the Wine storage in the east room.\"},{\"t\":\"Investigate the Broken pottery in the east room.\"},{\"t\":\"Investigate Livius in the east room.\"},{\"t\":\"Leave the cellar.\"},{\"t\":\"Interrogate Constantinius.\"},{\"t\":\"Interrogate Cozyac.\"},{\"t\":\"Interrogate Pavo.\"},{\"t\":\"Interrogate Xocotla.\"},{\"t\":\"Interrogate Patzi and Adala.\"},{\"t\":\"Return to the guards with the information you've found so far.\",\"s\":[\"I think I've found everything there is to find so far. What now?\"]},{\"t\":\"Pickpocket Adala until you find Wine labels.\",\"i\":[\"Wine labels\"]},{\"t\":\"Pickpocket Cozyac until you find a threatening note.\",\"i\":[\"Threatening note\"]},{\"t\":\"Pickpocket Pavo until you find a drinking flask.\",\"i\":[\"Drinking flask\"]},{\"t\":\"Pickpocket Xocotla until you find a shipping contract.\",\"i\":[\"Shipping contract\"]},{\"t\":\"Inspect the Wine labels in your inventory.\",\"i\":[\"Wine labels\"]},{\"t\":\"Inspect the Threatening note in your inventory.\",\"i\":[\"Threatening note\"]},{\"t\":\"Inspect the Drinking flask in your inventory.\",\"i\":[\"Drinking flask\"]},{\"t\":\"Inspect the Shipping contract in your inventory.\",\"i\":[\"Shipping contract\"]},{\"t\":\"Return to the guards with the stolen items.\",\"s\":[\"I think I've found everything there is to find so far. What now?\"],\"i\":[\"Wine labels\",\"Threatening note\",\"Drinking flask\",\"Shipping contract\"]},{\"t\":\"Talk to the guards to tell them you're ready to make an accusation.\",\"s\":[\"I'm ready.\"]},{\"t\":\"Accuse Adala of the crime, ready for a fight you cannot lose.\",\"s\":[\"Accuse Adala.\"]},{\"t\":\"Talk to Adala to get her confession.\"},{\"t\":\"Talk to the guards about Adala.\"}]},{\"n\":\"The show must go on\",\"st\":[{\"t\":\"Talk to Stradius at the backstage of the theatre.\"},{\"t\":\"Talk to the Costumer in the theatre cellar.\"},{\"t\":\"Search the crate next to the stairs.\"},{\"t\":\"Search the bookshelf on the west wall.\"},{\"t\":\"Search the costume rack to the north.\"},{\"t\":\"Talk to the Costumer about what you found.\"},{\"t\":\"Report back to Stradius near the theatre and accuse Naiatli.\",\"s\":[\"More options...\",\"Naiatli.\",\"Previous options...\"]},{\"t\":\"Talk to Stradius to enter the theatre.\"},{\"t\":\"Confront Naiatli, attacking her when she runs away. When Clodius appears, attack him instead.\"},{\"t\":\"Talk to Naiatli.\"},{\"t\":\"Talk to Stradius and Hutza to finish the quest.\"}]}]}"
        "Death to the Dorgeshuun" -> "{\"n\":\"Death to the Dorgeshuun\",\"items\":[\"A light source\",\"2 full ham robe sets (7 pieces/set)\",\"Tinderbox\",\"Any pickaxe\",\"Magic or melee combat gear\"],\"rec\":[\"Lumbridge teleports (3)\",\"Games necklace (requires Tears of Guthix to teleport to Juna)\"],\"enemies\":[\"3 H.A.M. Guards (level 22)\",\"Sigmund (level 50, melee or magic only)\"],\"rewards\":[\"1 Quest point\",\"2,000 Thieving XP\",\"2,000 Ranged XP\",\"Ability to use Dorgeshuun Special Attacks\",\"Access to H.A.M. Store Rooms.\",\"Access to Dorgesh-Kann.\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Travel through the tunnels under Lumbridge Castle until you reach Mistag, then talk to him.\",\"s\":[\"What is this favour?\",\"I'll act as a guide.\",\"Yes.\"]},{\"t\":\"Talk to Zanik in Lumbridge Castle's basement.\",\"s\":[\"Yes, I'm !\",\"Yes, I have two sets of robes!\"]}],\"i\":[\"A light source\",\"2 full ham robe sets (7 pieces/set)\"]},{\"n\":\"Exploring Lumbridge\",\"st\":[{\"t\":\"Talk to the Lumbridge Cook.\"},{\"t\":\"Talk to the Duke.\"},{\"t\":\"Leave the castle, and go through the entire leaving cutscene. If you cut it short, enter/leave again.\"},{\"t\":\"Talk to any man or woman around Lumbridge.\"},{\"t\":\"Talk to the Lumbridge Guide.\"},{\"t\":\"Talk to Bob in south Lumbridge.\"},{\"t\":\"Talk to Father Aereck.\"},{\"t\":\"Approach the goblins east of the River Lum.\"},{\"t\":\"Talk to the Lumbridge General Store shopkeeper.\"},{\"t\":\"Talk to Zanik about her head sign.\",\"s\":[\"Have you seen enough of Lumbridge yet?\",\"Yes please!\"]}],\"i\":[\"A light source\",\"2 full ham robe sets (7 pieces/set)\"]},{\"n\":\"Infiltrate the H.A.M\",\"st\":[{\"t\":\"Enter the H.A.M lair west of Lumbridge.\"},{\"t\":\"Talk to Johanhus in the south east of the base.\",\"s\":[\"Are you planning to do anything about the cave goblins?\"]},{\"t\":\"Go stand at the south of the stage until Zanik talks about the speaker. Don't skip the dialog.\"},{\"t\":\"Go stand next to the rubble south of the stage until Zanik notices it.\"},{\"t\":\"Picklock the trapdoor south of the stage and go down it.\"}],\"i\":[\"A light source\",\"Full ham robe sets (7 pieces)(equipped)\"]},{\"n\":\"Reaching the meeting\",\"st\":[{\"t\":\"Sneak your way to the end of the secret area.\"},{\"t\":\"Listen to the large door.\"}]},{\"n\":\"Saving Zanik\",\"st\":[{\"t\":\"Inspect Zanik outside the H.A.M base.\"},{\"t\":\"Take Zanik to Juna in the Lumbridge Swamp. Using a games necklace is recommended.\"},{\"t\":\"Talk to Zanik about what happened to her.\",\"s\":[\"Yes.\",\"Yes please!\"]}],\"i\":[\"A light source\",\"Tinderbox\",\"Any pickaxe\"]},{\"n\":\"Foiling H.A.M\",\"st\":[{\"t\":\"Talk to Zanik under the Lumbridge Castle.\",\"s\":[\"Let's go!\",\"Yes.\",\"Yes please!\"]},{\"t\":\"Search a crate south of the farm east of Lumbridge. If Zanik isn't appearing when doing so, call her in the 'Worn equipment' tab with the 'Call follower' button with a whistle icon.\",\"s\":[\"I don't know, what are you thinking?\",\"Good idea.\"],\"i\":[\"Magic or melee combat gear\",\"Full ham robe sets (7 pieces)(equipped)\"]},{\"t\":\"Enter the trapdoor outside the farm.\",\"i\":[\"Magic or melee combat gear\",\"Full ham robe sets (7 pieces)(equipped)\"]},{\"t\":\"Kill the guards to the west.\"},{\"t\":\"Defeat Sigmund. You need to use magic or melee to hurt him.\",\"i\":[\"Magic or melee combat gear\"]},{\"t\":\"Destroy the drilling machine.\"},{\"t\":\"Leave the area via the exit to the south to finish the quest.\"}],\"i\":[\"Full ham robe sets (7 pieces)(equipped)\",\"Magic or melee combat gear\"],\"c\":1,\"e\":[\"Sigmund (level 50, melee or magic only)\"]}]}"
        "Defender of Varrock" -> "{\"n\":\"Defender of Varrock\",\"items\":[\"Combat gear and food\",\"Any pickaxe\"],\"rec\":[\"Teleport to the Lumberyard\",\"Varrock teleport (2)\",\"Mind Altar or Lassar teleport tablet or spell\"],\"enemies\":[\"At least six armoured zombies (level 85)\",\"Multiple Chaos Golems (level 70)\"],\"rewards\":[\"2 Quest points\",\"15,000 Smithing XP\",\"15,000 Hunter XP\",\"Access to Zemouregal's Base\",\"5000 exp lamp and 5 kudos from Historian Minas\"],\"sec\":[{\"n\":\"Intrigue\",\"st\":[{\"t\":\"Talk to Elias White in the Jolly Boar Inn north-east of Varrock.\",\"s\":[\"Yes.\",\"Ready when you are.\"],\"i\":[\"Combat gear and food\"]},{\"t\":\"Inspect the plant north of the pub.\"},{\"t\":\"Inspect the small rocks to the west.\"},{\"t\":\"Follow the path to the south and inspect the plant south west of the Jolly Boar Inn.\"},{\"t\":\"Continue south-east of the Saradomin statue, and inspect the bush there.\"},{\"t\":\"Search the bush next to the gate to the east, by the gate to Silvarea.\"},{\"t\":\"Inspect the small bush further to the east.\"},{\"t\":\"Enter the trapdoor to the north, near to the wilderness ditch.\",\"s\":[\"Let's do it.\"],\"i\":[\"Combat gear and food\"]},{\"t\":\"Talk to Elias in the dungeon.\"},{\"t\":\"Look over the balcony to the north.\"},{\"t\":\"Pick up 3 bottles nearby.\",\"i\":[\"Bottle (3)\"]},{\"t\":\"Kill armoured zombies and fill the 3 bottles with the clouds they leave behind.\"},{\"t\":\"Collect the red mist in a bottle.\"},{\"t\":\"Go through the gate, and finish the cutscene with Arrav. If you skip it, try re-entering the gate.\"},{\"t\":\"Kill zombies to fill 3 bottles with mist again, and continue deeper into the dungeon.\",\"i\":[\"Bottle of mist (3)\"]},{\"t\":\"Look over the balcony facing over the zombie army.\"}],\"i\":[\"Combat gear and food\",\"Teleport to the Lumberyard\",\"Varrock teleport\"],\"c\":1},{\"n\":\"Crisis\",\"st\":[{\"t\":\"Report back to Elias White in the Varrock Palace.\"},{\"t\":\"Talk to Captain Rovin upstairs in the north west of Varrock Castle.\"},{\"t\":\"Enter Camdozaal, west of Ice Mountain.\",\"i\":[\"Any pickaxe\",\"Combat gear and food\"]},{\"t\":\"Talk to Ramarno to the north by the sacred forge.\",\"s\":[\"I need your help with a shield.\"]},{\"t\":\"Mine a barronite deposit.\",\"i\":[\"Any pickaxe\"]},{\"t\":\"Kill chaos golems in the eastern cavern for a chaos core.\",\"i\":[\"Chaos core\"]},{\"t\":\"Use a chaos core on a barronite deposit.\",\"i\":[\"Chaos core\",\"Barronite deposit\"]},{\"t\":\"Use the imbued barronite on the sacred forge.\",\"i\":[\"Imbued barronite\"]}],\"i\":[\"Combat gear and food\",\"Any pickaxe\",\"Mind Altar or Lassar teleport tablet or spell\"],\"c\":1},{\"n\":\"Invasion\",\"st\":[{\"t\":\"Talk to Captain Rovin upstairs in the north west of Varrock Castle.\"},{\"t\":\"Talk to Reldo in the Varrock Castle library.\"},{\"t\":\"Search the scrolls in the north-east of the library.\"},{\"t\":\"Read the list of elders.\",\"i\":[\"List of elders\"]},{\"t\":\"Read the Varrock Census.\"},{\"t\":\"Talk to King Roald.\",\"i\":[\"Shield of arrav\"]},{\"t\":\"Talk to Aeonisig Raispher next to King Roald.\",\"i\":[\"Shield of arrav\"]},{\"t\":\"Talk to Sir Prysin in the south west corner of Varrock Castle.\",\"i\":[\"Shield of arrav\"]},{\"t\":\"Talk to Romeo in Varrock Square.\",\"i\":[\"Shield of arrav\"]},{\"t\":\"Talk to Horvik north-east of Varrock Square.\",\"s\":[\"I need your help with a shield.\"],\"i\":[\"Shield of arrav\"]},{\"t\":\"Talk to Curator Haig in the Varrock Museum.\",\"s\":[\"I need your help with the zombie invasion.\"],\"i\":[\"Shield of arrav\"]},{\"t\":\"Talk to Dimintheis in the south-east of Varrock.\",\"s\":[\"Other\",\"I need your help with the zombie invasion.\"],\"i\":[\"Shield of arrav\"]},{\"t\":\"Talk to Captain Rovin upstairs in the north west of Varrock Castle to finish the quest.\"}],\"i\":[\"Varrock teleport\"]}]}"
        "Demon Slayer" -> "{\"n\":\"Demon Slayer\",\"items\":[\"Coin\",\"Bones (UNNOTED) (25)\",\"Bucket of water\",\"Armour\",\"Food\"],\"rec\":[\"Varrock teleport\",\"Teleport to the Wizards' Tower\"],\"enemies\":[\"Delrith (level 27)\"],\"rewards\":[\"3 Quest points\",\"Silverlight\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Talk to Aris in her tent in Varrock Square.\",\"s\":[\"The Demon Slayer Quest\",\"Yes.\",\"Ok, here you go.\",\"Okay, where is he? I'll kill him for you!\",\"So how did Wally kill Delrith?\"],\"i\":[\"Coin\"]},{\"t\":\"Talk to Sir Prysin in the south west corner of Varrock Castle.\",\"s\":[\"Aris said I should come and talk to you.\",\"I need to find Silverlight.\",\"He's back and unfortunately I've got to deal with him.\",\"So give me the keys!\",\"Can you give me your key?\"]}],\"i\":[\"Coin\",\"Bucket of water\"]},{\"n\":\"Get Rovin's key\",\"st\":[{\"t\":\"Talk to Captain Rovin upstairs in the north west of Varrock Castle.\",\"s\":[\"Yes I know, but this is important.\",\"There's a demon who wants to invade this city.\",\"Yes, very.\",\"It's not them who are going to fight the demon, it's me.\",\"Sir Prysin said you would give me the key.\",\"Why did he give you one of the keys then?\"]}],\"i\":[\"Bucket of water\"]},{\"n\":\"Get Prysin's key\",\"st\":[{\"t\":\"Use the bucket of water on the drain outside the kitchen.\",\"i\":[\"Bucket of water\"]},{\"t\":\"Go down into Varrock Sewer via the Manhole south east of Varrock Castle.\"},{\"t\":\"Pick up the Rusty Key north of the Sewer entrance.\"}]},{\"n\":\"Get Traiborn's key\",\"st\":[{\"t\":\"Bring Wizard Traiborn 25 bones in the Wizards' Tower. You don't need to bring them all at once.\",\"s\":[\"Talk about Demon Slayer.\",\"I need to get a key given to you by Sir Prysin.\",\"Well, have you got any keys knocking around?\",\"I'll get the bones for you.\"],\"i\":[\"Bones (UNNOTED) (25)\"]}],\"i\":[\"Bones (UNNOTED) (25)\"]},{\"n\":\"Kill Delrith\",\"st\":[{\"t\":\"Return to Sir Prysin in the south west of Varrock Castle.\",\"i\":[\"Silverlight key\"]},{\"t\":\"Kill Delrith (level 27) using Silverlight at the dark wizards south of Varrock. Once defeated, you'll need to say the magic words to banish him.\",\"i\":[\"Silverlight\",\"Armour\"]}],\"i\":[\"Silverlight key\",\"Armour\",\"Food\"],\"c\":1,\"e\":[\"Delrith (level 27)\"]}]}"
        "Desert Treasure I" -> "{\"n\":\"Desert Treasure I\",\"items\":[\"Coins (650)\",\"Magic logs (can be noted) (12)\",\"Steel bar (can be noted) (6)\",\"Molten glass (can be noted) (6)\",\"Ashes\",\"Charcoal\",\"Blood rune\",\"Bones\",\"Silver bar\",\"Garlic powder\",\"Spice\",\"Cake\",\"Spiked boots\",\"Climbing boots\",\"Facemask (or other face covering)\",\"Tinderbox\",\"Ice gloves/smiths gloves(i)\",\"Many lockpicks\"],\"rec\":[\"Decent combat gear\",\"Food\",\"Prayer potions\",\"Energy/Stamina potions\",\"Restore potions\",\"Digsite pendant/teleport\",\"Teleport to Bedabin Camp. Fairy Ring (BIQ), Camulet (2)\",\"Teleport to Pollnivneach. Pollnivneach house teleport\",\"Teleport to the Waterfall. Skills necklace (Fishing Guild [1]), Games necklace (Barbarian Outpost [2]) (2)\",\"Teleport to Bandit Camp (desert). Fairy Ring (BIQ), Camulet (2)\",\"Teleport to Canifis. Fairy Ring (CKS), Fenkenstrain's teleport (3)\",\"Teleport to Draynor Village. Amulet of Glory (Draynor Village [3]), Draynor Manor Teleport\",\"Teleport to Trollheim. Trollheim teleport, Ghommal's hilt (any tier)\",\"Teleport to Jaldraocht Pyramid. Camulet, Pollnivneach house teleport\"],\"enemies\":[\"Dessous (level 139)\",\"Kamil (level 154)\",\"Fareed (level 167)\",\"Damis (level 103, then level 174 in second phase)\",\"5 ice trolls (level 120-124)\"],\"rewards\":[\"3 Quest points\",\"20,000 Magic XP\",\"Ring of Visibility\",\"Ability to use Ancient Magicks.\",\"Ability to purchase an Ancient Staff.\",\"Access to Smoke Dungeon.\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Talk to the Archaeologist in the Bedabin Camp. You can use the flying carpet service from the Shantay Pass to get here.\",\"s\":[\"Do you have any quests?\",\"Yes.\",\"Yes, I'll help you.\"]},{\"t\":\"Talk to the Terry Balando in the Exam Centre found south-east of Varrock, directly south of the Digsite.\",\"s\":[\"Ask about the Desert Treasure quest.\"],\"i\":[\"Etchings\"]},{\"t\":\"Talk to the Terry Balando again.\",\"s\":[\"Ask about the Desert Treasure quest.\"]},{\"t\":\"Bring the translation to the Archaeologist in the Bedabin Camp.\",\"s\":[\"Don't read book\"],\"i\":[\"Translation\"]},{\"t\":\"Talk to the Archaeologist again.\",\"s\":[\"Help him\"]},{\"t\":\"Unequip any god-related items you have on, or else you'll be attacked by bandits. Go buy a drink from the pub in the Bandit Camp, then talk to the Bartender again.\",\"s\":[\"Buy a drink\",\"Buy a beer\"],\"i\":[\"Coins (650)\"]},{\"t\":\"Talk to the bartender in the Bandit Camp again.\",\"s\":[\"I heard about four diamonds...\"]},{\"t\":\"Talk to Eblis in the east of the Bandit Camp.\",\"s\":[\"Tell me of The four diamonds of Azzanadra\",\"Yes\"]}],\"i\":[\"Coins (650)\",\"Ashes\",\"Blood rune\",\"Bones\",\"Charcoal\",\"Molten glass (can be noted) (6)\",\"Magic logs (can be noted) (12)\",\"Steel bar (can be noted) (6)\"],\"tr\":[\"Digsite pendant/teleport\",\"Teleport to Bedabin Camp. Fairy Ring (BIQ), Camulet\"]},{\"n\":\"Smoke diamond\",\"st\":[{\"t\":\"Enter the smokey well west of Pollnivneach. You'll need to run a lot, so bring energy/stamina potions if you can.\",\"i\":[\"Tinderbox\",\"Facemask (or other face covering)\",\"Ice gloves/smiths gloves(i)\",\"Water spells or melee gear\"]},{\"t\":\"Light all the torches in the corners of the dungeon. This is timed, so try to do it as fast as possible. Start with the north east torch, and work your way to the south west.\",\"i\":[\"Tinderbox\"]},{\"t\":\"Open the chest in the middle of the dungeon.\"},{\"t\":\"Use the warm key on the gate in the east of the dungeon. Be prepared to fight Fareed. If you aren't wearing ice gloves he'll unequip your weapon.\",\"i\":[\"Warm key\",\"Ice gloves/smiths gloves(i)\",\"Water spells or melee gear\"]},{\"t\":\"Kill Fareed. Either use melee with ice gloves, or water spells.\",\"i\":[\"Ice gloves/smiths gloves(i)\",\"Water spells or melee gear\"]}],\"i\":[\"Facemask (or other face covering)\",\"Tinderbox\",\"Ice gloves/smiths g