        "Desert Treasure II - The Fallen Empire" -> "{\"n\":\"Desert Treasure II - The Fallen Empire\",\"items\":[\"Combat gear\",\"Runes for shadow, smoke, blood, and ice burst\",\"Facemask\",\"Ring of visibility\"],\"rec\":[\"Nardah teleport, or Fairy Ring to DLQ\",\"Full waterskin, or any protection from the desert\",\"Senntisten teleport\",\"Stamina potions (4)\",\"Freezing spells STRONGLY recommended + reasonable mage accuracy\",\"Xeric's talisman\",\"Teleport to Temple of the Eye via minigame teleport or Amulet of the Eye\",\"Icy basalt\",\"Mind altar or lassar teleport\"],\"enemies\":[\"Ancient Guardian (level 153)\",\"Vardorvis (level 553)\",\"Kasonde (level 193)\",\"A number of lesser demons, black demons, and abyssal creatures\",\"The Leviathan (level 577)\",\"Jhallan (level 491)\",\"Duke Sucellus (level 519)\",\"The Whisperer (level 568)\",\"Mysterious Figure (level 271)\",\"The Forsaken Assassin (level 252)\",\"Ketla the Unworthy (level 236)\",\"Kasonde the Craven (level 221)\",\"Persten the Deceitful (level 264)\"],\"rewards\":[\"5 Quest points\",\"Ring of Shadows\",\"3 x Ancient Lamp (100k exp in a combat skill)\",\"Ability to use Ancient Rings.\",\"Access to four new bosses\"],\"sec\":[{\"n\":\"The Vault\",\"st\":[{\"t\":\"Attempt to enter the Vault door north-east of Nardah.\",\"s\":[\"Yes.\"]},{\"t\":\"Talk to Asgarnia Smith inside the Vault.\"},{\"t\":\"Inspect the plaque.\"},{\"t\":\"Inspect the north-east statue.\"},{\"t\":\"Inspect the north-west statue.\"},{\"t\":\"Inspect the south-west statue.\"},{\"t\":\"Inspect the south-east statue.\"}],\"tr\":[\"Nardah teleport, or Fairy Ring to DLQ\",\"Senntisten teleport\"],\"r\":[\"Full waterskin, or any protection from the desert\"]},{\"n\":\"Learning of the Ancients\",\"st\":[{\"t\":\"Talk to the Terry Balando in the Exam Centre found south-east of Varrock, directly south of the Digsite.\"},{\"t\":\"Enter the winch on the east side of the Digsite.\",\"i\":[\"Combat gear\"]},{\"t\":\"Talk to Dr Banikan.\"},{\"t\":\"Get a pickaxe from the crate in the north-east of the cavern.\"},{\"t\":\"Mine the rocks in the south-east of the cavern.\",\"i\":[\"Any pickaxe\"]},{\"t\":\"Enter the hole in the south-east of the cavern, ready for a fight.\",\"i\":[\"Combat gear\"]},{\"t\":\"Kill the Ancient Guardian. The shield needs to be broken to hurt it, and it will regenerate the shield unless you are using melee attacks with a pickaxe in the inventory.\",\"i\":[\"Combat gear\"]},{\"t\":\"Talk to Dr Banikan in the room you defeated the Ancient Guardian.\"},{\"t\":\"Inspect the golem to the north.\"},{\"t\":\"Inspect the altar to the north-west.\"},{\"t\":\"Cast blood burst or higher on the blood totem.\",\"i\":[\"Blood burst runes\"]},{\"t\":\"Cast shadow burst or higher on the shadow totem.\",\"i\":[\"Shadow burst runes\"]},{\"t\":\"Cast smoke burst or higher on the smoke totem.\",\"i\":[\"Smoke burst runes\"]},{\"t\":\"Cast ice burst or higher on the smoke totem.\",\"i\":[\"Ice burst runes\"]},{\"t\":\"Search the crate in the room with the golem.\"},{\"t\":\"Imbue the cells at the altar.\",\"i\":[\"Uncharged cells\"]},{\"t\":\"Inspect the golem again.\"},{\"t\":\"Operate the golem, and search for the terms : \\\"Vardorvis\\\", \\\"Perseriya\\\", \\\"Sucellus\\\", and \\\"Whisperer\\\". Make sure to talk to Banikan about each one!\",\"s\":[\"Yes.\"]},{\"t\":\"Talk to Banikan about what to do next.\"},{\"t\":\"Try operating the golem again until Banikan leaves, and the golem lets you know the last search term.\"}],\"i\":[\"Combat gear\",\"Runes for shadow, smoke, blood, and ice burst\"],\"tr\":[\"Senntisten teleport\"],\"c\":1,\"e\":[\"Ancient Guardian (level 153)\",\"Vardorvis (level 553)\"]},{\"n\":\"Vardorvis\",\"st\":[{\"t\":\"Talk to Elissa in the north-east of the Digsite on the surface.\",\"s\":[\"I hear you visited Lovakengj recently.\"]}],\"i\":[\"Combat gear\"],\"r\":[\"Xeric's talisman\",\"Freezing spells STRONGLY recommended + reasonable mage accuracy\"],\"c\":1},{\"n\":\"Secrets\",\"st\":[{\"t\":\"Return to the Vault door north-east of Nardah with the final medallion. Come equipped with two combat styles.\",\"i\":[\"Whisperer's medallion\",\"Vardorvis' medallion\",\"Sucellus' medallion\",\"Perseriya's medallion\",\"Melee combat gear\",\"Ranged combat gear\",\"Food\",\"Prayer potions\"]},{\"t\":\"Search the bed for a hairclip.\"},{\"t\":\"Escape the cell. Guess the correct code to open, with correct numbers in the correct place being marked in green, and correct numbers in the wrong places being marked with blue.\",\"i\":[\"Hair clip\"]},{\"t\":\"Retrieve your items from the chest in the north-east room.\"},{\"t\":\"Inspect the altar in the north-west room.\"},{\"t\":\"Fight the Mysterious Figure. When frozen, spam-click to move away to avoid taking damage. Use Protect from Magic for the entire fight.\"},{\"t\":\"Pick up the medallion.\",\"i\":[\"Medallion\"]},{\"t\":\"Enter to the Vault door north-east of Nardah with the final medallion, ready to fight.\",\"i\":[\"Whisperer's medallion\",\"Vardorvis' medallion\",\"Sucellus' medallion\",\"Perseriya's medallion\",\"Combat gear\",\"Food\",\"Prayer potions\"]},{\"t\":\"Go deeper into the Vault down the steps.\",\"i\":[\"Combat gear\"]},{\"t\":\"Watch the cutscene, then defeat the wights.\"},{\"t\":\"Defeat The Forsaken Assassin. Protect from ranged, and lure him into the white smoke. He will sometimes throw 3 vials, avoid them, as they will poison you and deal large damage.\"},{\"t\":\"Defeat Ketla the Unworthy. Protect from ranged. She will spawn shadow clones, which you should hide behind whenever she has a skull above her.\"},{\"t\":\"Defeat Kasonde the Craven. Protect from ranged if at a distance or melee if up close. The fight is similar to earlier in the quest.\"},{\"t\":\"Defeat Persten the Deceitful. Protect from Magic. Avoid the lighting strikes by moving. Destroy any portals she spawns, or run from corner to corner avoiding the leeches that spawn from the portal.\"},{\"t\":\"Talk to Azzanadra.\"}],\"i\":[\"Melee combat gear\",\"Ranged combat gear\",\"Food\",\"Prayer potions\"],\"tr\":[\"Nardah teleport, or Fairy Ring to DLQ\"],\"r\":[\"Stamina potions (4)\"],\"c\":1,\"e\":[\"Kasonde (level 193)\",\"Mysterious Figure (level 271)\",\"The Forsaken Assassin (level 252)\",\"Ketla the Unworthy (level 236)\",\"Kasonde the Craven (level 221)\",\"Persten the Deceitful (level 264)\"]}]}"
        "Devious Minds" -> "{\"n\":\"Devious Minds\",\"items\":[\"Mithril 2h Sword\",\"Bow String\",\"Large/Colossal Pouch (non-degraded)\"],\"rec\":[\"Falador Teleports (2)\",\"Lumberyard Teleports (3)\",\"Amulet of Glory (Teleports to Port Sarim and Edgeville)\"],\"enemies\":[\"Survive against Abyssal Creatures in multicombat in the Abyss\"],\"rewards\":[\"1 Quest point\",\"5,000 Fletching XP\",\"5,000 Runecraft XP\",\"6,500 Smithing XP\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Start by talking to the Monk outside the Paterdomus temple, east of Varrock.\",\"s\":[\"Sure thing, what do you need?\"]}]},{\"n\":\"Making the Bow-sword\",\"st\":[{\"t\":\"Use the Mithril 2H sword on Doric's Whetstone. (Doric is located north of Falador).\",\"i\":[\"Mithril 2h Sword\"]},{\"t\":\"Use the bow-string on the Slender blade to make the Bow-sword.\",\"i\":[\"Bow String\",\"Slender Blade\"]}],\"i\":[\"Mithril 2h Sword\",\"Bow String\"]},{\"n\":\"A Gift for Entrana\",\"st\":[{\"t\":\"Return to the monk near the Paterdomus temple with the bow-sword.\",\"s\":[\"Yep, got it right here for you.\"],\"i\":[\"Bow Sword\"]},{\"t\":\"Use the Orb on the Large/Colossal Pouch. You will also be going to Entrana via the Abyss, so you must bank all combat gear.\",\"i\":[\"Orb\",\"Large/Colossal Pouch (non-degraded)\"]},{\"t\":\"Teleport with the Mage of Zamorak IN THE WILDERNESS (other players can attack you here) to the Abyss. You will be attacked by monsters upon entering, and your prayer drained to 0!\",\"i\":[\"Illuminated Pouch\",\"Banked all equipment and weapons\"]},{\"t\":\"Enter the central area through a gap/passage/eyes. Enter the Law Rift.\",\"i\":[\"Illuminated Pouch\",\"Banked all equipment and weapons\"]},{\"t\":\"Enter the portal to leave the Law Altar.\",\"i\":[\"Illuminated Pouch\",\"Banked all equipment and weapons\"]},{\"t\":\"Use the illuminated pouch on the Altar in the Entrana Church.\",\"i\":[\"Illuminated Pouch\"]}],\"i\":[\"Large/Colossal Pouch (non-degraded)\"]},{\"n\":\"Surprise!\",\"st\":[{\"t\":\"Go back to the monk near Paterdomus temple and search the dead monk's body.\"},{\"t\":\"Talk to the High Priest in the Entrana Church (Rat Pits Port Sarim Minigame teleport is the closest teleport).\"},{\"t\":\"Talk to Sir Tiffy Cashien in Falador park to complete the quest.\",\"s\":[\"Devious Minds.\"]}]}]}"
        "Doric's Quest" -> "{\"n\":\"Doric's Quest\",\"items\":[\"Clay (UNNOTED) (6)\",\"Copper ore (UNNOTED) (4)\",\"Iron ore (UNNOTED) (2)\"],\"rec\":[],\"enemies\":[],\"rewards\":[\"1 Quest point\",\"1,300 Mining XP\",\"180 x Coins\",\"Use of Doric's Anvil\"],\"sec\":[{\"n\":\"Help Doric\",\"st\":[{\"t\":\"Bring Doric north of Falador all the required items. You can mine them all in the Dwarven Mines, or buy them from the Grand Exchange.\",\"s\":[\"I wanted to use your anvils.\",\"Yes.\",\"Yes, I will get you the materials.\"],\"i\":[\"Clay (UNNOTED) (6)\",\"Copper ore (UNNOTED) (4)\",\"Iron ore (UNNOTED) (2)\"]}],\"i\":[\"Clay (UNNOTED) (6)\",\"Copper ore (UNNOTED) (4)\",\"Iron ore (UNNOTED) (2)\"],\"c\":0}]}"
        "Dragon Slayer I" -> "{\"n\":\"Dragon Slayer I\",\"items\":[\"Unfired bowl\",\"Wizard's mind bomb\",\"Lobster pot\",\"Silk\",\"Either 33 Magic for Telegrab and a ranged/mage weapon, or 10,000 coins\",\"Hammer\",\"Planks (3)\",\"Steel nails (90)\",\"Coins (2000)\",\"Combat equipment\"],\"rec\":[\"The Chronicle for teleports to Champions' Guild\",\"Teleports to Port Sarim/Rimmington/Draynor Village area\",\"Teleports to Edgeville for getting to Oziach\",\"Rings of Recoil for Elvarg\",\"Antifire potion for Elvarg\"],\"enemies\":[\"Zombie rats (level 3)\",\"Ghosts (level 19)\",\"Skeletons (level 22)\",\"Zombies (level 24)\",\"Melzar the Mad (level 43)\",\"Lesser demon (level 82) (safespottable)\",\"Elvarg (level 83)\"],\"rewards\":[\"2 Quest points\",\"18,650 Strength XP\",\"18,650 Defence XP\",\"The ability to equip a Green D'hide Body, Rune Platebody & Dragon Platebody\",\"Access to Crandor\",\"Access to the Corsair Cove Resource Area.\",\"Ability to receive dragons as a slayer task.\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Talk to the Guildmaster in the Champions' Guild, south of Varrock.\",\"s\":[\"Can I have a quest?\"]},{\"t\":\"Talk to Oziach in his house in north western Edgeville.\",\"s\":[\"Can you sell me a rune platebody?\",\"The Guildmaster of the Champions' Guild told me.\",\"I thought you were going to give me a quest.\",\"A dragon, that sounds like fun.\"]},{\"t\":\"Return to the Guildmaster and ask him all the available questions.\",\"s\":[\"About my quest to kill the dragon...\",\"I talked to Oziach...\",\"Where can I find the right ship?\"]}]},{\"n\":\"Thalzar's map piece\",\"st\":[{\"t\":\"Talk to the Oracle on top of Ice Mountain.\",\"s\":[\"I seek a piece of the map to the island of Crandor.\"],\"i\":[\"Silk\",\"Lobster pot\",\"Wizard's mind bomb\",\"Unfired bowl\"]},{\"t\":\"Go down the ladder in the dwarven camp to the south into the Dwarven Mines.\",\"i\":[\"Silk\",\"Lobster pot\",\"Wizard's mind bomb\",\"Unfired bowl\"]},{\"t\":\"Go to the north east of the Dwarven Mines and use the silk on the magic door.\",\"i\":[\"Silk\",\"Lobster pot\",\"Wizard's mind bomb\",\"Unfired bowl\"]},{\"t\":\"Go to the north east of the Dwarven Mines and use the lobster pot on the magic door.\",\"i\":[\"Lobster pot\",\"Wizard's mind bomb\",\"Unfired bowl\"]},{\"t\":\"Go to the north east of the Dwarven Mines and use the unfired bowl on the magic door.\",\"i\":[\"Wizard's mind bomb\",\"Unfired bowl\"]},{\"t\":\"Go to the north east of the Dwarven Mines and use the wizard's mind bomb on the magic door (BE CAREFUL NOT TO DRINK IT).\",\"i\":[\"Lobster pot\",\"Wizard's mind bomb\",\"Unfired bowl\"]},{\"t\":\"Search the chest for Thalzar's map piece.\"}],\"i\":[\"Silk\",\"Lobster pot\",\"Unfired bowl\",\"Wizard's mind bomb\"]},{\"n\":\"Lozar's map piece\",\"st\":[{\"t\":\"Go to Port Sarim Jail. You can either pay Wormbrain there 10,000 coins for Lozar's map piece, or kill him with ranged/mage and telegrab it with level 33 magic.\",\"s\":[\"I believe you've got a piece of a map that I need.\",\"I suppose I could pay you for the map piece...\",\"Alright then, 10,000 it is.\"],\"i\":[\"Either 33 Magic for Telegrab and a ranged/mage weapon, or 10,000 coins\"]}],\"i\":[\"Either 33 Magic for Telegrab and a ranged/mage weapon, or 10,000 coins\"],\"c\":1},{\"n\":\"Melzar's map piece\",\"st\":[{\"t\":\"Enter Melzar's Maze north of Rimmington. Be prepared to fight multiple monsters up to a level 82 lesser demon.\",\"s\":[\"About my quest to kill the dragon...\",\"I talked to Oziach...\",\"How can I find the route to Crandor?\",\"Where is Melzar's map piece?\"],\"i\":[\"Maze key\"]},{\"t\":\"Kill the marked zombie rat for a key.\"},{\"t\":\"Go through the north west red door\",\"i\":[\"Key\"]},{\"t\":\"Climb up the ladder.\"},{\"t\":\"Kill the marked ghost for a key.\",\"i\":[\"Key\"]},{\"t\":\"Go through second yellow door from the north.\",\"i\":[\"Key\"]},{\"t\":\"Kill the marked skeleton for a key\",\"i\":[\"Key\"]},{\"t\":\"Go through south west yellow door.\",\"i\":[\"Key\"]},{\"t\":\"Climb down the ladder.\"},{\"t\":\"Climb down again.\"},{\"t\":\"Climb down the ladder into the basement.\"},{\"t\":\"Kill the marked zombie for a key\",\"i\":[\"Key\"]},{\"t\":\"Go through the blue door in the north west corner.\"},{\"t\":\"Kill Melzar the Mad for a magenta key.\",\"i\":[\"Key\"]},{\"t\":\"Go through the magenta door.\"},{\"t\":\"Kill the lesser demon. You can safe spot it from the spot east of the magenta door.\",\"i\":[\"Key\"]},{\"t\":\"Go through the green door.\",\"i\":[\"Key\"]},{\"t\":\"Open the chest and get Melzar's map part.\"}],\"i\":[\"Maze key\",\"Combat equipment\",\"Food\"],\"c\":1,\"e\":[\"Zombie rats (level 3)\",\"Ghosts (level 19)\",\"Skeletons (level 22)\",\"Zombies (level 24)\",\"Melzar the Mad (level 43)\",\"Lesser demon (level 82) (safespottable)\"]},{\"n\":\"Get an anti-dragon shield\",\"st\":[{\"t\":\"Talk to Duke Horacio on the first floor of Lumbridge castle for the anti-dragon shield if you don't have one.\",\"s\":[\"I seek a shield that will protect me from dragonbreath.\",\"Elvarg, the dragon of Crandor island!\",\"Yes\",\"So, are you going to give me the shield or not?\"]}]},{\"n\":\"Get a boat\",\"st\":[{\"t\":\"Talk to Klarense on the south Port Sarim docks and buy his boat.\",\"s\":[\"I'd like to buy her.\",\"Yep, sounds good.\"],\"i\":[\"Planks (3)\",\"Steel nails (90)\",\"Hammer\",\"Coins (2000)\"]},{\"t\":\"Board your new ship.\",\"i\":[\"Steel nails (90)\",\"Planks (3)\",\"Hammer\"]},{\"t\":\"Go down into the ship's hull.\"},{\"t\":\"Repair the hole in the hull 3 times.\",\"i\":[\"Steel nails (90)\",\"Planks (3)\",\"Hammer\"]}],\"i\":[\"Hammer\",\"Planks (3)\",\"Steel nails (90)\",\"Coins (2000)\"]},{\"n\":\"Get a captain ready\",\"st\":[{\"t\":\"Use the three map parts together to repair the map.\",\"i\":[\"Map part\"]},{\"t\":\"Bring Ned your map and ask him to be your captain.\",\"s\":[\"You're a sailor? Could you take me to Crandor?\"],\"i\":[\"Crandor map\"]}]},{\"n\":\"Slaying Elvarg\",\"st\":[{\"t\":\"Prepare to fight Elvarg (level 83). When you're ready, go board your boat in Port Sarim and talk to Ned.\",\"i\":[\"Anti-dragon shield\",\"Combat equipment\"]},{\"t\":\"Go to the center of the island and go down the hole.\"},{\"t\":\"Go all the way south and through the wall to unlock the shortcut to return here if needed.\"},{\"t\":\"Return back through the shortcut.\"},{\"t\":\"Enter Elvarg's area and kill her.\",\"i\":[\"Anti-dragon shield\"]},{\"t\":\"Kill Elvarg.\"}],\"i\":[\"Combat equipment\",\"Anti-dragon shield\",\"Food\"],\"c\":1,\"e\":[\"Elvarg (level 83)\"]},{\"n\":\"Finish the quest\",\"st\":[{\"t\":\"Talk to Oziach in his house in north western Edgeville to finish the quest.\"}]}]}"
        "Dragon Slayer II" -> "{\"n\":\"Dragon Slayer II\",\"items\":[\"Any pickaxe\",\"Any axe\",\"Oak planks (8)\",\"Swamp paste (10)\",\"Nails, bring more in case some break (12)\",\"Hammer\",\"Any machete\",\"Saw\",\"Catspeak amulet (e)\",\"A light source\",\"Goutweed\",\"Astral rune\",\"Seal of passage\",\"Tinderbox\",\"Pestle and mortar\",\"Dragonstone\",\"Molten glass (2)\",\"Glassblowing pipe\",\"Ghostspeak amulet\",\"Chisel\",\"Spade\",\"3 casts of Fire Wave or Fire Surge\",\"Antifire shield\"],\"rec\":[\"Ardougne teleport\",\"Varrock teleport\",\"Falador teleport\",\"Port Phasmatys teleport\",\"Karamja teleport\",\"Rellekka teleport\"],\"enemies\":[\"Spawn (level 100)\",\"Robert the Strong (level 194)\",\"Vorkath (level 392)\",\"Numerous chromatic and metal dragons\",\"Galvek (level 608)\"],\"rewards\":[\"5 Quest points\",\"80,000 Smithing XP\",\"60,000 Mining XP\",\"50,000 Agility XP\",\"50,000 Thieving XP\",\"4 x 25,000 Experience Tome (Any Combat Skill).\",\"A Locator Orb\",\"Access to the Myths Guild.\",\"Ability to make Super Antifire Potions\",\"Access to the Fountain of Uhld.\",\"Access to the Wrath Altar.\",\"Ability to purchase the Mythical Cape\",\"Access to Adamant and Rune Dragons\",\"Access to Vorkath\",\"Ability to re-forge the dragon platebody and kiteshield.\",\"Ability to craft Ferocious Gloves\",\"Ability to further upgrade your Ava's device.\",\"Ability to teleport to Lithkren with the Digsite Pendant.\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Talk to Alec Kincade outside the Myths' Guild.\",\"s\":[\"How can I gain access to the guild?\",\"Yes.\"]},{\"t\":\"Talk to Dallas Jones in the Pub on Musa Point.\",\"s\":[\"Yes I know it well.\"],\"i\":[\"Any pickaxe\",\"Combat gear, food and potions\"]},{\"t\":\"Talk to Dallas in Elvarg's Lair.\"},{\"t\":\"Use a pickaxe on the blockage in the north east of Elvarg's Lair.\",\"i\":[\"Any pickaxe\"]},{\"t\":\"Enter the passage in the north east of Elvarg's Lair.\",\"i\":[\"Combat gear, food and potions\"]},{\"t\":\"Inspect the mural.\"},{\"t\":\"Kill the spawn.\",\"i\":[\"Combat gear, food and potions\"]},{\"t\":\"Investigate the mural again.\"},{\"t\":\"Talk to Dallas about the mural.\"}],\"i\":[\"Any pickaxe\",\"Combat gear, food and potions\"],\"c\":1,\"e\":[\"Spawn (level 100)\"]},{\"n\":\"Investigating Fossil Island\",\"st\":[{\"t\":\"Travel to the House on the Hill on Fossil Island. The fastest way here is with the digsite pendant.\"},{\"t\":\"Talk to Dallas.\",\"s\":[\"Ask about the island.\",\"So how do we know which island to go to?\"]},{\"t\":\"Search the stone chest in the north of the room. Whilst finding map pieces you can talk to Dallas to give him your current pieces.\",\"s\":[\"Let's talk about the investigation.\"]},{\"t\":\"Climb the ladder to go upstairs in the house. Talk to Dallas if you want to give him your current map pieces.\",\"s\":[\"Let's talk about the investigation.\"]},{\"t\":\"Search the stone chest in the north of the house's top floor.\"},{\"t\":\"Leave the house down the stairs to the west.\"},{\"t\":\"Search the fungi north of the stairs.\"},{\"t\":\"Search the hook briar south of the house.\"},{\"t\":\"Search the mushtree east of the house.\"},{\"t\":\"Return to Dallas with the map pieces.\"},{\"t\":\"Click on the incomplete map for a puzzle to solve.\"},{\"t\":\"Talk to Dallas after solving the map.\"}]},{\"n\":\"Investigating Lithkren\",\"st\":[{\"t\":\"Talk to Jardric in the museum camp.\"},{\"t\":\"Build a rowing boat on the west coast of Fossil Island.\",\"i\":[\"Hammer\",\"Saw\",\"Oak planks (8)\",\"Swamp paste (10)\",\"Nails, bring more in case some break (12)\"]},{\"t\":\"Talk to Dallas near the boat.\",\"s\":[\"I'm ready.\"]},{\"t\":\"Climb up the stairs to the west.\"},{\"t\":\"Climb down the trapdoor to the south.\"},{\"t\":\"Climb down the staircase to the north.\"},{\"t\":\"Talk to Dallas in the far north of the room.\"},{\"t\":\"Search the skeleton east of Dallas.\"},{\"t\":\"Read Aivas' Diary.\",\"i\":[\"Aivas' diary\"]},{\"t\":\"Talk to Dallas again.\"}],\"i\":[\"Oak planks (8)\",\"Swamp paste (10)\",\"Nails, bring more in case some break (12)\",\"Hammer\",\"Saw\"]},{\"n\":\"Contacting Bob\",\"st\":[{\"t\":\"Use a catspeak amulet (e) to locate Bob the Cat and talk to him. He's often in Catherby Archery Shop or at the Varrock Anvil.\",\"i\":[\"Catspeak amulet (e)\"]},{\"t\":\"Talk to the Sphinx in Sophanem.\",\"s\":[\"Ask the Sphinx for help with Bob's memories.\"]}],\"i\":[\"Catspeak amulet (e)\"]},{\"n\":\"Entering a dream\",\"st\":[{\"t\":\"Talk to the Oneiromancer in the south east of Lunar Isle.\",\"s\":[\"Bob's memories.\",\"No thanks.\"],\"i\":[\"Seal of passage\"]},{\"t\":\"Fill the vial with water.\",\"i\":[\"Dream vial (empty)\"]},{\"t\":\"Add a goutweed to the dream vial.\",\"i\":[\"Dream vial (water)\",\"Goutweed\"]},{\"t\":\"Use a hammer on an astral rune.\",\"i\":[\"Hammer\",\"Astral rune\"]},{\"t\":\"Use a pestle and mortar on the astral rune shards.\",\"i\":[\"Pestle and mortar\",\"Astral rune shards\"]},{\"t\":\"Add the ground astral rune to the dream vial.\",\"i\":[\"Ground astral rune\",\"Dream vial (herb)\"]},{\"t\":\"Equip your combat equipment, food, and light the Brazier in the west of Lunar Isle's town. Be prepared for a fight. You will need melee gear, preferably a crush weapon, to fight.\",\"i\":[\"Seal of passage\",\"Tinderbox\",\"Dream potion\",\"Combat gear, food and potions\"]},{\"t\":\"Use the dream potion on the brazier.\",\"s\":[\"I'm ready.\",\"Yes.\"],\"i\":[\"Seal of passage\",\"Dream potion\",\"Combat gear, food and potions\"]},{\"t\":\"Talk to Bob in the dream.\"},{\"t\":\"When you're ready, fight Robert.\"},{\"t\":\"Talk to Bob next to the brazier.\"}],\"i\":[\"Seal of passage\",\"Goutweed\",\"Astral rune\",\"Hammer\",\"Pestle and mortar\",\"Tinderbox\",\"Combat gear, food and potions\"],\"c\":1},{\"n\":\"Karamja key piece\",\"st\":[{\"t\":\"Go down the staircase in the south east of the Kharazi Jungle. MAKE SURE TO HAVE AUTO-RETALIATE OFF BEFORE ENTERING.\"},{\"t\":\"Get to the centre of the maze.\"}],\"i\":[\"Any machete\",\"Any axe\",\"Food\"]},{\"n\":\"Varrock key piece\",\"st\":[{\"t\":\"Talk to Reldo in the Varrock Castle Library.\",\"s\":[\"I'm looking for information on a Fourth Age hero.\",\"Ask about Tristan.\"]},{\"t\":\"Search the bookcases for the census\"},{\"t\":\"Talk to Reldo again.\",\"s\":[\"About Tristan Corvo...\",\"Ask about Tristan.\"],\"i\":[\"Varrock census records\"]},{\"t\":\"Talk to Sarah in Port Phasmatys.\",\"i\":[\"Ghostspeak amulet\"]},{\"t\":\"Talk to Ava in Draynor Manor.\",\"s\":[\"I need your help with a key piece.\"],\"i\":[\"Dragonstone\",\"Molten glass (2)\",\"Glassblowing pipe\"]},{\"t\":\"Use the glassblowing pipe on a dragonstone.\",\"i\":[\"Glassblowing pipe\",\"Dragonstone\",\"Molten glass (2)\"]},{\"t\":\"Talk to Ava again.\",\"s\":[\"I need your help with a key piece.\"],\"i\":[\"Inert locator orb\"]},{\"t\":\"Use the locator orb in Mort Myre to locate the dig spot. Once you find the spot, dig there.\",\"i\":[\"Locator orb\",\"Spade\"]}],\"i\":[\"Ghostspeak amulet\",\"Dragonstone\",\"Molten glass (2)\",\"Glassblowing pipe\",\"Spade\"],\"tr\":[\"Port Phasmatys teleport\"]},{\"n\":\"Kourend key piece\",\"st\":[{\"t\":\"Talk to Amelia south west of the Shayzien Archery Store.\"},{\"t\":\"Enter the Crypt west of Amelia.\",\"i\":[\"A light source\"]},{\"t\":\"Climb down to the bottom of the crypts.\"},{\"t\":\"Inspect the tomb in the south room.\"},{\"t\":\"Solve the crypt puzzle.\"},{\"t\":\"Inspect the tomb for the key.\"}],\"i\":[\"Combat gear, food and potions\",\"A light source\"],\"c\":1},{\"n\":\"Fremennik key piece\",\"st\":[{\"t\":\"Talk to Brundt in Rellekka.\",\"s\":[\"Ask about the dragonkin fortress.\"]},{\"t\":\"Talk to Torfinn on the Rellekka docks to go to Ungael.\",\"s\":[\"I'm ready.\",\"Yes please.\"]},{\"t\":\"Defeat Vorkath. This is a hard fight, so if you're unfamiliar with it it's recommended you watch a video on it first.\",\"i\":[\"Ranged combat gear\"]},{\"t\":\"Enter the cave on the north west of Ungael.\",\"s\":[\"I'm sure.\"]},{\"t\":\"Pull the lever in the south west corner. Make sure you have run energy before doing so, as you need to run to the east room afterwards.\"},{\"t\":\"RUN to the east room.\"},{\"t\":\"Search the stone chest in the room for the key piece.\"}],\"i\":[\"Combat gear, food and potions\"],\"c\":1,\"e\":[\"Vorkath (level 392)\"]},{\"n\":\"Unlocking the door\",\"st\":[{\"t\":\"Open the Mithril Door in the Ancient Caverns.\",\"s\":[\"Yes, I wish to enter the unknown.\"]},{\"t\":\"Cast fire wave or surge on the 3 dragon heads.\"},{\"t\":\"Forge the dragon key on the anvils in the south of the Ancient Caverns.\",\"s\":[\"Yes.\"]},{\"t\":\"Open the door on Lithkren.\"},{\"t\":\"Enter the grandiose doors and talk to Dallas in the new area.\"},{\"t\":\"Talk to Bob underground in Lithkren.\"}],\"i\":[\"Ancient key\",\"3 casts of Fire Wave or Fire Surge\",\"Dragon key piece (Fremmennik)\",\"Dragon key piece (Kharazi)\",\"Dragon key piece (Varrock)\",\"Dragon key piece (Kourend)\",\"Hammer\",\"Antifire shield\"]},{\"n\":\"Creating an army\",\"st\":[{\"t\":\"Talk to King Roald in Varrock Castle.\",\"s\":[\"I'm here to talk about dragons.\",\"About the dragon threat...\",\"Talk about the dragon threat\"]},{\"t\":\"Talk to Brundt in Rellekka.\",\"s\":[\"Ask about the dragon threat.\"]},{\"t\":\"Talk to Sir Amik Varze upstairs in Falador Castle.\",\"s\":[\"Talk about the dragon threat.\"]},{\"t\":\"Talk to King Lathas/Thoros in East Ardougne castle.\",\"s\":[\"Talk about the dragon threat.\"]},{\"t\":\"Enter the Varrock Castle dining room.\"},{\"t\":\"Talk to Bob in Varrock Castle.\"}]},{\"n\":\"Final showdown\",\"st\":[{\"t\":\"Talk to Torfinn on the Rellekka docks to go to Ungael. Be prepared for a lot of fighting.\",\"s\":[\"Yes please.\",\"Yes.\"],\"i\":[\"Combat gear, food and potions\",\"Antifire shield\"]},{\"t\":\"Keep the boat afloat by filling leaks, putting out fires, healing warriors and repairing the masts. This is where the four inventory slots are needed.\"},{\"t\":\"Travel to the main ship, killing dragons along the way.\"},{\"t\":\"Kill the blue and green dragons.\"},{\"t\":\"Kill the black, steel, and brutal red dragon. Occasionally Galvek will shoot a fireball in the air, move to avoid it.\"},{\"t\":\"Kill the metal dragons.\"},{\"t\":\"Kill Galvek. This is a hard fight, so it's recommended you check a video to see what you'll have to do.\"},{\"t\":\"Talk to Alec Kincade to become a Myth!\",\"s\":[\"Let's talk about my quest.\"]}],\"i\":[\"Combat gear, food and potions\",\"Antifire shield\"],\"c\":1,\"e\":[\"Galvek (level 608)\"]}]}"
        "Dream Mentor" -> "{\"n\":\"Dream Mentor\",\"items\":[\"Seal of passage\",\"some type of food (7)\",\"some other type of food (7)\",\"a third type of food (6)\",\"Goutweed\",\"Astral rune\",\"Hammer\",\"Pestle and mortar\",\"Tinderbox\",\"Combat gear\"],\"rec\":[\"Lunar isle teleport (3)\",\"Stamina potion\"],\"enemies\":[\"The Inadequacy (level 343)\",\"The Everlasting (level 223, safespottable)\",\"The Untouchable (level 274, safespottable)\",\"The Illusive (level 108, won't attack you)\"],\"rewards\":[\"2 Quest points\",\"15,000 Hitpoints XP\",\"10,000 Magic XP\",\"15,000 Experience Lamp (Combat, No Prayer or Attack)\",\"7 New Lunar Spells\",\"Ability to bank without the Seal of Passage by talking to 'Birds-Eye-Jack'\"],\"sec\":[{\"n\":\"Helping Cyrisus\",\"st\":[{\"t\":\"Enter the mine in the north east of Lunar Isle.\",\"i\":[\"food: 5x some type food, 5x some other type of food, 4x a third type of food (14)\"]},{\"t\":\"Enter the cave entrance on the north wall.\"},{\"t\":\"Attempt to talk to the fallen man.\",\"s\":[\"Yes.\"]},{\"t\":\"Feed the fallen man 4 food. You'll need to alternate between at least 3 different types of food.\",\"i\":[\"food: 1x some type of food, 1x some other type of food, 2x a third type of food (4)\"]},{\"t\":\"Talk to the fallen man.\"},{\"t\":\"Feed Cyrisus 6 food. You'll need to alternate between at least 3 different types of food.\",\"i\":[\"food: 2x some type of food, 2x some other type of food, 2x a third type of food (6)\"]},{\"t\":\"Talk to Cyrisus.\",\"s\":[\"You're looking better now.\",\"Well, you look and sound more lively.\",\"Are you looking forward to getting out?\",\"That's the spirit!\",\"You seem like a nice guy.\",\"Just being honest.\",\"When we get out of here I'll buy you a drink!\",\"Whatever and wherever you want - my treat.\",\"I'm very impressed you managed to get into this cave.\",\"I would have given up personally.\",\"You'll survive this easily.\",\"Think of all the places you can visit when you get out!\",\"Just don't worry.\",\"Of course.\",\"What are you going to do when you get out of here?\",\"That's up to you. You could travel with me!\",\"It's a good thing you have me to look after you.\",\"Not that I'm bragging or anything.\",\"Not long now and you'll be back on your feet!\",\"On whether you mind me helping you further.\",\"You're sounding much better.\",\"If you need anything, just let me know.\",\"It's quite cosy in here.\",\"The perfect environment for getting back on your feet!\",\"You're very safe in this little cave.\",\"The suqah will never fit through that tunnel.\",\"Tell me a bit about yourself.\",\"Fishing!\"]},{\"t\":\"Talk to 'Bird's-Eye' Jack in the Lunar Isle bank for Cyrisus's equipment.\",\"s\":[\"Cyrisus in the mine\"],\"i\":[\"Seal of passage\"]},{\"t\":\"Give Cyrisus his equipment.\",\"s\":[\"Talk about the Armament\"],\"i\":[\"Cyrisus's chest\"]},{\"t\":\"Feed Cyrisus alternating types of food.\",\"i\":[\"food: 2x some type of food, 2x some other type of food, 2x a third type of food (6)\"]},{\"t\":\"Talk to Cyrisus until he's fully recovered.\",\"s\":[\"You're looking better now.\",\"Well, you look and sound more lively.\",\"Are you looking forward to getting out?\",\"That's the spirit!\",\"You seem like a nice guy.\",\"Just being honest.\",\"When we get out of here I'll buy you a drink!\",\"Whatever and wherever you want - my treat.\",\"I'm very impressed you managed to get into this cave.\",\"I would have given up personally.\",\"You'll survive this easily.\",\"Think of all the places you can visit when you get out!\",\"Just don't worry.\",\"Of course.\",\"What are you going to do when you get out of here?\",\"That's up to you. You could travel with me!\",\"It's a good thing you have me to look after you.\",\"Not that I'm bragging or anything.\",\"Not long now and you'll be back on your feet!\",\"On whether you mind me helping you further.\",\"You're sounding much better.\",\"If you need anything, just let me know.\",\"It's quite cosy in here.\",\"The perfect environment for getting back on your feet!\",\"You're very safe in this little cave.\",\"The suqah will never fit through that tunnel.\",\"Tell me a bit about yourself.\",\"Fishing!\"]}],\"i\":[\"some type of food (7)\",\"some other type of food (7)\",\"a third type of food (6)\",\"Seal of passage\"],\"tr\":[\"Lunar isle teleport (3)\"],\"r\":[\"Stamina potion\"]},{\"n\":\"Defeating his fear\",\"st\":[{\"t\":\"Talk to the Oneiromancer in the south east of Lunar Isle.\",\"s\":[\"Cyrisus.\"],\"i\":[\"Seal of passage\"]},{\"t\":\"Fill the vial with water.\",\"i\":[\"Dream vial (empty)\"]},{\"t\":\"Add a goutweed to the dream vial.\",\"i\":[\"Dream vial (water)\",\"Goutweed\"]},{\"t\":\"Use a hammer on an astral rune.\",\"i\":[\"Hammer\",\"Astral rune\"]},{\"t\":\"Use a pestle and mortar on the astral rune shards.\",\"i\":[\"Pestle and mortar\",\"Astral rune shards\"]},{\"t\":\"Add the ground astral rune to the dream vial.\",\"i\":[\"Ground astral rune\",\"Dream vial (herb)\"]},{\"t\":\"Equip your combat equipment, food, and light the Brazier in the west of Lunar Isle's town. The upcoming fight is hard, and you can only leave via the lecturn in the arena and cannot pray. Magic attacks are extremely effective for the fight.\",\"i\":[\"Seal of passage\",\"Tinderbox\",\"Combat gear\"]},{\"t\":\"Talk to Cyrisus to enter the dream.\",\"s\":[\"Yes, let's go!\"],\"i\":[\"Combat gear\",\"Seal of passage\"]},{\"t\":\"Kill The Inadequacy.\"},{\"t\":\"Kill The Everlasting. You can safe spot it by the entry book.\"},{\"t\":\"Kill The Untouchable. You can safe spot it by the entry book.\"},{\"t\":\"Kill The Illusive.\"},{\"t\":\"Talk to the Oneiromancer to finish the quest!\",\"s\":[\"Cyrisus.\"],\"i\":[\"Seal of passage\"]}],\"i\":[\"Seal of passage\",\"Goutweed\",\"Astral rune\",\"Hammer\",\"Pestle and mortar\",\"Tinderbox\",\"Combat gear\"],\"c\":1,\"e\":[\"The Inadequacy (level 343)\",\"The Everlasting (level 223, safespottable)\",\"The Untouchable (level 274, safespottable)\",\"The Illusive (level 108, won't attack you)\"]}]}"
        "Druidic Ritual" -> "{\"n\":\"Druidic Ritual\",\"items\":[\"Raw rat meat\",\"Raw bear meat\",\"Raw beef\",\"Raw chicken\"],\"rec\":[],\"enemies\":[],\"rewards\":[\"4 Quest points\",\"250 Herblore XP\",\"Access to the Herblore Skill\"],\"sec\":[{\"n\":\"Helping the druids\",\"st\":[{\"t\":\"Talk to Kaqemeex in the Druids' Circle in Taverley.\",\"s\":[\"I'm in search of a quest.\",\"Yes.\"]},{\"t\":\"Talk to Sanfew upstairs in the Taverley herblore store.\",\"s\":[\"I've been sent to help purify the Varrock stone circle.\"]},{\"t\":\"Enter Taverley Dungeon south of Taverley.\",\"s\":[\"Ok, I'll do that then.\"],\"i\":[\"Raw rat meat\",\"Raw bear meat\",\"Raw beef\",\"Raw chicken\"]},{\"t\":\"Spam-click the Prison door to enter the room with the cauldron in Taverley dungeon. Spam-clicking lets you skip the fight with the suits of armour standing nearby.\",\"i\":[\"Raw rat meat\",\"Raw bear meat\",\"Raw beef\",\"Raw chicken\"]},{\"t\":\"Use the four meats on the cauldron in Taverley dungeon.\"},{\"t\":\"Bring the enchanted meats to Sanfew upstairs in the Taverley herblore store.\",\"i\":[\"Enchanted rat\",\"Enchanted bear\",\"Enchanted beef\",\"Enchanted chicken\"]},{\"t\":\"Return to Kaqemeex in the Druids' Circle to finish the quest.\"}],\"i\":[\"Raw rat meat\",\"Raw bear meat\",\"Raw beef\",\"Raw chicken\"],\"c\":0}]}"
        "Dwarf Cannon" -> "{\"n\":\"Dwarf Cannon\",\"items\":[\"Hammer\"],\"rec\":[\"Stamina Potions\",\"Teleport to Falador, Amulet of Glory, or Combat Bracelet\",\"Teleport to Ardougne, Skills Necklace, or Games Necklace\"],\"enemies\":[],\"rewards\":[\"1 Quest point\",\"750 Crafting XP\",\"Ability to purchase and use the Dwarf Multicannon.\",\"Ability to make cannonballs.\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Talk to Captain Lawgof near the Coal Truck Mining Site (north of Fishing Guild, West of McGrubor's Wood).\",\"s\":[\"Yes.\"]}],\"c\":0},{\"n\":\"Repair and Retrieval\",\"st\":[{\"t\":\"Talk to Captain Lawgof to get more railings.\",\"i\":[\"Hammer\",\"Railing\"]},{\"t\":\"Inspect the six damaged railings around the camp to fix them.\",\"i\":[\"Hammer\",\"Railing\"]},{\"t\":\"Talk to Captain Lawgof after repairing the damaged railings.\"},{\"t\":\"Go to the top floor of the tower, south of Captain Lawgof, and get the remains there.\"},{\"t\":\"Return the remains to Captain Lawgof.\"}],\"i\":[\"Hammer\"],\"c\":0},{\"n\":\"Finding the lad\",\"st\":[{\"t\":\"Enter the goblin cave, east of the Fishing Guild entrance.\"},{\"t\":\"Search the crates in the north west corner to find Lollk.\"},{\"t\":\"Return to Captain Lawgof.\",\"s\":[\"Okay, I'll see what I can do.\"]},{\"t\":\"Talk to Captain Lawgof after repairing the multicannon.\",\"s\":[\"Okay then, just for you!\"]}],\"c\":0},{\"n\":\"Get Ammo Mould\",\"st\":[{\"t\":\"Talk to Nulodion at the Dwarven Black Guard camp, south of Ice Mountain.\"},{\"t\":\"Return to Captain Lawgof with the ammo mould and Nulodion's Notes.\",\"i\":[\"Nulodion's notes\",\"Ammo mould\"]}],\"c\":0}]}"
        "Eadgar's Ruse" -> "{\"n\":\"Eadgar's Ruse\",\"items\":[\"Climbing boots or 12 coins\",\"Vodka\",\"Pineapple chunks\",\"Logs (2)\",\"Grain (10)\",\"Raw chicken (5)\",\"Tinderbox\",\"Pestle and Mortar\",\"Ranarr potion (unf)\"],\"rec\":[\"Taverley teleports (3)\",\"Ardougne teleport\",\"Burthorpe teleport\"],\"enemies\":[],\"rewards\":[\"1 Quest point\",\"11,000 Herblore XP\",\"Ability to use the Trollheim teleport\",\"Ability to use Scrolls of Redirection to Trollheim.\",\"Ability to trade Goutweed to Sanfew for herbs.\"],\"sec\":[{\"n\":\"Start the quest\",\"st\":[{\"t\":\"Talk to Sanfew upstairs in the Taverley herblore store.\",\"s\":[\"Ask general questions.\",\"Have you any more work for me, to help reclaim the circle?\",\"I'll do it.\",\"Yes.\"]}],\"c\":0},{\"n\":\"Talk to Burntmeat\",\"st\":[{\"t\":\"Leave Eadgar's cave.\"},{\"t\":\"Enter the Troll Stronghold.\"},{\"t\":\"Go down the south staircase.\"},{\"t\":\"Talk to Burntmeat.\"},{\"t\":\"Talk to Eadgar in his cave on top of Trollheim.\"}],\"i\":[\"Climbing boots\"],\"c\":0},{\"n\":\"Get a parrot\",\"st\":[{\"t\":\"Travel to Ardougne Zoo and talk to Parroty Pete. Ask him both question 2 and 3, then use the vodka on the pineapple chunks.\",\"s\":[\"No thanks, Eadgar.\",\"What do you feed them?\",\"When did you add it?\"],\"i\":[\"Pineapple chunks\",\"Vodka\"]},{\"t\":\"Use the alco-chunks on the aviary hatch of the parrot cage.\",\"i\":[\"Alco-chunks\"]},{\"t\":\"Return the parrot to Eadgar on top of Trollheim.\"},{\"t\":\"Take the parrot to the Troll Stronghold prison, and hide it in the rack there.\",\"i\":[\"Drunk parrot\"]}],\"i\":[\"Vodka\",\"Pineapple chunks\",\"Climbing boots\"],\"c\":0},{\"n\":\"Making a fake man\",\"st\":[{\"t\":\"Talk to Tegid in the south of Taverley for a dirty robe. Once you have it, return to Eadgar with all the items he needs.\",\"s\":[\"Sanfew won't be happy...\"],\"i\":[\"Robe\",\"Grain (10)\",\"Raw chicken (5)\",\"Logs (2)\",\"Climbing boots\",\"Ranarr potion (unf)\",\"Tinderbox\",\"Pestle and Mortar\"]},{\"t\":\"Bring Eadgar all the listed items. Check the quest log if you're not sure what items you've already handed in.\",\"i\":[\"Robe\",\"Grain (10)\",\"Raw chicken (5)\",\"Logs (2)\",\"Climbing boots\",\"Ranarr potion (unf)\",\"Tinderbox\",\"Pestle and Mortar\"]},{\"t\":\"Go pick a troll thistle from outside Eadgar's cave.\",\"i\":[\"Ranarr potion (unf)\",\"Logs\",\"Tinderbox\"]},{\"t\":\"Light a fire then use the troll thistle on it.\",\"i\":[\"Logs\",\"Tinderbox\"]},{\"t\":\"Use the troll thistle on the fire.\",\"i\":[\"Troll thistle\"]},{\"t\":\"Use the pestle and mortar on the dried thistle\",\"i\":[\"Pestle and Mortar\",\"Dried thistle\"]},{\"t\":\"Use the ground thistle on a ranarr potion (unf)\",\"i\":[\"Ground thistle\",\"Ranarr potion (unf)\"]},{\"t\":\"Bring Eadgar the troll potion.\",\"i\":[\"Troll potion\"]},{\"t\":\"Get the parrot from the Troll Stronghold prison.\"},{\"t\":\"Return to Eadgar with the parrot.\",\"i\":[\"Drunk parrot\"]}],\"i\":[\"Climbing boots\",\"Logs (2)\",\"Tinderbox\",\"Pestle and Mortar\",\"Grain (10)\",\"Raw chicken (5)\",\"Ranarr potion (unf)\"],\"c\":0},{\"n\":\"Get the Goutweed\",\"st\":[{\"t\":\"Take the fake man to Burntmeat.\",\"i\":[\"Fake man\"]},{\"t\":\"Search the kitchen drawers south east of Burntmeat.\"},{\"t\":\"Go down to the storeroom from the Troll Stronghold kitchen.\"},{\"t\":\"Enter the storeroom.\",\"i\":[\"Storeroom key\"]},{\"t\":\"Search the goutweed crates for goutweed. You'll need to avoid the troll guards or you'll be kicked out and take damage.\"},{\"t\":\"If you wish to do Dream Mentor or Dragon Slayer II, grab two more goutweed. Afterwards, return to Sanfew upstairs in the Taverley herblore store.\",\"s\":[\"Ask general questions.\"],\"i\":[\"Goutweed\"]}],\"c\":0}]}"
        "Eagles' Peak" -> "{\"n\":\"Eagles' Peak\",\"items\":[\"Yellow dye\",\"Coins (50)\",\"Swamp tar\"],\"rec\":[\"Teleport to Eagle's Peak. Fairy ring (AKQ), Necklace of passage (The Outpost [2]) (2)\",\"Varrock teleport\",\"Ardougne teleport (2)\"],\"enemies\":[],\"rewards\":[\"2 Quest points\",\"2,500 Hunter XP\",\"Ability to use Box Traps\",\"Ability to use Eagle Transport System\",\"Ability to hunt Rabbits.\"],\"sec\":[{\"n\":\"Start the quest\",\"st\":[{\"t\":\"Speak to Charlie in the Ardougne Zoo.\",\"s\":[\"Ah, you sound like someone who needs a quest doing!\",\"Sure. Any idea where I should start looking?\",\"Yes.\"]}],\"i\":[\"Ardougne teleport\"],\"c\":0},{\"n\":\"Go to Eagles' Peak\",\"st\":[{\"t\":\"Go to the camp north of Eagles' Peak and search the pile of books for a Bird Book. The closest fairy ring is AKQ or teleport to The Outpost using the Necklace of Passage.\",\"s\":[\"The Outpost\"]},{\"t\":\"Click the Bird Book for a Metal Feather.\",\"i\":[\"Bird book\"]},{\"t\":\"Use the Metal Feather on the Rocky Outcrop on Eagles' Peak.\",\"i\":[\"Metal feather\"]}],\"i\":[\"Teleport to Eagle's Peak. Fairy ring (AKQ), Necklace of passage (The Outpost [2])\"],\"c\":0},{\"n\":\"In Eagles' Peak\",\"st\":[{\"t\":\"Enter Eagles' Peak through the Rocky Outcrop.\"},{\"t\":\"Shout to Nickolaus from across the chasm.\",\"s\":[\"The Ardougne zookeeper sent me to find you.\",\"Well if you gave me a ferret I could take it back for you.\",\"Could I help at all?\"]},{\"t\":\"Pick up 10 Eagle feathers from the piles in the main cavern.\",\"i\":[\"Eagle feather (10)\"]}],\"c\":0},{\"n\":\"Make a disguise\",\"st\":[{\"t\":\"Go speak to Asyff in south-east Varrock to have a disguise made.\",\"s\":[\"Well, specifically I'm after a couple of bird costumes.\"],\"i\":[\"Yellow dye\",\"Coins (50)\",\"Swamp tar\",\"Eagle feather (10)\"]},{\"t\":\"Speak to Asyff again.\",\"s\":[\"I've got the feathers and materials you requested.\",\"Okay, here are the materials. Eagle me up.\"],\"i\":[\"Yellow dye\",\"Coins (50)\",\"Swamp tar\",\"Eagle feather (10)\"]}],\"i\":[\"Yellow dye\",\"Coins (50)\",\"Swamp tar\",\"Eagle feather (10)\"],\"tr\":[\"Varrock teleport\",\"Teleport to Eagle's Peak. Fairy ring (AKQ), Necklace of passage (The Outpost [2])\"],\"c\":0},{\"n\":\"Return to Eagles' Peak\",\"st\":[{\"t\":\"Enter Eagles' Peak through the Rocky Outcrop.\",\"i\":[\"Fake beak (2)\",\"Eagle cape (2)\"]}],\"i\":[\"Fake beak (2)\",\"Eagle cape (2)\"],\"tr\":[\"Teleport to Eagle's Peak. Fairy ring (AKQ), Necklace of passage (The Outpost [2])\"],\"c\":0},{\"n\":\"Get the bronze feather\",\"st\":[{\"t\":\"Enter the south-western cavern of Eagles' Peak.\"},{\"t\":\"Try to take the feather from the pedestal.\"},{\"t\":\"Use the winches in the corners of the room.\"},{\"t\":\"Take the feather from the pedestal.\"},{\"t\":\"Return to the main cavern.\"}],\"c\":0},{\"n\":\"Get the silver feather\",\"st\":[{\"t\":\"Enter the north-western cavern of Eagles' Peak.\"},{\"t\":\"Inspect the Stone Pedestal here.\"},{\"t\":\"Inspect the rocks east of the pedestal.\"},{\"t\":\"Inspect the rocks north east of the last rock.\"},{\"t\":\"Inspect the opening north of the second rock.\"},{\"t\":\"Right-click threaten the Kebbit that appears. If the kebbit's gone, re-inspect the opening.\",\"s\":[\"Taunt the kebbit.\"]},{\"t\":\"Pick up the silver feather. If it's despawned, inspect the opening to get it.\"},{\"t\":\"Return to the main cavern.\"}],\"c\":0},{\"n\":\"Get the golden feather\",\"st\":[{\"t\":\"Enter the tunnel in the north east of the main cavern.\"},{\"t\":\"Collect 6 birdseed from the Birdseed holder.\",\"i\":[\"Odd bird seed (6)\"]},{\"t\":\"Pull the lever west of the entrance down.\"},{\"t\":\"Use the odd bird seed on the Bird feeder in the far south eastern corner.\",\"i\":[\"Odd bird seed\"]},{\"t\":\"Use the odd bird seed on the marked Bird feeder.\",\"i\":[\"Odd bird seed\"]},{\"t\":\"Pull the lever in the south east corner down.\"},{\"t\":\"Push the lever west of the entrance up.\"},{\"t\":\"Put odd bird feed into the feeder in the north east of the room.\",\"i\":[\"Odd bird seed\"]},{\"t\":\"Pull the lever in the south west corner down.\"},{\"t\":\"Put odd bird feed into the feeder in the south of the room.\",\"i\":[\"Odd bird seed\"]},{\"t\":\"Pull the lever in the north west corner down.\"},{\"t\":\"Put odd bird feed into the feeder in the south west of the room\",\"i\":[\"Odd bird seed\"]},{\"t\":\"Grab the Golden feather from the pedestal.\"},{\"t\":\"Return to the main cavern.\"}],\"c\":0},{\"n\":\"Free Nickolaus\",\"st\":[{\"t\":\"Use all three feathers on the door.\",\"i\":[\"Golden feather\",\"Silver feather\",\"Bronze feather\"]},{\"t\":\"Go through the feather door and sneak past the Eagle whilst wearing your eagle disguise.\",\"i\":[\"Fake beak (2)\",\"Eagle cape (2)\"]},{\"t\":\"Speak to Nickolaus.\",\"i\":[\"Fake beak (2)\",\"Eagle cape (2)\"]}],\"c\":0},{\"n\":\"Learn how to catch ferrets\",\"st\":[{\"t\":\"Speak to Nickolaus in his camp north of Eagles' Peak.\",\"s\":[\"Well I was originally sent to find you because of a ferret.\",\"That sounds good to me.\"]},{\"t\":\"Bring the ferret back to Charlie in Ardougne Zoo.\",\"i\":[\"Ferret\"]}],\"i\":[\"Ardougne teleport\"],\"c\":0}]}"
        "Elemental Workshop I" -> "{\"n\":\"Elemental Workshop I\",\"items\":[\"Knife\",\"Any pickaxe\",\"Needle\",\"Thread\",\"Leather\",\"Hammer\",\"Coal (4)\"],\"rec\":[\"Combat gear\"],\"enemies\":[\"Earth elemental (level 35)\"],\"rewards\":[\"1 Quest point\",\"5,000 Crafting XP\",\"5,000 Smithing XP\",\"An Elemental Shield\",\"Access to the Elemental Workshop.\",\"Ability to craft and wield Elemental equipment.\"],\"sec\":[{\"n\":\"Forging a Shield\",\"st\":[{\"t\":\"Search the marked bookcase in Seers' Village.\"},{\"t\":\"Read the battered book.\",\"s\":[\"Yes.\"],\"i\":[\"Battered book\"]},{\"t\":\"Use a knife on the battered book.\",\"i\":[\"Knife\",\"Battered book\"]},{\"t\":\"Open the odd wall to the north of the bookcase.\",\"i\":[\"Battered Key\",\"Slashed book\"]},{\"t\":\"Climb down the staircase.\"},{\"t\":\"Turn the marked water control in the north room.\"},{\"t\":\"Turn the other marked water control in the north room.\"},{\"t\":\"Pull the lever in the north room.\"},{\"t\":\"Repair the bellows in the east room.\",\"i\":[\"Needle\",\"Thread\",\"Leather\"]},{\"t\":\"Pull the lever next to the bellows.\"},{\"t\":\"Search the boxes in the north east of the central room.\"},{\"t\":\"Use the stone bowl on the lava trough in the south room.\",\"i\":[\"A stone bowl\"]},{\"t\":\"Use the lava-filled bowl on the furnace.\",\"i\":[\"A stone bowl\"]},{\"t\":\"Mine one of the elemental rocks in the west room, ready to fight a level 35.\",\"i\":[\"Any pickaxe\"]},{\"t\":\"Kill the rock elemental that appeared.\"},{\"t\":\"Pick up the elemental ore.\",\"i\":[\"Elemental ore\"]},{\"t\":\"Use the elemental ore on the furnace in the south room.\",\"i\":[\"Elemental ore\",\"Coal (4)\"]},{\"t\":\"Use the bar on one of the workbenches in the central room to complete the quest.\",\"i\":[\"Elemental bar\",\"Hammer\",\"Slashed book\"]}],\"i\":[\"Knife\",\"Any pickaxe\",\"Needle\",\"Thread\",\"Leather\",\"Hammer\",\"Coal (4)\"]}]}"
        "Elemental Workshop II" -> "{\"n\":\"Elemental Workshop II\",\"items\":[\"Any pickaxe\",\"Hammer\",\"Coal (8)\",\"Battered Key\"],\"rec\":[\"Digsite teleport\",\"Camelot teleport\",\"Slashed book if you want to smith a mind shield after this quest\"],\"enemies\":[\"2 Earth elementals (level 35)\"],\"rewards\":[\"1 Quest point\",\"7,500 Crafting XP\",\"7,500 Smithing XP\",\"A Mind Helmet\",\"Ability to craft and equip Mind Elemental Equipment\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Search the marked bookcase in the Exam Centre in the Dig Site.\",\"s\":[\"Yes.\"]},{\"t\":\"Read the beaten book.\",\"i\":[\"Beaten book\"]},{\"t\":\"Read the scroll.\",\"i\":[\"Scroll\"]}]},{\"n\":\"Unlocking the Hatch\",\"st\":[{\"t\":\"Search the machinery in the north of the elemental workshop.\",\"i\":[\"Battered Key\",\"Beaten book\",\"Slashed book if you want to smith a mind shield after this quest\"]},{\"t\":\"Unlock the hatch the middle of the workshop.\",\"i\":[\"Battered Key\",\"Beaten book\",\"Slashed book if you want to smith a mind shield after this quest\"]}],\"i\":[\"Battered Key\",\"Any pickaxe\",\"Coal (8)\",\"Hammer\",\"Beaten book\"],\"r\":[\"Slashed book if you want to smith a mind shield after this quest\"]},{\"n\":\"Repairing the crane\",\"st\":[{\"t\":\"Take crane schematics from the crate to the south.\",\"s\":[\"Crane schematic\"]},{\"t\":\"Make a claw from an elemental bar.\",\"i\":[\"Battered Key\",\"Beaten book\",\"Slashed book if you want to smith a mind shield after this quest\"]},{\"t\":\"Go back down to the deeper workshop and use the claw on the crane.\",\"i\":[\"Battered Key\",\"Beaten book\",\"Slashed book if you want to smith a mind shield after this quest\"]}]},{\"n\":\"Repairing the workshop\",\"st\":[{\"t\":\"Sort the pipes in the junction box on the catwalk.\",\"i\":[\"Battered Key\",\"Beaten book\",\"Slashed book if you want to smith a mind shield after this quest\"]},{\"t\":\"Search the marked crates on the catwalk AND DOWN THE STAIRS for 3 cogs and a pipe.\",\"i\":[\"Small cog\",\"Medium cog\",\"Large cog\",\"Pipe\"]},{\"t\":\"Use the pipe on the broken pipe to the north of the catwalk.\",\"i\":[\"Battered Key\",\"Beaten book\",\"Slashed book if you want to smith a mind shield after this quest\"]},{\"t\":\"Place cogs on the pegs outside the wind tunnel.\",\"i\":[\"Battered Key\",\"Beaten book\",\"Slashed book if you want to smith a mind shield after this quest\"]}]},{\"n\":\"Priming a bar\",\"st\":[{\"t\":\"Place the elemental bar on the jig cart.\",\"i\":[\"Elemental metal. Bring an additional elemental metal if you want to smith a mind shield after this quest\"]},{\"t\":\"Pull the south west lever to lower the claw.\"},{\"t\":\"Pull the south west lever to raise the claw.\"},{\"t\":\"Pull the south east lever to rotate the claw.\"},{\"t\":\"Pull the south west lever to lower the claw into the lava.\"},{\"t\":\"Pull the south west lever to raise the claw out of the lava.\"},{\"t\":\"Pull the south east lever to rotate the claw back.\"},{\"t\":\"Pull the south west lever to lower the bar back onto the jig.\"},{\"t\":\"Pull the south west lever to raise the claw once more.\"},{\"t\":\"Pull the central lever to activate the press.\"},{\"t\":\"Pull the west lever to move the jig to the press.\"},{\"t\":\"Pull the central lever to move the jig to the water tank.\"},{\"t\":\"Pull the north lever to open the water tank.\"},{\"t\":\"Turn the corkscrew.\"},{\"t\":\"Turn the corkscrew again.\"},{\"t\":\"Pull the north lever to close the water tank.\"},{\"t\":\"Turn the north west water valve.\"},{\"t\":\"Turn the north east water valve.\"},{\"t\":\"Turn the north east water valve again.\"},{\"t\":\"Turn the north west water valve again.\"},{\"t\":\"Pull the north lever to open the water tank again.\"},{\"t\":\"Turn the corkscrew once more.\"},{\"t\":\"Pull the central lever to move the jig to the wind tunnel.\"},{\"t\":\"Pull the east lever to start the wind tunnel.\"},{\"t\":\"Pull the east lever to stop the wind tunnel.\"},{\"t\":\"Pull the central lever to move the jig back to the start.\"},{\"t\":\"Pick up the primed bar.\"}],\"i\":[\"Elemental metal. Bring an additional elemental metal if you want to smith a mind shield after this quest\"]},{\"n\":\"Making a Mind Helm\",\"st\":[{\"t\":\"Go down from the priming room.\"},{\"t\":\"Use the primed bar on the extractor gun in the east room.\",\"i\":[\"Primed bar. Bring an additional primed bar if you want to smith a mind shield after this quest\"]},{\"t\":\"Sit in the extractor chair.\"},{\"t\":\"Take the mind bar.\"},{\"t\":\"Make the mind helm.\",\"i\":[\"Battered Key\",\"Beaten book\",\"Slashed book if you want to smith a mind shield after this quest\"]}],\"i\":[\"Primed bar. Bring an additional primed bar if you want to smith a mind shield after this quest\",\"Hammer\",\"Beaten book\"],\"r\":[\"Slashed book if you want to smith a mind shield after this quest\"]}]}"
        "Enakhra's Lament" -> "{\"n\":\"Enakhra's Lament\",\"items\":[\"Any pickaxe\",\"Chisel\",\"Soft clay\",\"Bread or cake\",\"Tinderbox\",\"Logs\",\"Oak logs\",\"Willow logs\",\"Maple logs\",\"Candle\",\"Coal\",\"Runes to cast Fire Bolt or stronger\",\"Runes to cast Wind Bolt or stronger\",\"Runes for crumble undead spell\"],\"rec\":[],\"enemies\":[],\"rewards\":[\"2 Quest points\",\"7,000 Crafting XP\",\"7,000 Mining XP\",\"7,000 Firemaking XP\",\"7,000 Magic XP\",\"Akthanakos's Camulet\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Before you begin, ensure that you have enough prayer points to use Protect from Melee for around five seconds (you will need this later in the temple). Talk to Lazim in the quarry south of the Bandit Camp.\",\"s\":[\"Yes.\",\"Of course!\"],\"i\":[\"Any pickaxe\"]}],\"c\":0},{\"n\":\"Craft a statue\",\"st\":[{\"t\":\"Get 32kg of sandstone and give it to Lazim. This can be done in batches, and you can mine some nearby.\",\"s\":[\"Okay, I'll get on with it.\",\"Yes, I have more stone.\",\"Here's a large 10 kg block.\",\"Here's a medium 5 kg block.\",\"Here's a small 2 kg block.\",\"Here's a tiny 1 kg block.\"]},{\"t\":\"Use a chisel on the sandstone 32kg.\",\"i\":[\"Chisel\",\"Sandstone 32kg\"]},{\"t\":\"Place the base on the flat ground nearby.\",\"i\":[\"Sandstone base\"]},{\"t\":\"Talk to Lazim again.\",\"s\":[\"I'll do it right away!\"]},{\"t\":\"Get 20kg of sandstone and give it to Lazim. This can be done in batches, and you can mine some nearby.\",\"s\":[\"I'll do it right away!\",\"Yes, I have more stone.\",\"Here's a large 10 kg block.\",\"Here's a medium 5 kg block.\",\"Here's a small 2 kg block.\",\"Here's a tiny 1 kg block.\"]},{\"t\":\"Use a chisel on the sandstone 20kg.\",\"i\":[\"Chisel\",\"Sandstone 20kg\"]},{\"t\":\"Place the body on the sandstone base.\",\"i\":[\"Sandstone body\"]},{\"t\":\"Use a chisel on the headless statue.\",\"i\":[\"Chisel\"]},{\"t\":\"Talk to Lazim and choose the head you'd like the statue to have.\"},{\"t\":\"Get 2 x granite (5kg). You can mine some nearby.\",\"i\":[\"Granite (5kg) (2)\"]},{\"t\":\"Use a chisel on a piece of granite 5kg, and choose the head you decided on to craft.\",\"i\":[\"Chisel\",\"Granite (5kg)\"]},{\"t\":\"Give Lazim the head.\",\"i\":[\"Stone head\"]}],\"i\":[\"Any pickaxe\",\"Chisel\",\"Soft clay\",\"Bread or cake\",\"Tinderbox\",\"Logs\",\"Oak logs\",\"Willow logs\",\"Maple logs\",\"Candle\",\"Coal\",\"Runes to cast Fire Bolt or stronger\",\"Runes to cast Wind Bolt or stronger\",\"Earth rune (2)\",\"Air rune (2)\",\"Chaos rune\"],\"c\":0},{\"n\":\"Explore the ground floor\",\"st\":[{\"t\":\"Talk to Lazim in the temple.\"},{\"t\":\"Use a chisel on the fallen statue to get all its limbs.\",\"s\":[\"Remove the statue's left arm\",\"Remove the statue's right arm\",\"Remove the statue's left leg\",\"Remove the statue's right leg\"],\"i\":[\"Chisel\"]},{\"t\":\"Take the M sigil from the pedestal in the room.\"},{\"t\":\"Enter the right arm door.\",\"i\":[\"Stone right arm\"]},{\"t\":\"Enter the left leg door.\",\"i\":[\"Stone left leg\"]},{\"t\":\"Enter the door with an M.\",\"i\":[\"M sigil\"]},{\"t\":\"Open the central room's doors using the metal letters. Go up the ladder in the central room.\"}],\"c\":0},{\"n\":\"Solve the puzzles\",\"st\":[{\"t\":\"Use soft clay on the pedestal.\",\"i\":[\"Soft clay\"]},{\"t\":\"Use a chisel on granite (5kg).\",\"i\":[\"Granite (5kg)\",\"Chisel\"]},{\"t\":\"Use the camel stone head on the pedestal.\",\"i\":[\"Stone head\"]},{\"t\":\"Right-click use bread or cake on Pentyn.\",\"i\":[\"Bread or cake\"]},{\"t\":\"Cast a fire spell on the frozen fountain.\",\"i\":[\"Runes to cast Fire Bolt or stronger\"]},{\"t\":\"Cast an air spell on the furnace.\",\"i\":[\"Runes to cast Wind Bolt or stronger\"]},{\"t\":\"Use a normal log on the south west brazier.\",\"i\":[\"Logs\"]},{\"t\":\"Use an oak log on the south brazier.\",\"i\":[\"Oak logs\"]},{\"t\":\"Use a willow log on the south east brazier.\",\"i\":[\"Willow logs\"]},{\"t\":\"Use a maple log on the north west brazier.\",\"i\":[\"Maple logs\"]},{\"t\":\"Use a candle on the north brazier.\",\"i\":[\"Candle\"]},{\"t\":\"Use coal on the north east brazier.\",\"i\":[\"Coal\"]}],\"c\":0},{\"n\":\"Free Akthankos\",\"st\":[{\"t\":\"Pass through the magic barrier and go up the ladder.\"},{\"t\":\"Go up the ladder.\"},{\"t\":\"Cast crumble undead on the Boneguard. Make sure you take off any armour or weapons which give you a negative magic attack bonus or else you might splash.\",\"i\":[\"Earth rune (2)\",\"2 air runes\",\"Chaos rune\"]},{\"t\":\"Climb down the stone ladder past the Boneguard.\"},{\"t\":\"Put on Protect from Melee, then talk to the Boneguard.\"},{\"t\":\"Take sandstone from the nearby rubble, and use it to repair the south wall. For each piece added, use a chisel on the wall.\",\"s\":[\"Of course, I'll help you out.\",\"Okay, I'll start building.\"],\"i\":[\"Sandstone (5kg)\"]},{\"t\":\"Talk to the Boneguard to finish the quest.\"}],\"c\":0}]}"
        "Enlightened Journey" -> "{\"n\":\"Enlightened Journey\",\"items\":[\"Papyrus (3)\",\"Ball of wool\",\"Sack of potatoes (10)\",\"Empty sack (8)\",\"Unlit candle\",\"Yellow dye\",\"Red dye\",\"Silk (10)\",\"Bowl\",\"Logs (10)\",\"Tinderbox\",\"Willow branches (12)\"],\"rec\":[\"Draynor/Port Sarim teleport\"],\"enemies\":[],\"rewards\":[\"1 Quest point\",\"2,000 Crafting XP\",\"3,000 Farming XP\",\"1,500 Woodcutting XP\",\"4,000 Firemaking XP\",\"Bomber Jacket\",\"Bomber Cap\",\"Access to the Hot Air Balloon transport system.\",\"Ability to make origami balloons.\"],\"sec\":[{\"n\":\"Making a balloon\",\"st\":[{\"t\":\"Bank all weapons and armour you have, and go to Port Sarim to get a boat to Entrana.\"},{\"t\":\"Talk to Auguste on Entrana 3 times.\",\"s\":[\"Yes! Sign me up.\",\"Umm, yes. What's your point?\",\"Yes.\"],\"i\":[\"Papyrus (3)\",\"Ball of wool\"]},{\"t\":\"Use papyrus on a ball of wool.\",\"i\":[\"Papyrus\",\"Ball of wool\"]},{\"t\":\"Use a candle on the balloon.\",\"i\":[\"Unlit candle\",\"Balloon structure\"]},{\"t\":\"Talk to Auguste again.\",\"s\":[\"Yes, I have them here.\"],\"i\":[\"Origami balloon\"]},{\"t\":\"Talk to Auguste with 2 papyrus and a sack of potatoes.\",\"s\":[\"Yes, I have them here.\"],\"i\":[\"Papyrus (2)\",\"Sack of potatoes (10)\"]},{\"t\":\"Talk to Auguste after the flash mob.\"},{\"t\":\"Fill your empty sacks on the sand pit south of Auguste.\",\"i\":[\"Empty sack (8)\"]}],\"i\":[\"Papyrus (3)\",\"Ball of wool\",\"Unlit candle\",\"Sack of potatoes (10)\",\"Empty sack (8)\",\"Yellow dye\",\"Red dye\",\"Silk (10)\",\"Bowl\"],\"c\":0},{\"n\":\"Flying\",\"st\":[{\"t\":\"Get 12 willow branches and use them on the platform next to Auguste to make the basket.\",\"i\":[\"Willow branches (12)\"]},{\"t\":\"Talk to Auguste to fly.\",\"s\":[\"Okay.\"],\"i\":[\"Logs (10)\",\"Tinderbox\"]},{\"t\":\"Talk to Auguste in Taverley to finish the quest.\"}],\"i\":[\"Willow branches (12)\",\"Logs (10)\",\"Tinderbox\"],\"c\":0}]}"
        "Enter the Abyss" -> "{\"n\":\"Enter the Abyss\",\"items\":[],\"rec\":[\"Teleport to Edgeville\",\"Teleports to Varrock (2)\",\"Teleport to Wizards' Tower\",\"Teleport to Ardougne\"],\"enemies\":[],\"rewards\":[\"1,000 Runecraft XP\",\"A small rune pouch\",\"Ability to enter The Abyss\"],\"sec\":[{\"n\":\"Helping the Zamorakians\",\"st\":[{\"t\":\"Talk to the Mage of Zamorak in the Wilderness north of Edgeville. BRING NOTHING AS YOU CAN BE KILLED BY OTHER PLAYERS HERE.\"},{\"t\":\"Talk to the Mage of Zamorak in south east Varrock.\",\"s\":[\"Where do you get your runes from?\",\"Maybe I could make it worth your while?\",\"Yes, but I can still help you as well.\",\"I did it so that I could then steal their secrets.\",\"Deal.\",\"But I'm a loyal servant of Zamorak as well!\",\"Okay, fine. I don't really serve Zamorak.\",\"Because I can still help you.\"]},{\"t\":\"Teleport to the essence mine with Aubury in south east Varrock.\",\"s\":[\"Can you teleport me to the Rune Essence Mine?\"],\"i\":[\"Scrying orb\"]},{\"t\":\"Teleport to the essence mine with Sedridor in the Wizard Tower's basement.\",\"s\":[\"Can you teleport me to the Rune Essence Mine?\"],\"i\":[\"Scrying orb\"]},{\"t\":\"Teleport to the essence mine with Wizard Cromperty in East Ardougne.\",\"s\":[\"Can you teleport me to the Rune Essence Mine?\"],\"i\":[\"Scrying orb\"]},{\"t\":\"Talk to the Mage of Zamorak again.\"}],\"c\":0}]}"
        "Ernest the Chicken" -> "{\"n\":\"Ernest the Chicken\",\"items\":[],\"rec\":[],\"enemies\":[\"Able to survive a skeleton (level 22) attacking you\"],\"rewards\":[\"4 Quest points\",\"300 x Coins\",\"Access to the Killerwatt plane (Members Only).\",\"Ability to be assigned Killerwatts as a Slayer task.\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Talk to Veronica outside of Draynor Manor.\",\"s\":[\"Aha, sounds like a quest. I'll help.\"]}]},{\"n\":\"Get the Gauge and Tube\",\"st\":[{\"t\":\"Enter Draynor Manor's ground floor.\"},{\"t\":\"Go upstairs and pick up the fish food.\"},{\"t\":\"Pick up the fish food in the south room.\",\"i\":[\"Fish food\"]},{\"t\":\"Go back downstairs and pick up the poison from the north west room.\"},{\"t\":\"Pick up the poison from the north west room.\",\"i\":[\"Poison\"]},{\"t\":\"Use the poison on the fish food\",\"i\":[\"Poison\",\"Fish food\"]},{\"t\":\"Pick up the spade in the east room. Exit the manor through the door in the same room.\",\"i\":[\"Spade\"]},{\"t\":\"Search the compost heap west of the manor.\",\"i\":[\"Spade\"]},{\"t\":\"Use the poisoned fish food on the fountain south west of the manor.\",\"i\":[\"Poisoned fish food\"]},{\"t\":\"Search the fountain.\"},{\"t\":\"Go back into the manor's ground floor.\"},{\"t\":\"Enter the small room north of the staircase with the key and pick up the rubber tube.\",\"i\":[\"Rubber tube\"]}]},{\"n\":\"Get the oil can\",\"st\":[{\"t\":\"Search the bookcase in the west room to enter the secret room.\"},{\"t\":\"Climb down the ladder into the basement.\"},{\"t\":\"Pick up the oil can in the west room.\",\"i\":[\"Oil can\"]}]},{\"n\":\"Bring items to Oddenstein\",\"st\":[{\"t\":\"Talk to Professor Oddenstein on the top floor.\",\"s\":[\"I'm looking for a guy called Ernest.\",\"Change him back this instant!\"]},{\"t\":\"Give Professor Oddenstein the items to finish.\",\"i\":[\"Oil can\",\"Rubber tube\",\"Pressure gauge\"]}]}]}"
        "Ethically Acquired Antiquities" -> "{\"n\":\"Ethically Acquired Antiquities\",\"items\":[],\"rec\":[\"Coins (3000)\",\"Varrock Teleport\",\"Civitas Illa Fortis Teleport (2)\",\"Stamina potion\"],\"enemies\":[],\"rewards\":[\"1 Quest point\",\"6,000 Thieving XP\",\"5000 x Coins\"],\"sec\":[{\"n\":\"Grand Museum\",\"st\":[{\"t\":\"Inspect the empty display case at the Grand Museum in Civitas illa Fortis to start the quest.\",\"s\":[\"Yes.\"]},{\"t\":\"Speak to Curator Herminius in the centre of the Grand Museum.\",\"s\":[\"Could you tell me more about that empty display?\"]},{\"t\":\"Investigate the tools behind the empty display case.\"},{\"t\":\"Inspect the empty display case again.\"},{\"t\":\"Talk to any academic in the room.\"},{\"t\":\"Talk to any tourist in the room.\"},{\"t\":\"Talk to any citizen in the room.\"}],\"i\":[\"Civitas Illa Fortis Teleport\"],\"c\":0},{\"n\":\"Done with museum visit\",\"st\":[{\"t\":\"Speak to Regulus Cento south of the Grand Museum.\",\"s\":[\"Have you seen anybody suspicious around?\"]},{\"t\":\"Head east to the docks and speak to any Trader Crewmember.\",\"s\":[\"Have you seen a man with a case?\",\"As long as it is just the one favour...\"]},{\"t\":\"Head south of the Fortis Cothon to Artima's crafting store and speak to her.\",\"s\":[\"I was hoping for some help.\",\"Go on then.\",\"So about those sails...\"],\"i\":[\"Tattered sails\"]},{\"t\":\"Return up north and speak to any Trader Crewmember.\",\"s\":[\"So, about that man with the case.\"]},{\"t\":\"Head to Port Sarim and speak to Trader Stan or any Trader Crewmember on the southern deck. To get to Port Sarim quickly, you can charter a ship.\",\"s\":[\"Port Sarim (wily cats)\",\"Have you seen a grey-haired man with a case?\"]},{\"t\":\"Head to the Rune Shop in north western Port Sarim and speak to Betty.\",\"s\":[\"Have you seen a grey-haired man with a case?\"]},{\"t\":\"Read Betty's notes.\",\"i\":[\"Betty's Notes\"]}],\"i\":[\"Coins (3000)\"],\"c\":0},{\"n\":\"