        "Fairytale I - Growing Pains" -> "{\"n\":\"Fairytale I - Growing Pains\",\"items\":[\"Secateurs\",\"Spade\",\"Ghostspeak amulet\",\"Dramen or lunar staff\",\"Draynor skull\"],\"rec\":[\"Varrock teleport\",\"Falador teleport\",\"Lumbridge teleport\",\"Teleport to Morytania\",\"Food\"],\"enemies\":[\"Tanglefoot (level 111)\"],\"rewards\":[\"2 Quest points\",\"3,500 Farming XP\",\"2,000 Attack XP\",\"1,000 Magic XP\",\"Magic Secateurs\"],\"sec\":[{\"n\":\"Investigating\",\"st\":[{\"t\":\"Talk to Martin in the Draynor Market.\",\"s\":[\"Ask about the quest.\",\"Anything I can help with?\",\"Now that I think about it, you're right!\"]},{\"t\":\"Talk to 5 farmers, then return to Martin in Draynor Village. The recommended 5 are:\",\"s\":[\"Are you a member of the Group of Advanced Gardeners?\"]},{\"t\":\"Return to Martin in the Draynor Market.\",\"s\":[\"Ask about the quest.\"]}]},{\"n\":\"Unnatural events\",\"st\":[{\"t\":\"Travel to Zanaris.\",\"i\":[\"Dramen or lunar staff\"]},{\"t\":\"Talk to the Fairy Godfather in the Throne Room.\",\"s\":[\"Where's the Fairy Queen?\"]},{\"t\":\"Talk to Fairy Nuff in north west Zanaris.\"},{\"t\":\"Talk to Zandar in the Dark Wizards' Tower west of Falador.\",\"i\":[\"Symptoms list\"]}],\"i\":[\"Dramen or lunar staff\"]},{\"n\":\"Finding a cure\",\"st\":[{\"t\":\"Dig for a skull in the north of Draynor Manor.\"},{\"t\":\"Talk to Malignius Mortifer west of Port Sarim.\",\"s\":[\"I need help with fighting a Tanglefoot.\",\"I was asking you about fighting a Tanglefoot...\"],\"i\":[\"Draynor skull\"]}],\"i\":[\"Draynor skull or a spade to get it\"]},{\"n\":\"Enchanting secateurs\",\"st\":[{\"t\":\"Get the items Mortifer tells you to get, and enter the Grotto in the south of Mort Myre.\",\"i\":[\"Ghostspeak amulet\",\"Secateurs\",\"3 items Mortifer told you to get\"]},{\"t\":\"Talk to the Nature Spirit.\",\"i\":[\"Ghostspeak amulet\",\"Secateurs\",\"3 items Mortifer told you to get\"]}],\"i\":[\"Ghostspeak amulet\",\"Secateurs\",\"3 items Mortifer told you to get\"]},{\"n\":\"Defeat the Tanglefoot\",\"st\":[{\"t\":\"Travel to Zanaris, ready to fight the Tanglefoot.\",\"i\":[\"Dramen or lunar staff\",\"Magic secateurs\"]},{\"t\":\"Enter the tanglefoot lair in the south of Zanaris, near the cosmic altar.\",\"i\":[\"Magic secateurs\",\"Food\"]},{\"t\":\"Kill the large Tanglefoot with the Magic Secateurs. You can flinch it on a corner.\",\"i\":[\"Magic secateurs\"]},{\"t\":\"Talk to the Fairy Godfather to finish the quest.\",\"i\":[\"Queen's secateurs\"]}],\"i\":[\"Dramen or lunar staff\",\"Magic secateurs\",\"Food\"],\"c\":1,\"e\":[\"Tanglefoot (level 111)\"]}]}"
        "Fairytale II - Cure a Queen" -> "{\"n\":\"Fairytale II - Cure a Queen\",\"items\":[\"Dramen or lunar staff\",\"Vial of water\",\"Pestle and mortar\"],\"rec\":[\"Combat gear\"],\"enemies\":[\"At least 1 Gorak (level 145)\"],\"rewards\":[\"2 Quest points\",\"3,500 Herblore XP\",\"2,500 Thieving XP\",\"2,500 Experience Lamp (Any skill over level 30.)\",\"Access to Fairy Rings.\",\"Access to Fairy Fixit's Fairy Enhancement Store.\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Talk to Martin in the Draynor Market.\",\"s\":[\"Ask about the quest.\"]},{\"t\":\"Wait 5 minutes.\"},{\"t\":\"Return to Martin in the Draynor Market.\",\"s\":[\"Ask about the quest.\",\"I suppose I'd better go and see what the problem is then.\"]}]},{\"n\":\"Betrayal\",\"st\":[{\"t\":\"Travel to Zanaris.\",\"i\":[\"Dramen or lunar staff\"]},{\"t\":\"Search the healing certificate in Fairy Nuff's room.\"},{\"t\":\"Right-click study the certificate.\",\"i\":[\"Nuff's certificate\"]},{\"t\":\"Read the sign near the Cosmic Temple in the south of Zanaris.\"},{\"t\":\"Talk to the Fairy Godfather in the Throne Room.\",\"s\":[\"Where is the Fairy Queen?\",\"Where could she have been taken to?\",\"Yes, okay.\"]},{\"t\":\"While carrying Nuff's certificate, use the Fairy Rings to travel to A.I.R., D.L.R., D.J.Q. then A.J.S.\",\"i\":[\"Dramen or lunar staff\",\"Nuff's certificate\"]},{\"t\":\"Talk to Fairy Nuff.\"},{\"t\":\"Pickpocket the Fairy Godfather in the Zanaris Throne Room.\"},{\"t\":\"Give Fairy Nuff the Queen's Secateurs.\",\"i\":[\"Queen's secateurs\"]}],\"i\":[\"Dramen or lunar staff\",\"Vial of water\",\"Pestle and mortar\"]},{\"n\":\"Making a cure\",\"st\":[{\"t\":\"Travel to C.K.P with a Fairy Ring. Even if you've already made a magic essence (unf), you'll need to make another.\",\"i\":[\"Dramen or lunar staff\"]},{\"t\":\"Wait for a star flower to appear.\"},{\"t\":\"Pick a star flower.\"},{\"t\":\"Travel to D.I.R. with a Fairy Ring, ready to kill a Gorak. Goraks can hit through