        "Fallen From Grace" -> "{\"n\":\"Fallen From Grace\",\"items\":[\"A raft or a skiff\",\"Any pickaxe\",\"Chisel\",\"Hammer\",\"Combat gear\"],\"rec\":[],\"enemies\":[\"Mad Angel (lvl 270)\",\"3 Mountain Trolls (level 69)\"],\"rewards\":[\"2 Quest points\",\"10,000 Crafting XP\",\"12,500 Sailing XP\",\"5,000 Mining XP\",\"5,000 Runecraft XP\",\"Access to Mad Angel boss\",\"Access to Sunstone Golem Crafting & Mining\",\"Teleports to Wyrmscraig on the Slayer Ring and Necklace of Passage\"],\"sec\":[{\"n\":\"Investigating\",\"st\":[{\"t\":\"Talk to Ffion to be allowed onto the island.\"},{\"t\":\"Talk to Cormac in Auchrie village on Wyrmscraig island.\",\"s\":[\"Yes.\"]},{\"t\":\"Talk to Muriel in the house north east of Cormac.\"},{\"t\":\"Search the tent to the south east on the coast for a pickaxe, hammer, and chisel.\"},{\"t\":\"Inspect the sunstone monolith on the coast south east of Muriel.\"},{\"t\":\"Mine a sunstone fragment off the sunstone monolith.\",\"i\":[\"Any pickaxe\"]},{\"t\":\"Use a chisel on the sunstone fragment.\",\"i\":[\"Sunstone\",\"Chisel\"]},{\"t\":\"Investigate the large hat on a basalt column on the south west corner of the island.\",\"i\":[\"Large hat\"]},{\"t\":\"Return to Cormac in Auchrie village on Wyrmscraig island.\"}]},{\"n\":\"Below the church\",\"st\":[{\"t\":\"Sail into the cave on the south west of the island with either a skiff or a raft.\",\"i\":[\"Combat gear\",\"Sunstone core\"]},{\"t\":\"Disembark onto the gangplank and talk to Mortimer.\"},{\"t\":\"Kill the 3 trolls near to Mortimer.\"},{\"t\":\"Talk to Mortimer again.\"},{\"t\":\"Investigate the broken golem in the far north of the cavern.\"},{\"t\":\"Use your sunstone core on the broken golem.\",\"i\":[\"Sunstone core\"]},{\"t\":\"Right-click destroy the ancient sunstone core.\",\"i\":[\"Ancient sunstone core\"]},{\"t\":\"Climb the staircase, ready for the boss fight.\",\"i\":[\"Combat gear\",\"Staircase key\"]},{\"t\":\"Defeat the Mad Angel. Use Protect from Melee.