        "Fight Arena" -> "{\"n\":\"Fight Arena\",\"items\":[\"Coins (5)\"],\"rec\":[\"Combat equipment and food (magic/ranged if you want to safe spot)\"],\"enemies\":[\"Khazard Scorpion (level 44) (safespottable)\",\"Khazard Ogre (level 63) (safespottable)\",\"Bouncer (level 137) (safespottable)\",\"General Khazard (level 142) (safespottable) (optional)\"],\"rewards\":[\"2 Quest points\",\"12,175 Attack XP\",\"2,175 Thieving XP\",\"1000 x Coins\",\"Khazard Armor\"],\"sec\":[{\"n\":\"Start quest\",\"st\":[{\"t\":\"Talk to Lady Servil, west-southwest of the Monastery south of Ardougne.\",\"s\":[\"Yes.\"]},{\"t\":\"Search the chest to the east for some Khazard armour.\"},{\"t\":\"Equip Khazard armour, talk to the Khazard Guard in the southeast of the prison.\",\"i\":[\"Khazard helmet\",\"Khazard armour\"]},{\"t\":\"Buy Khali brew from the nearby bar to the west for 5 coins.\",\"s\":[\"I'd like a Khali Brew please.\"],\"i\":[\"Coins (5)\"]},{\"t\":\"Take the brew back to the Khazard Guard.\",\"i\":[\"Khazard helmet\",\"Khazard armour\",\"Khali brew\"]}],\"i\":[\"Coins (5)\"]},{\"n\":\"Fight!\",\"st\":[{\"t\":\"Get another set of keys from the Khazard Guard\",\"i\":[\"Khazard helmet\",\"Khazard armour\"]},{\"t\":\"Get ready to fight the monsters (all safespottable), starting with Khazard Ogre (level 63). Use the keys on Sammy's cell door to free him.\",\"i\":[\"Combat equipment and food (magic/ranged if you want to safe spot)\",\"Khazard cell keys\"]},{\"t\":\"Kill the Ogre. You can lure it behind a skeleton to safespot it.\",\"i\":[\"Combat equipment and food (magic/ranged if you want to safe spot)\"]},{\"t\":\"Talk to Hengrad.\"},{\"t\":\"Kill the Scorpion. You can lure it behind a skeleton to safespot it.\",\"i\":[\"Combat equipment and food (magic/ranged if you want to safe spot)\"]},{\"t\":\"Kill Bouncer. You can lure it behind a skeleton to safespot it. Warning: After Bouncer is killed, you will be unable to re-enter the arena.\",\"i\":[\"Combat equipment and food (magic/ranged if you want to safe spot)\"]}],\"i\":[\"Combat equipment and food (magic/ranged if you want to safe spot)\"],\"c\":1,\"e\":[\"Khazard Ogre (level 63) (safespottable)\",\"Bouncer (level 137) (safespottable)\"]},{\"n\":\"Finish quest\",\"st\":[{\"t\":\"Exit the arena (can ignore General Khazard). Warning: You will be unable to re-enter the arena.\",\"s\":[\"Yes.\"]},{\"t\":\"Go back to Lady Servil to end the quest.\"}],\"c\":1,\"e\":[\"General Khazard (level 142) (safespottable) (optional)\"]}]}"
        "Fishing Contest" -> "{\"n\":\"Fishing Contest\",\"items\":[\"Coins (5)\",\"Red Vine Worm\",\"Garlic\",\"Spade\",\"Fishing Rod\"],\"rec\":[\"Combat Bracelet\",\"Camelot Teleport\"],\"enemies\":[],\"rewards\":[\"1 Quest point\",\"2,437 Fishing XP\",\"Access to the underground White Wolf Mountain passage\",\"Ability to catch minnows in The Fishing Guild.\"],\"sec\":[{\"n\":\"Fishing Contest\",\"st\":[{\"t\":\"Talk to Vestri just north of Catherby.\",\"s\":[\"I was wondering what was down those stairs?\",\"Why not?\",\"If you were my friend I wouldn't mind it.\",\"Well, let's be friends!\",\"And how am I meant to do that?\",\"Yes.\"]},{\"t\":\"Enter Hemenster with your fishing pass.\",\"s\":[\"Ranging Guild\"]},{\"t\":\"Speak to Bonzo to start the competition.\",\"s\":[\"I'll enter the competition please.\"],\"i\":[\"Coins (5)\"]},{\"t\":\"Put garlic in the pipes.\",\"i\":[\"Garlic\"]},{\"t\":\"Catch the winning fish at the fishing spot near the pipes.\",\"i\":[\"Fishing Rod\",\"Red Vine Worm\"]},{\"t\":\"Bring Vestri just north of Catherby the trophy.\",\"i\":[\"Fishing Trophy\"]}],\"i\":[\"Fishing Rod\",\"Garlic\",\"Coins (5)\",\"Red Vine Worm\",\"Spade\"],\"c\":0}]}"
        "Forgettable Tale..." -> "{\"n\":\"Forgettable Tale...\",\"items\":[\"Coins (500)\",\"Barley malt (2)\",\"Bucket of water (2)\",\"Seed dibber\",\"Rake\",\"Kebab\",\"Beer (3)\",\"Dwarven stout\",\"Beer glass\",\"A random item per player\"],\"rec\":[\"Grand exchange teleport to access the Mine Cart from there\"],\"enemies\":[],\"rewards\":[\"2 Quest points\",\"5,000 Cooking XP\",\"5,000 Farming XP\",\"2 x Dwarven Stout (m)\"],\"sec\":[{\"n\":\"Brewing\",\"st\":[{\"t\":\"Talk to Veldaban in Keldagrim.\",\"s\":[\"Yes please.\"]},{\"t\":\"Talk to the Drunken Dwarf in Keldagrim.\",\"s\":[\"Yes please.\"]},{\"t\":\"Give the Drunken Dwarf some beer.\",\"s\":[\"Yes please.\"]},{\"t\":\"Talk to the Rowdy Dwarf roaming the east Keldagrim pub, then give him the item he requests.\",\"s\":[\"Yes please.\"]},{\"t\":\"Talk to Khorvak under White Wolf Mountain.\",\"s\":[\"Yes please.\"]},{\"t\":\"Give Khorvak under White Wolf Mountain a dwarven stout.\",\"s\":[\"Yes please.\"]},{\"t\":\"Talk to Gauss in west Keldagrim.\",\"s\":[\"Yes please.\"]},{\"t\":\"Talk to Rind in west Keldagrim.\",\"s\":[\"Yes please.\"]},{\"t\":\"Grow the kelda seed near Rind.\",\"s\":[\"Yes please.\"]},{\"t\":\"Wait for the kelda hops to grow. This'll take 15-20 minutes.\"},{\"t\":\"Harvest the kelda hops.\",\"s\":[\"Yes please.\"]},{\"t\":\"Go brew the hops.\",\"s\":[\"Yes please.\"]},{\"t\":\"Pick up the pot in the brewing room.\",\"i\":[\"Pot\"]},{\"t\":\"Buy yeast from Blandebir. You can get a pot from the table in the brewing room.\",\"s\":[\"Do you have any spare ale yeast?\",\"That's a good deal - please fill my pot with ale yeast for 25GP.\"],\"i\":[\"Coins (25)\",\"Pot\"]},{\"t\":\"Add 2 buckets of water to the vat.\",\"i\":[\"Bucket of water (2)\"]},{\"t\":\"Add 2 barley malts to the vat.\",\"i\":[\"Barley malt (2)\"]},{\"t\":\"Add the kelda hops to the vat.\",\"i\":[\"Kelda hops\"]},{\"t\":\"Add the yeast to the vat.\",\"i\":[\"Ale yeast\"]},{\"t\":\"Wait for the kelda to brew. This'll ta