        "Garden of Tranquillity" -> "{\"n\":\"Garden of Tranquillity\",\"items\":[\"Ring of Charos\",\"Rake\",\"Seed dibber\",\"Spade\",\"Secateurs\",\"Watering can\",\"Gardening trowel\",\"Plant cure (2)\",\"Marigold seed\",\"Cabbage seeds (6 to be safe) (3)\",\"Onion seeds (6 to be safe) (3)\",\"Fishing rod\",\"Hammer\",\"Rune/Pure essence\",\"Pestle and mortar\",\"Filled plant pot\",\"Normal/Super/Ultra compost (2)\"],\"rec\":[\"Normal/Super/Ultra compost (5)\",\"Varrock teleport\",\"Draynor teleport\",\"Port Phasmatys teleport\",\"Ardougne teleport\",\"Camelot teleport\",\"Burthorpe teleport\",\"Edgeville teleport\",\"Lumbridge teleport\",\"Falador teleport\",\"Taverley teleport\"],\"enemies\":[],\"rewards\":[\"2 Quest points\",\"5,000 Farming XP\",\"Compost Potion (4)\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Talk to Ellamaria east of Varrock Castle.\",\"s\":[\"I would be happy to help someone who is so in touch with the people.\"]}],\"c\":0},{\"n\":\"Learning Persuasion\",\"st\":[{\"t\":\"Talk to the Wise Old Man in Draynor Village.\",\"s\":[\"Queen Ellamaria has sent me to seek your guidance.\",\"I have returned to you with the Ring of Charos.\",\"Can I retake the diplomacy test?\"],\"i\":[\"Ring of Charos\"]}],\"i\":[\"Ring of Charos\"],\"c\":0},{\"n\":\"Delpheniums\",\"st\":[{\"t\":\"Talk to Elstan north west of Draynor Village.\",\"s\":[\"Do you have any delphinium seeds to spare?\",\"[Charm] That is why I have come to an expert for advice.\",\"[Charm] Not just AN expert, Elstan - they say you are THE expert.\",\"[Charm] Oh no, I love listening to gardening stories...\",\"[Charm] Millions? Ah, just what I wanted to hear...\",\"Okay, I'll grow you some marigolds.\"],\"i\":[\"Ring of charos (a)\"]},{\"t\":\"Plant a marigold near to Elstan.\",\"i\":[\"Marigold seed\",\"Rake\",\"Seed dibber\",\"Spade\"]}],\"i\":[\"Ring of charos (a)\",\"Marigold seed\",\"Spade\",\"Rake\",\"Seed dibber\"],\"c\":0},{\"n\":\"Orchids\",\"st\":[{\"t\":\"Talk to Lyra west of Port Phasmatys.\",\"s\":[\"Do you have any orchid seeds to spare?\",\"[Charm] If you tell me your problems, I may be able to help you.\",\"[Charm] Yes, I was wondering about that.\",\"[Charm] Times must be very hard for you.\",\"[Charm] Whatever you've done, I'm sure you had just cause.\",\"[Charm] And what is the nature of this fee that you pay?\",\"[Charm] If not yours, then whose blood are you offering?\",\"[Charm] How can you deal with so much guilt?\",\"That's a deal - I'll grow a patch of onions for you.\"],\"i\":[\"Ring of charos (a)\"]},{\"t\":\"Plant onions in a patch near Lyra. Plant in both for the best chance of one not dying.\",\"i\":[\"Onion seeds (6 to be safe) (3)\",\"Rake\",\"Seed dibber\",\"Spade\"]}],\"i\":[\"Ring of charos (a)\",\"Onion seeds (6 to be safe) (3)\",\"Spade\",\"Rake\",\"Seed dibber\"],\"c\":0},{\"n\":\"Snowdrops\",\"st\":[{\"t\":\"Talk to Kragen northeast of Ardougne.\",\"s\":[\"Do you have any snowdrop seeds to spare?\",\"[Charm] You seem to be a little irritable, my friend.\",\"[Charm] I don't like to see a fellow human being so upset.\",\"[Charm] So what ails you, my friend?\",\"[Charm] Well, is there anything I can do for you?\",\"[Charm] So what can I do for you?\",\"That's a deal - I'll let you know when your cabbages are ready.\"],\"i\":[\"Ring of charos (a)\"]},{\"t\":\"Plant cabbage seeds in the patches near Kragen. Plant in both to be safe.\",\"i\":[\"Cabbage seeds (6 to be safe) (3)\",\"Rake\",\"Seed dibber\"]}],\"i\":[\"Ring of charos (a)\",\"Cabbage seeds (6 to be safe) (3)\",\"Spade\",\"Rake\",\"Seed dibber\"],\"c\":0},{\"n\":\"White Tree\",\"st\":[{\"t\":\"Talk to Dantaera north of Catherby.\",\"s\":[\"Do you know how I could grow a White Tree?\",\"[Charm] I think that there is something that you are not telling me.\",\"[Charm] A secret is a dreadful burden to have to keep to yourself.\",\"[Charm] Unless you allow me to do this she will die anyway.\"],\"i\":[\"Ring of charos (a)\"]},{\"t\":\"Use secateurs on the white tree on top of Ice Mountain.\",\"i\":[\"Secateurs\",\"Filled plant pot\",\"Gardening trowel\",\"Watering can\"]},{\"t\":\"Use the shoot on a plant pot.\",\"i\":[\"White tree shoot\",\"Filled plant pot\"]},{\"t\":\"Water the white tree shoot.\",\"i\":[\"White tree shoot (pot)\",\"Watering can\"]}],\"i\":[\"Ring of charos (a)\",\"Secateurs\",\"Gardening trowel\",\"Filled plant pot\",\"Watering can\"],\"c\":0},{\"n\":\"Roses\",\"st\":[{\"t\":\"Talk to Brother Althric in the Edgeville Monastery.\",\"s\":[\"[Charm] These are the most beautiful rosebushes I've ever seen.\"],\"i\":[\"Ring of charos (a)\"]},{\"t\":\"Use the Ring of charos(a) on the well in Edgeville.\",\"i\":[\"Ring of charos (a)\"]},{\"t\":\"Take some seeds from the white roses.\"},{\"t\":\"Take some seeds from the pink roses.\"},{\"t\":\"Take some seeds from the red roses.\"}],\"i\":[\"Ring of charos (a)\",\"Fishing rod\"],\"c\":0},{\"n\":\"Getting your ring back\",\"st\":[{\"t\":\"Use a fishing rod on the well in Edgeville to retrieve the ring of charos. This can take a few attempts.\",\"i\":[\"Fishing rod\"]}],\"i\":[\"Fishing rod\"],\"c\":0},{\"n\":\"Vines\",\"st\":[{\"t\":\"Talk to Bernald in Burthorpe.\",\"s\":[\"[Charm] But it is the only way that these vines will be cured.\",\"I accept the deal.\"],\"i\":[\"Ring of charos (a)\"]},{\"t\":\"Use plant cure on Bernald's grapevines.\",\"i\":[\"Plant cure\"]},{\"t\":\"Talk to Alain in Taverley with your ring of charos UNEQUIPPED.\",\"s\":[\"I need to ask you about strong plant cures.\"]},{\"t\":\"Use a hammer on some essence.\",\"i\":[\"Hammer\",\"Rune/Pure essence\"]},{\"t\":\"Use a pestle and mortar on the essence shards.\",\"i\":[\"Pestle and mortar\",\"Rune shards\"]},{\"t\":\"Use the rune dust on some plant cure.\",\"i\":[\"Rune dust\",\"Plant cure\"]},{\"t\":\"Use the enhanced plant cure on Bernald's grapevines.\",\"i\":[\"Plant cure (improved)\"]},{\"t\":\"Talk to Bernald for his seeds.\",\"i\":[\"Ring of charos (a)\"]}],\"i\":[\"Ring of charos (a)\",\"Plant cure (2)\",\"Rune/Pure essence\",\"Hammer\",\"Pestle and mortar\"],\"c\":0},{\"n\":\"Collecting the last seeds\",\"st\":[{\"t\":\"Harvest marigolds from the Falador Allotment patches. If yours died, you'll need to grow some more there.\",\"i\":[\"Spade\"]},{\"t\":\"Give Elstan a marigold for his seeds.\",\"s\":[\"I have those marigolds for you.\"],\"i\":[\"Marigold\"]},{\"t\":\"Talk to Lyra west of Port Phasmatys again for her seeds.\",\"s\":[\"Okay, I've grown those onions like you asked.\"]},{\"t\":\"Talk to Kragen northeast of Ardougne for his seeds.\",\"s\":[\"Okay, I've grown those cabbages like you asked.\"]}],\"i\":[\"Spade\"],\"c\":0},{\"n\":\"Planting the Garden\",\"st\":[{\"t\":\"Fill the plantpots in Ellamaria's garden with compost.\",\"i\":[\"Normal/Super/Ultra compost\"]},{\"t\":\"Plant the pink orchids in the marked plantpot.\",\"i\":[\"Orchid seeds (pink) (3)\",\"Seed dibber\"]},{\"t\":\"Plant the yellow orchids in the marked plantpot.\",\"i\":[\"Orchid seeds (yellow) (3)\",\"Seed dibber\"]},{\"t\":\"Plant the vine seeds.\",\"i\":[\"Vine seeds (4)\",\"Rake\",\"Seed dibber\"]},{\"t\":\"Plant snowdrops in the east patch.\",\"i\":[\"Snowdrop seeds (4)\",\"Rake\",\"Seed dibber\"]},{\"t\":\"Plant the white tree.\",\"i\":[\"White tree sapling\",\"Rake\",\"Spade\"]},{\"t\":\"Plant the delphinum seeds.\",\"i\":[\"Delphinium seeds (4)\",\"Rake\",\"Seed dibber\"]},{\"t\":\"Plant the rose seeds.\",\"i\":[\"Red rose seed (4)\",\"Rake\",\"Seed dibber\"]}],\"i\":[\"Normal/Super/Ultra compost (2)\",\"Rake\",\"Seed dibber\",\"Spade\",\"Delphinium seeds (4)\",\"Orchid seeds (pink) (3)\",\"Orchid seeds (yellow) (3)\",\"Snowdrop seeds (4)\",\"White tree sapling\",\"Pink rose seed (4)\",\"White rose seed (4)\",\"Red rose seed (4)\",\"Vine seeds (4)\"],\"c\":0},{\"n\":\"Getting statues\",\"st\":[{\"t\":\"Talk to Ellamaria for a trolley.\",\"s\":[\"How am I supposed to move statues all the way here?\"]},{\"t\":\"Use a trolley on the king statue outside Lumbridge Castle.\",\"i\":[\"Trolley\"]},{\"t\":\"Push the trolley across the River Lum, then to the marked plinth in the garden. Right-click 'place' the statue when it's next to the plinth.\"},{\"t\":\"Use the trolley on the statue of Saradomin in Falador.\",\"i\":[\"Trolley\"]},{\"t\":\"Push the trolley out of Falador, then to the marked plinth in the garden. Right-click 'place' the statue when it's next to the plinth.\"}],\"c\":0},{\"n\":\"Showing off the Garden\",\"st\":[{\"t\":\"Talk to Ellamaria once everything's finished growing.\"},{\"t\":\"Talk to King Roald in Varrock Castle, watch the cutscene, then finish the dialog with Ellamaria to finish the quest!\",\"s\":[\"Ask King Roald to follow me.\",\"[Charm] Of course, your majesty - please forgive me.\",\"[Charm] The Queen asked me to bring you.\",\"Would you like to follow me for a minute?\"],\"i\":[\"Ring of charos (a)\"]}],\"i\":[\"Ring of charos (a)\"],\"c\":0}]}"
        "Gertrude's Cat" -> "{\"n\":\"Gertrude's Cat\",\"items\":[\"Bucket of milk\",\"Coins (100)\",\"Raw Sardine\"],\"rec\":[\"Varrock teleports (2)\",\"Lumberyard teleport\"],\"enemies\":[],\"rewards\":[\"1 Quest point\",\"1,525 Cooking XP\",\"A pet Kitten\",\"Chocolate Cake\",\"Stew\",\"Ability to raise kittens.\"],\"sec\":[{\"n\":\"Starting out\",\"st\":[{\"t\":\"Talk to Gertrude west of Varrock to start the quest.\",\"s\":[\"Yes.\"]},{\"t\":\"Pickup some Doogle Leaves south of Gertrude's house.\",\"i\":[\"Doogle Leaves\",\"Raw Sardine\"]},{\"t\":\"Use your Doogle Leaves on the Sardine.\",\"i\":[\"Doogle Leaves\",\"Raw Sardine\"]},{\"t\":\"Talk to Shilop or Wilough in the Varrock Square.\",\"s\":[\"What will make you tell me?\",\"Okay then, I'll pay.\"],\"i\":[\"Seasoned Sardine\",\"Coins (100)\"]}],\"i\":[\"Raw Sardine\",\"Coins (100)\"],\"c\":0},{\"n\":\"The secret playground (Lumber Yard)\",\"st\":[{\"t\":\"Use a bucket of milk on Gertrude's cat upstairs in the Lumberyard north east of Varrock.\",\"i\":[\"Bucket of milk\"]},{\"t\":\"Use a seasoned sardine on Gertrude's cat upstairs in the Lumberyard north east of Varrock.\",\"i\":[\"Seasoned Sardine\"]},{\"t\":\"Search different crates downstairs in the Lumberyard until you find the kitten.\",\"i\":[\"Bucket of milk\"]}],\"i\":[\"Seasoned Sardine\",\"Bucket of milk\"],\"c\":0},{\"n\":\"Finish the quest\",\"st\":[{\"t\":\"Return to Gertrude west of Varrock to complete the quest.\"}],\"c\":0}]}"
        "Getting Ahead" -> "{\"n\":\"Getting Ahead\",\"items\":[\"You can get all the required items during the quest.\",\"Bear Fur\",\"Soft Clay\",\"Hammer\",\"Any saw\",\"Planks (2)\",\"Nails (6)\",\"Knife\",\"Red Dye\",\"Pot of Flour\",\"Needle\",\"Thread\"],\"rec\":[\"Food\",\"Stamina Potion\",\"Combat gear\",\"Skills Necklace\"],\"enemies\":[\"Headless Beast (level 82, safespottable)\"],\"rewards\":[\"1 Quest point\",\"4,000 Crafting XP\",\"3,200 Construction XP\",\"3000 x Coins\",\"Access to the tannery on Kebos Lowlands\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Talk to Gordon south of the Farming Guild.\",\"s\":[\"Need a hand with anything?\",\"Yes.\"]},{\"t\":\"Talk to Mary inside the main building, west of Gordon.\"}]},{\"n\":\"Killing the Beast\",\"st\":[{\"t\":\"Use the pot of flour on the cow pen gate.\"},{\"t\":\"Enter the Kebos Lowlands mine just west of the bridge and kill the Headless Beast (level 82).\",\"s\":[\"Yes.\"]},{\"t\":\"Return to Gordon and talk to him.\"}],\"i\":[\"Pot of Flour\"],\"c\":1,\"e\":[\"Headless Beast (level 82, safespottable)\"]},{\"n\":\"Making the fake head\",\"st\":[{\"t\":\"Talk to Mary inside the house.\"},{\"t\":\"Use the knife on the soft clay then talk to Gordon.\"},{\"t\":\"Use the bear fur on the clay head then talk to Gordon.\"},{\"t\":\"Use the red dye on the fur head then talk to Gordon.\",\"s\":[\"Take some red dye.\"]},{\"t\":\"Build the Mounted Head Space inside the farmhouse.\",\"i\":[\"Planks (2)\"]},{\"t\":\"Return to Gordon to finish the quest.\"}],\"i\":[\"Bear Fur\",\"Soft Clay\",\"Hammer\",\"Any saw\",\"Planks (2)\",\"Nails (6)\",\"Knife\",\"Red Dye\",\"Needle\",\"Thread\"]}]}"
        "Ghosts Ahoy" -> "{\"n\":\"Ghosts Ahoy\",\"items\":[\"Ghostspeak amulet\",\"Ring of Charos (a)\",\"Ecto-token, OR 10 Ecto-Tokens and coins to travel by Charter Ship (20)\",\"400+ coins\",\"Nettle tea\",\"Bucket of milk\",\"Silk\",\"Knife\",\"Needle/Thread or Costume needle\",\"3 colours of dyes. Which you'll need is random. To be prepared, bring 3 red/blue/yellow dyes\",\"Spade\",\"Oak longbow\",\"Bucket of slime\",\"Ecto-token, OR 25 Ecto-Tokens and coins to travel by Charter Ship (31)\"],\"rec\":[],\"enemies\":[\"Giant lobster (level 32) (safespottable)\"],\"rewards\":[\"2 Quest points\",\"2,400 Prayer XP\",\"Ectophial\",\"Free passage into Port Phasmatys\"],\"sec\":[{\"n\":\"Start the quest\",\"st\":[{\"t\":\"Enter Port Phasmatys.\",\"i\":[\"Ecto-token, or travel by Charter Ship (2)\",\"Ghostspeak amulet\"]},{\"t\":\"Talk to Velorina in east Port Phasmatys.\",\"s\":[\"Why, what is the matter?\",\"Yes, I do. It is a very sad story.\",\"Yes.\"],\"i\":[\"Ghostspeak amulet\"]},{\"t\":\"Talk to Necrovarus at the Ectofuntus.\",\"i\":[\"Ghostspeak amulet\"]},{\"t\":\"Return to Velorina in east Port Phasmatys.\",\"i\":[\"Ghostspeak amulet\"]}],\"i\":[\"Ghostspeak amulet\",\"Ecto-token, or travel by Charter Ship (4)\"]},{\"n\":\"Getting help\",\"st\":[{\"t\":\"Talk to the Old Crone east of the Slayer Tower.\",\"s\":[\"I'm here about Necrovarus.\"],\"i\":[\"Nettle tea\",\"Bucket of milk\"]},{\"t\":\"Use the nettle tea on the porcelain cup.\",\"i\":[\"Nettle tea\",\"Porcelain cup\"]},{\"t\":\"Use the bucket of milk on the porcelain cup.\",\"i\":[\"Bucket of milk\",\"Cup of tea\"]},{\"t\":\"Talk to the Old Crone and offer to help.\",\"s\":[\"I'm here about Necrovarus.\",\"You are doing so much for me - is there anything I can do for you?\",\"I am afraid I have lost the boat you gave to me.\"]}],\"i\":[\"Ghostspeak amulet\",\"Nettle tea\",\"Bucket of milk\"]},{\"n\":\"Finding the book\",\"st\":[{\"t\":\"Use the silk on the model ship.\",\"i\":[\"Silk\",\"Needle\",\"Thread\",\"Knife\",\"Model ship\"]},{\"t\":\"Attempt to search the chest in the east of the hull of the ship west of Port Phasmatys. A giant lobster will spawn you need to kill.\"},{\"t\":\"Kill the Giant Lobster.\"},{\"t\":\"Search the chest in the east of the hull again.\"}],\"i\":[\"Ghostspeak amulet\",\"Silk\",\"Needle\",\"Thread\",\"Knife\",\"3 colours of dyes. Which you'll need is random. To be prepared, bring 3 red/blue/yellow dyes\",\"Spade\",\"Ecto-token, or travel by Charter Ship and 10 ecto-tokens (12)\",\"Ring of Charos (a)\"],\"c\":1,\"e\":[\"Giant lobster (level 32) (safespottable)\"]},{\"n\":\"Finding the book\",\"st\":[{\"t\":\"Use the silk on the model ship.\",\"i\":[\"Silk\",\"Needle\",\"Thread\",\"Knife\",\"Model ship\"]},{\"t\":\"Attempt to search the chest in the east of the hull of the ship west of Port Phasmatys. A giant lobster will spawn you need to kill.\"},{\"t\":\"Kill the Giant Lobster.\"},{\"t\":\"Search the chest in the east of the hull again.\"}],\"i\":[\"Ghostspeak amulet\",\"Silk\",\"Needle\",\"Thread\",\"Knife\",\"3 colours of dyes. Which you'll need is random. To be prepared, bring 3 red/blue/yellow dyes\",\"Spade\",\"Ecto-token, or travel by Charter Ship and 25 ecto-tokens (27)\"],\"c\":1,\"e\":[\"Giant lobster (level 32) (safespottable)\"]},{\"n\":\"Finding the manual\",\"st\":[{\"t\":\"Talk to Ak-Haranu.\",\"s\":[\"Okay, wait here - I'll get you your bow.\"]},{\"t\":\"Talk to Robin in the Port Phasmatys pub. Keep playing runedraw until he agrees to sign your bow.\",\"s\":[\"Yes, I'll give you a game.\"],\"i\":[\"Oak longbow\",\"400+ coins\"]},{\"t\":\"Bring the signed bow to Ak-Haranu.\",\"i\":[\"Signed oak bow\"]}],\"i\":[\"400+ coins\",\"Oak longbow\"]},{\"n\":\"Finding the robes\",\"st\":[{\"t\":\"Talk to the Ghost Innkeeper.\",\"s\":[\"Do you have any jobs I can do?\",\"Yes, I'd be delighted.\"],\"i\":[\"Ghostspeak amulet\"]},{\"t\":\"Use a bucket of slime on the bedsheets.\",\"i\":[\"Bucket of slime\",\"Bedsheet\"]},{\"t\":\"Talk to Gravingas wearing the bedsheet.\",\"s\":[\"After hearing Velorina's story I will be happy to help out.\"],\"i\":[\"Bedsheet\",\"Ghostspeak amulet\"]},{\"t\":\"Alternate talking with the ghost villagers until you have 10 signatures.\",\"i\":[\"Ghostspeak amulet\"]},{\"t\":\"Bring the petition to Necrovarus at the Ectofuntus to cause him to drop a bone key.\",\"i\":[\"Petition form\",\"Ghostspeak amulet\"]},{\"t\":\"Go upstairs at the Ectofuntus.\"},{\"t\":\"Use the key on the south room's door.\",\"i\":[\"Bone key\"]},{\"t\":\"Search the coffin.\"}],\"i\":[\"Ghostspeak amulet\",\"Bucket of slime\"]},{\"n\":\"Undoing the curse\",\"st\":[{\"t\":\"Bring the items to the Old Crone east of the Slayer Tower.\",\"s\":[\"I'm here about Necrovarus.\"],\"i\":[\"Mystical robes\",\"Book of haricanto\",\"Translation manual\",\"Ghostspeak amulet\"]},{\"t\":\"Talk to Necrovarus at the Ectofuntus.\",\"s\":[\"Let any ghost who so wishes pass on into the next world.\"],\"i\":[\"Ghostspeak amulet\"]},{\"t\":\"Talk to Velorina in east Port Phasmatys to finish!\",\"i\":[\"Ghostspeak amulet\"]}],\"i\":[\"Ghostspeak amulet\",\"Book of haricanto\",\"Translation manual\",\"Mystical robes\"]}]}"
        "Goblin Diplomacy" -> "{\"n\":\"Goblin Diplomacy\",\"items\":[\"Blue dye\",\"Orange dye\",\"Goblin mail (3)\"],\"rec\":[],\"enemies\":[],\"rewards\":[\"5 Quest points\",\"200 Crafting XP\",\"A Gold Bar\"],\"sec\":[{\"n\":\"Prepare goblin mail\",\"st\":[{\"t\":\"You need three goblin mails, which you can find around the Goblin Village. The first is up the ladder in a crate in the south of the village.\"},{\"t\":\"The second goblin mail can be found in the west hut in a crate.\"},{\"t\":\"The last goblin mail is north of the generals' hut in a crate.\"},{\"t\":\"Use the blue dye on one of the goblin mail.\",\"i\":[\"Blue dye\",\"Goblin mail\"]},{\"t\":\"Use the orange dye on one of the goblin mail.\",\"i\":[\"Orange dye\",\"Goblin mail\"]}],\"i\":[\"Blue dye\",\"Orange dye\",\"Goblin mail (3)\"],\"c\":0},{\"n\":\"Present the armours\",\"st\":[{\"t\":\"Talk to one of the Goblin Generals in Goblin Village.\",\"s\":[\"Do you want me to pick an armour colour for you?\",\"What about a different colour?\",\"Yes.\",\"So how is life for the goblins?\",\"Yes, Wartface looks fat\",\"I have some orange armour here.\"],\"i\":[\"Orange goblin mail\"]},{\"t\":\"Talk to one of the Goblin Generals in Goblin Village again.\",\"s\":[\"So how is life for the goblins?\",\"I have some blue armour here.\"],\"i\":[\"Blue goblin mail\"]},{\"t\":\"Talk to one of the Goblin Generals in Goblin Village once more.\",\"s\":[\"So how is life for the goblins?\",\"Yes, Wartface looks fat\",\"I have some brown armour here.\"],\"i\":[\"Goblin mail\"]}],\"c\":0}]}"
        "Grim Tales" -> "{\"n\":\"Grim Tales\",\"items\":[\"Door key\",\"Tarromin potion (unf) (2)\",\"Seed dibber\",\"Watering can with at least 1 use\",\"Any axe\",\"Combat gear and food\"],\"rec\":[],\"enemies\":[\"Glod (level 138)\"],\"rewards\":[\"1 Quest point\",\"10,000 Farming XP\",\"15,000 Herblore XP\",\"5,000 Hitpoints XP\",\"60,000 Woodcutting XP\",\"25,000 Agility XP\",\"25,000 Thieving XP\",\"A Dwarven Helmet\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Talk to Sylas in Taverley.\",\"s\":[\"Yes.\"]}]},{\"n\":\"Griffin feather\",\"st\":[{\"t\":\"Talk to Grimgnash in the north east of White Wolf Mountain.\",\"s\":[\"I heard you were a great and mighty Griffin!\",\"There once was a graveyard filled with undead.\",\"There lived a skeleton named Skullrot.\",\"Skullrot was insane!\",\"Skullrot hungrily grabbed the gnome's hair.\",\"Started to strangle the poor gnome.\",\"He saw some bones lying in the corner.\"]},{\"t\":\"Steal a feather from Grimgnash.\"},{\"t\":\"Bring Sylas in Taverley a griffin feather.\",\"i\":[\"Griffin feather\"]}]},{\"n\":\"Rupert's helmet\",\"st\":[{\"t\":\"Climb over the crumbling wall of the tower south east of Goblin Village.\"},{\"t\":\"Talk to the drain pipe.\"},{\"t\":\"Talk to the drain pipe again.\",\"s\":[\"I could try and climb up.\",\"Is there anything up there that can help?\"]},{\"t\":\"Climb the beard.\"},{\"t\":\"Talk to Rupert the beard.\"},{\"t\":\"Climb down the beard.\"},{\"t\":\"Talk to Miazrqa.\",\"s\":[\"I see there is an embarrassed-looking dwarf...\",\"Your second-cousin, twice removed?\",\"I need a key for the house.\",\"I should be off, I think.\"]},{\"t\":\"Enter the witch's house.\",\"i\":[\"Door key\"]},{\"t\":\"Go down the ladder to the basement.\"},{\"t\":\"Play the piano. Press upper E-F-E-D-C, then lower A-E-G-A.\"},{\"t\":\"Right-click search the piano.\"},{\"t\":\"Add the shrunk ogleroot to both your tarromin potion (unf). You'll need the second potion for later in the quest.\",\"i\":[\"Tarromin potion (unf)\",\"Shrunk ogleroot\"]},{\"t\":\"Climb back up the ladder.\"},{\"t\":\"Stand in the south room and drink the shrink-me-quick potion.\",\"i\":[\"Shrink-me-quick\"]},{\"t\":\"Climb the nails in the north east of the room\"},{\"t\":\"Climb up the nails in the south west of the room.\"},{\"t\":\"Climb the nails in the south of the room.\"},{\"t\":\"Climb down the nails in the north east of the room.\"},{\"t\":\"Take the pendant and return to Miazrqa.\"},{\"t\":\"Return the pendant to Miazrqa.\",\"i\":[\"Miazrqa's pendant\"]},{\"t\":\"Talk to Rupert the beard to get his helmet.\"}],\"i\":[\"Tarromin potion (unf) (2)\",\"Door key\",\"Food\"]},{\"n\":\"Golden goblin\",\"st\":[{\"t\":\"Bring Sylas in Taverley Rupert's helmet.\",\"i\":[\"Rupert's helmet\"]},{\"t\":\"Plant the magic beans in the earth mound in south east Taverley\",\"i\":[\"Magic beans\",\"Seed dibber\",\"Watering can with at least 1 use\"]},{\"t\":\"Use your watering can on the magic beans you just planted in the earth mound\",\"i\":[\"Watering can with at least 1 use\"]},{\"t\":\"Climb the bean stalk, ready to fight Glod.\",\"i\":[\"Combat gear and food\"]},{\"t\":\"Kill Glod.\"},{\"t\":\"Pick up the golden goblin.\",\"i\":[\"Golden goblin\"]},{\"t\":\"Bring the golden goblin to Sylas in Taverley.\",\"i\":[\"Golden goblin\"]},{\"t\":\"Use a shrink potion on the bean stalk.\",\"i\":[\"Shrink-me-quick\",\"Any axe\"]},{\"t\":\"Chop down the bean stalk.\",\"i\":[\"Any axe\"]},{\"t\":\"Talk to Sylas in Taverley.\"}],\"i\":[\"Combat gear and food\",\"Food\",\"Seed dibber\",\"Watering can with at least 1 use\",\"Any axe\",\"Shrink-me-quick\"],\"c\":1,\"e\":[\"Glod (level 138)\"]}]}"
        "Haunted Mine" -> "{\"n\":\"Haunted Mine\",\"items\":[\"Combat gear\"],\"rec\":[\"Food\"],\"enemies\":[\"Treus Dayth (level 95)\"],\"rewards\":[\"2 Quest points\",\"22,000 Strength XP\",\"Ability to create the Salve Amulet\",\"Ability to access Tarn's Lair\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Talk to the Zealot outside the Abandoned Mine in south west Morytania.\",\"s\":[\"And what sort of purpose would that be?\",\"Yes.\",\"Is there any other way into the mines?\",\"I come seeking challenges and quests.\",\"I follow the path of Saradomin.\",\"What quest is that then?\"]},{\"t\":\"Pickpocket the Zealot outside the Abandoned Mine in south west Morytania.\"}],\"i\":[\"Combat gear\",\"Food\",\"Empty Inventory Spot (3)\"],\"c\":1},{\"n\":\"Getting a light source\",\"st\":[{\"t\":\"Enter the south cart tunnel around the back of the mine.\"},{\"t\":\"Climb down the ladder to the east.\"},{\"t\":\"Climb down another ladder to the east.\"},{\"t\":\"Go down the ladder to the south, making sure to avoid the moving mine cart.\"},{\"t\":\"Pick a glowing fungus.\"},{\"t\":\"Put the glowing fungus into the mine cart north west of the ladder.\",\"i\":[\"Glowing fungus\"]},{\"t\":\"Pull levers until the tracks are lined up to take the cart to the north west corner (the panel's map UI shows north as pointing to the right).\"},{\"t\":\"Check the Points Settings panel in the centre of the room. Click the 'Start' button in the interface.\"},{\"t\":\"Climb back up to the surface.\"}]},{\"n\":\"Getting the salve crystals\",\"st\":[{\"t\":\"Make sure you're prepared to fight Treus Dayth (level 95), then enter the north area of the Haunted Mine.\"},{\"t\":\"Climb down the west ladder.\"},{\"t\":\"Climb down the north east ladder.\"},{\"t\":\"Go down the north west ladder to collect the glowing fungus.\"},{\"t\":\"Search the mine cart for the glowing fungus.\",\"s\":[\"Take it.\"]},{\"t\":\"Take the fungus back upstairs.\"},{\"t\":\"Climb down the ladder in the room in the north east.\"},{\"t\":\"Pick up the chisel nearby.\",\"i\":[\"Chisel\"]},{\"t\":\"Use the Zealot's key on the water valve. Make sure you have some energy as you'll need to race to the lift afterwards.\",\"i\":[\"Zealot's key\"]},{\"t\":\"Race to the lift before the ghost turns off the valve.\"},{\"t\":\"Go down the east stairs.\"},{\"t\":\"Attempt to pick up the innocent-looking key. Treus Dayth (level 95) will spawn. Kill him.\"},{\"t\":\"Pick up the innocent-looking key.\"},{\"t\":\"Go back up to the flooded area.\"},{\"t\":\"Go down the west stairs.\"},{\"t\":\"Cut from a crystal outcrop with a chisel in the south room to finish the quest.\",\"i\":[\"Chisel\"]}],\"c\":1,\"e\":[\"Treus Dayth (level 95)\"]}]}"
        "Hazeel Cult" -> "{\"n\":\"Hazeel Cult\",\"items\":[],\"rec\":[\"Ardougne cloak for Monastery teleport\"],\"enemies\":[\"Alomone (level 13) if taking Ceril's side\"],\"rewards\":[\"1 Quest point\",\"1,500 Thieving XP\",\"2000 x (2,005 if siding with Ceril) Coins\",\"Hazeel's mark (if you sided with Hazeel)\",\"Carnillean armour (if you sided with Ceril)\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Talk to Ceril Carnillean in the south west of East Ardougne.\",\"s\":[\"What's wrong?\",\"Yes.\"]},{\"t\":\"Enter the cave south east of the Clock Tower entrance.\"},{\"t\":\"Talk to Clivet. You can choose to either side with him or with the Carnilleans.\",\"s\":[\"Alright, I've made my decision.\",\"Actually, I have no questions.\",\"I have no more questions.\",\"What do you mean?\"]}]},{\"n\":\"Siding with Hazeel\",\"st\":[{\"t\":\"Search a crate in the Carnillean's basement kitchen for a key.\"}]}]}"
        "Heroes' Quest" -> "{\"n\":\"Heroes' Quest\",\"items\":[\"Fishing rod\",\"Fishing bait\",\"Harralander potion (unf)\",\"Any pickaxe\",\"Ice gloves/Smiths gloves (i)\",\"Black full helm\",\"Black platebody\",\"Black platelegs\",\"A ranged or magic attack method\",\"Dusty key (obtainable in quest)\"],\"rec\":[\"Weapons, armour and food for the Ice Queen\",\"Varrock teleport\",\"Anti-dragon shield\",\"Burthorpe teleport (2)\",\"Taverley teleport (2)\",\"Varrock teleport (2)\",\"Port Sarim teleport (Explorer's ring 2/3/4, Amulet of Glory to Draynor) (2)\",\"Brimhaven teleport, or travel by boat from Ardougne/Port Sarim for 30gp\"],\"enemies\":[\"Ice Queen (level 111) for ice gloves\",\"Entrana firebird (level 2)\",\"Grip (level 26)\"],\"rewards\":[\"1 Quest point\",\"3,075 Attack XP\",\"3,075 Defence XP\",\"3,075 Strength XP\",\"2,075 Ranged XP\",\"3,075 Hitpoints XP\",\"2,725 Fishing XP\",\"2,825 Cooking XP\",\"1,575 Woodcutting XP\",\"1,575 Firemaking XP\",\"2,275 Smithing XP\",\"2,275 Mining XP\",\"1,325 Herblore XP\",\"Access to the Hero's Guild.\",\"Ability to use the Fountain of Rune.\",\"Ability to use Charge Dragonstone Jewellery scrolls.\",\"Ability to purchase and equip Dragon Battleaxes and Maces.\"],\"sec\":[{\"n\":\"Start the quest\",\"st\":[{\"t\":\"Talk to Achietties outside the Heroes' Guild, south of Burthorpe.\",\"s\":[\"I'm a hero, may I apply to join?\",\"I'll start looking for all those things then.\"]}],\"i\":[\"Burthorpe teleport\"]},{\"n\":\"Get the Lava Eel\",\"st\":[{\"t\":\"You need to get an oily rod. Talk to Gerrant in Port Sarim to get some slime.\",\"s\":[\"I want to find out how to catch a lava eel.\"]},{\"t\":\"Combine the harralander potion (unf) with the blamish snail slime.\",\"i\":[\"Harralander potion (unf)\",\"Blamish snail slime\"]},{\"t\":\"Use the Blamish oil on your fishing rod.\",\"i\":[\"Blamish oil\",\"Fishing rod\"]},{\"t\":\"Go to Taverley Dungeon. As you're 70 Agility, you don't need a dusty key.\",\"i\":[\"Oily fishing rod\",\"Fishing bait\"]},{\"t\":\"Fish a lava eel from the lava south of the blue dragons.\",\"i\":[\"Oily fishing rod\",\"Fishing bait\"]},{\"t\":\"Cook the Lava Eel at a range. You cannot fail this.\",\"i\":[\"Raw lava eel\"]}],\"i\":[\"Harralander potion (unf)\",\"Fishing rod\",\"Fishing bait\",\"Dusty Key\"],\"tr\":[\"Port Sarim teleport (Explorer's ring 2/3/4, Amulet of Glory to Draynor)\",\"Taverley teleport\"]},{\"n\":\"Get thieves' armband\",\"st\":[{\"t\":\"Talk to Katrine at the Black Arm Gang base in South west Varrock.\",\"s\":[\"Is there any way I can get the rank of master thief?\"]},{\"t\":\"Try to enter the house in east Brimhaven.\",\"s\":[\"Four leaved clover.\"]},{\"t\":\"Talk to Trobert inside.\",\"s\":[\"So can you help me get Scarface Pete's candlesticks?\",\"I volunteer to undertake that mission!\"]},{\"t\":\"Equip your black armour and enter the mansion in the north west of Brimhaven.\",\"i\":[\"Id papers\",\"Black full helm\",\"Black platebody\",\"Black platelegs\"]},{\"t\":\"Talk to Grip.\",\"i\":[\"Id papers\"]},{\"t\":\"Get a miscellaneous key from Grip then give it to your partner. Once you've done that, wait for your partner to enter the north east room of the mansion.After that, search the cupboard in the north room to lure Grip there. Your partner should kill them.\",\"s\":[\"So what do my duties involve?\",\"Anything I can do now?\",\"He won't notice me having a quick look.\"]},{\"t\":\"Pick up Grip's keyring\",\"i\":[\"Grip's keyring\"]},{\"t\":\"Use Grip's keyring on the treasure room door.\",\"i\":[\"Grip's keyring\"]},{\"t\":\"Search the chest in the treasure room for two candlesticks.\"},{\"t\":\"Give one of Pete's candlesticks to your partner. Afterwards, return to Katrine with Pete's candlestick\",\"s\":[\"I have a candlestick now.\"],\"i\":[\"Pete's candlestick\"]}],\"i\":[\"Black full helm\",\"Black platebody\",\"Black platelegs\"],\"tr\":[\"Varrock teleport (2)\",\"Brimhaven teleport, or travel by boat from Ardougne/Port Sarim for 30gp\"],\"c\":1,\"e\":[\"Grip (level 26)\"]},{\"n\":\"Get thieves' armband\",\"st\":[{\"t\":\"Head into the Phoenix Gang's base in south Varrock.\"},{\"t\":\"Talk to Straven.\"},{\"t\":\"Talk to Alfonse the Waiter in the restaurant in Brimhaven.\",\"s\":[\"Do you sell Gherkins?\"],\"i\":[\"A ranged or magic attack method\"]},{\"t\":\"You'll need your partner to give you a miscellaneous key.\",\"i\":[\"Miscellaneous key\"]},{\"t\":\"Talk to Charlie the Cook in the back of the restaurant.\",\"s\":[\"I'm looking for a gherkin...\",\"I want to steal Scarface Pete's candlesticks.\"]},{\"t\":\"Push the wall to enter Pete's garden.\"},{\"t\":\"Use the misc key on the door to the north west.\",\"i\":[\"Miscellaneous key\"]},{\"t\":\"Wait for your partner to lure Grip into the room next to yours, and kill him with magic/ranged. Afterwards, trade your partner for a candlestick.\"},{\"t\":\"Bring the candlestick back to Straven.\"}],\"i\":[\"A ranged or magic attack method\"],\"tr\":[\"Varrock teleport (2)\",\"Brimhaven teleport, or travel by boat from Ardougne/Port Sarim for 30gp\"],\"c\":1,\"e\":[\"Grip (level 26)\"]},{\"n\":\"Get ice gloves\",\"st\":[{\"t\":\"Head to White Wolf Mountain, and mine a rockslide in the northern part.\",\"i\":[\"Any pickaxe\"]},{\"t\":\"Take the south east ladder down.\"},{\"t\":\"Follow the tunnel south, then go up the ladder there.\"},{\"t\":\"Take the east ladder down.\"},{\"t\":\"Follow the path around until you reach a ladder, then climb it.\"},{\"t\":\"Take the north ladder down.\"},{\"t\":\"Kill the Ice Queen for ice gloves.\"}],\"i\":[\"Any pickaxe\"],\"tr\":[\"Taverley teleport\"],\"c\":1,\"e\":[\"Ice Queen (level 111) for ice gloves\"]},{\"n\":\"Get fire feather\",\"st\":[{\"t\":\"Travel to Entrana with the monks in Port Sarim.\",\"i\":[\"Ice gloves/Smiths gloves (i)\"]},{\"t\":\"Kill the entrana firebird on the north of Entrana.\",\"i\":[\"Ice gloves/Smiths gloves (i)\"]}],\"i\":[\"Ice gloves/Smiths gloves (i)\"],\"tr\":[\"Port Sarim teleport (Explorer's ring 2/3/4, Amulet of Glory to Draynor)\"],\"c\":1,\"e\":[\"Entrana firebird (level 2)\"]},{\"n\":\"Finish off\",\"st\":[{\"t\":\"Bring Achietties all the items to finish.\",\"i\":[\"Fire feather\",\"Thieves' armband\",\"Lava eel\"]}],\"i\":[\"Fire feather\",\"Thieves' armband\",\"Lava eel\"],\"tr\":[\"Burthorpe teleport\"]}]}"
        "His Faithful Servants" -> "{\"n\":\"His Faithful Servants\",\"items\":[\"Combat gear to kill all 6 Barrows Brothers\",\"Spade\"],\"rec\":[\"Barrows teleport\",\"Strange old lockpick\",\"Ghommal's hilt 2 or higher to remove prayer drain in crypts\"],\"enemies\":[\"Ahrim the Blighted (level 98)\",\"Dharok the Wretched (level 115)\",\"Guthan the Infested (level 115)\",\"Karil the Tainted (level 98)\",\"Torag the Corrupted (level 115)\",\"Verac the Defiled (level 115)\"],\"rewards\":[\"20,000 Prayer XP\",\"Crypt map, used to dispell minimap hiding in Barrows\"],\"sec\":[{\"n\":\"Helping Them\",\"st\":[{\"t\":\"Talk to the Strange Old Man at Barrows east of Burgh de Rott.\"},{\"t\":\"Defeat Dharok.\"},{\"t\":\"Defeat Ahrim.\"},{\"t\":\"Defeat Karil.\"},{\"t\":\"Defeat Guthan.\"},{\"t\":\"Defeat Torag.\"},{\"t\":\"Defeat Verac.\"},{\"t\":\"Enter the sarcophagus that was empty to enter the crypt.\"},{\"t\":\"Open the chest in the middle of the crypt. DO NOT SEARCH IT until you've killed the 6th brother.\"},{\"t\":\"Kill the final brother.\"},{\"t\":\"Search the chest in the middle of the crypt for the strange icon.\"},{\"t\":\"Return to the Strange Old Man with the strange icon.\",\"i\":[\"Strange icon\"]}],\"i\":[\"Combat gear to kill all 6 Barrows Brothers\",\"Spade\"],\"tr\":[\"Barrows teleport\"],\"r\":[\"Strange old lockpick\",\"Ghommal's hilt 2 or higher to remove prayer drain in crypts\"],\"c\":1}]}"
        "Holy Grail" -> "{\"n\":\"Holy Grail\",\"items\":[\"Excalibur\"],\"rec\":[\"Camelot Teleports (3)\",\"Ardougne Teleport (2)\",\"Draynor Teleport Tablet\",\"Falador Teleport\",\"Coins (60)\",\"Antipoison\",\"Food\",\"A weapon and armour (melee recommended)\"],\"enemies\":[\"Black Knight Titan (level 120)\"],\"rewards\":[\"2 Quest points\",\"11,000 Prayer XP\",\"15,300 Defence XP\",\"Access to the Fisher Realm.\",\"Ability to put King Arthur picture on the wall in the POH.\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Talk to King Arthur in Camelot Castle to start the quest.\",\"s\":[\"Tell me of this quest.\",\"Yes.\"]},{\"t\":\"Go upstairs and talk to Merlin.\"}]},{\"n\":\"Getting the Napkin\",\"st\":[{\"t\":\"Head to Port Sarim and talk to a monk of Entrana for passage to Entrana. Bank all combat gear.\"},{\"t\":\"Talk to the High Priest on Entrana.\",\"s\":[\"Ask about the Holy Grail Quest\",\"Ok, I will go searching.\"]},{\"t\":\"Talk to Galahad in his house west of McGrubor's Woods.\",\"s\":[\"I seek an item from the realm of the Fisher King.\"]}]},{\"n\":\"Getting the Magic Whistles\",\"st\":[{\"t\":\"Travel to Draynor Manor.\",\"i\":[\"Holy Table Napkin\"]},{\"t\":\"Enter Draynor Manor.\",\"i\":[\"Holy Table Napkin\"]},{\"t\":\"Go up the stairs in Draynor Manor.\",\"i\":[\"Holy Table Napkin\"]},{\"t\":\"Go up the second set of stairs in Draynor Manor.\",\"i\":[\"Holy Table Napkin\"]},{\"t\":\"Open the door to the Magic Whistles.\",\"i\":[\"Holy Table Napkin\"]},{\"t\":\"Pickup 2 Magic Whistles.\",\"i\":[\"Holy Table Napkin\"]}],\"i\":[\"Holy Table Napkin\"],\"tr\":[\"Draynor Teleport Tablet\"]},{\"n\":\"Fisher King Realm Pt.1\",\"st\":[{\"t\":\"Go to the tower on Karamja near gold mine west of Brimhaven.\",\"s\":[\"I'd like to go to Brimhaven.\"],\"i\":[\"Magic Whistles (2)\",\"Excalibur\"]},{\"t\":\"Blow the whistle once you are underneath of the tower.\",\"i\":[\"Magic Whistle (2)\",\"Excalibur\"]},{\"t\":\"Kill the Black Knight Titan with Excalibur. Melee is recommended as it has high Ranged and Magic defence. (You only need to deal the killing blow with excalibur!)\",\"i\":[\"Magic Whistles (2)\",\"Excalibur\"]},{\"t\":\"Talk to the fisherman by the river. After talking to him walk West to the castle.\",\"s\":[\"Any idea how to get into the castle?\"]},{\"t\":\"Pickup the grail bell outside of the castle. If it's not there, return to the fisherman and finish the conversation.\",\"s\":[\"Any idea how to get into the castle?\"],\"i\":[\"Grail Bell\"]},{\"t\":\"Ring the grail bell while standing directly north of the broken castle wall (Where you picked up the bell)\",\"i\":[\"Grail Bell\"]},{\"t\":\"Go up the stairs inside of the castle.\"},{\"t\":\"Talk to The Fisher King.\",\"s\":[\"You don't look too well.\"]}],\"i\":[\"Magic Whistles (2)\",\"Excalibur\"],\"r\":[\"Coins (30)\",\"Antipoison\"],\"c\":1,\"e\":[\"Black Knight Titan (level 120)\"]},{\"n\":\"Finding Percival\",\"st\":[{\"t\":\"Return to Camelot and talk to King Arthur.\",\"i\":[\"Empty Inventory Spot\"]},{\"t\":\"Travel to the Goblin Village, north of Falador. Right click and open the sacks.\",\"s\":[\"Come with me, I shall make you a king.\"],\"i\":[\"Magic Whistles (2)\"]}],\"i\":[\"Empty Inventory Spot\",\"Magic Whistles (2)\"]},{\"n\":\"Fisher King Realm Pt.2\",\"st\":[{\"t\":\"Go to the tower on Karamja near gold mine west of Brimhaven.\",\"s\":[\"I'd like to go to Brimhaven.\"],\"i\":[\"Magic Whistle\",\"Magic gold feather\"]},{\"t\":\"Blow the whistle once you are underneath of the tower.\",\"i\":[\"Magic Whistle\"]},{\"t\":\"Open the door to the castle and enter.\"},{\"t\":\"Go up the stairs to the east.\"},{\"t\":\"Climb the ladder on the second floor.\"},{\"t\":\"Pickup the Holy grail.\",\"i\":[\"Holy Grail\"]}],\"i\":[\"Magic Whistle\"],\"r\":[\"Coins (30)\",\"Antipoison\"]},{\"n\":\"Finishing up\",\"st\":[{\"t\":\"Return to Camelot and talk to King Arthur\",\"i\":[\"Holy Grail\"]}],\"i\":[\"Holy Grail\"]}]}"
        "Hopespear's Will" -> "{\"n\":\"Hopespear's Will\",\"items\":[\"Ghostspeak amulet\",\"Ring of Visibility\",\"Goblin potion\",\"Dramen or lunar staff\",\"Food and potions to defeat 5 enemies without armour, weapons, or magic\"],\"rec\":[\"Plain of mud sphere or charged Skills necklace\",\"90+ combat\"],\"enemies\":[\"Snothead (level 32)\",\"Snailfeet (level 56)\",\"Mosschin (level 88)\",\"Redeyes (level 121)\",\"Strongbones (level 184)\"],\"rewards\":[\"38,750 Prayer XP\"],\"sec\":[{\"n\":\"Obtaining the Goblin Bones\",\"st\":[{\"t\":\"Enter the Goblin Cave next to the Fishing Guild. A plain of mud sphere will teleport you inside the cave.\",\"i\":[\"Goblin potion\",\"Ring of Visibility\",\"Ghostspeak amulet\",\"Food and potions to defeat 5 enemies without armour, weapons, or magic\"]},{\"t\":\"Drink the goblin potion.\",\"i\":[\"Goblin potion\"]},{\"t\":\"Go down the stairs to the goblin temple.\"},{\"t\":\"Enter the door to the crypt.\"},{\"t\":\"Equip your ring and ghostspeak item and talk to the ghost in the crypt.\",\"s\":[\"Why are you here?\",\"I visited Yu'biusk.\",\"It was a wasteland.\",\"What favour?\",\"Yes.\"],\"i\":[\"Ring of Visibility\",\"Ghostspeak amulet\"]},{\"t\":\"Defeat Snothead WITHOUT using weapons, armour, or magic. He attacks using melee.\"},{\"t\":\"Defeat Snailfeet WITHOUT using weapons, armour, or magic. He attacks using melee and range.\"},{\"t\":\"Defeat Mosschin WITHOUT using weapons, armour, or magic. He attacks using melee and magic.\"},{\"t\":\"Defeat Redeyes WITHOUT using weapons, armour, or magic. He attacks using melee and magic, and lowers your attack, strength, and defence.\"},{\"t\":\"Defeat Strongbones WITHOUT using weapons, armour, or magic. He attacks using all 3 combat styles, lowers your attack, strength and defence. Ignore the level 29 Skoblins he spawns.\"}],\"i\":[\"Goblin potion\",\"Ring of Visibility\",\"Ghostspeak amulet\",\"Food and potions to defeat 5 enemies without armour, weapons, or magic\"],\"r\":[\"Plain of mud sphere or charged Skills necklace\"],\"c\":1,\"e\":[\"Snothead (level 32)\",\"Snailfeet (level 56)\",\"Mosschin (level 88)\",\"Redeyes (level 121)\",\"Strongbones (level 184)\"]},{\"n\":\"Freeing the Goblin Souls\",\"st\":[{\"t\":\"Take all five bones to Yu'Biusk. You must get there via fairy ring BLQ.\",\"i\":[\"Snothead bones\",\"Snailfeet bones\",\"Mosschin bones\",\"Redeyes bones\",\"Strongbones bones\"]},{\"t\":\"Bury Snothead's bone.\",\"i\":[\"Snothead bones\"]},{\"t\":\"Bury Snailfeet's bone.\",\"i\":[\"Snailfeet bones\"]},{\"t\":\"Bury Mosschin's bone.\",\"i\":[\"Mosschin bones\"]},{\"t\":\"Bury Redeyes' bone.\",\"i\":[\"Redeyes bones\"]},{\"t\":\"Bury Strongbones' bone.\",\"i\":[\"Strongbones bones\"]}],\"i\":[\"Dramen or lunar staff\",\"Snothead bones\",\"Snailfeet bones\",\"Mosschin bones\",\"Redeyes bones\",\"Strongbones bones\"],\"c\":1,\"e\":[\"Snothead (level 32)\",\"Snailfeet (level 56)\",\"Mosschin (level 88)\",\"Redeyes (level 121)\",\"Strongbones (level 184)\"]}]}"
        "Horror from the Deep" -> "{\"n\":\"Horror from the Deep\",\"items\":[\"Fire rune\",\"Air rune\",\"Water rune\",\"Earth rune\",\"Any sword you're willing to lose\",\"Any arrow\",\"Molten glass\",\"Tinderbox\",\"Hammer\",\"Steel nails (60)\",\"Plank (2)\",\"Swamp tar\",\"20+ casts of each element spell\"],\"rec\":[\"Games necklace\",\"Magic combat gear\",\"Food\",\"Prayer potions\"],\"enemies\":[\"Dagannoth (level 100)\",\"Dagannoth Mother (level 100)\"],\"rewards\":[\"2 Quest points\",\"4,662 Magic XP\",\"4,662 Strength XP\",\"4,662 Ranged XP\",\"A damaged God Book of your choice.\",\"Access to The Lighthouse\",\"Ability to receive Dagannoth as a Slayer task.\"],\"sec\":[{\"n\":\"Saving Jossik\",\"st\":[{\"t\":\"Talk to Larrissa outside the Lighthouse north of the Barbarian Outpost. You can get here by Fairy Ring (alp), by jumping over the bassalt rocks from the Barbarian Outpost, or from the Fremennik Province.\",\"s\":[\"With what?\",\"But how can I help?\",\"Okay, I'll help!\"]},{\"t\":\"Use a plank on the bridge east of the Lighthouse.\",\"i\":[\"Plank\",\"Steel nails (30)\",\"Hammer\"]},{\"t\":\"Use a plank on the other side of the bridge east of the Lighthouse.\",\"i\":[\"Plank\",\"Steel nails (30)\",\"Hammer\"]},{\"t\":\"Talk to Gunnjorn in the Barbarian Agility Course south of the lighthouse.\"},{\"t\":\"Unlock the Lighthouse.\",\"i\":[\"Lighthouse key\"]},{\"t\":\"Enter the Lighthouse.\"},{\"t\":\"Go to the top of the lighthouse.\"},{\"t\":\"Use swamp tar on the lighting mechanism.\",\"i\":[\"Swamp tar\"]},{\"t\":\"Use a tinderbox on the lighting mechanism.\",\"i\":[\"Tinderbox\"]},{\"t\":\"Use molten glass on the lighting mechanism.\",\"i\":[\"Molten glass\"]},{\"t\":\"Go to the basement of the lighthouse.\"},{\"t\":\"Use an air rune on the strange wall.\",\"i\":[\"Air rune\"]},{\"t\":\"Use a water rune on the strange wall.\",\"i\":[\"Water rune\"]},{\"t\":\"Use an earth rune on the strange wall.\",\"i\":[\"Earth rune\"]},{\"t\":\"Use a fire rune on the strange wall.\",\"i\":[\"Fire rune\"]},{\"t\":\"Use an arrow on the strange wall.\",\"i\":[\"Any arrow\"]},{\"t\":\"Use a sword on the strange wall. You will lose it.\",\"i\":[\"Any sword you're willing to lose\"]}],\"i\":[\"Hammer\",\"Steel nails (60)\",\"Plank (2)\",\"Molten glass\",\"Tinderbox\",\"Swamp tar\",\"Fire rune\",\"Air rune\",\"Water rune\",\"Earth rune\",\"Any sword you're willing to lose\",\"Any arrow\",\"20+ casts of each element spell\"]},{\"n\":\"Defeating the dagannoths\",\"st\":[{\"t\":\"Go through the strange wall, ready for fighting.\"},{\"t\":\"Talk to Jossik.\"},{\"t\":\"Defeat the dagannoth.\"},{\"t\":\"Defeat the Dagannoth mother. She can only be hurt by air spells when white, water spells when blue, earth spells when brown, fire spells when red, melee when orange and ranged when green.\",\"i\":[\"Magic combat gear\",\"20+ casts of each element spell\"]}],\"i\":[\"20+ casts of each element spell\"],\"c\":1,\"e\":[\"Dagannoth (level 100)\",\"Dagannoth Mother (level 100)\"]}]}"
        "Icthlarin's Little Helper" -> "{\"n\":\"Icthlarin's Little Helper\",\"items\":[\"Any cat or kitten\",\"Tinderbox\",\"Coins or more for various payments (600)\",\"Bag of Salt from a Slayer Master, or an empty bucket to get some\",\"Willow logs\",\"Bucket of sap\",\"Waterskin(4), bring a few to avoid drinking it\",\"1 x Linen or 30 coins to buy some\"],\"rec\":[\"Combat equipment\",\"Food\",\"Prayer potions\",\"Antipoison\"],\"enemies\":[\"Level 75 or 81 guardian\",\"Possessed priest (level 91)\"],\"rewards\":[\"2 Quest points\",\"4,500 Thieving XP\",\"4,000 Agility XP\",\"4,000 Woodcutting XP\",\"Catspeak Amulet\",\"Access to the city of Sophanem.\",\"Ability to take carpet rides from Pollnivneach to Sophanem and Menaphos.\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Talk to the Wanderer west of the Agility Pyramid.\",\"s\":[\"Yes.\",\"Why? What's your problem with it?\",\"Ok I'll get your supplies.\"],\"i\":[\"Waterskin(4), bring a few to avoid drinking it\",\"Tinderbox\"]},{\"t\":\"Talk to the Wanderer again with the required items.\",\"s\":[\"Yes. I have them all here.\"],\"i\":[\"Waterskin(4), bring a few to avoid drinking it\",\"Tinderbox\"]}],\"i\":[\"Any cat or kitten\",\"Waterskin(4), bring a few to avoid drinking it\",\"Tinderbox\",\"Coins or more for various payments (600)\",\"Bag of Salt from a Slayer Master, or an empty bucket to get some\",\"Willow logs\",\"Bucket of sap\"]},{\"n\":\"Remembering\",\"st\":[{\"t\":\"Enter the pyramid in the south of Sophanem.\"},{\"t\":\"Follow the path until you reach a pit, and jump it. Move using the minimap to avoid all the traps.\"},{\"t\":\"Attempt to open the western door.\"}]},{\"n\":\"Returning the jar\",\"st\":[{\"t\":\"Talk to the Sphinx in Sophanem with your cat, and answer its riddle with '9.'.\",\"s\":[\"I need help.\",\"Okay, that sounds fair.\",\"9.\",\"Totally positive.\"]},{\"t\":\"Talk to the High Priest in the south west of Sophanem.\",\"i\":[\"Sphinx's token\"]},{\"t\":\"Enter the pyramid in the south of Sophanem.\"},{\"t\":\"Follow the path again until you reach a pit, and jump it. Move using the minimap to avoid all the traps.\"},{\"t\":\"Try picking up the canopic jars in the north west room until a level 75-81 enemy spawns. Kill them. You can safespot them on the central table.\"},{\"t\":\"Try picking up the canopic jars in the north west room again.\"},{\"t\":\"Jump back over the pit with the jar.\"},{\"t\":\"Jump back over to the north side of the pit. Move using the minimap to avoid all the traps inside the pyramid.\"},{\"t\":\"Solve the door puzzle again.\"},{\"t\":\"Drop the canopic jar in the spot you took it from.\",\"i\":[\"Canopic jar\"]},{\"t\":\"Leave the pyramid and return to the High Priest.\"}],\"i\":[\"Combat equipment\",\"Food\",\"Any cat or kitten\"],\"c\":1},{\"n\":\"Prepare the ritual\",\"st\":[{\"t\":\"Talk to the Embalmer just south of the High Priest.\",\"i\":[\"Bag of Salt from a Slayer Master, or an empty bucket to get some\",\"Bucket of sap\"]},{\"t\":\"Get some linen. You can buy some from Raetul in east Sophanem for 30 coins.\",\"i\":[\"Coins (30)\"]},{\"t\":\"Talk to the Embalmer again just south of the High Priest.\",\"i\":[\"Bag of Salt from a Slayer Master, or an empty bucket to get some\",\"Linen\",\"Bucket of sap\"]},{\"t\":\"Talk to the Carpenter in the east of Sophanem until he gives you the holy symbol.\",\"s\":[\"Alright, I'll get the wood for you.\"],\"i\":[\"Willow logs\"]}],\"i\":[\"Bucket of sap\",\"Bag of Salt from a Slayer Master, or an empty bucket to get some\",\"1 x Linen or 30 coins to buy some\",\"Willow logs\"]},{\"n\":\"Save the ritual\",\"st\":[{\"t\":\"Enter the pyramid in the south of Sophanem.\",\"i\":[\"Holy symbol\"]},{\"t\":\"Follow the path again until you reach a pit, and jump it. Move using the minimap to avoid all the traps.\",\"i\":[\"Holy symbol\"]},{\"t\":\"Enter the east room.\"},{\"t\":\"Use the unholy symbol on a sarcophagus.\",\"i\":[\"Unholy symbol\"]},{\"t\":\"Leave the east room.\"},{\"t\":\"Jump over the pit.\",\"i\":[\"Holy symbol\"]},{\"t\":\"Enter the east room again.\"},{\"t\":\"Kill the possessed priest. Pray protect from magic against the priest.\"},{\"t\":\"Talk to the High Priest in the north east room of the pyramid.\"},{\"t\":\"Leave the pyramid and witness a cutscene at the exit.\"},{\"t\":\"Return to the High Priest in the south west of Sophanem to finish the quest.\"}],\"i\":[\"Combat equipment\",\"Food\",\"Any cat or kitten\"],\"c\":1,\"e\":[\"Possessed priest (level 91)\"]}]}"
        "Imp Catcher" -> "{\"n\":\"Imp Catcher\",\"items\":[\"Black bead\",\"White bead\",\"Red bead\",\"Yellow bead\"],\"rec\":[],\"enemies\":[\"Imps (level 2) if you plan on collecting the beads yourself\"],\"rewards\":[\"1 Quest point\",\"875 Magic XP\",\"An Amulet of Accuracy\"],\"sec\":[{\"n\":\"Bring Mizgog his beads\",\"st\":[{\"t\":\"Collect one of each bead. You can kill imps for these beads, or buy them on the Grand Exchange.\",\"i\":[\"Black bead\",\"White bead\",\"Red bead\",\"Yellow bead\"]},{\"t\":\"Head to the Wizards' Tower and climb up the staircase with the required beads.\",\"i\":[\"Black bead\",\"White bead\",\"Red bead\",\"Yellow bead\"]},{\"t\":\"Talk to Wizard Mizgog with the required beads to finish the quest.\",\"s\":[\"Give me a quest please.\",\"Yes.\"],\"i\":[\"Black bead\",\"White bead\",\"Red bead\",\"Yellow bead\"]}],\"i\":[\"Black bead\",\"White bead\",\"Red bead\",\"Yellow bead\"],\"c\":1,\"e\":[\"Imps (level 2) if you plan on collecting the beads yourself\"]}]}"
        "In Aid of the Myreque" -> "{\"n\":\"In Aid of the Myreque\",\"items\":[\"Food to put in a chest, multiple pieces in case a Ghast eats some\",\"Spade\",\"buckets (Can use 1 but is much slower) (5)\",\"Any pickaxe\",\"Hammer\",\"Plank (11)\",\"Any nails (44)\",\"Swamp paste (2)\",\"10 Raw mackerel or raw snail meat (random for each player)\",\"Bronze axe (10)\",\"Tinderbox (4)\",\"Steel bar (2)\",\"Coal\",\"Silver weapon (including Silverlight + varieties), blessed axe or Efaritay's Aid to damage vampyres\",\"Soft clay\",\"Rope\",\"Silver bar\",\"Mithril bar\",\"Sapphire\",\"Cosmic rune\",\"Water rune\"],\"rec\":[\"Steel med helm\",\"Steel chainbody\",\"Steel platelegs\",\"Silver sickle\",\"Teleports to Mort'ton (minigame tele, teleport scroll)\",\"Canifis teleports (ancients spell, nearby fairy ring bip)\"],\"enemies\":[\"Gadderanks (level 35)\",\"Vampyre Juvinates (levels 50-75)\"],\"rewards\":[\"2 Quest points\",\"2,000 Attack XP\",\"2,000 Strength XP\",\"2,000 Crafting XP\",\"2,000 Defence XP\",\"Access to Temple Trekking Minigame.\",\"Ability to make the Rod of Ivandis\"],\"sec\":[{\"n\":\"Finding a new base\",\"st\":[{\"t\":\"Enter the Myreque Hideout under the Canifis Pub and talk to Veliaf to start.\"},{\"t\":\"Travel to Burgh de Rott, south of Mort'ton, and talk to Florin at the entrance.\"},{\"t\":\"Place some food in the nearby chest.\",\"i\":[\"Any food\"]},{\"t\":\"Talk to Razvan in Burgh de Rott.\",\"s\":[\"Are there any 'out of the way' places here?\"]},{\"t\":\"Use a pickaxe on the rubble in the building south of Razvan.\",\"s\":[\"Yes.\"],\"i\":[\"Any pickaxe\"]},{\"t\":\"Enter the trapdoor.\"},{\"t\":\"Mine all the rubble in the room, and then clean it up with a spade. You'll need an empty bucket when using the spade. You can empty the buckets outside on the rubble pile.\",\"i\":[\"Any pickaxe\",\"Spade\",\"Bucket\"]}],\"i\":[\"Food to put in a chest, multiple pieces in case a Ghast eats some\",\"Any pickaxe\",\"buckets (Can use 1 but is much slower) (5)\",\"Spade\"]},{\"n\":\"Repairing the shop\",\"st\":[{\"t\":\"Talk to Aurel in north east Burgh de Rott.\",\"s\":[\"I'd like to help fix up the town.\"]},{\"t\":\"Go to the roof of Aurel's shop.\",\"i\":[\"Hammer\",\"Plank (3)\",\"Nails (12)\"]},{\"t\":\"Repair the broken roof.\",\"s\":[\"Yes.\"],\"i\":[\"Hammer\",\"Plank (3)\",\"Nails (12)\"]},{\"t\":\"Climb back down the ladder.\"},{\"t\":\"Repair the shop's wall.\",\"s\":[\"Yes.\"],\"i\":[\"Hammer\",\"Plank (3)\",\"Nails (12)\"]},{\"t\":\"Talk to Aurel again.\",\"s\":[\"What should I do now?\"]}],\"i\":[\"Hammer\",\"Plank (6)\",\"Nails (24)\"]},{\"n\":\"Repairing the bank\",\"st\":[{\"t\":\"Return to Aurel with the filled crate.\",\"i\":[\"Crate\"]},{\"t\":\"Repair the bank booth.\",\"s\":[\"Yes.\"],\"i\":[\"Hammer\",\"Plank (2)\",\"Swamp paste (2)\",\"Nails (8)\"]},{\"t\":\"Repair the bank's outside wall.\",\"s\":[\"Yes.\"],\"i\":[\"Hammer\",\"Plank (3)\",\"Nails (12)\"]},{\"t\":\"Talk to Cornelius and ask him to be the banker.\",\"s\":[\"What should I do now?\"]}],\"i\":[\"Hammer\",\"Plank (5)\",\"Nails (20)\",\"Swamp paste (2)\"]},{\"n\":\"Repairing the furnace\",\"st\":[{\"t\":\"Talk to Razvan.\",\"s\":[\"What should I do now?\"]},{\"t\":\"Repair the furnace in the south east of Burgh de Rott. You can use the bank you just made to get items out.\",\"s\":[\"Yes.\"],\"i\":[\"Hammer\",\"Steel bar (2)\",\"Coal\",\"Tinderbox\"]},{\"t\":\"Add coal to the furnace.\",\"s\":[\"Yes.\"],\"i\":[\"Coal\",\"Tinderbox\"]},{\"t\":\"Light the furnace.\",\"s\":[\"Yes.\"],\"i\":[\"Tinderbox\"]}],\"i\":[\"Hammer\",\"Steel bar (2)\",\"Coal\",\"Tinderbox\"]},{\"n\":\"Defending Burgh de Rott\",\"st\":[{\"t\":\"Talk to Gadderanks in the shop.\"},{\"t\":\"Talk to a juvinate in the shop.\"},{\"t\":\"Talk to Wiskit in the shop. Be prepared to fight the vampyres and Gadderanks.\",\"i\":[\"Silver weapon (including Silverlight + varieties), blessed axe or Efaritay's Aid to damage vampyres\"]},{\"t\":\"Defeat Gadderanks and the juvinates.\",\"i\":[\"Silver weapon (including Silverlight + varieties), blessed axe or Efaritay's Aid to damage vampyres\"]},{\"t\":\"Talk to Gadderanks.\"},{\"t\":\"Talk to Veliaf in Burgh de Rott.\"}],\"i\":[\"Silver weapon (including Silverlight + varieties), blessed axe or Efaritay's Aid to damage vampyres\"],\"c\":1,\"e\":[\"Gadderanks (level 35)\"]},{\"n\":\"Relocating\",\"st\":[{\"t\":\"Return the Myreque Hideout under the Canifis Pub and talk to Veliaf there. Bank any followers before going.\"},{\"t\":\"Talk to Polmafi in the Myreque Hideout.\"},{\"t\":\"Talk to Ivan in the Myreque Hideout to temple trek with him. The long route has 4 level 50 Juvinates and the short route has 2 level 75 Juvinates. You can give him a steel med helm / chainbody / platelegs, and salmon to help him survive.\"}],\"i\":[\"Silver weapon (including Silverlight + varieties), blessed axe or Efaritay's Aid to damage vampyres\"],\"r\":[\"Steel med helm\",\"Steel chainbody\",\"Steel platelegs\",\"Silver sickle\"],\"c\":1},{\"n\":\"Ivandis' legacy\",\"st\":[{\"t\":\"Talk to Drezel under the Paterdomus Temple.\",\"s\":[\"Veliaf told me about Ivandis.\",\"Is there somewhere that I might get more information on Ivandis?\",\"The lives of those pitiful few left in Morytania could rest on this!\"]},{\"t\":\"Use the key on the keyhole near Drezel.\",\"i\":[\"Temple library key\"]},{\"t\":\"Enter the library.\"},{\"t\":\"Search the bookcases for 'The Sleeping Seven' book.\"},{\"t\":\"Read 'The Sleeping Seven'.\",\"i\":[\"The sleeping seven\"]},{\"t\":\"Enter the trapdoor behind the Canifis pub.\"},{\"t\":\"Use a hammer on the boarded up cave.\",\"s\":[\"Yes.\"],\"i\":[\"Hammer\"]},{\"t\":\"Enter the cave.\"},{\"t\":\"Use a piece of soft clay on the coffin.\",\"i\":[\"Soft clay\"]},{\"t\":\"Make a silvthrill rod at any furnace.\",\"i\":[\"Rod mould\",\"Mithril bar\",\"Silver bar\",\"Sapphire\"]},{\"t\":\"Cast Lvl-1 enchant on the rod.\",\"i\":[\"Silvthrill rod\",\"Water rune\",\"Cosmic rune\"]},{\"t\":\"Go use the Silvthrill rod on the well in Paterdomus.\"},{\"t\":\"Bring the rod to Veliaf in the Burgh de Rott pub's basement to finish the quest.\"}],\"i\":[\"Hammer\",\"Soft clay\",\"Mithril bar\",\"Silver bar\",\"Cosmic rune\",\"Water rune\",\"Rope\",\"Sapphire\"]}]}"
        "In Search of Knowledge" -> "{\"n\":\"In Search of Knowledge\",\"items\":[\"Knife or slash weapon to cut through a web\",\"Food (5)\",\"Combat gear\"],\"rec\":[],\"enemies\":[\"Many monsters in the Forthos Dungeon\"],\"rewards\":[\"10,000 Experience Lamp (any skill over level 40).\"],\"sec\":[{\"n\":\"Helping Aimeri\",\"st\":[{\"t\":\"Enter the Forthos Dungeon.\",\"i\":[\"Knife or slash weapon to cut through a web\",\"Food (5)\"]},{\"t\":\"Talk to Aimeri again.\",\"s\":[\"Who are you?\"]}],\"i\":[\"Knife or slash weapon to cut through a web\",\"Food (5)\",\"Combat gear\"],\"c\":1},{\"n\":\"Getting the books\",\"st\":[{\"t\":\"Search the musty bookshelves to the west of Aimeri for the tomes of moon, sun, and temple.\"}]},{\"n\":\"Repairing the books\",\"st\":[{\"t\":\"Kill any monsters in the Forthos Dungeon for pages for the tomes. You'll need to use 4 pages on each tome.\",\"i\":[\"Combat gear\"]}],\"i\":[\"Combat gear\"],\"c\":1},{\"n\":\"Document the Tomes\",\"st\":[{\"t\":\"Give the tomes to Logosia in the Arceuus library.\",\"i\":[\"Tome of the moon\"]}],\"i\":[\"Tome of the moon\",\"Tome of the sun\",\"Tome of the temple\"]}]}"
