        "Jungle Potion" -> "{\"n\":\"Jungle Potion\",\"items\":[],\"rec\":[\"Food\",\"Antipoison\",\"Teleport to Karamja (Glory/house teleport)\"],\"enemies\":[\"Survive against level 53 Jogres and level 46 Harpie Bug Swarms.\"],\"rewards\":[\"1 Quest point\",\"775 Herblore XP\"],\"sec\":[{\"n\":\"Snake Weed\",\"st\":[{\"t\":\"Search a marshy jungle vine south of Tai Bwo Wannai for some snake weed.\"}]},{\"n\":\"Ardrigal\",\"st\":[{\"t\":\"Search the palm trees north east of Tai Bwo Wannai for an Ardrigal herb.\"}]},{\"n\":\"Sito Foil\",\"st\":[{\"t\":\"Search the scorched earth in the south of Tai Bwo Wannai for a Sito Foil herb.\"}]},{\"n\":\"Volencia Moss\",\"st\":[{\"t\":\"Search the rock for a Volencia Moss herb at the mine south east of Tai Bwo Wannai.\"}]},{\"n\":\"Rogues Purse\",\"st\":[{\"t\":\"Enter the cave to the north by clicking on the rocks.\",\"s\":[\"Yes, I'll enter the cave.\"]},{\"t\":\"Get the Rogues Purse from the fungus covered wall in the underground dungeon.\"}]}]}"
        "King's Ransom" -> "{\"n\":\"King's Ransom\",\"items\":[\"Runes for telekinetic grab or a lockpick\",\"Any granite\",\"Black full helm\",\"Black platebody\",\"Black platelegs\",\"Bronze med helm\",\"Iron chainbody\",\"Animate rock scroll\"],\"rec\":[\"Ardougne teleport\",\"Camelot teleport (3)\",\"Monastery with Combat Bracelet or Edgeville glory teleport\"],\"enemies\":[],\"rewards\":[\"1 Quest point\",\"33,000 Defence XP\",\"5,000 Magic XP\",\"5,000 Experience Lamp (any skill over 50).\"],\"sec\":[{\"n\":\"Investigating\",\"st\":[{\"t\":\"Talk to Gossip, just south of the Sinclair Mansion.\",\"s\":[\"Yes.\",\"How curious. Maybe I should investigate it.\"]},{\"t\":\"Talk to the Guard in the Sinclair Manor.\"},{\"t\":\"Right-click break the east window of the mansion, and enter it.\"},{\"t\":\"Pick up the scrap paper.\",\"i\":[\"Scrap paper\"]},{\"t\":\"Go upstairs.\"},{\"t\":\"Pick up the address form.\",\"i\":[\"Address form\"]},{\"t\":\"Search the west bookcase for a black knight helm.\"},{\"t\":\"Go down the staircase.\"},{\"t\":\"Step out of the window.\"},{\"t\":\"Return to the guard with the 3 items.\",\"s\":[\"I have proof that the Sinclairs have left.\",\"I have proof that links the Sinclairs to Camelot.\",\"I have proof of foul play.\"]},{\"t\":\"Ask Gossip all 3 chat options.\"}],\"c\":0},{\"n\":\"Freeing Anna\",\"st\":[{\"t\":\"Talk to Anna in the Seers' Village Court House.\",\"s\":[\"Okay, I guess I don't have much of a choice.\"]},{\"t\":\"Go down the stairs to the court room.\",\"s\":[\"Yes, I'm ready.\"]},{\"t\":\"Talk to the judge to call the Dog Handler and ask them about the poison.\",\"s\":[\"Dog handler\",\"Previous page\"]},{\"t\":\"Talk to the judge to call the Butler and ask them about the dagger.\",\"s\":[\"Butler\",\"Previous page\"]},{\"t\":\"Talk to the judge to call the Maid and ask them about the night of the murder.\",\"s\":[\"Maid\",\"Next page\"]},{\"t\":\"Ask anyone about the thread.\",\"s\":[\"Ask about the thread\"]},{\"t\":\"Leave the court room.\"}],\"c\":0},{\"n\":\"Saving Merlin and Knights\",\"st\":[{\"t\":\"Search the statue east of Camelot.\",\"i\":[\"Runes for telekinetic grab or a lockpick\"]},{\"t\":\"Talk to Merlin.\",\"s\":[\"What do we do now?\"]},{\"t\":\"Reach for the vent on the north wall.\"},{\"t\":\"Use telekinetic grab on the guard grooming their hair.\",\"i\":[\"Law rune\",\"Air rune\"]},{\"t\":\"Attempt to open the cell door.\",\"i\":[\"Hair clip or Lockpick\"]},{\"t\":\"Pick the door's lock.\"},{\"t\":\"Climb to the top of the keep.\"},{\"t\":\"Search the table and take the purple round box.\"},{\"t\":\"Talk to Wizard Cromperty in East Ardougne.\",\"s\":[\"Chat.\"]}],\"i\":[\"Runes for telekinetic grab or a lockpick\"],\"c\":0},{\"n\":\"Saving Arthur\",\"st\":[{\"t\":\"Enter the Black Knight Fortress wearing the bronze med helm and iron chainbody.\",\"i\":[\"Bronze med helm\",\"Iron chainbody\",\"Black full helm\",\"Black platebody\",\"Black platelegs\",\"Animate rock scroll\",\"Holy grail\",\"Any granite\"]},{\"t\":\"Enter the secret room wearing the black knight armour.\",\"i\":[\"Black full helm\",\"Black platebody\",\"Black platelegs\",\"Animate rock scroll\",\"Holy grail\",\"Any granite\"]},{\"t\":\"Enter the Black Knight Fortress basement.\"},{\"t\":\"Free King Arthur by using the animate rock scroll.\",\"i\":[\"Animate rock scroll\",\"Holy grail\",\"Any granite\"]},{\"t\":\"Talk to King Arthur in the basement.\",\"i\":[\"Bronze med helm\",\"Iron chainbody\"]},{\"t\":\"Talk to King Arthur in Camelot to finish the quest.\"}],\"i\":[\"Bronze med helm\",\"Iron chainbody\",\"Black full helm\",\"Black platebody\",\"Black platelegs\",\"Any granite\",\"Animate rock scroll\"],\"c\":0}]}"
        "Land of the Goblins" -> "{\"n\":\"Land of the Goblins\",\"items\":[\"Light source\",\"Toadflax potion (unf)\",\"Goblin mail\",\"Yellow dye\",\"Blue dye\",\"Orange dye\",\"Purple dye\",\"Pestle and mortar\",\"Vial\",\"Fishing rod\",\"Raw slimy eel\",\"Coins (5)\",\"Combat gear\"],\"rec\":[\"Tinderbox\",\"Dorgesh-Kaan sphere (2)\",\"Dramen staff\",\"Skills necklace (3)\",\"Combat bracelet\",\"Lumbridge teleport (2)\",\"Draynor Village teleport (2)\",\"Explorer's ring 3 or 4\"],\"enemies\":[\"Snothead (level 32)\",\"Snailfeet (level 56)\",\"Mosschin (level 88)\",\"Redeyes (level 121)\",\"Strongbones (level 184)\"],\"rewards\":[\"2 Quest points\",\"8,000 Agility XP\",\"8,000 Fishing XP\",\"8,000 Thieving XP\",\"8,000 Herblore XP\",\"Access to the Goblin Temple\",\"Access to Yu'Biusk (with fairy ring code BLQ)\",\"Ability to purchase plain of mud spheres\",\"Ability to make goblin potions\"],\"sec\":[{\"n\":\"Grubfoot's Dream\",\"st\":[{\"t\":\"Talk to Grubfoot in the Dorgeshuun Mines.\"},{\"t\":\"Enter the city of Dorgesh-Kaan.\"},{\"t\":\"Talk to Zanik in Oldak's lab.\",\"s\":[\"So why have you come to talk to Zanik?\",\"What was this new dream?\",\"It's just a dream. It doesn't mean anything.\",\"I think it must mean something.\",\"I don't know.\",\"I'm ready.\"]}],\"i\":[\"Light source\"]},{\"n\":\"Impostor Among Goblins\",\"st\":[{\"t\":\"Enter the Goblin Cave next to the Fishing Guild.\"},{\"t\":\"Talk to Zanik and get her to follow you.\",\"s\":[\"Follow me.\"]},{\"t\":\"Talk to the goblin guard in the northwest of the cave.\"},{\"t\":\"Talk to the Makeover Mage southwest of Falador.\",\"s\":[\"Can you turn me into a goblin?\",\"I need to slip past some goblin guards.\",\"Can you turn me into a goblin or not?\"],\"i\":[\"Toadflax potion (unf)\"]},{\"t\":\"Pick some Pharmakos berries from the bushes outside.\",\"i\":[\"Toadflax potion (unf)\"]},{\"t\":\"Use the pharmakos berries on the unfinished toadflax potion.\",\"i\":[\"Pharmakos berries\",\"Toadflax potion (unf)\"]}],\"i\":[\"Toadflax potion (unf)\"],\"r\":[\"Skills necklace (3)\",\"Inventory space to unequip all your items\"]},{\"n\":\"The Temple of Tribes\",\"st\":[{\"t\":\"Go back to the Goblin Cave outside the Fishing Guild.\",\"i\":[\"Goblin potion\",\"Vial\",\"Pestle and mortar\"]},{\"t\":\"Go to the area outside the temple near the guards.\",\"i\":[\"Goblin potion\"]},{\"t\":\"Pick some black mushrooms and use it on a vial to make black dye.\",\"i\":[\"Goblin potion\",\"Vial\",\"Pestle and mortar\"]},{\"t\":\"Make black dye by using the blackmushrooms on a vial.\",\"i\":[\"Black mushroom\",\"Vial\",\"Pestle and mortar\"]},{\"t\":\"Drink the goblin potion.\",\"i\":[\"Goblin potion\"]},{\"t\":\"Talk to the goblin guard to enter the temple. If you want, you can tell them to guess your name until you get one you like.\",\"s\":[\"Me want get into temple.\",\"Yes.\",\"Me want get into temple.\",\"Yes.\"],\"i\":[\"Black dye\"]},{\"t\":\"Use the black dye on the goblin mail.\",\"i\":[\"Black dye\",\"Goblin mail\"]},{\"t\":\"Pass by the guard to the northeastern room. WARNING: If you teleport away with a full inventory and while wearing the goblin mail, it will be DESTROYED.\",\"i\":[\"Black goblin mail\"]},{\"t\":\"Search the crate for a Dorgesh-Kaan sphere.\"},{\"t\":\"Talk to Zanik in the cell.\",\"i\":[\"Dorgesh-Kaan sphere\"]},{\"t\":\"Pass by the guard to leave the northeastern room.\"},{\"t\":\"Talk to High Priest Bighead. When prompted, answer in this order: True, False, False.\",\"s\":[\"Yes.\",\"I understand Big High War God.\",\"Big High War God commands it.\",\"Goblins not mighty warriors before he chose us.\",\"That one of the commandments.\",\"Lead goblins to victory over whole world.\",\"Me want to know about Yu'biusk.\",\"Where is Yu'biusk?\",\"Can I talk to old high priests?\"]},{\"t\":\"Pass by the guard to the northeastern room again.\",\"i\":[\"Black goblin mail\"]},{\"t\":\"Pickpocket a key from the priest.\"}],\"i\":[\"Goblin potion\",\"Vial\",\"Pestle and mortar\",\"Goblin mail\"],\"r\":[\"Skills necklace\",\"Inventory space to unequip all your items\",\"Dorgesh-Kaan sphere (2)\"]},{\"n\":\"Keys to the Crypt\",\"st\":[{\"t\":\"Talk to Aggie in Draynor Village.\",\"s\":[\"Draynor Village\",\"Can you make dyes for me, please?\",\"Can you make black or white dye?\",\"Thanks.\"]},{\"t\":\"Go to Hemenster to catch a whitefish.\",\"s\":[\"Ranging Guild\",\"I need to catch a Hemenster Whitefish.\"],\"i\":[\"Fishing rod\",\"Raw slimy eel\"]},{\"t\":\"Catch a Hemenster whitefish.\",\"i\":[\"Fishing rod\",\"Raw slimy eel\"]},{\"t\":\"Bring the whitefish and black goblin mail to Aggie.\",\"s\":[\"Draynor Village\",\"Can you make dyes for me, please?\",\"Could you remove the dye from this goblin mail?\"],\"i\":[\"Coins (5)\",\"Whitefish\",\"Black goblin mail\"]},{\"t\":\"Return to the goblin temple with all the dyes and some combat gear.\"},{\"t\":\"Pickpocket the priest in the western room for the Saragorak key.\"},{\"t\":\"Use the yellow dye on your goblin mail. It is safe to unequip the goblin mail inside the enclave, you will be thrown out to the center area.\",\"i\":[\"Yellow dye\",\"Goblin mail\"]},{\"t\":\"Pickpocket the priest in the north-western room for the Yurkolgokh key.\"},{\"t\":\"Use the blue dye on your goblin mail. It is safe to unequip the goblin mail inside the enclave, you will be thrown out to the center area.\",\"i\":[\"Blue dye\",\"Goblin mail\"]},{\"t\":\"Pickpocket the priest in the eastern room for the Ekeleshuun key.\"},{\"t\":\"Use the orange dye on your goblin mail. It is safe to unequip the goblin mail inside the enclave, you will be thrown out to the center area.\",\"i\":[\"Orange dye\",\"Goblin mail\"]},{\"t\":\"Pickpocket the priest in the south-eastern room for the Narogoshuun key.\"},{\"t\":\"Use the purple dye on your goblin mail. It is safe to unequip the goblin mail inside the enclave, you will be thrown out to the center area.\",\"i\":[\"Purple dye\",\"Goblin mail\"]},{\"t\":\"Pickpocket the priest in the south-western room for the Horogothgar key.\"},{\"t\":\"Unlock the door using the 6 keys. You may leave to gear up after unlocking it.\",\"i\":[\"Huzamogaarb key\",\"Saragorgak key\",\"Yurkolgokh key\",\"Ekeleshuun key\",\"Narogoshuun key\",\"Horogothgar key\"]}],\"i\":[\"Fishing rod\",\"Raw slimy eel\",\"Coins (5)\",\"Yellow dye\",\"Blue dye\",\"Orange dye\",\"Purple dye\",\"Black goblin mail\",\"Goblin potion\",\"Huzamogaarb key\",\"Combat gear\"],\"tr\":[\"Draynor Village teleport (2)\"],\"r\":[\"Combat bracelet\",\"Skills necklace\"],\"c\":1},{\"n\":\"High Priests of Ages Past\",\"st\":[{\"t\":\"Enter the crypt.\",\"s\":[\"Yes.\"],\"i\":[\"Combat gear\"]},{\"t\":\"Say Snothead's name at the south-west grave.\"},{\"t\":\"Defeat Snothead. He attacks using melee.\"},{\"t\":\"Say Snailfeet's name at the south-east grave.\",\"s\":[\"Snailfeet.\"]},{\"t\":\"Defeat Snailfeet. He attacks using melee and range.\"},{\"t\":\"Say Mosschin's name at the north-west grave.\",\"s\":[\"Mosschin.\"]},{\"t\":\"Defeat Mosschin. He attacks using melee and magic.\"},{\"t\":\"Say Redeyes's name at the north-east grave.\",\"s\":[\"Redeyes.\"]},{\"t\":\"Defeat Redeyes. He attacks using melee and magic, and lowers your attack, strength, and defence.\"},{\"t\":\"Say Strongbones's name at the north grave.\",\"s\":[\"Strongbones.\"]},{\"t\":\"Defeat Strongbones. He attacks using all 3 combat styles, lowers your attack, strength and defence. Ignore the level 29 Skoblins he spawns.\"},{\"t\":\"Talk to Strongbones to learn where Yu'biusk is.\",\"s\":[\"Where is Yu'biusk?\"]}],\"i\":[\"Combat gear\"],\"c\":1,\"e\":[\"Snothead (level 32)\",\"Snailfeet (level 56)\",\"Mosschin (level 88)\",\"Redeyes (level 121)\",\"Strongbones (level 184)\"]},{\"n\":\"Path to Yu'biusk\",\"st\":[{\"t\":\"Return to Dorgesh-Kaan and speak to Oldak.\"},{\"t\":\"Talk to Oldak in his workshop.\"},{\"t\":\"Talk to Oldak near the machine at the fairy ring in the the caves south of Dorgesh-Kaan.\"},{\"t\":\"Fix the machine.\"},{\"t\":\"Watch the cutscene.\"},{\"t\":\"Walk up to the strange box and watch the cutscene. Quest complete!\"}],\"i\":[\"Light source\"],\"tr\":[\"Dramen staff\"],\"r\":[\"Dorgesh-Kaan sphere (2)\"]}]}"
