        "Lost City" -> "{\"n\":\"Lost City\",\"items\":[\"Any axe\",\"Knife\"],\"rec\":[\"Runes, or a way of dealing damage which you can smuggle onto Entrana. Runes for Crumble Undead (level 39 Magic) are best\",\"Teleport, preferably to Lumbridge. Home teleport will work if off cooldown\"],\"enemies\":[\"Multiple zombies (level 25) (can be safespotted)\",\"Dramen Tree Spirit (level 101) (can be safespotted)\"],\"rewards\":[\"3 Quest points\",\"Access to Zanaris.\",\"Ability to craft Cosmic Runes\",\"Ability to buy and wield Dragon Daggers & Longswords\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Talk to the Warrior south east of Draynor Village.\",\"s\":[\"What are you camped out here for?\",\"What makes you think it's out here?\",\"If it's hidden how are you planning to find it?\",\"Looks like you don't know either.\",\"Yes.\"]}],\"i\":[\"Any axe\"]},{\"n\":\"Finding Shamus\",\"st\":[{\"t\":\"Try cutting the tree just to the west.\",\"s\":[\"I've been in that shed, I didn't see a city.\"],\"i\":[\"Any axe\"]},{\"t\":\"Talk to Shamus.\",\"s\":[\"I've been in that shed, I didn't see a city.\"]}]},{\"n\":\"Getting a Dramen branch\",\"st\":[{\"t\":\"Bank all weapons and armour you have (including the axe), and go to Port Sarim to get a boat to Entrana.\",\"i\":[\"Runes, or a way of dealing damage which you can smuggle onto Entrana. Runes for Crumble Undead (level 39 Magic) are best\"]},{\"t\":\"Climb down the ladder on the north side of the island. Once you go down, you can only escape via teleport.\",\"s\":[\"Well that is a risk I will have to take.\"]},{\"t\":\"Kill zombies until one drops an axe.\"},{\"t\":\"Attempt to cut a branch from the Dramen tree. Be prepared for a Tree Spirit (level 101) to appear, which you can safespot behind nearby fungus.\",\"i\":[\"Bronze or Iron axe\"]},{\"t\":\"Kill the Tree Spirit. They can be safespotted behind nearby fungi to the east.\"},{\"t\":\"Cut at least one branch from the Dramen tree. It's recommended you cut at least 4 branches so you don't have to return in future quests.\"},{\"t\":\"Teleport away with the branches, preferably to Lumbridge.\",\"i\":[\"Dramen branch\"]}],\"tr\":[\"Teleport, preferably to Lumbridge. Home teleport will work if off cooldown\"],\"r\":[\"Runes, or a way of dealing damage which you can smuggle onto Entrana. Runes for Crumble Undead (level 39 Magic) are best\"]},{\"n\":\"Entering Zanaris\",\"st\":[{\"t\":\"Use a knife on the dramen branch to craft a dramen staff.\",\"i\":[\"Knife\",\"Dramen branch\"]},{\"t\":\"Enter the shed south of Lumbridge with your Dramen Staff equipped.\",\"i\":[\"Dramen staff\"]}],\"i\":[\"Knife\"]}]}"
        "Lunar Diplomacy" -> "{\"n\":\"Lunar Diplomacy\",\"items\":[\"Bullseye lantern\",\"Tinderbox\",\"Guam leaf\",\"Marrentill\",\"Dramen staff\",\"Access to the Air Altar\",\"Access to the Earth Altar\",\"Access to the Fire Altar\",\"Access to the Water Altar\",\"Any pickaxe\",\"Pestle and mortar\",\"Hammer\",\"Thread\",\"Needle\",\"Spade\"],\"rec\":[\"Combat gear\",\"Combat runes\",\"Moonclan Teleport\"],\"enemies\":[\"Multiple Suqah (level 111)\",\"Me (level 79)\"],\"rewards\":[\"2 Quest points\",\"5,000 Magic XP\",\"5,000 Runecraft XP\",\"50 x Astral Runes\",\"A Seal of Passage\",\"A set of Lunar Equipment\",\"Access to Lunar Island\",\"Access to the Lunar Spellbook\",\"Access to the Astral Altar\"],\"sec\":[{\"n\":\"Investigating\",\"st\":[{\"t\":\"Talk to Lokar Searunner on Rellekka's docks.\",\"s\":[\"Yes.\",\"You've been away from these parts a while?\",\"Why did you leave?\",\"Why not, I've always wondered what the state of my innards are!\"]},{\"t\":\"Talk to Brundt in Rellekka's longhall.\",\"s\":[\"Ask about a Seal of Passage.\"]},{\"t\":\"Return to Lokar Searunner on Rellekka's docks.\",\"s\":[\"Arrr! Yar! Let's be on our way, yar!\"],\"i\":[\"Seal of passage\"]},{\"t\":\"Climb up to the ship.\"},{\"t\":\"Talk to Captain Bentley.\",\"s\":[\"Can we sail to Lunar Isle now?\"],\"i\":[\"Seal of passage\"]}],\"i\":[\"Bullseye lantern\",\"Tinderbox\"]},{\"n\":\"The curse\",\"st\":[{\"t\":\"Go down to talk to 'Birds-Eye' Jack.\"},{\"t\":\"Go upstairs to talk to Bentley again.\"},{\"t\":\"Go down to talk to 'Birds-Eye' Jack again.\"},{\"t\":\"Talk to 'Eagle-eye' Shultz on the north end of the ship.\"},{\"t\":\"Go to the bottom deck to talk to 'Beefy' Burns.\"},{\"t\":\"Go to the top deck to talk to 'Lecherous' Lee.\"},{\"t\":\"Go down to the deck to talk to First mate 'Davey-boy'.\"},{\"t\":\"Go up to the Cabin Boy.\"},{\"t\":\"Use the emerald lens on the lantern.\",\"i\":[\"Emerald lens\",\"Bullseye lantern\"]},{\"t\":\"Light the emerald lantern.\",\"i\":[\