        "Mage Arena I" -> "{\"n\":\"Mage Arena I\",\"items\":[\"Knife or sharp weapon to cut through a web\",\"Runes for fighting Kolodion\"],\"rec\":[],\"enemies\":[\"Kolodion in 5 forms, up to level 112\"],\"rewards\":[\"A God Staff\",\"A God Cape\",\"Ability to unlock 3 new God Spells.\"],\"sec\":[{\"n\":\"Getting to the Mage Arena\",\"st\":[{\"t\":\"Pull the lever in the building north of the Mage Arena. This is IN THE WILDERNESS, so don't bring anything you don't want to lose.\",\"i\":[\"Knife or sharp weapon to cut through a web\"]}],\"i\":[\"Knife or sharp weapon to cut through a web\"],\"c\":1},{\"n\":\"Defeating Kolodion\",\"st\":[{\"t\":\"Talk to Kolodion, ready for fighting him in the Mage Arena.\",\"s\":[\"Can I fight here?\",\"Yes indeedy.\",\"Okay, let's fight.\"],\"i\":[\"Runes for fighting Kolodion\"]},{\"t\":\"Defeat Kolodion's various forms.\"}],\"i\":[\"Runes for fighting Kolodion\"]},{\"n\":\"Getting your rewards\",\"st\":[{\"t\":\"Enter the sparkling pool.\"},{\"t\":\"Pray at the statue of the god whose cape you want. Pick up the cape which appears.\"},{\"t\":\"Talk to the Chamber Guardian for your staff.\",\"i\":[\"God cape\"]}]}]}"
        "Mage Arena II" -> "{\"n\":\"Mage Arena II\",\"items\":[\"Knife or sharp weapon to cut through a web\",\"Zamorak staff\",\"Guthix staff\",\"Saradomin staff\",\"Runes for 50+ casts of god spells\"],\"rec\":[\"Magic combat gear\",\"Saradomin brews\",\"Super restores\",\"Food\",\"Rings of recoil\"],\"enemies\":[\"Porazdir (level 235)\",\"Justiciar Zachariah (level 348)\",\"Derwen (level 235)\"],\"rewards\":[\"Ability to upgrade your God Cape\"],\"sec\":[{\"n\":\"Upgrading the God Cape\",\"st\":[{\"t\":\"Pull the lever in the building north of the Mage Arena. This is IN THE WILDERNESS, so don't bring anything you don't want to lose.\",\"i\":[\"Knife or sharp weapon to cut through a web\"]},{\"t\":\"Talk to Kolodion.\",\"s\":[\"Are there any more challenges available?\",\"Great, I've been waiting for an improvement!\"]},{\"t\":\"Use the Enchanted Symbol to locate the 3 bosses. It's recommended to find where a boss is with just food and the symbol, then once you have the location gear up and come fight it. Fight bosses with their respective god staff and spell, food, potions, and armour you're willing to risk. Protect from Magic, and once you've killed them take their drop to Kolodion.\"},{\"t\":\"Use a god cape of your choice on Kolodion to have it imbued.\",\"s\":[\"Yes.\"],\"i\":[\"God cape\"]}],\"i\":[\"Knife or sharp weapon to cut through a web\",\"Saradomin staff\",\"Guthix staff\",\"Zamorak staff\",\"Runes for 50+ casts of god spells\"],\"c\":1}]}"
        "Making Friends with My Arm" -> "{\"n\":\"Making Friends with My Arm\",\"items\":[\"Hammer\",\"Saw\",\"Bolt of cloth\",\"Mahogany plank (5)\",\"Cadava berries\",\"Combat gear, preferably ranged or melee\"],\"rec\":[\"Draynor teleport (2)\",\"Trollheim teleports\",\"Varrock teleport\"],\"enemies\":[\"Don't Know What (level 163)\",\"Mother (level 198)\"],\"rewards\":[\"2 Quest points\",\"10,000 Construction XP\",\"40,000 Firemaking XP\",\"50,000 Mining XP\",\"50,000 Agility XP\",\"Access to the Salt Mines.\",\"Ability to build fire pits\",\"Ability to tune a house portal to Troll Stronghold.\",\"Access to a disease free herb patch in Weiss.\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Talk to Burntmeat in the Troll Stronghold's kitchen.\",\"s\":[\"Yes, I'll take your quest.\",\"Why in the heck would you choose My Arm?\"]},{\"t\":\"Talk to My Arm on the roof of the Troll Stronghold.\",\"s\":[\"I'm doing another quest for Burntmeat.\",\"Wolfbone said we should go by sea.\"]}]},{\"n\":\"Getting to Weiss\",\"st\":[{\"t\":\"Talk to Larry north east of Rellekka.\",\"s\":[\"Can I transport My Arm in your boat?\",\"Never mind, I just need to borrow your boat.\"]},{\"t\":\"Talk to Larry again.\",\"s\":[\"Can I transport My Arm in your boat?\",\"Never mind, I just need to borrow your boat.\"]},{\"t\":\"Board Larry's boat to Weiss.\",\"s\":[\"Travel to Weiss.\"]},{\"t\":\"Attempt to mine the cave entrance.\"},{\"t\":\"Search the wrecked boat for a pickaxe and rope.\",\"s\":[\"Take rope\",\"Take pickaxe\"]},{\"t\":\"Climb the rockslide.\"},{\"t\":\"Use a rope on the nearby tree.\",\"i\":[\"Rope\"]},{\"t\":\"Climb the rope.\"},{\"t\":\"Cross the ledge.\"},{\"t\":\"Continue climbing.\"},{\"t\":\"Pass the fallen tree.\"},{\"t\":\"Talk to Boulder.\",\"s\":[\"You only need to let My Arm in, not me.\"]}]},{\"n\":\"Infiltrating Weiss\",\"st\":[{\"t\":\"Sneak into Weiss via the fence to the east.\",\"s\":[\"I'll be back!\"]},{\"t\":\"You need to reach the hole at the north west corner, avoiding the trolls and the boulders they throw. Go south, then west, then north.\"},{\"t\":\"Wait a few seconds, and run into the hole.\"},{\"t\":\"Enter the narrow gap to the south quickly.\"},{\"t\":\"Swim across the water.\"},{\"t\":\"You now need to make a path with the stones thrown at you in the water. Have the troll throw 5 rocks next to each other going out from the north shore.\"},{\"t\":\"Mine the cave exit.\",\"i\":[\"Any pickaxe\"]},{\"t\":\"Talk to Mother in Weiss.\",\"s\":[\"Let's move on with the chat.\",\"Tell him goutweed is delicious.\",\"Tell him how tough Stronghold trolls are.\",\"Tell him to show respect to his daughter.\",\"Tell him you love his daughter!\"]},{\"t\":\"Talk to My Arm in Weiss.\",\"s\":[\"Odd Mushroom, why are you here with us?\",\"Does Mother respect anything except fighting?\",\"I did some fishing and fetched some stuff.\"]}],\"i\":[\"Any pickaxe\"],\"c\":1,\"e\":[\"Mother (level 198)\"]},{\"n\":\"Faking death\",\"st\":[{\"t\":\"Talk to the Wise Old Man in Draynor Village.\",\"s\":[\"Ask about My Arm.\",\"Can you pretend you're dead?\",\"You owe me a favour after the Fishing Colony quest.\"]},{\"t\":\"Build the coffin in the Wise Old Man's house.\",\"i\":[\"Saw\",\"Hammer\",\"Mahogany plank (5)\",\"Bolt of cloth\"]},{\"t\":\"Talk to the Apothecary in Varrock.\",\"s\":[\"Talk about Making Friends with My Arm.\"],\"i\":[\"Cadava berries\"]},{\"t\":\"Bring the cadava potion to the Wise Old Man in Draynor Village.\",\"s\":[\"Ask about My Arm.\"],\"i\":[\"Reduced cadava potion\"]},{\"t\":\"Pick up the coffin in the Wise Old Man's house.\"}],\"i\":[\"Saw\",\"Hammer\",\"Mahogany plank (5)\",\"Bolt of cloth\",\"Cadava berries\"]},{\"n\":\"Rising up\",\"st\":[{\"t\":\"Talk to My Arm in Weiss.\",\"i\":[\"Old man's coffin\",\"Combat gear, preferably ranged or melee\"]},{\"t\":\"Talk to Odd Mushroom in the prison.\",\"s\":[\"I'll never leave you.\"]},{\"t\":\"Talk to Snowflake. Be prepared to fight Don't Know What. Protect from Ranged, and move around to avoid his attacks.\",\"s\":[\"So I can't teleport, and I may lose stuff? Okay.\"],\"i\":[\"Combat gear, preferably ranged or melee\"]},{\"t\":\"Kill Don't Know What. Move around and Protect from Ranged to avoid his attacks.\"},{\"t\":\"You now need to put out the fire. Pick up a bucket from the bucket pile.\"},{\"t\":\"Fill the bucket on the barrel of water.\",\"i\":[\"Bucket\"]},{\"t\":\"Use the full bucket on the Fire of Domination.\",\"i\":[\"Bucket of water\"]},{\"t\":\"Kill Mother. Protect from Ranged, keep moving and keep your distance.\"}],\"i\":[\"Old man's coffin\",\"Combat gear, preferably ranged or melee\"],\"c\":1,\"e\":[\"Don't Know What (level 163)\",\"Mother (level 198)\"]},{\"n\":\"Finishing off\",\"st\":[{\"t\":\"Talk to My Arm in Weiss.\"},{\"t\":\"Talk to the Wise Old Man in Weiss.\"},{\"t\":\"Talk to Snowflake in Weiss.\",\"s\":[\"Okay, I'll be back.\"]},{\"t\":\"Pick up some goat poo from the north east building of Weiss.\",\"i\":[\"Bucket\"]},{\"t\":\"Bring the goat poo to Snowflake.\",\"i\":[\"Goat dung\"]},{\"t\":\"Read the Weiss fire notes.\",\"i\":[\"Weiss fire notes\"]},{\"t\":\"Talk to Snowflake to finish.\"}]}]}"
