        "Meat and Greet" -> "{\"n\":\"Meat and Greet\",\"items\":[],\"rec\":[\"Stamina potion\",\"Prayer potion\",\"Combat gear\",\"Food\",\"Teleport to Civitas illa Fortis (3)\"],\"enemies\":[\"Dire Wolf Alpha (lvl 113)\",\"Minotaur (lvl 193)\"],\"rewards\":[\"1 Quest point\",\"8,000 Cooking XP\",\"Access to Emelio's Kebab Shop\"],\"sec\":[{\"n\":\"Supply chain issues\",\"st\":[{\"t\":\"Talk to Emelio in Outer Fortis at the south-eastern entrance of Civitas illa Fortis to start the quest.\",\"s\":[\"Yes.\"]},{\"t\":\"Talk to the Spice Merchant in the Bazaar in the middle of Civitas illa Fortis about the missing delivery.\",\"s\":[\"I'm here about a missing delivery.\",\"Could I have a look at that locked box?\",\"About that missing delivery...\"]},{\"t\":\"Figure out the correct code to unlock the box of spices.\"},{\"t\":\"Talk to Alba in the farmhouse west of Civitas illa Fortis.\"},{\"t\":\"Head west from the farm and enter the Wolf Den, prepared to kill the Dire Wolf Alpha.\",\"i\":[\"Combat gear\",\"Food\"]},{\"t\":\"Kill the Dire Wolf Alpha. Use Protect from Melee to avoid most damage. His pups deal ranged damage.\",\"i\":[\"Combat gear\",\"Food\"]},{\"t\":\"Return to Alba in the farmhouse west of Civitas illa Fortis to tell them about the Dire Wolf Alpha's demise.\"}],\"i\":[\"Stamina potion\",\"Prayer potion\",\"Combat gear\",\"Food\"],\"c\":1,\"e\":[\"Dire Wolf Alpha (lvl 113)\"]},{\"n\":\"The golden ratio\",\"st\":[{\"t\":\"Return to Emelio in Outer Fortis at the south-eastern entrance of Civitas illa Fortis to find the perfect ratio of ingredients for the kebab.\"},{\"t\":\"Figure out the correct ratio of meat, salad, spice, and sauce by talking to the kebab connoisseurs outside then give the final recipe to Emelio.\",\"s\":[\"I think so.\",\"Adjust meat (currently at one portion).\",\"Adjust meat (currently at two portions).\",\"Adjust meat (currently at three portions).\",\"Adjust salad (currently at one portion).\",\"Adjust salad (currently at three portions).\",\"Adjust salad (currently at four portions).\",\"Adjust spice (currently at two portions).\",\"Adjust spice (currently at three portions).\",\"Adjust spice (currently at four portions).\",\"Adjust sauce (currently at one portion).\",\"Adjust sauce (currently at two portions).\",\"Adjust sauce (currently at four portions).\",\"Cancel.\",\"Four (current).\",\"Four.\",\"Two (current).\",\"Two.\",\"One (current).\",\"One.\",\"Three (current).\",\"Three.\"]},{\"t\":\"Return to Emelio with news of your kebab success!\"}],\"i\":[\"Stamina potion\",\"Prayer potion\",\"Combat gear\",\"Food\"],\"c\":1},{\"n\":\"Guerilla marketing\",\"st\":[{\"t\":\"Head into the Fortis Colosseum, then into the southern room and talk to Lelia about kebab sales.\",\"i\":[\"Combat gear\",\"Food\",\"Test kebab (2)\"]},{\"t\":\"Talk to Lelia after letting her taste your test kebab.\",\"i\":[\"Combat gear\",\"Food\",\"Test kebab\"]},{\"t\":\"Talk to Lelia in the southern room, ready to fight the Minotaur.\",\"s\":[\"I think so.\"],\"i\":[\"Combat gear\",\"Food\",\"Test kebab\"]},{\"t\":\"Fight the Minotaur. Protect from Melee to avoid most damage. When it shouts Moo! switch to Protect from Magic for one attack.\"},{\"t\":\"Talk to Lelia in the southern room of the Fortis Colosseum after defeating the Minotaur.\"},{\"t\":\"Return to Emelio in Outer Fortis at the south-eastern entrance of Civitas illa Fortis and tell him about your success.\"}],\"i\":[\"Prayer potion\",\"Combat gear\",\"Food\"],\"c\":1,\"e\":[\"Minotaur (lvl 193)\"]}]}"
        "Merlin's Crystal" -> "{\"n\":\"Merlin's Crystal\",\"items\":[\"Combat gear + food for Sir Mordred (level 39)\",\"Bread\",\"Tinderbox\",\"Bucket of wax\",\"Bat bones\"],\"rec\":[\"Teleport to Varrock\",\"Teleport to Camelot\",\"Teleports to Falador (2)\"],\"enemies\":[\"Sir Mordred (level 39)\"],\"rewards\":[\"6 Quest points\",\"Excalibur\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Talk to King Arthur in Camelot Castle to start.\",\"s\":[\"Yes.\",\"I want to become a Knight of the Round Table!\"]},{\"t\":\"Talk to Sir Gawain about how Merlin got trapped.\",\"s\":[\"Do you know how Merlin got trapped?\"]},{\"t\":\"Go upstairs to talk to Lancelot.\"},{\"t\":\"Talk to Sir Lancelot about getting into Morgan Le Faye's stronghold.\",\"s\":[\"Any ideas on how to get into Morgan Le Faye's stronghold?\",\"Thank you for the information.\"]}]},{\"n\":\"Infiltrate the fortress\",\"st\":[{\"t\":\"Hide in Arhein's crate behind the Candle Maker's shop in Catherby.\",\"s\":[\"Yes.\"]},{\"t\":\"Go up the stairs in the fortress.\"},{\"t\":\"Go up another floor.\"},{\"t\":\"Attack Sir Mordred down to 0hp to cause Morgan Le Faye to spawn.\",\"s\":[\"Tell me how to untrap Merlin and I might.\",\"Ok I will do all that.\"]},{\"t\":\"Go through Morgan le Faye's dialog. IF YOU EXIT FROM THIS DIALOG YOU WILL HAVE TO FIGHT MORDRED AGAIN.\",\"s\":[\"Tell me how to untrap Merlin and I might.\",\"Ok I will do all that.\"]}],\"i\":[\"Combat gear + food for Sir Mordred (level 39)\"],\"c\":1,\"e\":[\"Sir Mordred (level 39)\"]},{\"n\":\"Get bat bones\",\"st\":[{\"t\":\"Climb down from Keep Le Faye and step through the front door, then kill a Giant bat for some bat bones.\"},{\"t\":\"Kill a Giant bat outside Keep Le Faye for some bat bones.\",\"i\":[\"Bat bones\"]}]},{\"n\":\"Get a Black Candle\",\"st\":[{\"t\":\"Return to Catherby.\"},{\"t\":\"If you still need wax, go grab the insect repellent in a house in north Catherby. Otherwise, get your wax out.\",\"i\":[\"Insect repellent\"]},{\"t\":\"Go grab the bucket in the bee field west of Catherby.\",\"i\":[\"Bucket\"]},{\"t\":\"Use the insect repellent on a bee hive, then try to take some wax.\",\"i\":[\"Bucket\",\"Insect repellent\"]},{\"t\":\"Talk to the Candle Maker in Catherby twice until he gives you a black candle.\",\"s\":[\"Have you got any black candles?\"],\"i\":[\"Bucket of wax\"]}]},{\"n\":\"Get Excalibur\",\"st\":[{\"t\":\"Talk to the Lady of the Lake in Taverley.\",\"s\":[\"I seek the sword Excalibur.\"]},{\"t\":\"Attempt to enter the jewelery store in Port Sarim.\",\"s\":[\"Yes certainly.\",\"Yes, here you go.\"],\"i\":[\"Bread\"]},{\"t\":\"Talk to the beggar who appears and give him some bread.\",\"s\":[\"Yes certainly.\",\"Yes, here you go.\"],\"i\":[\"Bread\"]}],\"i\":[\"Bread\"]},{\"n\":\"Learn magic words\",\"st\":[{\"t\":\"Check the altar in the Zamorak Temple in south east Varrock. If you've already learnt the spell, just mark this step complete in the Quest Helper sidebar.\"}]},{\"n\":\"Perform the spell\",\"st\":[{\"t\":\"Enter the gates towards Camelot Castle.\",\"i\":[\"Excalibur\",\"Black candle\",\"Bat bones\",\"Tinderbox\"]},{\"t\":\"Go stand in the star symbol north east of Camelot Castle.\",\"s\":[\"Snarthon Candtrick Termanto\"],\"i\":[\"Excalibur\",\"Black candle\",\"Bat bones\",\"Tinderbox\"]},{\"t\":\"Light the Black candle with your tinderbox.\",\"i\":[\"Black candle\",\"Tinderbox\"]},{\"t\":\"Right-click drop the bat bones in the star.\",\"s\":[\"Snarthon Candtrick Termanto\"],\"i\":[\"Bat bones\",\"Excalibur\",\"Lit black candle\"]},{\"t\":\"Say the spell 'Snarthon Candtrick Termanto'. Be careful not to click the wrong option or you'll have to get another Black Candle.\",\"s\":[\"Snarthon Candtrick Termanto\"],\"i\":[\"Excalibur\"]}],\"i\":[\"Black candle\",\"Bat bones\",\"Excalibur\",\"Tinderbox\"]},{\"n\":\"Free Merlin\",\"st\":[{\"t\":\"Go up the ladder in the south east of Camelot castle.\",\"i\":[\"Excalibur\"]},{\"t\":\"Go up the next ladder.\",\"i\":[