        "Misthalin Mystery" -> "{\"n\":\"Misthalin Mystery\",\"items\":[],\"rec\":[],\"enemies\":[],\"rewards\":[\"1 Quest point\",\"600 Crafting XP\",\"Uncut Ruby\",\"Uncut Emerald\",\"Uncut Sapphire\"],\"sec\":[{\"n\":\"Talk to Abigale\",\"st\":[{\"t\":\"Talk to Abigale in the south east corner of Lumbridge Swamp.\",\"s\":[\"Yes.\"]}],\"c\":0},{\"n\":\"Enter the manor\",\"st\":[{\"t\":\"Board the rowboat south of Abigale.\"},{\"t\":\"Pick up the bucket near the fountain.\",\"i\":[\"Bucket\"]},{\"t\":\"Search the barrel of rainwater north of the fountain to trigger a cutscene.\",\"i\":[\"Bucket\"]},{\"t\":\"Use the bucket on the barrel of rainwater.\",\"i\":[\"Bucket\"]},{\"t\":\"Search the barrel of rainwater for the manor key.\"},{\"t\":\"Enter the manor.\"}],\"c\":0},{\"n\":\"Solve the first puzzle\",\"st\":[{\"t\":\"Take the knife from the table.\",\"i\":[\"Knife\"]},{\"t\":\"Try to open the door with the pink handle.\"},{\"t\":\"Pick up the note that appeared.\"},{\"t\":\"Read the notes.\",\"i\":[\"Notes\"]},{\"t\":\"Use a knife on the marked painting.\",\"i\":[\"Knife\"]},{\"t\":\"Search the painting for a ruby key.\"},{\"t\":\"Go through the door with the ruby handle.\",\"i\":[\"Ruby key\"]}],\"c\":0},{\"n\":\"Solve the second puzzle\",\"st\":[{\"t\":\"Search the shelves for a tinderbox.\"},{\"t\":\"Light the unlit candles in the room.\",\"i\":[\"Tinderbox\"]},{\"t\":\"Light the fuse on the barrel.\",\"i\":[\"Tinderbox\"]},{\"t\":\"Leave the room to trigger the explosion.\"},{\"t\":\"Climb over the damaged wall.\"}],\"c\":0},{\"n\":\"Solve the third puzzle\",\"st\":[{\"t\":\"Observe Lacey through the trees.\"},{\"t\":\"Pick up the note that appeared by the fence.\"},{\"t\":\"Read the notes.\",\"i\":[\"Notes\"]},{\"t\":\"Right-click search the piano for the emerald key.\"}],\"c\":0},{\"n\":\"Witness another murder\",\"st\":[{\"t\":\"Climb back over the damaged wall into the manor.\",\"i\":[\"Emerald key\"]},{\"t\":\"Go through the door with the green handle.\