        "Monk's Friend" -> "{\"n\":\"Monk's Friend\",\"items\":[\"Jug of Water\",\"Logs\"],\"rec\":[\"Ardougne cloak 1 or higher for teleports to the monastery\"],\"enemies\":[],\"rewards\":[\"1 Quest point\",\"2,000 Woodcutting XP\",\"8 x Law Runes\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Talk to Brother Omad in the monastery south of East Ardougne.\",\"s\":[\"Why can't you sleep, what's wrong?\",\"Yes.\"]}],\"i\":[\"Jug of Water\",\"Logs\"],\"c\":0},{\"n\":\"Finding the blanket\",\"st\":[{\"t\":\"Go down the ladder in a circle of stones west of the monastery.\"},{\"t\":\"Pick up the Child's blanket in the room to the south.\",\"i\":[\"Child's blanket\"]},{\"t\":\"Go back up the ladder.\",\"i\":[\"Child's blanket\"]},{\"t\":\"Bring the blanket back to Brother Omad in the monastery.\",\"i\":[\"Child's blanket\"]}],\"c\":0},{\"n\":\"Help Cedric\",\"st\":[{\"t\":\"Talk to Brother Omad again.\",\"s\":[\"Is there anything else I can help with?\",\"Who's Brother Cedric?\",\"Where should I look?\"]},{\"t\":\"Talk to Brother Cedric north of the monastery.\"},{\"t\":\"Talk to Brother Cedric again.\",\"s\":[\"Yes, I'd be happy to!\"],\"i\":[\"Jug of Water\"]},{\"t\":\"Talk to Brother Cedric once again with logs.\",\"i\":[\"Logs\"]},{\"t\":\"Return to Brother Omad to finish the quest.\"}],\"c\":0}]}"
        "Monkey Madness I" -> "{\"n\":\"Monkey Madness I\",\"items\":[\"Gold bar\",\"Ball of wool\",\"Banana (5)\",\"Monkey bones or corpse\"],\"rec\":[\"Combat gear, food and potions\",\"Antipoison\",\"Food\",\"Prayer potions\",\"Tree Gnome Stronghold teleport via Spirit Tree (2), Gnome Glider (Ta Quir Priw), or Grand Seed Pod (4)\",\"Any teleport to leave Ape Atoll (3)\",\"Ardougne teleport\"],\"enemies\":[\"Jungle Demon (level 195)\"],\"rewards\":[\"3 Quest points\",\"55,000 Experience Combat Lamp (Over multiple Skills)\",\"10000 x Coins\",\"3 x Diamonds\",\"Ability to purchase and wield the Dragon Scimitar.\",\"Full access to Ape Atoll.\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Talk to King Narnode Shareen in the Tree Gnome Stronghold.\",\"s\":[\"Yes.\"],\"i\":[\"Stamina potions\"]}],\"i\":[\"Tree Gnome Stronghold teleport via Spirit Tree (2), Gnome Glider (Ta Quir Priw), or Grand Seed Pod\"]},{\"n\":\"Investigate the shipyard\",\"st\":[{\"t\":\"Fly with Captain Errdo to Gandius.\"},{\"t\":\"Talk to G.L.O. Caranock in the shipyard.\"},{\"t\":\"Return to King Narnode Shareen in the Tree Gnome Stronghold.\"}]},{\"n\":\"Traveling to Ape Atoll\",\"st\":[{\"t\":\"Talk to Daero on the 1st floor of the Tree Gnome Stronghold. Make sure to go through all of the Chat Options until you're given a 'Leave...' option.\",\"s\":[\"Leave...\",\"Who is it?\",\"Yes\",\"Talk about the 10th squad...\"],\"i\":[\"Narnode's orders\",\"Food\",\"Prayer potions\",\"Antipoison\",\"Stamina potions\",\"Any teleport to leave Ape Atoll\"]},{\"t\":\"Talk to Daero in the hangar.\"},{\"t\":\"Operate the reinitialisation panel and solve the puzzle.\"},{\"t\":\"Talk to Daero in the hangar again.\"},{\"t\":\"Talk to Waydar.\",\"s\":[\"Yes\"]},{\"t\":\"Talk to Lumdo.\"},{\"t\":\"Talk to Waydar on Crash Island.\",\"s\":[\"I cannot convince Lumdo to take us to the island...\"]}],\"i\":[\"Prayer potions\",\"Food\",\"Antipoison\",\"Stamina potions\",\"Any teleport to leave Ape Atoll\"]},{\"n\":\"Finding Garkor\",\"st\":[{\"t\":\"Head west and enter the valley going north WITH PROTECT FROM RANGED ON. Be wary of poison and taking damage.\"},{\"t\":\"Wait for the gorilla guard to start going away from the prison cell, then sneak out and go to the north side of the prison.\"},{\"t\":\"Stick to the east edge of the town, and make your way to Garkor to the south east.\"}]},{\"n\":\"Getting amulet parts\",\"st\":[{\"t\":\"Head west and enter the large open building via the south door. DO NOT STAND ON THE LIGHT FLOOR IN THE BUILDING.\"},{\"t\":\"DO NOT WALK ON THE LIGHT FLOOR. Search the stacked crates for monkey dentures.\",\"s\":[\"Yes\"]},{\"t\":\"Search the crate in the south east corner and go down into the cavern.\",\"s\":[\"Yes, I'm sure.\"]},{\"t\":\"Search the crate in the north west of the room for a M'amulet mould.\",\"s\":[\"Yes\"]},{\"t\":\"Teleport out to prepare for a dangerous portion. You'll want energy/stamina potions, food and prayer potions.\"}]},{\"n\":\"Making an Enchanted Bar\",\"st\":[{\"t\":\"Get food, antipoison, energy / stamina / prayer potions, and return to Ape Atoll.\",\"i\":[\"Gold bar\",\"Monkey dentures\",\"M'amulet mould\",\"Food\",\"Antipoison\",\"Prayer potions\",\"Stamina potions\",\"Any teleport to leave Ape Atoll\"]},{\"t\":\"Enter the dungeon in south Ape Atoll.\",\"i\":[\"Gold bar\",\"Monkey dentures\",\"M'amulet mould\"]},{\"t\":\"Talk to Zooknock in the north east of the dungeon.\",\"s\":[\"What do we need for the monkey amulet?\",\"I'll be back later.\"],\"i\":[\"Gold bar\",\"Monkey dentures\",\"M'amulet mould\"]},{\"t\":\"Use the monkey dentures on Zooknock in the north east of the dungeon. If you've already done so, open the quest journal to re-sync your current state.\",\"i\":[\"Monkey dentures\"]},{\"t\":\"Use the m'amulet mould on Zooknock in the north east of the dungeon. If you've already done so, open the quest journal to re-sync your current state.\",\"i\":[\"M'amulet mould\"]},{\"t\":\"Use the gold bar on Zooknock in the north east of the dungeon. If you've already done so, open the quest journal to re-sync your current state.\",\"i\":[\"Gold bar\"]}],\"i\":[\"Gold bar\",\"Monkey dentures\",\"M'amulet mould\"],\"tr\":[\"Tree Gnome Stronghold teleport via Spirit Tree (2), Gnome Glider (Ta Quir Priw), or Grand Seed Pod\",\"Any teleport to leave Ape Atoll\"],\"r\":[\"Antipoison\",\"Food\",\"Prayer potions\",\"Stamina potions\"]},{\"n\":\"Making an amulet\",\"st\":[{\"t\":\"Teleport out to prepare to make the amulet. You'll want some food, prayer potions, antipoisons, the mould and the enchanted bar.\"},{\"t\":\"Get food, antipoison, prayer potions, and return to Ape Atoll.\",\"i\":[\"Enchanted bar\",\"M'amulet mould\",\"Ball of wool\",\"Food\",\"Antipoison\",\"Prayer potions\",\"Stamina potions\",\"Any teleport to leave Ape Atoll\"]},{\"t\":\"Head west and enter the valley going north WITH PROTECT FROM RANGED ON. Be wary of poison and taking damage.\",\"i\":[\"Enchanted bar\",\"M'amulet mould\",\"Ball of wool\"]},{\"t\":\"Wait for the gorilla guard to start going away from the prison cell, then sneak out and go to the north side of the prison. Afterwards, head into the temple's basement.\",\"i\":[\"Enchanted bar\",\"M'amulet mould\",\"Ball of wool\"]},{\"t\":\"Use the enchanted bar on the wall of flame.\",\"i\":[\"Enchanted bar\"]}],\"i\":[\"Enchanted bar\",\"M'amulet mould\",\"Ball of wool\"],\"tr\":[\"Tree Gnome Stronghold teleport via Spirit Tree (2), Gnome Glider (Ta Quir Priw), or Grand Seed Pod\",\"Any teleport to leave Ape Atoll\"],\"r\":[\"Banana (5)\",\"Antipoison\",\"Food\",\"Combat gear, food and potions\",\"Prayer potions\",\"Stamina potions\"]},{\"n\":\"Getting the talisman\",\"st\":[{\"t\":\"Climb the rope out. If you plan on doing Recipe for Disaster, also kill a Zombie Monkey for its bones whilst here, and a gorilla upstairs.\",\"i\":[\"Zombie monkey bones\"]},{\"t\":\"Go to the north west of the island and talk to the monkey child there a few times. Eventually you'll give him 5 bananas, and he'll give you a monkey talisman.\",\"s\":[\"Well I'll be a monkey's uncle!\",\"How many bananas did Aunty want?\",\"Ok, I promise!\",\"I've lost that toy you gave me...\",\"Wow - can I borrow it?\"],\"i\":[\"M'speak amulet\",\"Banana (5)\"]},{\"t\":\"Talk to the monkey child again.\",\"i\":[\"M'speak amulet\"]},{\"t\":\"Give the monkey child 5 bananas.\",\"i\":[\"M'speak amulet\",\"Banana (5)\"]},{\"t\":\"Wait for the aunt to make another round, then talk to the monkey child for the talisman.\",\"i\":[\"M'speak amulet\"]}],\"i\":[\"M'speak amulet\",\"Banana (5)\"]},{\"n\":\"Bones for RFD (optional)\",\"st\":[{\"t\":\"This section will help you get ready for Recipe for Disaster. If you aren't interested in this, tick the box for this section in the sidebar to skip it.\",\"s\":[\"I've lost that toy you gave me...\",\"Wow - can I borrow it?\",\"Ok, I promise!\"],\"i\":[\"M'speak amulet\",\"Monkey talisman (4)\"]},{\"t\":\"Kill a monkey archer for their bones.\",\"i\":[\"Ninja monkey bones\"]},{\"t\":\"Kill a gorilla in the temple for their bones. If they can attack you they will heal on hit, so it's recommended to safespot or flinch one.\",\"i\":[\"Gorilla bones\"]},{\"t\":\"Enter into the temple's basement to kill a zombie monkey for their bones.\",\"i\":[\"Combat gear, food and potions\"]},{\"t\":\"Kill a zombie monkey for their bones.\",\"i\":[\"Zombie monkey bones\"]}],\"i\":[\"M'speak amulet\"],\"r\":[\"Combat gear, food and potions\"]},{\"n\":\"Making a greegree\",\"st\":[{\"t\":\"Teleport out to prepare to make the talisman. You'll want some food, prayer potions, and antipoisons.\",\"i\":[\"Monkey talisman\",\"Gorilla bones\",\"Zombie monkey bones\",\"Ninja monkey bones\",\"Monkey talisman (4)\"]},{\"t\":\"Get food, antipoison, prayer potions, and return to Ape Atoll.\",\"i\":[\"Monkey talisman\",\"Monkey bones or corpse\",\"Food\",\"Antipoison\",\"Prayer potions\",\"Stamina potions\",\"Ardougne teleport\"]},{\"t\":\"Enter the dungeon in south Ape Atoll.\",\"i\":[\"Monkey talisman\",\"Monkey bones or corpse\"]},{\"t\":\"Use the monkey talisman on Zooknock in the north east of the dungeon. If you've already done so, open the quest journal to re-sync your current state.\",\"i\":[\"Monkey talisman\"]},{\"t\":\"Use the monkey bones on Zooknock in the north east of the dungeon. If you've already done so, open the quest journal to re-sync your current state.\",\"i\":[\"Monkey bones or corpse\"]},{\"t\":\"If you want to make a zombie, ninja and gorilla greegree for RFD talk to and give Zooknock the bones/talismans. Once you're done, teleport away for the next step.\",\"s\":[\"Can you make another monkey talisman?\",\"Yes\"],\"i\":[\"Ninja monkey bones\",\"Gorilla bones\",\"Zombie monkey bones\"]}],\"i\":[\"Monkey talisman\",\"Monkey bones or corpse\"],\"tr\":[\"Ardougne teleport\"],\"r\":[\"Prayer potions\",\"Food\",\"Antipoison\",\"Stamina potions\",\"Ninja monkey bones\",\"Gorilla bones\",\"Zombie monkey bones\",\"Monkey talisman (4)\"]},{\"n\":\"Save a monkey\",\"st\":[{\"t\":\"Talk to the Monkey Minder in the Ardougne Zoo whilst wielding the Karamjan monkey greegree.\",\"i\":[\"Karamjan monkey greegree\",\"M'speak amulet\",\"Stamina potions\"]},{\"t\":\"Talk to a monkey in the pen.\"},{\"t\":\"UNEQUIP the greegree, then talk to the Monkey Minder again to leave.\"},{\"t\":\"WALK/RUN to Daero to return to Ape Atoll. If you teleport, you'll have to start again.\",\"i\":[\"Karamjan monkey greegree\",\"M'speak amulet\",\"Monkey\",\"Stamina potions\"]},{\"t\":\"Talk to Garkor.\",\"i\":[\"Karamjan monkey greegree\",\"M'speak amulet\",\"Monkey\"]},{\"t\":\"Talk to a guard outside the building in the south east of Marim. If you already have, open the quest guide to resync.\"},{\"t\":\"Talk to Kruk in the north west of the island.\",\"i\":[\"Karamjan monkey greegree\",\"M'speak amulet\",\"Monkey\"]},{\"t\":\"Talk to Awowogei twice.\",\"i\":[\"Karamjan monkey greegree\",\"M'speak amulet\",\"Monkey\"]}],\"i\":[\"Karamjan monkey greegree\",\"M'speak amulet\"],\"r\":[\"Stamina potions\"]},{\"n\":\"Defeat the demon\",\"st\":[{\"t\":\"Prepare to fight the Jungle Demon. Once you're ready, equip the 10th squad sigil.\",\"i\":[\"10th squad sigil\",\"Combat gear, food and potions\",\"Food\",\"Prayer potions\"]},{\"t\":\"Kill the Jungle Demon. Use Protect from Magic and keep your distance to kill it safely.\"},{\"t\":\"Return to King Narnode Shareen in the Tree Gnome Stronghold.\"}],\"i\":[\"Combat gear, food and potions\"],\"tr\":[\"Tree Gnome Stronghold teleport via Spirit Tree (2), Gnome Glider (Ta Quir Priw), or Grand Seed Pod\"],\"r\":[\"Food\",\"Prayer potions\"],\"c\":1,\"e\":[\"Jungle Demon (level 195)\"]}]}"
        "Monkey Madness II" -> "{\"n\":\"Monkey Madness II\",\"items\":[\"Lemon\",\"Grapes\",\"Pestle and mortar\",\"Any pickaxe\",\"Logs\",\"A lightsource\",\"Translation book\",\"Hammer (obtainable in quest)\",\"Chisel (obtainable in quest)\",\"M'speak amulet\",\"Monkey talisman or 1000 coins\",\"Ninja greegree\"],\"rec\":[\"Magic logs\",\"Food\",\"Stamina potions\",\"Prayer potions\",\"Antidote\",\"Combat gear\"],\"enemies\":[\"Kruk (level 149, flinchable)\",\"Keef (level 178, safespottable)\",\"Kob (level 185, safespottable)\",\"9 Tortured gorillas (level 141)\",\"2 Demonic Gorillas (level 275)\",\"Glough (level 431)\"],\"rewards\":[\"4 Quest points\",\"80,000 Slayer XP\",\"60,000 Agility XP\",\"50,000 Thieving XP\",\"50,000 Hunter XP\",\"2 x 50,000 Experience Lamps (Any Combat Skill)\",\"A Royal Seed Pod\",\"A pet monkey\",\"Access to Demonic Gorillas\",\"A new Gnome Glider location\",\"Access to a bank on Ape Atoll\",\"Ability to wield the Heavy Ballista\",\"Access to Maniacal Monkey hunting area\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Talk to King Narnode Shareen in the Tree Gnome Stronghold.\",\"s\":[\"I'll help you look for Glough.\"]},{\"t\":\"Investigate the tree in the 2nd floor of Glough's house.\"},{\"t\":\"Go talk to Anita in the west of the Tree Gnome Stronghold.\",\"s\":[\"What's wrong?\",\"He might be in trouble, I could help.\"]},{\"t\":\"Return to Glough's house and climb to the 3rd floor.\"},{\"t\":\"Investigate the nearby statue and turn it.\",\"s\":[\"Yes\"]},{\"t\":\"Search the fire remains.\"},{\"t\":\"Search the crates.\"},{\"t\":\"Use a pestle and mortar on a lemon\",\"i\":[\"Pestle and mortar\",\"Lemon\"]},{\"t\":\"Use the notes on the candles.\",\"i\":[\"Mysterious note\"]},{\"t\":\"Use a pestle and mortar on some grapes.\",\"i\":[\"Pestle and mortar\",\"Grapes\"]},{\"t\":\"Use the brush on the note.\",\"i\":[\"Juice-coated brush\",\"Mysterious note\"]},{\"t\":\"Read the note.\",\"i\":[\"Scrawled note\"]},{\"t\":\"Use the translation book on the scrawled note.\",\"i\":[\"Translation book\",\"Scrawled note\"]},{\"t\":\"Go talk to Narnode.\"},{\"t\":\"Return to Narnode with the translation.\"},{\"t\":\"Talk to Auguste on Entrana. You can take the hot air balloon there from south of the Grand Tree with a log, or travel from Port Sarim.\",\"s\":[\"Talk about Assistant Le Smith.\"],\"i\":[\"No combat items to travel to Entrana\"]},{\"t\":\"Return to King Narnode Shareen.\",\"s\":[\"Thanks for the information.\"]}],\"i\":[\"Lemon\",\"Grapes\",\"Translation book\",\"Pestle and mortar\",\"No combat items to travel to Entrana\"],\"r\":[\"Logs\",\"Magic logs\"],\"c\":1,\"e\":[\"Glough (level 431)\"]},{\"n\":\"Going undercover\",\"st\":[{\"t\":\"Talk to Garkor on Ape Atoll.\",\"s\":[\"King Narnode has sent me.\",\"It's worth a shot.\"],\"i\":[\"Ninja greegree\",\"M'speak amulet\",\"Monkey talisman or 1000 coins\",\"A lightsource\",\"Food\"]},{\"t\":\"Talk to Awowogei.\",\"s\":[\"I'm here to discuss military strategies.\",\"Of course, my king.\"],\"i\":[\"Ninja greegree\",\"M'speak amulet\"]},{\"t\":\"Talk to Garkor again.\",\"i\":[\"Ninja greegree\"]},{\"t\":\"Talk to a monkey archer on the west of Ape Atoll. Buy a monkey talisman for 1000 coins now if you need one.\",\"i\":[\"Ninja greegree\",\"M'speak amulet\"]},{\"t\":\"Enter the trapdoor under some grass in the north west of Ape Atoll.\",\"s\":[\"Yes\"],\"i\":[\"A lightsource\",\"Combat gear\",\"Food\",\"Prayer potions\",\"Stamina potions\"]}],\"i\":[\"Ninja greegree\",\"M'speak amulet\",\"Monkey talisman or 1000 coins\",\"A lightsource\",\"Combat gear\",\"Food\",\"Prayer potions\",\"Stamina potions\"],\"c\":1},{\"n\":\"Defeating trolls and ogres\",\"st\":[{\"t\":\"Enter the Troll Stronghold, ready to fight Kob.\",\"i\":[\"Climbing boots\",\"Combat gear\"]},{\"t\":\"Talk to Kob with Protect from Melee on, ready to fight.\",\"s\":[\"I know about your deal with the monkeys.\",\"You won't be around to crush anyone when I'm done with you.\",\"I accept your challenge.\"]},{\"t\":\"Fight Kob. He can be safespotted from the doorway.\"},{\"t\":\"Talk to Keef in Gu'Tanoth. Get to him via the agility shortcut next to him. Be prepared to fight him and pray Protect from Melee.\",\"s\":[\"I know about your deal with the monkeys.\",\"I offer to spare your life.\",\"I accept your challenge.\"]},{\"t\":\"Fight Keef. He can be safespotted.\"}],\"i\":[\"Combat gear\",\"Climbing boots\"],\"c\":1,\"e\":[\"Keef (level 178, safespottable)\"]},{\"n\":\"Sabotage\",\"st\":[{\"t\":\"Talk to Garkor on Ape Atoll.\",\"i\":[\"Kruk monkey greegree\"]},{\"t\":\"Search around the various rooftops in Ape Atoll for Assistant Le Smith.\",\"i\":[\"Kruk monkey greegree\"]},{\"t\":\"Talk to Assistant Le Smith.\",\"s\":[\"I was going to ask you the same question.\",\"Why is that?\",\"Awowogei has already informed me about the battleships.\",\"Where is the fleet, currently?\"],\"i\":[\"Kruk monkey greegree\"]},{\"t\":\"Talk to Garkor.\",\"i\":[\"Kruk monkey greegree\"]},{\"t\":\"Talk to the monkey guard on the north west of Ape Atoll.\",\"s\":[\"What's going on here?\",\"Construction platform?\",\"Can I visit the platform?\",\"I would like to go back to the construction platform.\"],\"i\":[\"Kruk monkey greegree\",\"M'speak amulet\"]}],\"i\":[\"Kruk monkey greegree\",\"M'speak amulet\"]},{\"n\":\"Glough's experiments\",\"st\":[{\"t\":\"Return to Garkor on Ape Atoll.\",\"i\":[\"Kruk monkey greegree\",\"M'speak amulet\"]},{\"t\":\"Enter the trapdoor under some grass in the north west of Ape Atoll.\",\"s\":[\"Yes\"],\"i\":[\"Kruk monkey greegree\"]},{\"t\":\"Climb across the monkey bars to the north as Kruk.\",\"i\":[\"Kruk monkey greegree\"]},{\"t\":\"Enter the passage to the north.\",\"i\":[\"Kruk monkey greegree\"]},{\"t\":\"Climb onto the stunted gorilla.\",\"i\":[\"Kruk monkey greegree\"]},{\"t\":\"Fight the tortured gorillas. When you're done, be careful NOT to click out of the cutscene or you'll need to do this again.\"},{\"t\":\"Dismount 