        "Mountain Daughter" -> "{\"n\":\"Mountain Daughter\",\"items\":[\"Rope\",\"Any pickaxe\",\"Any axe\",\"Any plank\",\"Almost any gloves\",\"A staff or a pole\"],\"rec\":[\"Slayer ring for teleports\",\"Combat gear for The Kendal fight\"],\"enemies\":[\"The Kendal (level 70)\"],\"rewards\":[\"2 Quest points\",\"1,000 Attack XP\",\"2,000 Prayer XP\",\"A Bearhead\",\"Access to the Mountain Camp\"],\"sec\":[{\"n\":\"Speak to Hamal\",\"st\":[{\"t\":\"Use your rope on the boulder outside the Mountain Camp east of Rellekka.\",\"i\":[\"Rope\"]},{\"t\":\"Speak to Hamal the Chieftain in the Mountain Camp.\",\"s\":[\"Why is everyone so hostile?\",\"So what are you doing up here?\",\"I will search for her!\"],\"i\":[\"Rope\",\"Any pickaxe\",\"Any axe\",\"Any plank\",\"A staff or a pole\",\"Almost any gloves\"]}],\"i\":[\"Rope\",\"Any plank\",\"Any pickaxe\"]},{\"n\":\"Go to the centre of the lake\",\"st\":[{\"t\":\"Head south of Hamal's tent and dig some mud from the mud pond.\"},{\"t\":\"Pick up the pole north of Hamal's tent.\",\"i\":[\"A staff or a pole\"]},{\"t\":\"Use mud on the Tall Tree on the lake north of the camp, and then climb it.\",\"i\":[\"Mud\",\"A staff or a pole\",\"Any plank\"]},{\"t\":\"Climb the Tall Tree on the lake north of the camp.\",\"i\":[\"A staff or a pole\",\"Any plank\"]},{\"t\":\"Use your pole or a staff on the clump of rocks.\",\"i\":[\"A staff or a pole\",\"Any plank\"]},{\"t\":\"Use a plank on the flat stone.\",\"i\":[\"Any plank\"]},{\"t\":\"Listen to the Shining Pool.\",\"s\":[\"Hello! Who are you?\",\"So what exactly do you want from me?\",\"That sounds like something I can do.\",\"I'll get right on it.\"]}]},{\"n\":\"Find out how to help\",\"st\":[{\"t\":\"Speak to Hamal the Chieftain in the Mountain Camp.\",\"s\":[\"About the people of Rellekka...\"],\"i\":[\"Rope\",\"Any pickaxe\",\"Any axe\",\"Any plank\",\"A staff or a pole\",\"Almost any gloves\"]},{\"t\":\"Speak to Jokul north of Hamal's tent.\"}]},{\"n\":\"Making peace with Rellekka\",\"st\":[{\"t\":\"Speak to Svidi who roams in the forest east of Rellekka.\",\"s\":[\"Can't I persuade you to go in there somehow?\"],\"i\":[\"Any pickaxe\"]},{\"t\":\"Speak to Brundt the Chieftain in the Rellekka's longhall.\",\"s\":[\"Ask about the mountain camp.\",\"Did it look pretty?\"],\"i\":[\"Rope\",\"Any pickaxe\",\"Any axe\",\"Any plank\",\"A staff or a pole\",\"Almost any gloves\"]},{\"t\":\"Use a pickaxe on the Ancient Rock in the Mountain Camp.\",\"i\":[\"Any pickaxe\"]},{\"t\":\"Return to Brundt the Chieftain in the Rellekka's longhall.\",\"s\":[\"Ask about the mountain camp.\"],\"i\":[\"Half a rock\"]},{\"t\":\"Return to Svidi who roams in the forest east of Rellekka.\",\"i\":[\"Safety Guarantee\"]}]},{\"n\":\"Find a new food source\",\"st\":[{\"t\":\"Go to the top of White Wolf Mountain and pick the Thorny Bushes whilst wearing gloves.\",\"i\":[\"Almost any gloves\"]},{\"t\":\"Eat the White Pearl.\",\"i\":[\"White pearl\"]}],\"i\":[\"Any axe\",\"Almost any gloves\"]},{\"n\":\"Tell Hamal about your success\",\"st\":[{\"t\":\"Return to Hamal the Chieftain in the Mountain Camp.\",\"s\":[\"About the people of Rellekka...\"],\"i\":[\"White pearl seed\"]}]},{\"n\":\"Tell Asleif about your success\",\"st\":[{\"t\":\"Return to the centre of the pool north of the Mountain Camp and listen to it.\",\"i\":[\"A staff or a pole\",\"Any plank\"]}]},{\"n\":\"Find Asleif's corpse\",\"st\":[{\"t\":\"Cut through the trees north east of the lake and enter the cave there. Bring combat gear.\",\"i\":[\"Any axe\"]},{\"t\":\"Speak to the Kendal, then kill him.\",\"s\":[\"It's just me, no one special.\",\"You mean a sacrifice?\",\"You look like a man in a bearsuit!\",\"Can I see that corpse?\",\"I humbly request to be given the remains.\",\"I will kill you myself!\"]},{\"t\":\"Pick up the Corpse of Woman.\"}],\"c\":1,\"e\":[\"The Kendal (level 70)\"]},{\"n\":\"Bring Asleif's corpse to Hamal\",\"st\":[{\"t\":\"Bring the corpse to Hamal.\",\"s\":[\"But he's not a god!\",\"I will.\"],\"i\":[\"Corpse of woman\"]}]},{\"n\":\"Bury Asleif\",\"st\":[{\"t\":\"Collect 5 Muddy Rocks from around the camp.\",\"i\":[\"Muddy rock (5)\"]},{\"t\":\"Speak to Ragnar.\",\"s\":[\"Thank you. I will make sure she's given a proper burial now.\"],\"i\":[\"Corpse of woman\",\"Muddy rock (5)\"]},{\"t\":\"Return to the centre of the lake and bury the corpse.\",\"i\":[\"Corpse of woman\",\"A staff or a pole\",\"Any plank\"]},{\"t\":\"Use the Muddy rocks on the Burial Mound at the centre of the Mountain Camp's lake.\",\"i\":[\"Muddy rock (5)\"]}]}]}"
        "Mourning's End Part I" -> "{\"n\":\"Mourning's End Part I\",\"items\":[\"Bear fur\",\"Silk (2)\",\"Red dye\",\"Yellow dye\",\"Blue dye\",\"Green dye\",\"Bucket of water\",\"Feather\",\"Rotten apple\",\"Toad crunchies (can be Premade t'd crunch)\",\"Magic logs\",\"Leather\",\"Ogre bellows\",\"Barrel of coal tar + 10-20 coal, or a barrel of naphtha\"],\"rec\":[\"Teleport to the Outpost. Necklace of passage (The Outpost [2])\",\"Teleport to Taverley. Taverley Teleport, Games necklace (Burthorpe. [1])\",\"Lletya teleport. Teleport crystal\",\"West ardougne teleport (3)\"],\"enemies\":[\"Mourner (level 11) (will decrease all combat skills to 20, including Hitpoints)\"],\"rewards\":[\"2 Quest points\",\"40,000 Thieving XP\",\"25,000 Hitpoints XP\",\"Elven Teleport Crystal\",\"Access to the Mourner HQ\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Talk to Islwyn in Isafdar. If he's not at the marked location, try hopping worlds to find him here.\",\"s\":[\"I'm ready now.\",\"I'm ready.\",\"Yes.\"]},{\"t\":\"Talk to Arianwyn in Lletya.\",\"s\":[\"Okay, let's begin.\"]}]},{\"n\":\"Get Mourner's outfit\",\"st\":[{\"t\":\"Kill a mourner travelling through the Arandar pass. This is more easily accessed from the north entrance. You'll need 7 free inventory spaces.\"},{\"t\":\"Pick up everything the mourner dropped.\",\"i\":[\"Mourner boots\",\"Mourner cloak\",\"Mourner gloves\",\"Ripped mourner trousers\",\"Gas mask\",\"Mourner letter\",\"Bloody mourner top\"]}],\"i\":[\"Teleport to the Outpost. Necklace of passage (The Outpost [2])\",\"Teleport to Taverley. Taverley Teleport, Games necklace (Burthorpe. [1])\"],\"c\":1,\"e\":[\"Mourner (level 11) (will decrease all combat skills to 20, including Hitpoints)\"]},{\"n\":\"Clean Mourner top\",\"st\":[{\"t\":\"Search Tegid's laundry basket in south Taverley for some soap.\",\"s\":[\"Steal the soap.\"]},{\"t\":\"Use the soap on the bloody mourner top\",\"i\":[\"Tegid's soap\",\"Bucket of water\",\"Bloody mourner top\"]}