        "Mourning's End Part II" -> "{\"n\":\"Mourning's End Part II\",\"items\":[\"Full mourners' outfit\",\"Chisel\",\"Access to the Death Altar or 50 items asked of you by a dwarf\",\"Rope\"],\"rec\":[\"Stamina potions\",\"Prayer potions for Protect from Melee\",\"Food\",\"West ardougne teleport\",\"Lletya teleport. Teleport crystal\"],\"enemies\":[\"Able to survive Shadows (level 73) continually attacking you\"],\"rewards\":[\"2 Quest points\",\"60,000 Agility XP\",\"A Crystal Trinket\",\"A Death Talisman\",\"Ability to craft Death Runes.\",\"Ability to kill Dark Beasts and receive them as a slayer task.\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Talk to Arianwyn in Lletya.\",\"s\":[\"Yes.\"]}]},{\"n\":\"Explore the caves\",\"st\":[{\"t\":\"Talk to Essyllt.\"},{\"t\":\"Enter the Mourner Caves.\"},{\"t\":\"Follow the caves to the west until you reach the Temple of Light. Search the guard corpse nearby.\"},{\"t\":\"Follow the caves to the west to the Temple of Light. Go up the stairs in it.\"},{\"t\":\"Go up the south staircase.\"},{\"t\":\"Go down the staircase north of you.\"},{\"t\":\"Go up the stairs to the north.\"},{\"t\":\"Use a chisel on the dark crystal to the east.\",\"i\":[\"Chisel\"]},{\"t\":\"Bring the crystal to Arianwyn in Lletya.\",\"i\":[\"Blackened crystal\"]},{\"t\":\"Talk to Eluned in Lletya next to Arianwyn.\"},{\"t\":\"Talk to Arianwyn in Lletya.\"}],\"i\":[\"Chisel\",\"Full mourners' outfit\"],\"tr\":[\"West ardougne teleport\",\"Lletya teleport. Teleport crystal\"]},{\"n\":\"Return to the Temple\",\"st\":[{\"t\":\"If you are an ironman, you can earn the death talisman later. Return to the Temple of Light. Make sure you're prepared for shadows to be continuously attacking you.\"}],\"i\":[\"Rope\",\"Full mourners' outfit\",\"Access to the Death Altar\"]},{\"n\":\"Puzzle 1\",\"st\":[{\"t\":\"Go up the stairs to the first floor.\"},{\"t\":\"Pull the Crystal Dispenser in the east room.\",\"s\":[\"Pull the lever.\",\"Pull it.\",\"Take everything.\"]},{\"t\":\"Put a mirror in the pillar next to the dispenser and have the light point north.\",\"i\":[\"Hand mirror\"]},{\"t\":\"Put a mirror in the pillar to the north and point it west.\",\"i\":[\"Hand mirror\"]},{\"t\":\"Put a mirror in the pillar to the west and point it south.\",\"i\":[\"Hand mirror\"]},{\"t\":\"Put a yellow crystal in the pillar to the south.\",\"i\":[\"Yellow crystal\"]},{\"t\":\"Put a mirror in the pillar to the south and point it east.\",\"i\":[\"Hand mirror\"]},{\"t\":\"Attempt to climb the wall support to the south west. You may fail this multiple times. Agility boosts help your chances.\"},{\"t\":\"Search the chest in the blue light room.\"}]},{\"n\":\"Puzzle 2\",\"st\":[{\"t\":\"Pull the Crystal Dispenser in the east room to reset the puzzle.\",\"s\":[\"Pull it.\",\"Take everything.\"]},{\"t\":\"Put a mirror in the pillar next to the dispenser and have the light point north.\",\"i\":[\"Hand mirror\"]},{\"t\":\"Put a mirror in the pillar to the north and point it west.\",\"i\":[\"Hand mirror\"]},{\"t\":\"Put a cyan crystal in the pillar to the west.\",\"i\":[\"Cyan crystal\"]},{\"t\":\"Put a mirror in the pillar to the west and point it north.\",\"i\":[\"Hand mirror\"]},{\"t\":\"Put a mirror in the pillar to the north and point it east.\",\"i\":[\"Hand mirror\"]},{\"t\":\"Put a yellow crystal in the pillar to the east.\",\"i\":[\"Yellow crystal\"]},{\"t\":\"Search the chest in the magenta room in the north east corner.\"}]},{\"n\":\"Puzzle 3\",\"st\":[{\"t\":\"Take the yellow crystal out of the pillar, and replace it with a mirror pointing up.\"},{\"t\":\"Go up the north ladder to the second floor.\"},{\"t\":\"Put a mirror in the pillar next to you and point it west.\",\"i\":[\"Hand mirror\"]},{\"t\":\"Go down the north ladder to the first floor.\"},{\"t\":\"Go up the south staircase to the second floor.\"},{\"t\":\"Place a mirror in the far north-west corner's pillar pointing down.\",\"i\":[\"Hand mirror\"]},{\"t\":\"Go down to the ground floor.\"},{\"t\":\"Enter the room in the far north west corner.\"},{\"t\":\"Turn the mirror in the pillar in the room to point the light south.\"},{\"t\":\"Search the chest in the room south of you.\"}]},{\"n\":\"Puzzle 4\",\"st\":[{\"t\":\"Go up the stairs to the first floor.\"},{\"t\":\"Take the cyan crystal out of the pillar north of the stairs, and replace it with a yellow crystal.\"},{\"t\":\"Go up the south staircase to the second floor.\"},{\"t\":\"Place a mirror in the far north-west corner's pillar pointing south.\",\"i\":[\"Hand mirror\"]},{\"t\":\"Go to the far south-west corner and place a mirror pointing down.\",\"i\":[\"Hand mirror\"]},{\"t\":\"Go down to the first floor.\"},{\"t\":\"Use a rope on the rocks in the small room in the south of the first floor.\",\"i\":[\"Rope\"]},{\"t\":\"Go down the rope you tied in the south room of the first floor.\"},{\"t\":\"Search the chest in the south west room.\"}],\"i\":[\"Rope\"]},{\"n\":\"Puzzle 5 P1\",\"st\":[{\"t\":\"Return to the first floor and reset the puzzle.\"},{\"t\":\"Pull the Crystal Dispenser in the east room to reset the puzzle, and take all the items.\",\"s\":[\"Pull it.\",\"Take everything.\"]},{\"t\":\"Put a mirror in the pillar next to the dispenser and have the light point north.\",\"i\":[\"Hand mirror\"]},{\"t\":\"Put a mirror in the pillar to the north and point it west.\",\"i\":[\"Hand mirror\"]},{\"t\":\"Put a mirror in the pillar to the west and point it south.\",\"i\":[\"Hand mirror\"]},{\"t\":\"Put a yellow crystal in the pillar to the south.\",\"i\":[\"Yellow crystal\"]},{\"t\":\"Put a mirror in the pillar to the south and point it east.\",\"i\":[\"Hand mirror\"]},{\"t\":\"Make sure you have the blue crystal, and attempt to climb the wall support to the south west. You may fail this multiple times.\",\"i\":[\"Blue crystal\"]},{\"t\":\"Put a blue crystal in the pillar in the blue room.\",\"i\":[\"Blue crystal\"]}]},{\"n\":\"Puzzle 5 P2\",\"st\":[{\"t\":\"REMOVE the mirror from the pillar in the south of the first floor.\"},{\"t\":\"Have the mirror in the pillar north west of the dispenser point up.\",\"i\":[\"Hand mirror\"]},{\"t\":\"Go up the south staircase to the second floor.\"},{\"t\":\"Go down the staircase north of you.\"},{\"t\":\"Go up the stairs to the north.\"},{\"t\":\"Place a mirror in the pillar north east of you and face it south.\",\"i\":[\"Hand mirror\"]},{\"t\":\"Go back to the south side of floor 2.\"},{\"t\":\"Place the fractured crystal in the pillar a bit east.\",\"i\":[\"Fractured crystal\"]},{\"t\":\"Place a mirror in the pillar to the west and point it down.\",\"i\":[\"Hand mirror\"]},{\"t\":\"Place a mirror in the pillar to the south east and point it east.\",\"i\":[\"Hand mirror\"]},{\"t\":\"Place a mirror in the pillar to the east and point it down.\",\"i\":[\"Hand mirror\"]},{\"t\":\"Go down to the first floor.\"},{\"t\":\"Go down to the ground floor.\"},{\"t\":\"Add a mirror to the pillar where green light is coming down, and point it south.\",\"i\":[\"Hand mirror\"]},{\"t\":\"Add a mirror to the pillar to the south, and point it east.\",\"i\":[\"Hand mirror\"]},{\"t\":\"Enter the south east room, and add a mirror pointing to the north.\",\"i\":[\"Hand mirror\"]},{\"t\":\"Search the chest in the room north of you.\"}]},{\"n\":\"Reach the Death Altar\",\"st\":[{\"t\":\"Pull the Crystal Dispenser in the east room to reset the puzzle, and take all the items.\",\"s\":[\"Pull it.\",\"Take everything.\"]},{\"t\":\"Go up the stairs to the first floor.\"},{\"t\":\"Put a mirror in the pillar next to the dispenser and have the light point north.\",\"i\":[\"Hand mirror\"]},{\"t\":\"Put a mirror in the pillar to the north and point it down.\",\"i\":[\"Hand mirror\"]},{\"t\":\"Go down to the ground floor.\"},{\"t\":\"Put a mirror in the pillar north of the stairs and have the light point west.\",\"i\":[\"Hand mirror\"]},{\"t\":\"Put the fractured crystal (dark/light side split down middle) in the pillar to the west.\",\"i\":[\"Fractured crystal\"]},{\"t\":\"Put a mirror in the pillar north and have the light point up.\",\"i\":[\"Hand mirror\"]},{\"t\":\"Put the other fractured crystal in the pillar south of the other fractured crystal.\",\"i\":[\"Fractured crystal\"]},{\"t\":\"Add a mirror to the pillar to the west, and point it up.\",\"i\":[\"Hand mirror\"]},{\"t\":\"Put a mirror in the pillar to the east and have the light point up.\",\"i\":[\"Hand mirror\"]},{\"t\":\"Go to the far north where the ladder going up is, and place the yellow crystal there.\",\"i\":[\"Yellow crystal\"]},{\"t\":\"Go up the north ladder to the second floor.\"},{\"t\":\"Put a mirror in the pillar next to you and point it west.\",\"i\":[\"Hand mirror\"]},{\"t\":\"Go down the north ladder to the first floor.\"},{\"t\":\"Go up the south staircase to the second floor.\"},{\"t\":\"Place a mirror in the pillar to the north of the stairs and point it west.\",\"i\":[\"Hand mirror\"]},{\"t\":\"Place a mirror in the pillar to the far east, and point it west.\",\"i\":[\"Hand mirror\"]},{\"t\":\"Place a mirror to the west and point it north.\",\"i\":[\"Hand mirror\"]},{\"t\":\"Go down the staircase north of you.\"},{\"t\":\"Go up the stairs to the north.\"},{\"t\":\"Place a mirror in the pillar north east of the stairs pointing west.\",\"i\":[\"Hand mirror\"]},{\"t\":\"Place the blue crystal in the pillar to the west.\",\"i\":[\"Blue crystal\"]},{\"t\":\"Place a mirror in the far north-west corner's pillar pointing south.\",\"i\":[\"Hand mirror\"]},{\"t\":\"Place a mirror in the south pillar pointing east.\",\"i\":[\"Hand mirror\"]},{\"t\":\"Go down to the central area.\"},{\"t\":\"Enter the central area, and turn the pillar's mirror west.\"}]},{\"n\":\"Repair the defences\",\"st\":[{\"t\":\"Enter the barrier to the death altar to the west.\"},{\"t\":\"You need to get a Death Talisman. Either kill Dark Beasts for one, or bring 50 items requested by Thorgel at the Death Altar to him.\"},{\"t\":\"Enter the death altar ruins.\",\"i\":[\"Access to the Death Altar\"]},{\"t\":\"Use the newly made crystal on the death altar.\"},{\"t\":\"Leave the Death Altar and go use the charged crystal on the dark crystal.\"},{\"t\":\"Return to Arianwyn in Lletya.\"}],\"i\":[\"Access to the Death Altar\"]}]}"
        "Murder Mystery" -> "{\"n\":\"Murder Mystery\",\"items\":[\"Pot\"],\"rec\":[],\"enemies\":[],\"rewards\":[\"3 Quest points\",\"1,406 Crafting XP\",\"2000 x Coins\"],\"sec\":[{\"n\":\"Go to the Sinclair Manor\",\"st\":[{\"t\":\"Talk to the Guard in the Sinclair Manor north of Camelot.\",\"s\":[\"Yes.\"]}],\"i\":[\"Pot\"],\"c\":0},{\"n\":\"Collect evidence\",\"st\":[{\"t\":\"Search the window for a clothing thread. The colour of the thread will match the killer's trousers.\",\"i\":[\"Criminal's thread\"]},{\"t\":\"Enter the mansion and pick up the pungent pot inside the east room.\",\"i\":[\"Pungent pot\"]},{\"t\":\"Pick up the criminal's dagger.\",\"i\":[\"Criminal's dagger\"]}],\"c\":0},{\"n\":\"Collect fingerprints\",\"st\":[{\"t\":\"Investigate the sacks in the shed for flypaper. Get 2 pieces.\",\"s\":[\"Yes, it might be useful.\"],\"i\":[\"Flypaper (2)\"]},{\"t\":\"Search the suspect's barrel.\"},{\"t\":\"Fill your pot with flour from the barrel in the mansion's kitchen.\"},{\"t\":\"Use the pot of flour on the Criminal's dagger.\",\"i\":[\"Pot of flour\",\"Criminal's dagger\"]},{\"t\":\"Use the flypaper on the dagger.\",\"i\":[\"Flypaper\",\"Criminal's dagger\"]},{\"t\":\"Use flour on the suspect's item.\"},{\"t\":\"Use flypaper on the suspect's item.\"},{\"t\":\"Compare prints with the suspect.\"}],\"c\":0},{\"n\":\"Finishing off\",\"st\":[{\"t\":\"Talk to Gossip, just south of the Sinclair Mansion.\",\"s\":[\"Who do you think was responsible?\"]},{\"t\":\"Talk to the Poison Salesman in the Seers' Village pub about his customers.\",\"s\":[\"Who did you sell Poison to at the house?\",\"Talk about the Murder Mystery Quest\"]},{\"t\":\"Talk to the Poison Salesman in the Seers' Village pub about the pungent pot.\",\"s\":[\"I have this pot I found at the murder scene...\",\"Talk about the Murder Mystery Quest\"],\"i\":[\"Pungent pot\"]},{\"t\":\"Talk to the suspect.\",\"s\":[\"Why'd you buy poison the other day?\"]},{\"t\":\"Disprove the suspect's alibi by checking the thing they claimed to clean.\"},{\"t\":\"Return to the guard outside the Sinclair Mansion and tell him your findings.\",\"s\":[\"I know who did it!\"]}],\"c\":0}]}"
        "My Arm's Big Adventure" -> "{\"n\":\"My Arm's Big Adventure\",\"items\":[\"Climbing boots\",\"Ugthanki dung (3)\",\"Supercompost (8)\",\"Rake\",\"Seed dibber\",\"Spade\",\"Bucket\"],\"rec\":[\"Combat gear, preferably magic\",\"Food\",\"Prayer potions\",\"Games necklace for Burthorpe teleport\"],\"enemies\":[\"Baby Roc (level 75)\",\"Giant Roc (level 172)\"],\"rewards\":[\"1 Quest point\",\"10,000 Herblore XP\",\"5,000 Farming XP\",\"Access to a disease-free herb patch on top of the Troll Stronghold.\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Talk to Burntmeat in the Troll Stronghold.\",\"s\":[\"What do you want now?\"]},{\"t\":\"Talk to My Arm near Burntmeat.\",\"s\":[\"Alright, I'll lend him a hand.\"]}],\"i\":[\"Climbing boots\"],\"tr\":[\"Games necklace for Burthorpe teleport\"]},{\"n\":\"Preparing to grow\",\"st\":[{\"t\":\"Use a bucket on the cooking pot on the Death Plateau. You can find a bucket next to the pot.\",\"i\":[\"Bucket\"]},{\"t\":\"Return to My Arm with the goutweedy lump.\",\"i\":[\"Goutweedy lump\"]},{\"t\":\"Talk to My Arm on the roof of the Troll Stronghold.\"},{\"t\":\"Read the farming manual.\",\"i\":[\"Farming manual\"]}],\"i\":[\"Climbing boots\",\"Bucket\",\"Spade\",\"Supercompost (7)\",\"Ugthanki dung (3)\"],\"tr\":[\"Games necklace for Burthorpe teleport\"]},{\"n\":\"Karamja adventure\",\"st\":[{\"t\":\"Talk to Captain Barnaby on Ardougne dock.\",\"s\":[\"This is My Arm. We'd like to go to Karamja.\"]},{\"t\":\"Talk to My Arm on Brimhaven dock.\"},{\"t\":\"Talk to My Arm east of the Tai Bwo Wannai general store.\"},{\"t\":\"Talk to Murcaily in east Tai Bwo Wannai.\",\"s\":[\"A troll called My Arm wants a favour...\",\"I was asking you about goutweed...\",\"I was asking you about hardy goutweed...\"]},{\"t\":\"Talk to My Arm again east of the Tai Bwo Wannai general store.\"}]},{\"n\":\"Troll farming\",\"st\":[{\"t\":\"Talk to My Arm on the roof of the Troll Stronghold.\"},{\"t\":\"Give My Arm a rake.\",\"i\":[\"Rake\"]},{\"t\":\"Give My Arm some supercompost.\",\"i\":[\"Supercompost\"]},{\"t\":\"Give My Arm some hardy gout tubers.\",\"i\":[\"Hardy gout tubers\"]},{\"t\":\"Give My Arm a seed dibber.\",\"i\":[\"Seed dibber\"]},{\"t\":\"Talk to My Arm. Be prepared to fight a baby and giant Roc.\"},{\"t\":\"Kill the Baby Roc.\"},{\"t\":\"Kill the Giant Roc. Use protect from missiles, and keep your distance. You can dodge the boulders it throws.\"},{\"t\":\"Give My Arm a spade.\",\"i\":[\"Spade\"]},{\"t\":\"Talk to My Arm.\"},{\"t\":\"Talk to Burntmeat in the Troll Stronghold.\"},{\"t\":\"Talk to My Arm to finish the quest.\"}],\"i\":[\"Combat gear, preferably magic\",\"Rake\",\"Supercompost\",\"Seed dibber\",\"Spade\",\"Hardy gout tubers\"],\"c\":1,\"e\":[\"Baby Roc (level 75)\",\"Giant Roc (level 172)\"]}]}"
        "Nature Spirit" -> "{\"n\":\"Nature Spirit\",\"items\":[\"Ghostspeak amulet\",\"Silver sickle\"],\"rec\":[\"Salve Graveyard Teleports (2)\",\"Combat gear to kill the ghasts\"],\"enemies\":[\"3 Ghasts (level 30)\"],\"rewards\":[\"2 Quest points\",\"3,000 Crafting XP\",\"2,000 Defence XP\",\"2,000 Hitpoints XP\",\"Access to Mort Myre Swamp\",\"Ability to fight Ghasts.\"],\"sec\":[{\"n\":\"Start the quest\",\"st\":[{\"t\":\"Talk to Drezel under the Paterdomus Temple.\",\"s\":[\"Well, what is it, I may be able to help?\",\"Yes.\"]},{\"t\":\"Enter the Mort Myre from the north gate.\",\"i\":[\"Ghostspeak amulet\"]},{\"t\":\"Attempt to enter the Grotto in the south of Mort Myre.\",\"s\":[\"How long have you been a ghost?\"],\"i\":[\"Ghostspeak amulet\"]},{\"t\":\"Talk to Filliman Tarlock.\",\"s\":[\"How long have you been a ghost?\"],\"i\":[\"Ghostspeak amulet\"]},{\"t\":\"Pick up the washing bowl.\",\"i\":[\"Washing bowl\"]},{\"t\":\"Pick up the mirror.\",\"i\":[\"Mirror\"]},{\"t\":\"Use the mirror on Filliman Tarlock.\",\"s\":[\"How long have you been a ghost?\"],\"i\":[\"Ghostspeak amulet\",\"Mirror\"]},{\"t\":\"Right-click search the grotto tree.\"},{\"t\":\"Use the journal on Filliman Tarlock.\",\"s\":[\"How can I help?\"],\"i\":[\"Ghostspeak amulet\",\"Journal\"]}],\"i\":[\"Ghostspeak amulet\",\"Silver sickle\"]},{\"n\":\"Helping Filliman\",\"st\":[{\"t\":\"Return to Drezel under the Paterdomus Temple to get blessed.\"},{\"t\":\"Cast the druidic spell next to a rotten log in Mort Myre to grow a mushroom. Pick it. If you already have, open the quest journal to re-sync your state.\",\"s\":[\"Could I have another bloom scroll please?\"],\"i\":[\"Druidic spell\"]},{\"t\":\"Use the mushroom on the brown stone outside the grotto. If you already have, search it instead.\",\"i\":[\"Mort myre fungus\"]},{\"t\":\"Use the used spell on the gray stone outside the grotto. If you already have, search it instead.\",\"i\":[\"A used spell or druidic spell\"]},{\"t\":\"Stand on the orange stone outside the grotto.\"},{\"t\":\"Tell Filliman Tarlock you're ready.\",\"s\":[\"I think I've solved the puzzle!\"],\"i\":[\"Ghostspeak amulet\"]},{\"t\":\"Enter the Grotto in the south of Mort Myre.\",\"i\":[\"Ghostspeak amulet\",\"Silver sickle\"]},{\"t\":\"Search the grotto inside.\",\"i\":[\"Ghostspeak amulet\"]},{\"t\":\"Talk to Filliman in the grotto to bless your sickle.\",\"i\":[\"Ghostspeak amulet\",\"Silver sickle\"]},{\"t\":\"Talk to the Nature Spirit in the grotto to bless your sickle.\",\"i\":[\"Ghostspeak amulet\",\"Silver sickle\"]}],\"i\":[\"Ghostspeak amulet\",\"Silver sickle\"]},{\"n\":\"Killing Ghasts\",\"st\":[{\"t\":\"Right-click 'bloom' the blessed sickle next to rotten logs for mort myre fungi. Use these to fill the druid pouch.\",\"i\":[\"Silver sickle (b)\",\"Druidic pouch\"]},{\"t\":\"Use the filled druid pouch on a ghast to make it attackable and kill it. You'll need to kill 3.\",\"i\":[\"Druidic pouch\"]},{\"t\":\"Enter the Grotto in the south of Mort Myre.\",\"i\":[\"Ghostspeak amulet\"]},{\"t\":\"Talk to the Nature Spirit in the grotto to finish the quest!\",\"i\":[\"Ghostspeak amulet\"]}],\"i\":[\"Ghostspeak amulet\",\"Silver sickle (b)\"],\"c\":1,\"e\":[\"3 Ghasts (level 30)\"]}]}"
        "Observatory Quest" -> "{\"n\":\"Observatory Quest\",\"items\":[\"Plank (3)\",\"Bronze bar\",\"Molten glass\"],\"rec\":[\"Ring of dueling\",\"Antipoison (there is a spawn of superantipoison near the Observatory)\",\"Food\"],\"enemies\":[\"Goblin Guard (level 42, or you can lure it/have someone else kill it)\"],\"rewards\":[\"2 Quest points\",\"2,250 Crafting XP\",\"A reward depending on which constellation you observed.\"],\"sec\":[{\"n\":\"Helping the Professor\",\"st\":[{\"t\":\"Talk to the Observatory professor north of Castle Wars.\",\"s\":[\"Talk about the Observatory quest.\",\"An Observatory?\",\"Yes.\"],\"i\":[\"Plank (3)\",\"Molten glass\",\"Bronze bar\"]},{\"t\":\"Give the professor 3 planks.\",\"s\":[\"Talk about the Observatory quest.\"],\"i\":[\"Plank (3)\"]},{\"t\":\"Give the professor a bronze bar.\",\"s\":[\"Talk about the Observatory quest.\"],\"i\":[\"Bronze bar\"]},{\"t\":\"Give the professor some molten glass.\",\"s\":[\"Talk about the Observatory quest.\"],\"i\":[\"Molten glass\"]},{\"t\":\"Enter the dungeon east of the Professor.\"},{\"t\":\"Search only the marked chests in the dungeon. Unmarked chests contain monsters and may poison you.\"},{\"t\":\"Prod the sleeping guard in the north of the dungeon. He'll attack you. You need to then either kill him, or get him in the marked spot to the north of the gate.\"},{\"t\":\"Either kill or trap the guard on the marked tile to the north, then search the goblin stove.\"},{\"t\":\"Climb the stairs back to the surface.\"},{\"t\":\"Give the professor the lens mould. If you don't have it, check your bank.\",\"s\":[\"Talk about the Observatory quest.\"],\"i\":[\"Lens mould\"]},{\"t\":\"Use the molten glass on the mould.\",\"i\":[\"Molten glass\",\"Lens mould\"]},{\"t\":\"Give the professor the lens mould and lens.\",\"s\":[\"Talk about the Observatory quest.\"],\"i\":[\"Observatory lens\"]},{\"t\":\"Follow the dungeon around anti-clockwise to a staircase, then climb it.\"},{\"t\":\"Climb up the stairs in the observatory.\"},{\"t\":\"Use the telescope.\"}],\"i\":[\"Plank (3)\",\"Bronze bar\",\"Molten glass\"]}]}"
        "Olaf's Quest" -> "{\"n\":\"Olaf's Quest\",\"items\":[\"Any axe\",\"Tinderbox\",\"Spade\"],\"rec\":[\"Combat gear\",\"Food\",\"Prayer potions\"],\"enemies\":[\"Skeleton fremennik (level 40)\",\"Ulfric (level 100)\"],\"rewards\":[\"1 Quest point\",\"12,000 Defence XP\",\"4 x Rubies\",\"Access to Brine Rats and the ability to receive them as a slayer task.\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Talk to Olaf Hradson north east of Rellekka.\",\"s\":[\"Yes.\"]},{\"t\":\"Chop a log from the Windswept Tree east of Olaf.\",\"i\":[\"Any axe\"]},{\"t\":\"Bring the logs to Olaf Hradson north east of Rellekka.\",\"i\":[\"Windswept logs\"]},{\"t\":\"Talk to Ingrid Hradson near the well in southeast Rellekka.\",\"i\":[\"Crude carving\"]},{\"t\":\"Talk to Volf Olafson north of the longhall in Rellekka.\",\"i\":[\"Cruder carving\"]},{\"t\":\"Return to Olaf Hradson north east of Rellekka.\"},{\"t\":\"Use the damp planks on Olaf's embers.\",\"i\":[\"Damp planks\"]},{\"t\":\"Talk to Olaf again, and give him some food.\",\"s\":[\"Alright, here, have some food. Now give me the map.\"],\"i\":[\"Food\"]}],\"i\":[\"Any axe\",\"Tinderbox\",\"Spade\"]},{\"n\":\"Finding treasure\",\"st\":[{\"t\":\"Dig next to the Windswept Tree.\"},{\"t\":\"Go deeper into the caverns and kill a Skeleton Fremennik for a key.\"},{\"t\":\"Search the picture wall in the north room.\"},{\"t\":\"Pick up 2 rotten barrels and 6 ropes from around the room.\",\"i\":[\"Rotten barrel (2)\",\"Rope (6)\"]},{\"t\":\"WALK onto the walkway to the east, and use a barrel on it to repair it.\",\"i\":[\"Rotten barrel\",\"Rope (3)\"]},{\"t\":\"WALK on the walkway and repair the next hole in it.\",\"i\":[\"Rotten barrel\",\"Rope (3)\"]},{\"t\":\"Open the gate on the walkway, clicking the key hole which matches your key.\",\"i\":[\"Key\"]},{\"t\":\"WALK off the remaining walkway, and search the chest in the wreck. Be prepared to fight Ulfric.\"},{\"t\":\"Kill Ulfric.\"},{\"t\":\"Search the chest again to finish the quest.\"}],\"i\":[\"Spade\",\"Combat gear\"],\"c\":1,\"e\":[\"Skeleton fremennik (level 40)\",\"Ulfric (level 100)\"]}]}"
        "One Small Favour" -> "{\"n\":\"One Small Favour\",\"items\":[\"Steel bar (4)\",\"Bronze bar\",\"Iron bar\",\"Chisel\",\"Guam leaf (2)\",\"Marrentill\",\"Harralander\",\"Hammer\",\"Empty cup\",\"Pot\",\"Bowl of hot water\"],\"rec\":[\"Draynor Teleport with glory, 2 or more charges\",\"Teleports to Lumbridge (4)\",\"Teleports to Varrock (2)\",\"Teleports to Taverley or Falador (2)\",\"Teleports to Camelot or Catherby (2)\",\"Fishing and Mining Guild Teleport for Dwarven Mine with skills necklace, 4 or more charges\",\"Teleports to Ardougne (2)\",\"Teleports to Port Khazard (2)\",\"Teleports to Feldip Hills (2)\",\"Opal (2)\",\"Jade (2)\",\"Red topaz (2)\",\"Coins (3000)\",\"Any pickaxe to kill Slagilith\"],\"enemies\":[\"Slagilith (level 92)\",\"3x Dwarf gang members (level 44)\"],\"rewards\":[\"2 Quest points\",\"2 x 10,000 Experience Lamps (Any skill over level 30)\",\"A Steel Keyring\",\"The ability to make Guthix Rest tea.\",\"Gnome Glider in Feldip Hills.\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Talk to Yanni Salika in Shilo Village. CKR fairy ring or take cart from Brimhaven.\",\"s\":[\"Is there anything else interesting to do around here?\",\"Yes.\"]}]},{\"n\":\"A few small favours\",\"st\":[{\"t\":\"Talk to a Jungle Forester south of Shilo Village.\",\"s\":[\"I need to talk to you about red mahogany.\",\"Okay, I'll take your axe to get it sharpened.\"]},{\"t\":\"Talk to Brian in the Port Sarim axe shop.\",\"s\":[\"Do you sharpen axes?\",\"Look, can you sharpen this cursed axe or what?\",\"Ok, ok, I'll do it! I'll go and see Aggie.\"],\"i\":[\"Blunt axe\"]},{\"t\":\"Talk to Aggie in Draynor Village.\",\"s\":[\"Could I ask you about being a character witness?\",\"Let me guess, you're going to ask me to do you a favour?\",\"Oh, okay, I'll see if I can find Jimmy.\"]},{\"t\":\"Talk to Johanhus Ulsbrecht in the south of the H.A.M hideout.\",\"s\":[\"I'm looking for Jimmy the Chisel.\",\"And I suppose you need me to do you a favour?\",\"Ok, Jimmy has to be worth more than a few scrawny chickens!\"]},{\"t\":\"Talk to Fred the Farmer north of Lumbridge.\",\"s\":[\"I need to talk to you about Jimmy.\"]},{\"t\":\"Talk to Seth Groats in the farm north east of Lumbridge, across the river.\",\"s\":[\"Oh, ok! I guess it's not that much further to Varrock!\"]},{\"t\":\"Talk to Horvik in the armour shop north east of the Varrock square.\",\"s\":[\"Hi, I need to talk to you about chicken cages!\",\"Ok, I guess one good turn deserves another.\"],\"i\":[\"Steel bar (3)\"]},{\"t\":\"Talk to the Apothecary in west Varrock.\",\"s\":[\"Talk about One Small Favour.\",\"Oh, ok, I guess it's not that far to the Barbarian Village.\",\"I guess I can go to the Barbarian Village.\"]},{\"t\":\"Talk to Tassie Slipcast in the Barbarian Village pottery building.\",\"s\":[\"Ok, I'll deal with Hammerspike!\"]},{\"t\":\"Talk to Hammerspike Stoutbeard in the west cavern of the Dwarven Mine.\",\"s\":[\"Have you always been a gangster?\",\"Ok, another favour...I think I can manage that.\"]},{\"t\":\"Talk to Sanfew upstairs in the Taverley herblore store.\",\"s\":[\"Are you taking any new initiates?\",\"Do you accept dwarves?\",\"A dwarf I know wants to become an initiate.\",\"Yep, it's a deal.\"]},{\"t\":\"Make Guthix Rest by using a bowl of hot water on an empty tea cup, then using 2 guams, a marrentill and a harralander on it.\",\"i\":[\"Empty cup\",\"Bowl of hot water\",\"Guam leaf (2)\",\"Marrentill\",\"Harralander\"]},{\"t\":\"Right-click talk to Captain Bleemadge on White Wolf Mountain.\",\"s\":[\"I have a special tea here for you from Sanfew!\"],\"i\":[\"Guthix rest(3)\"]},{\"t\":\"Talk to Arhein in Catherby.\",\"s\":[\"I need to talk T.R.A.S.H. to you.\",\"Yes, Ok, I'll do it!\"]},{\"t\":\"Talk to Phantuwti in the south west house of Seers' Village.\",\"s\":[\"Hi, can you give me a weather forecast?\",\"What can I do to help?\",\"Yes, Ok, I'll do it.\"]},{\"t\":\"Enter the cave south east of the Fishing Guild.\"},{\"t\":\"Right-click search the sculpture in the wall in the north east corner of the cave.\"},{\"t\":\"Talk to Wizard Cromperty in north east Ardougne.\",\"s\":[\"Chat.\",\"I need to talk to you about a girl stuck in some rock!\",\"Oh! Ok, one more 'small favour' isn't going to kill me...I hope!\"]},{\"t\":\"Talk to Tindel Marchant in Port Khazard.\",\"s\":[\"Wizard Cromperty sent me to get some iron oxide.\",\"Ask about iron oxide.\",\"Okay, I'll do it!\"]},{\"t\":\"Talk to Rantz in the Feldip Hills. AKS fairy ring or Feldip Hills Teleport.\",\"s\":[\"I need to talk to you about a mattress.\",\"Ok, I'll see what I can do.\"]},{\"t\":\"Talk to Gnormadium Avlafrim west of Rantz.\",\"s\":[\"Rantz said I should help you finish this project.\",\"Yes, I'll take a look at them.\"]},{\"t\":\"Take the gems out of each of the gnome lamps, cut them, then put back in the cut gem.\"}],\"i\":[\"Chisel\",\"Steel bar (3)\",\"Empty cup\",\"Bowl of hot water\",\"Guam leaf (2)\",\"Marrentill\",\"Harralander\"],\"r\":[\"Opal (2)\",\"Jade (2)\",\"Red topaz (2)\",\"Coins (3000)\"]},{\"n\":\"Completing the favours\",\"st\":[{\"t\":\"Talk to Gnormadium Avlafrim again.\",\"s\":[\"I've fixed all the lights!\"]},{\"t\":\"Return to Rantz in the Feldip Hills. AKS fairy ring or Feldip Hills Teleport.\",\"s\":[\"Ok, I've helped that Gnome, he shouldn't bother you anymore.\"],\"i\":[\"Stodgy mattress\"]},{\"t\":\"Return to Tindel Marchant in Port Khazard.\",\"s\":[\"I have the mattress.\"],\"i\":[\"Comfy mattress\"]},{\"t\":\"Return to Wizard Cromperty in north east Ardougne.\",\"s\":[\"Chat.\",\"I have that iron oxide you asked for!\"],\"i\":[\"Iron oxide\"]},{\"t\":\"Get 5 pigeon cages from behind Jerico's house in central East Ardougne.\",\"i\":[\"Pigeon cages (5)\"]},{\"t\":\"Enter the cave south east of the Fishing Guild. Be prepared to fight the Slagilith(level 92, takes reduced damage from anything other than pickaxes).\",\"i\":[\"Pigeon cages (5)\",\"Animate rock scroll\",\"Any pickaxe to kill Slagilith\"]},{\"t\":\"Use the animate rock scroll next to the sculpture in the north east cavern.\",\"i\":[\"Animate rock scroll\"]},{\"t\":\"Kill the Slagilith. They take reduced damage from anything other than a pickaxe.\"},{\"t\":\"Read the animate rock scroll again.\",\"i\":[\"Animate rock scroll\"]},{\"t\":\"Talk to Petra Fiyed.\"},{\"t\":\"Return to Phantuwti in the south west house of Seers' Village.\",\"s\":[\"I've released Petra, she should have returned.\",\"I'll run you through if you don't give me that weather report.\",\"Why can't you get a clear picture?\"]},{\"t\":\"Right-click search the weathervane on top of the Seers' building.\"},{\"t\":\"Use a hammer on the weathervane.\",\"i\":[\"Hammer\"]},{\"t\":\"Right-click search the weathervane on top of the Seers' building again.\"},{\"t\":\"Repair the vane parts on an anvil. You can find one in the north of Seers' Village.\",\"i\":[\"Broken vane part\",\"Hammer\",\"Steel bar\",\"Iron bar\",\"Bronze bar\"]},{\"t\":\"Go back up to the Seers' roof and fix the vane.\"},{\"t\":\"Talk to Arhein in Catherby.\",\"s\":[\"What did you want me to do again?\",\"I have the weather report for you.\"],\"i\":[\"Weather report\"]},{\"t\":\"Right-click talk to Captain Bleemadge on White Wolf Mountain.\",\"s\":[\"Hey there, did you get your T.R.A.S.H?\"]},{\"t\":\"Return to Sanfew upstairs in the Taverley herblore store.\",\"s\":[\"Hi there, the Gnome Pilot has agreed to take you to see the ogres!\"]},{\"t\":\"Return to Hammerspike Stoutbeard in the west cavern of the Dwarven Mine.\"},{\"t\":\"Kill 3 dwarf gang members until Hammerspike gives in. One dwarf gang member should appear after each kill.\"},{\"t\":\"Return to Hammerspike Stoutbeard in the west cavern of the Dwarven Mine after killing his dwarf gang members.\"},{\"t\":\"Return to Tassie Slipcast in the Barbarian Village pottery building.\"},{\"t\":\"Spin the clay into a pot lid.\",\"i\":[\"Soft clay\"]},{\"t\":\"Fire the unfired pot lid.\",\"i\":[\"Unfired pot lid\"]},{\"t\":\"Get a pot to put your lid on. There's one in the Barbarian Village helmet shop.\",\"i\":[\"Pot\"]},{\"t\":\"Use the pot lid on a pot.\",\"i\":[\"Pot\",\"Pot lid\"]},{\"t\":\"Return to the Apothecary in west Varrock.\",\"s\":[\"Talk about One Small Favour.\"],\"i\":[\"Airtight pot\"]},{\"t\":\"Return to Horvik in the armour shop north east of the Varrock square.\",\"s\":[\"I have the tincture and the breathing salts.\"],\"i\":[\"Pigeon cages (5)\",\"Breathing salts\",\"Herbal tincture\"]},{\"t\":\"Talk to Horvik once more in the armour shop north east of the Varrock square.\",\"s\":[\"I have the five pigeon cages you asked for!\"],\"i\":[\"Pigeon cages (5)\"]},{\"t\":\"Return to Seth Groats in the farm north east of Lumbridge, across the river.\",\"i\":[\"Chicken cage (5)\"]},{\"t\":\"Return to Johanhus Ulsbrecht in the south of the H.A.M hideout.\",\"s\":[\"You're in luck, I've managed to swing that chicken deal for you.\"]},{\"t\":\"Return to Aggie in Draynor Village.\",\"s\":[\"Good news! Jimmy has been released!\"]},{\"t\":\"Return to Brian in the Port Sarim axe shop.\",\"s\":[\"I've returned with good news.\"]},{\"t\":\"Return to a Jungle Forester south of Shilo Village. CKR fairy ring or take cart from Brimhaven.\",\"s\":[\"Good news, I have your sharpened axe!\"],\"i\":[\"Sharpened axe\"]},{\"t\":\"Return to Yanni Salika in Shilo Village.\",\"s\":[\"Here's the red mahogany you asked for.\"],\"i\":[\"Red mahogany log\"]}],\"i\":[\"Bronze bar\",\"Iron bar\",\"Steel bar\",\"Hammer\",\"Pot\"],\"r\":[\"Combat gear to fight Slagilith and the dwarf gang members\",\"Any pickaxe to kill Slagilith\"],\"c\":1,\"e\":[\"Slagilith (level 92)\"]}]}"
        "Pandemonium" -> "{\"n\":\"Pandemonium\",\"items\":[\"Hammer\",\"Saw\"],\"rec\":[],\"enemies\":[],\"rewards\":[\"1 Quest point\",\"300 Sailing XP\",\"25 x Sawmill Coupon (wood plank)\",\"2 x Repair kits\",\"Spyglass\",\"Access to the Sailing Skill\",\"Access to Pandemonium\",\"Your very own mighty ship!\"],\"sec\":[{\"n\":\"You got the job!\",\"st\":[{\"t\":\"Talk to Will or Anne on the docks of Port Sarim to start the quest.\",\"s\":[\"Yes.\",\"Okay.\"]},{\"t\":\"Talk to Will or Anne on the docks to board the ship.\"}],\"c\":0},{\"n\":\"What's the job?\",\"st\":[{\"t\":\"Listen to the job explanation.\"},{\"t\":\"Navigate using the helm.\"},{\"t\":\"Raise your sails.\"},{\"t\":\"Sail south to the wreck north of the Pandemonium!\"},{\"t\":\"Learn about the other part of your job.\"},{\"t\":\"Deploy the Salvaging Hook.\"},{\"t\":\"Watch the salvaging cutscene.\"}],\"c\":0},{\"n\":\"You lost the job!\",\"st\":[{\"t\":\"Get back to the Pandemonium. You can travel with Captain Tobias on Port Sarim dock for 30gp.\",\"s\":[\"Yes please.\",\"I'd like to go to the Pandemonium.\"]},{\"t\":\"Talk to 'Squawking' Steve Beanie behind the bar to learn about where you are.\"},{\"t\":\"Talk to 'Squawking' Steve Beanie about Will and Anne.\"},{\"t\":\"Talk to Ribs near the door to learn about the map.\",\"s\":[\"No, tell me about him.\",\"Now's not really the time for tales.\"]},{\"t\":\"Ask 'Squawking' Steve Beanie behind the bar about Will and Anne's location.\",\"s\":[\"About Will and Anne...\",\"Do you have any idea where Will and Anne might have gone?\"]},{\"t\":\"Ask Junior Jim by the docks about getting a ship.\",\"s\":[\"I think I might have lost a cup here.\"],\"i\":[\"Old cup\"]},{\"t\":\"Hand over the cup to Junior Jim and receive your mighty vessel!\",\"s\":[\"I think I might have lost a cup here.\"],\"i\":[\"Old cup\"]}],\"c\":0},{\"n\":\"Your mighty vessel\",\"st\":[{\"t\":\"Talk to Junior Jim to enter the shipyard.\"},{\"t\":\"Pick up a saw from the crate of saws.\"},{\"t\":\"Pick up a hammer from the crate of hammers.\"},{\"t\":\"Board your vessel.\"},{\"t\":\"Build the Cargo Hold.\"},{\"t\":\"Disembark your vessel.\"},{\"t\":\"Leave the shipyard using the portal.\"},{\"t\":\"Talk to Junior Jim to get a log book.\"}],\"c\":0},{\"n\":\"You got the job... again!\",\"st\":[{\"t\":\"Talk to Junior Jim for a new job.\"},{\"t\":\"Navigate using the helm.\"},{\"t\":\"Raise your sails.\"},{\"t\":\"Let go of the helm.\"},{\"t\":\"Leave your ship.\"},{\"t\":\"Pick up the cargo from the ledger table on the docks.\"}],\"c\":0},{\"n\":\"Deliver the cargo.\",\"st\":[{\"t\":\"Deposit the crate into your cargo hold.\"},{\"t\":\"Navigate using the helm.\"},{\"t\":\"Raise your sails.\"},{\"t\":\"Let go of the helm.\"},{\"t\":\"Pick up the cargo from your ship's cargo hold.\"},{\"t\":\"Leave your ship.\"},{\"t\":\"Deliver the cargo at the ledger table on the docks.\"}],\"c\":0},{\"n\":\"Finishing up\",\"st\":[{\"t\":\"Tell Junior Jim about your delivery.\"},{\"t\":\"Meet 'Squawking' Steve Beanie and Old Grog at the bar.\"},{\"t\":\"Talk to 'Squawking' Steve Beanie to finish the quest.\"}],\"c\":0}]}"
        "Perilous Moons" -> "{\"n\":\"Perilous Moons\",\"items\":[\"Pestle and mortar\",\"Big fishing net\",\"Knife\",\"Rope\",\"Combat armour with high defensive bonuses\"],\"rec\":[\"Stamina potions\",\"Antipoison\"],\"enemies\":[\"Sulphur Nagua (level 98)\",\"Blue Moon (level 329)\",\"Blood Moon (level 329)\",\"Eclipse Moon (level 329)\"],\"rewards\":[\"2 Quest points\",\"40,000 Slayer XP\",\"5,000 Runecraft XP\",\"5,000 Hunter XP\",\"5,000 Fishing XP\",\"Access to Neypotzli and the Moons of Peril\"],\"sec\":[{\"n\":\"Ruined\",\"st\":[{\"t\":\"Talk to Attala, stood south of Ralos' Rise.\",\"s\":[\"Yes.\"]},{\"t\":\"Kill the sulphur nagua just atop the cliff north east of Attala. You can climb the rocks just to the east to reach it quickly with 47 Agility.\"},{\"t\":\"Return to Attala.\"},{\"t\":\"Enter the entrance to Cam Torum.\"},{\"t\":\"Talk to Jessamine in the far north end of Cam Torum.\",\"s\":[\"Can I be of any help with the dig?\"]},{\"t\":\"Enter the Neypotzli entrance in the far north of the cavern.\"},{\"t\":\"Talk to Attala near the entrance.\"},{\"t\":\"Talk to Zuma near the entrance.\"},{\"t\":\"Talk to Jessamine near the entrance.\"}],\"i\":[\"Combat armour with high defensive bonuses\"],\"c\":1,\"e\":[\"Sulphur Nagua (level 98)\"]},{\"n\":\"Camping up\",\"st\":[{\"t\":\"Take some building supplies from the crates near Jessamine.\"},{\"t\":\"Enter the south-west entrance.\",\"i\":[\"Building supplies\",\"Hammer\",\"Saw\"]},{\"t\":\"Make your way to the camp spot, marked on the minimap with a cooking range icon.\",\"i\":[\"Building supplies\",\"Hammer\",\"Saw\"]},{\"t\":\"Return to the antechamber.\"},{\"t\":\"Enter the north-west entrance.\",\"i\":[\"Building supplies\",\"Hammer\",\"Saw\"]},{\"t\":\"Enter the north-east entrance.\"}]},{\"n\":\"Enchanting\",\"st\":[{\"t\":\"Talk to Jessamine near the Monolith.\",\"s\":[\"What does the inscription say?\",\"What do we do now?\"]},{\"t\":\"Return to Cam Torum through the south entrance.\"},{\"t\":\"Talk to Nahta in the magic shop.\",\"s\":[\"Actually, I've been sent by Attala.\"],\"i\":[\"Earth talisman\",\"Water talisman\"]},{\"t\":\"Talk to the blacksmith near the anvils.\",\"s\":[\"I need your help with these talismans.\",\"Can you help?\"],\"i\":[\"Enchanted earth talisman\",\"Enchanted water talisman\"]},{\"t\":\"Enter the Neypotzli entrance in the far north of Cam Torum.\"},{\"t\":\"Use the talismans to find the correct location. Earth tells you if it's east/west, and the water talisman tells you north/south.\"},{\"t\":\"Talk to Eyatlalli.\"},{\"t\":\"Talk to Jessamine near the Monolith again.\"}]},{\"n\":\"Ritual\",\"st\":[{\"t\":\"Enter the north-east entrance to the streambound cavern.\"},{\"t\":\"Take herblore supplies from the supply crates in the camp. You only need the pestle and mortar.\",\"s\":[\"Take herblore supplies.\"]},{\"t\":\"Collect a grub from the grubby sapling east of the camp.\"},{\"t\":\"Use a pestle and mortar on the moonlight grub.\",\"i\":[\"Pestle and mortar\",\"Moonlight grub\"]},{\"t\":\"Take fishing supplies from the supply crates in the camp.\",\"s\":[\"Take fishing supplies.\"]},{\"t\":\"Fish a bream from the stream east of the camp.\",\"i\":[\"Big fishing net\",\"Knife\"]},{\"t\":\"Use a knife on the raw bream.\",\"i\":[\"Knife\",\"Raw bream\"]},{\"t\":\"Take hunter supplies from the supply crates in the camp. You only need the rope, and the knife from the fishing supplies.\",\"s\":[\"Take hunting supplies.\"]},{\"t\":\"Enter the entrance north of the camp.\",\"i\":[\"Rope\",\"Knife\"]},{\"t\":\"Set up a trap by clicking two rocks near one another.\",\"i\":[\"Rope\"]},{\"t\":\"Rustle the nearby bush to trap a lizard.\"},{\"t\":\"Pick up the raw moss lizard.\",\"i\":[\"Raw moss lizard\"]},{\"t\":\"Use a knife on the raw moss lizard.\",\"i\":[\"Knife\",\"Raw moss lizard\"]},{\"t\":\"Leave the area back to the antechamber via the south-east entrance.\"},{\"t\":\"Talk to Eyatlalli with the items.\",\"i\":[\"Moonlight grub paste\",\"Bream scales\",\"Moss lizard tail\"]}]},{\"n\":\"Blue moon\",\"st\":[{\"t\":\"Enter the north-west entrance to the earthbound cavern when you're ready for the blue moon fight. Make food and potions from the lizards, breams, and grubby saplings before the fights.\",\"i\":[\"Crush weapon\",\"Combat armour with high defensive bonuses\"]},{\"t\":\"Enter the entrance to the blue moon fight.\",\"i\":[\"Crush weapon\",\"Combat armour with high defensive bonuses\"]},{\"t\":\"Defeat the blue moon. Use a crush weapon. Protection prayers have no effect.\"}],\"i\":[\"Crush weapon\",\"Combat armour with high defensive bonuses\"],\"c\":1,\"e\":[\"Blue Moon (level 329)\"]},{\"n\":\"Blood moon\",\"st\":[{\"t\":\"Enter the ancient prison when you're ready for the blood moon fight. Make food and potions from the lizards, breams, and grubby saplings before the fights.\",\"i\":[\"Slash weapon\",\"Combat armour with high defensive bonuses\"]},{\"t\":\"Enter the north-east entrance to the blood moon fight.\",\"i\":[\"Slash weapon\",\"Combat armour with high defensive bonuses\"]},{\"t\":\"Defeat the blood moon. Use a slash weapon. Protection prayers have no effect.\"}],\"i\":[\"Slash weapon\",\"Combat armour with high defensive bonuses\"],\"c\":1,\"e\":[\"Blood Moon (level 329)\"]},{\"n\":\"Eclipse moon\",\"st\":[{\"t\":\"Enter the streambound cavern when you're ready for the eclipse moon fight. Make food and potions from the lizards, breams, and grubby saplings before the fights.\",\"i\":[\"Stab weapon\",\"Combat armour with high defensive bonuses\"]},{\"t\":\"Enter the south entrance to the eclipse moon fight.\",\"i\":[\"Stab weapon\",\"Combat armour with high defensive bonuses\"]},{\"t\":\"Defeat the eclipse moon. Use a stab weapon. Protection prayers have no effect.\"}],\"i\":[\"Stab weapon\",\"Combat armour with high defensive bonuses\"],\"c\":1,\"e\":[\"Eclipse Moon (level 329)\"]},{\"n\":\"Finishing off\",\"st\":[{\"t\":\"Return to Jessamine near the Monolith again.\"},{\"t\":\"Talk to Zuma.\"},{\"t\":\"Talk to Eyatlalli to finish the quest.\"}]}]}"
        "Pirate's Treasure" -> "{\"n\":\"Pirate's Treasure\",\"items\":[\"Coins (60)\",\"Spade\",\"Bananas (10)\"],\"rec\":[\"A teleport to Varrock\",\"A teleport to Falador\"],\"enemies\":[\"Gardener (level 4)\"],\"rewards\":[\"2 Quest points\",\"A Gold Ring\",\"An Emerald\",\"450 x Coins\"],\"sec\":[{\"n\":\"Talk to Redbeard Frank\",\"st\":[{\"t\":\"Talk to Redbeard Frank in Port Sarim.\",\"s\":[\"I'm in search of treasure.\",\"Yes.\"]}],\"i\":[\"Coins (60)\"]},{\"n\":\"Discover the treasure\",\"st\":[{\"t\":\"Climb up the stairs in The Blue Moon Inn in Varrock.\",\"i\":[\"Chest key\"]},{\"t\":\"Open the chest by using the key on it.\",\"s\":[\"Ok thanks, I'll go and get it.\"],\"i\":[\"Chest key\"]},{\"t\":\"Read the Pirate message.\",\"i\":[\"Pirate message\"]},{\"t\":\"Dig in the middle of the cross in Falador Park, and kill the Gardener (level 4) who appears. Once killed, dig again.\"}],\"i\":[\"Spade\"],\"c\":1,\"e\":[\"Gardener (level 4)\"]}]}"
        "Plague City" -> "{\"n\":\"Plague City\",\"items\":[\"Dwellberries\",\"Spade\",\"Rope\",\"Bucket of milk\",\"Chocolate dust\",\"Snape grass\"],\"rec\":[\"Bucket of water (4)\"],\"enemies\":[],\"rewards\":[\"1 Quest point\",\"2,425 Mining XP\",\"Ability to use Ardougne teleport spell and tablets\"],\"sec\":[{\"n\":\"Start the quest\",\"st\":[{\"t\":\"Talk to Edmond in the north-west corner of East Ardougne.\",\"s\":[\"What's happened to her?\",\"Yes.\"]}],\"i\":[\"Dwellberries\",\"Spade\",\"Rope\",\"Bucket of milk\",\"Chocolate dust\",\"Snape grass\"],\"c\":0},{\"n\":\"Infiltrate West Ardougne\",\"st\":[{\"t\":\"Talk to Alrena and give her the dwellberries.\",\"i\":[\"Dwellberries\"]},{\"t\":\"Grab the Picture from Edmond's house.\",\"i\":[\"Picture\"]},{\"t\":\"Talk to Edmond again.\"},{\"t\":\"Use four buckets of water on the mud patch in Edmond's garden patch.\",\"i\":[\"Bucket of water (4)\"]},{\"t\":\"Use a spade on the mud patch.\",\"i\":[\"Spade\"]},{\"t\":\"Go down the hole.\"},{\"t\":\"Attempt to pull the grill in the south of the sewer.\"},{\"t\":\"Use a rope on the grill.\",\"i\":[\"Rope\"]},{\"t\":\"Talk to Edmond and ask him to help you pull off the grill.\"},{\"t\":\"Equip the gas mask and climb through the pipe.\",\"i\":[\"Gas mask\"]}],\"c\":0},{\"n\":\"Discover Elena's location\",\"st\":[{\"t\":\"Talk to Jethick east of where you emerge.\",\"s\":[\"Yes, I'll return it for you.\"],\"i\":[\"Gas mask\",\"Picture\"]},{\"t\":\"Enter the tall house in north West Ardougne.\"},{\"t\":\"Talk to Martha or Ted Rehnison\"},{\"t\":\"Talk to Milli upstairs.\"}],\"c\":0},{\"n\":\"Freeing Elena\",\"st\":[{\"t\":\"Try to enter the house in the south-east corner of West Ardougne.\",\"s\":[\"I fear not a mere plague.\",\"I want to check anyway.\"]},{\"t\":\"Talk to the Clerk in the large building north of the manhole.\",\"s\":[\"I need permission to enter a plague house.\",\"This is urgent though! Someone's been kidnapped!\"]},{\"t\":\"Talk to Bravek in the room to the east.\",\"s\":[\"This is really important though!\",\"Do you know what's in the cure?\"]},{\"t\":\"Use your chocolate dust on the bucket of milk.\",\"i\":[\"Bucket of milk\",\"Chocolate dust\"]},{\"t\":\"Use the snape grass on the chocolatey milk\",\"i\":[\"Chocolatey milk\",\"Snape grass\"]},{\"t\":\"Give the hangover cure to Bravek.\",\"i\":[\"Hangover cure\"]},{\"t\":\"Talk to Bravek to receive the warrant you need to enter the plague house.\",\"s\":[\"They won't listen to me!\"]},{\"t\":\"Try to enter the plague house again.\",\"i\":[\"Warrant\"]},{\"t\":\"Search the barrel in the room for a small key.\"},{\"t\":\"Go downstairs in the plague house.\",\"i\":[\"A small key\"]},{\"t\":\"Enter the jail and talk to Elena.\",\"i\":[\"A small key\"]}],\"c\":0},{\"n\":\"Finishing off\",\"st\":[{\"t\":\"Return to Edmond to finish the quest.\"}],\"c\":0}]}"
        "Priest in Peril" -> "{\"n\":\"Priest in Peril\",\"items\":[\"Rune or Pure Essence (50)\",\"Bucket\"],\"rec\":[\"Ranged or melee weapon + armour\",\"Varrock teleports (3)\",\"Essence pouches for carrying essence\"],\"enemies\":[\"Temple Guardian (level 30). You cannot use Magic. Rings of recoil will not award the kill.\",\"Monk of Zamorak (level 30)\"],\"rewards\":[\"1 Quest point\",\"1,406 Prayer XP\",\"Wolfbane Dagger\",\"Access to Canifis and Morytania\"],\"sec\":[{\"n\":\"Start the quest\",\"st\":[{\"t\":\"Speak to King Roald in Varrock Castle.\",\"s\":[\"I'm looking for a quest!\",\"Yes.\"]}]},{\"n\":\"Go to the temple\",\"st\":[{\"t\":\"Go to the temple east of Varrock by the river and click on the large door.\",\"s\":[\"I'll get going.\",\"Roald sent me to check on Drezel.\",\"Sure. I'm a helpful person!\"],\"i\":[\"Ranged or melee weapon + armour\"]},{\"t\":\"Kill the Temple Guardian (level 30). It is immune to magic so you will need to use either ranged or melee.\"},{\"t\":\"Return to King Roald.\",\"s\":[\"About that job I'm doing...\"]}],\"i\":[\"Ranged or melee weapon + armour\"],\"c\":1,\"e\":[\"Temple Guardian (level 30). You cannot use Magic. Rings of recoil will not award the kill.\"]},{\"n\":\"Return to the temple\",\"st\":[{\"t\":\"Return to the temple.\",\"i\":[\"Bucket\",\"As much essence as you can carry, you'll need to bring 50 UNNOTED in total\",\"Combat gear, ranged or mage to safespot\"]},{\"t\":\"Kill a Monk of Zamorak (level 30) for a golden key. You can safespot using the pews.\",\"i\":[\"Golden key\"]},{\"t\":\"Talk to Drezel on the top floor of the temple.\",\"s\":[\"So, what now?\",\"Yes, of course.\"]}],\"i\":[\"Ranged or melee weapon + armour\",\"Bucket\",\"As much essence as you can carry, you'll need to bring 50 UNNOTED in total\"],\"c\":1,\"e\":[\"Monk of Zamorak (level 30)\"]},{\"n\":\"Freeing Drezel\",\"st\":[{\"t\":\"Go down to the underground of the temple.\",\"i\":[\"Bucket\"]},{\"t\":\"Go to the central room, and study the monuments to find which has a key on it. Use the Golden Key on it.\",\"i\":[\"Golden key\"]},{\"t\":\"Use the bucket on the well in the central room.\",\"i\":[\"Bucket\"]},{\"t\":\"Go back up to the top floor of the temple.\"},{\"t\":\"Open the cell door.\",\"i\":[\"Iron key\"]},{\"t\":\"Talk to Drezel to bless the water.\",\"i\":[\"Murky water\"]},{\"t\":\"Use the blessed water on the coffin.\",\"i\":[\"Blessed water\"]},{\"t\":\"Talk to Drezel again.\"}],\"i\":[\"Ranged or melee weapon + armour\",\"Bucket\",\"As much essence as you can carry, you'll need to bring 50 UNNOTED in total\"],\"c\":1},{\"n\":\"Curing the Salve\",\"st\":[{\"t\":\"Talk to Drezel in the east of the underground temple area.\",\"i\":[\"As much essence as you can carry, you'll need to bring 50 UNNOTED in total\"]}],\"i\":[\"Rune or Pure Essence (50)\"]}]}"
        "Prince Ali Rescue" -> "{\"n\":\"Prince Ali Rescue\",\"items\":[\"Soft clay\",\"Balls of wool (3)\",\"Yellow dye\",\"Redberries\",\"Ashes\",\"Bucket of water\",\"Pot of flour\",\"Bronze bar\",\"Pink skirt\",\"Beers (3)\",\"Rope\",\"Coins minimum (100)\"],\"rec\":[\"Amulet of Glory for Al Kharid and Draynor Village teleports\"],\"enemies\":[\"Able to survive jail guards (level 26) attacking you\"],\"rewards\":[\"3 Quest points\",\"700 x Coins\",\"Free use of the Al Kharid toll gates.\",\"Access to Sorceress's Garden Minigame (Members)\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Talk to Hassan in the Al Kharid Palace.\",\"s\":[\"Is there anything I can help you with?\",\"Yes.\"]},{\"t\":\"Talk to Osman north of the Al Kharid Palace.\"}]},{\"n\":\"Make a blonde wig\",\"st\":[{\"t\":\"Have Ned in Draynor Village make you a wig from 3 balls of wool. He can also sell you a rope for 15 coins via dialogue (or bought from his shop for 18 coins) or 4 balls of wool.\",\"s\":[\"Could you make other things apart from rope?\",\"How about some sort of wig?\",\"I have them here. Please make me a wig.\"],\"i\":[\"Balls of wool (3)\"]},{\"t\":\"Dye the wig with yellow dye. Buy a yellow dye with two onions and 5 coins if you still need it from Aggie in Draynor Village.\",\"i\":[\"Yellow dye\",\"Wig\"]}],\"i\":[\"Yellow dye\",\"Balls of wool (3)\"]},{\"n\":\"Make paste\",\"st\":[{\"t\":\"Talk to Aggie in Draynor Village to get some paste.\",\"s\":[\"Can you make skin paste?\",\"Yes please. Mix me some skin paste.\"],\"i\":[\"Redberries\",\"Ashes\",\"Pot of flour\",\"Bucket of water\"]}],\"i\":[\"Redberries\",\"Ashes\",\"Pot of flour\",\"Bucket of water\"]},{\"n\":\"Make a key print\",\"st\":[{\"t\":\"Talk to Keli in the jail east of Draynor Village. If you've already made the key print, open the quest journal to re-sync.\",\"s\":[\"Heard of you? You're famous in Gielinor!\",\"What's your latest plan then?\",\"How do you know someone won't try to free him?\",\"Could I see the key please?\",\"Could I touch the key for a moment please?\"],\"i\":[\"Soft clay\"]}],\"i\":[\"Soft clay\"]},{\"n\":\"Make the key\",\"st\":[{\"t\":\"Use the key print on any furnace with a bronze bar in your inventory to make a key.\",\"i\":[\"Key print\",\"Bronze bar\"]}],\"i\":[\"Bronze bar\",\"Key print\"]},{\"n\":\"Return with the items\",\"st\":[{\"t\":\"Talk to Leela east of Draynor Village.\",\"i\":[\"Beers (3)\",\"Wig (dyed)\",\"Paste\",\"Rope\",\"Pink skirt\"]}],\"i\":[\"Wig (dyed)\",\"Paste\",\"Rope\",\"Beers (3)\",\"Pink skirt\"]},{\"n\":\"Free Ali\",\"st\":[{\"t\":\"Bring everything to the jail and give Joe there three beers.\",\"s\":[\"I have some beer here. Fancy one?\"],\"i\":[\"Beers (3)\",\"Bronze key\",\"Wig (dyed)\",\"Paste\",\"Rope\",\"Pink skirt\"]},{\"t\":\"Use rope on Keli.\",\"i\":[\"Rope\"]},{\"t\":\"Use the key on the prison door. If Lady Keli respawned you'll need to tie her up again.\",\"i\":[\"Bronze key\",\"Wig (dyed)\",\"Paste\",\"Pink skirt\"]},{\"t\":\"Talk to Prince Ali and free him.\",\"i\":[\"Bronze key\",\"Wig (dyed)\",\"Paste\",\"Pink skirt\"]}],\"i\":[\"Bronze key\",\"Wig (dyed)\",\"Paste\",\"Rope\",\"Beers (3)\",\"Pink skirt\"]},{\"n\":\"Return to Al Kharid\",\"st\":[{\"t\":\"Return to Hassan in the Al Kharid Palace to complete the quest.\"}]}]}"
        "Prying Times" -> "{\"n\":\"Prying Times\",\"items\":[\"Hammer\",\"Steel bar\",\"Redberry pie\",\"Captain's log\"],\"rec\":[],\"enemies\":[\"Drink Troll (level 14) (can be ignored)\"],\"rewards\":[\"1 Quest point\",\"800 Sailing XP\",\"1,000 Smithing XP\",\"25 x Sawmill Coupon (oak plank)\",\"Unlimited Crowbars from the crate of crowbars\",\"Ability to chart forgotten drinks\"],\"sec\":[{\"n\":\"Looty!\",\"st\":[{\"t\":\"Talk to 'Squawking' Steve Beanie behind the Pandemonium bar to start the quest. You can travel there via Captain Tobias on Port Sarim docks for 30gp.\",\"s\":[\"Any word from Old Grog?\",\"Yes.\"],\"i\":[\"Captain's log\"]},{\"t\":\"Let 'Squawking' Steve Beanie behind the bar know you delivered the looty.\",\"s\":[\"I delivered that cargo for you.\"]}],\"i\":[\"Captain's log\"]},{\"n\":\"A key!\",\"st\":[{\"t\":\"Get the key from Thurgo in the shed near Mudskipper's Point.\",\"s\":[\"I need some help with a 'special key'.\",\"So, can you help me make a crowbar?\",\"Can you help me make another crowbar?\",\"Yes.\"],\"i\":[\"Hammer\",\"Steel bar\",\"Redberry pie\"]},{\"t\":\"Give the 'key' to 'Squawking' Steve Beanie behind the Pandemonium bar. You can travel there via Captain Tobias on Port Sarim docks for 30gp.\",\"s\":[\"I made that 'special key' you needed.\"],\"i\":[\"Crowbar\"]},{\"t\":\"Sail to the crate north-west of Pandemonium.\",\"i\":[\"Crowbar\"]},{\"t\":\"Open the Sealed crate with the newly acquired 'key'.\",\"i\":[\"Crowbar\"]},{\"t\":\"Drink the stout. Warning: you will be attacked by a level 14 Drink Troll.\",\"i\":[\"Bottle of fish bladder stout\"]},{\"t\":\"Kill the Drink Troll, or log out.\"},{\"t\":\"Tell 'Squawking' Steve Beanie behind the Pandemonium bar the key works.\",\"s\":[\"About that crate...\"],\"i\":[\"Crowbar\"]},{\"t\":\"Open Steve's crate in the corner behind the bar.\",\"i\":[\"Crowbar\"]}],\"i\":[\"Hammer\",\"Steel bar\",\"Redberry pie\"],\"c\":1,\"e\":[\"Drink Troll (level 14) (can be ignored)\"]}]}"
        "Rag and Bone Man I" -> "{\"n\":\"Rag and Bone Man I\",\"items\":[\"Coins (8)\",\"Pot (8)\",\"Logs (8)\",\"Tinderbox\"],\"rec\":[\"Combat gear\",\"Varrock teleport\",\"Lumbridge teleport\",\"Digsite pendant\",\"Draynor teleport\",\"Karamja teleport\"],\"enemies\":[\"8 low leveled monsters for their bones\"],\"rewards\":[\"1 Quest point\",\"500 Cooking XP\",\"500 Prayer XP\"],\"sec\":[{\"n\":\"Starting out\",\"st\":[{\"t\":\"Talk to the Odd Old Man east of Varrock.\",\"s\":[\"Anything I can do to help?\",\"Yes.\"]}]},{\"n\":\"Collecting bones\",\"st\":[{\"t\":\"Kill a giant rat south east of Varrock.\"},{\"t\":\"Kill the unicorn south east of Varrock.\"},{\"t\":\"Kill the bear south east of Varrock.\"},{\"t\":\"Kill a ram south of Varrock.\"},{\"t\":\"Kill a goblin east of Lumbridge.\"},{\"t\":\"Kill a big frog in the Lumbridge Swamp.\"},{\"t\":\"Kill a monkey on Karamja.\"},{\"t\":\"Kill a giant bat in the Karamja Volcano Dungeon.\"},{\"t\":\"Pickup the bone.\"}],\"r\":[\"Combat gear\"]},{\"n\":\"Preparing the bones\",\"st\":[{\"t\":\"Talk to Fortunato in Draynor Village, and then buy 8 jugs of vinegar from him.\",\"i\":[\"Coins (8)\"]},{\"t\":\"Use the vinegar on pots for 8 pots of vinegar.\",\"i\":[\"Jug of vinegar (8)\",\"Pot (8)\"]},{\"t\":\"Use the bones on the pots of vinegar.\",\"i\":[\"Pot of vinegar\"]}]},{\"n\":\"Cleaning the bones\",\"st\":[{\"t\":\"Place logs under the pot-boiler near the Odd Old Man. If you've already polished all the bones, hand them in to the Odd Old Man.\",\"i\":[\"Logs\"]},{\"t\":\"Add a bone to the pot boiler.\"},{\"t\":\"Light the logs under the pot-boiler.\",\"i\":[\"Tinderbox\"]},{\"t\":\"Wait for the bones to be cleaned. You can hop worlds to make this happen instantly.\"},{\"t\":\"Take the pot from the pot-boiler.\"},{\"t\":\"Repeat the steps until all the bones are cleaned.\"}]},{\"n\":\"Handing the bones in\",\"st\":[{\"t\":\"Give the Odd Old Man the bones.\"}]}]}"
