        "Regicide" -> "{\"n\":\"Regicide\",\"items\":[\"Bow (not crossbow)\",\"Arrows (metal, unpoisoned)\",\"Rope (2)\",\"Spade\",\"Limestone\",\"Tinderbox\",\"Strip of cloth\",\"Pestle and mortar\",\"Gloves which fully cover your hand\",\"Pot\",\"Coal (20)\",\"Cooked rabbit\"],\"rec\":[\"Stamina Potions\",\"Antidotes/antipoisons\",\"Summer pie as food + agility boost\",\"Plank\",\"Falador teleport\",\"Combat Equipment\",\"West Ardougne teleport (4)\"],\"enemies\":[\"Tyras guard (level 110)\"],\"rewards\":[\"3 Quest points\",\"13,750 Agility XP\",\"15000 x Coins\",\"Access to Tirannwn & Arandar\",\"Ability to wield the Dragon Halberd\",\"Ability to charter a ship to Port Tyras.\",\"Ability to use Iorwerth Camp teleport scrolls.\",\"Ability to use Zul-Andra teleport scrolls and battle Zulrah.\"],\"sec\":[{\"n\":\"Starting out\",\"st\":[{\"t\":\"Talk to King Lathas.\",\"s\":[\"I assume you have a plan?\",\"I can handle it.\",\"Yes.\"]}]},{\"n\":\"To the Elven Lands\",\"st\":[{\"t\":\"Traverse the Underground Pass.\",\"i\":[\"Bow (not crossbow)\",\"Arrows (metal, unpoisoned)\",\"Rope\",\"Spade\"]},{\"t\":\"WAIT OUTSIDE AROUND the cave entrance for Idris to appear and talk to her (If Idris does not appear in the couple minutes enter and exit the cave). Afterwards, Go talk to Lord Iorwerth in the north west of the elven forest.\"},{\"t\":\"Go talk to the Elven Tracker in the south of the forest.\"},{\"t\":\"Return to Lord Iorwerth in the north west of the elven forest.\"},{\"t\":\"Return to the Elven Tracker in the south of the forest.\"},{\"t\":\"Click the tracks near the Tracker.\"},{\"t\":\"Talk to the Elven Tracker again.\"},{\"t\":\"Climb through the dense forest near the Tracker, and defeat the guard you find. This requires 56 Agility.\"},{\"t\":\"Enter the Tyras Camp.\"},{\"t\":\"Fill some barrels with tar, pick up some sulphur there, and then return to Lord Iorwerth.\"},{\"t\":\"Read the big book of bangs.\",\"i\":[\"Big book of bangs\"]},{\"t\":\"Ask Iorwerth a