        "Secrets of the North" -> "{\"n\":\"Secrets of the North\",\"items\":[\"Coins (100)\",\"Lockpick\",\"Tinderbox\",\"Combat Gear\",\"Food\"],\"rec\":[\"Antipoisons\",\"Any Ardougne Cloak\",\"Icy Basalt\"],\"enemies\":[\"Evelot (level 148)\",\"Assassin (level 262)\",\"Strange Creature (level 368)\"],\"rewards\":[\"2 Quest points\",\"60,000 Agility XP\",\"50,000 Thieving XP\",\"40,000 Hunter XP\",\"Ability to mine ancient essence crystals in the Ghorrock Dungeon\",\"Access to a new boss, the Phantom Muspah\"],\"sec\":[{\"n\":\"Starting Off\",\"st\":[{\"t\":\"Talk to the guard outside of the Carnillean Mansion in East Ardougne.\",\"s\":[\"Yes.\"]},{\"t\":\"Climb the stairs in Carnillean Mansion and talk to the guard there.\"},{\"t\":\"Inspect Ceril Carnillean's body.\"},{\"t\":\"Inspect the broken Window on the East side of the room.\"},{\"t\":\"Knock-at the wall on the North side of the room.\",\"s\":[\"Yes.\"]},{\"t\":\"Climb the Ladder.\"},{\"t\":\"Inspect the chest.\"},{\"t\":\"Descend the ladder and talk to the guard about what you've found.\"}]},{\"n\":\"Hunting Down Evelot\",\"st\":[{\"t\":\"Climb down the staircase.\"},{\"t\":\"Head to the Fight Arena Bar and talk to the Khazard Barman.\",\"s\":[\"Do you know anyone called Evelot?\"],\"i\":[\"Coins (100)\",\"Combat Gear\"]},{\"t\":\"Inspect the barrels outside the Fight Arena Bar entrance.\",\"i\":[\"Combat Gear\"]},{\"t\":\"Inspect the boulder to the north.\",\"i\":[\"Combat Gear\"]},{\"t\":\"Continue north and inspect the bush there.\",\"i\":[\"Combat Gear\"]},{\"t\":\"Inspect the stump to the east.\",\"i\":[\"Combat Gear\"]},{\"t\":\"Inspect the boulder to the south east.\",\"i\":[\"Combat Gear\"]},{\"t\":\"Inspect the bush to the east.\",\"i\":[\"Combat Gear\"]},{\"t\":\"Approach Evelot to the east to start the fight. Protect from melee and reactivate prayer after she special attacks.\",\"i\":[\"Combat Gear\"]},{\"t\":\"Talk to Evelot again after the fight.\"}],\"i\":[\"Coins (100)\",\"Combat Gear\"],