        "Shades of Mort'ton" -> "{\"n\":\"Shades of Mort'ton\",\"items\":[\"Tarromin potion (unf) (2)\",\"Tinderbox\",\"A log whose pyre version you can burn\",\"Ashes (2)\",\"Coins for building materials, or 18000 if you want to buy a Flamtaer hammer (5000)\",\"Hammer or Flamtaer Hammer\"],\"rec\":[\"Combat gear\",\"A Mort'ton teleport or Barrows teleport tablet\",\"Food\",\"Flamtaer hammer\",\"Flamtaer bracelet\"],\"enemies\":[\"5 Loar Shades (level 40)\"],\"rewards\":[\"3 Quest points\",\"2,000 Crafting XP\",\"2,000 Herblore XP\",\"Ability to play the Shades of Mort'ton Minigame\"],\"sec\":[{\"n\":\"Investigating the town\",\"st\":[{\"t\":\"Search the shelf in the south building of Mort'ton.\"},{\"t\":\"Read the diary.\",\"i\":[\"Diary\"]},{\"t\":\"Add ashes to a tarromin potion (unf).\",\"i\":[\"Tarromin potion (unf)\",\"Ashes\"]}],\"i\":[\"Tarromin potion (unf) (2)\",\"Ashes (2)\",\"Tinderbox\",\"A log whose pyre version you can burn\",\"Coins for building materials, or 18000 if you want to buy a Flamtaer hammer (5000)\",\"Hammer or Flamtaer Hammer\"]},{\"n\":\"Helping Razmire\",\"st\":[{\"t\":\"Use the serum 207 on Razmire in the north of Mort'ton.\",\"i\":[\"Serum 207\"]},{\"t\":\"Talk to Razmire in the north of Mort'ton.\",\"s\":[\"What are all these shadowy creatures?\",\"Yes, I'll dispatch those dark and evil creatures.\"],\"i\":[\"Serum 207\"]},{\"t\":\"Kill 5 Loar Shades and pick up their remains.\",\"i\":[\"Loar remains (5)\"]}],\"i\":[\"Serum 207\",\"Tinderbox\",\"A log whose pyre version you can burn\",\"Coins for building materials, or 18000 if you want to buy a Flamtaer hammer (5000)\",\"Hammer or Flamtaer Hammer\"],\"c\":1,\"e\":[\"5 Loar Shades (level 40)\"]},{\"n\":\"Helping Ulsquire\",\"st\":[{\"t\":\"Buy some olive oil from Razmire's general store, and 5 timber beams, 5 limestone bricks, and 25 swamp paste from their builders' store. Afterwards, use some serum 207 on Ulsquire.\",\"s\":[\"Can you open a store for me?\",\"Can I see the general store please?\"],\"i\":[\"Serum 207\"]},{\"t\":\"Talk to Ulsquire in the east of Mort'ton.\"},{\"t\":\"Talk to Ulsquire again.\",\"s\":[\"What can you tell me about that temple?\"]},{\"t\":\"Repair the temple north east of Mort'ton. Do this on World 377 to make it faster and easier.\",\"i\":[\"Olive oil\",\"Serum 207\",\"Hammer or Flamtaer Hammer\",\"Limestone brick (5)\",\"Timber beam (5)\",\"Swamp paste (25)\"]},{\"t\":\"Light the fire altar\",\"i\":[\"Tinderbox\"]},{\"t\":\"Keep repairing the temple until 20 sanctity.\",\"i\":[\"Olive oil\",\"Serum 207\",\"Hammer or Flamtaer Hammer\",\"Limestone brick (5)\",\"Timber beam (5)\",\"Swamp paste (25)\"]},{\"t\":\"Use the olive oil on the temple's fire.\",\"i\":[\"Olive oil\"]},{\"t\":\"Use a serum 207 (with 2 or more doses) on the temple's fire.\",\"i\":[\"Serum 207\"]},{\"t\":\"Use the sacred oil on a log.\",\"i\":[\"A log whose pyre version you can burn\",\"Sacred oil\"]},{\"t\":\"Use the pyre log in a funeral pyre, then a loar remain. Finally, burn it.\",\"i\":[\"A pyre log you can burn\",\"Loar remains\"]},{\"t\":\"Use the serum 208 on Razmire in the north of Mort'ton.\",\"i\":[\"Serum 208\"]},{\"t\":\"Use some serum 208 on Ulsquire in the east of Mort'ton.\",\"i\":[\"Serum 208\"]},{\"t\":\"Talk to Ulsquire to finish the quest.\"}],\"i\":[\"Serum 207\",\"Tinderbox\",\"A log whose pyre version you can burn\",\"Coins for building materials, or 18000 if you want to buy a Flamtaer hammer (5000)\",\"Hammer or Flamtaer Hammer\"]}]}"
        "Shadow of the Storm" -> "{\"n\":\"Shadow of the Storm\",\"items\":[\"Silverlight\",\"pieces of black clothing (3)\",\"Silver bar\"],\"rec\":[\"Combat gear + potions\",\"Coins or more for carpet rides (400)\",\"Al Kharid Teleport\"],\"enemies\":[\"Agrith-Naar (level 100)\"],\"rewards\":[\"1 Quest point\",\"10,000 Experience Lamp (Any combat skill except Prayer)\",\"Darklight\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Talk to Father Reen outside Al Kharid bank.\",\"s\":[\"That's me!\",\"Yes.\"]}]},{\"n\":\"Infiltrate the cult\",\"st\":[{\"t\":\"Talk to Father Badden in Uzer.\",\"s\":[\"Uzer\",\"Reen sent me.\",\"So what do you want me to do?\",\"How can I do that?\"],\"i\":[\"Silverlight\",\"pieces of black clothing (3)\"]},{\"t\":\"Pick up some black mushrooms.\"},{\"t\":\"Use the black mushrooms on Silverlight.\",\"i\":[\"Silverlight\",\"Black mushroom\"]},{\"t\":\"Enter the Uzer ruins.\",\"i\":[\"Silverlight (dyed)\",\"pieces of black clothing (3)\"]},{\"t\":\"Pick up the strange implement in the north west corner of the ruin.\",\"i\":[\"Strange implement\"]},{\"t\":\"Talk to Evil Dave with the dyed Silverlight and 3 dark clothing items equipped.\",\"s\":[\"I want to join your group.\",\"I'm evil!\"],\"i\":[\"Silverlight (dyed)\",\"pieces of black clothing (3)\"]},{\"t\":\"Talk to Denath next to the throne.\",\"s\":[\"What do I have to do?\"]},{\"t\":\"Talk to Jennifer.\",\"s\":[\"Do you have the demonic sigil mould?\"]},{\"t\":\"Talk to Matthew.\",\"s\":[\"Do you know what happened to Josef?\"]}],\"i\":[\"Silverlight\",\"pieces of black clothing (3)\"]},{\"n\":\"Uncovering the truth\",\"st\":[{\"t\":\"Travel to any furnace with the sigil mould and silver bar and smelt a sigil.\",\"i\":[\"Silver bar\",\"Demonic sigil mould\"]},{\"t\":\"Talk to the Golem in Uzer.\",\"s\":[\"Uzer\",\"Did you see anything happen last night?\"],\"i\":[\"Silverlight (dyed)\",\"Demonic sigil\",\"Combat gear + potions\"]},{\"t\":\"Read the book.\",\"i\":[\"Demonic tome\