        "Shield of Arrav" -> "{\"n\":\"Shield of Arrav\",\"items\":[\"Coins (20)\"],\"rec\":[],\"enemies\":[\"Jonny the beard (level 2)\"],\"rewards\":[\"1 Quest point\",\"600 x Coins\"],\"sec\":[{\"n\":\"Locating the Phoenix Gang\",\"st\":[{\"t\":\"Talk to Reldo in the Varrock Castle library.\",\"s\":[\"I'm in search of a quest.\",\"Yes.\"]},{\"t\":\"Search the marked bookcase for a book, then read it.\",\"i\":[\"Book\"]},{\"t\":\"Talk to Reldo again.\",\"s\":[\"Okay, I've read that book about the Shield of Arrav.\"]},{\"t\":\"Talk to Baraek in the Varrock Square.\",\"s\":[\"Can you tell me where I can find the Phoenix Gang?\",\"Okay. Have 20 gold coins.\"],\"i\":[\"Coins (20)\"]},{\"t\":\"Head into the Phoenix Gang's base in south Varrock.\"},{\"t\":\"Talk to Straven.\",\"s\":[\"I know who you are!\",\"I'd like to offer you my services.\"]}]},{\"n\":\"Joining the gang\",\"st\":[{\"t\":\"Go back up to the surface.\"},{\"t\":\"Kill Jonny the Beard in the Blue Moon Inn in Varrock.\"},{\"t\":\"Pick up the Intel Report.\",\"i\":[\"Intel report\"]},{\"t\":\"Return to the Phoenix Gang's base.\"},{\"t\":\"Talk to Straven again.\"}],\"c\":1,\"e\":[\"Jonny the beard (level 2)\"]},{\"n\":\"Returning the shield\",\"st\":[{\"t\":\"Search the chest in the Phoenix base for half of the Shield of Arrav.\"},{\"t\":\"Trade your weapon store key to your partner. If you can't trade, use the key on them to drop it at their feet. AFTERWARDS, talk to Curator Haig in the Varrock Museum.\",\"i\":[\"Broken shield\"]},{\"t\":\"Trade one of your certificate halves for the other half with another player. If you cannot trade, use the certificate on them to drop it at their feet. They can do the same for you.\"},{\"t\":\"Use the two certificate halves together to create the certificate.\",\"i\":[\"Half certificate\"]},{\"t\":\"Talk to King Roald in Varrock Castle to finish the quest.\",\"i\":[\"Certificate\"]}]}]}"
        "Shilo Village" -> "{\"n\":\"Shilo Village\",\"items\":[\"Spade\",\"Lit torch or candle\",\"Rope\",\"Bronze wire\",\"Chisel\",\"Bones (3)\"],\"rec\":[\"Combat gear\",\"Food\",\"Stamina potions\",\"Antipoisons\",\"Prayer potions\",\"A quick teleport for escaping\",\"Papyrus\",\"Charcoal\",\"Crumble undead spell for final boss\"],\"enemies\":[\"Nazastarool 3 times (levels 68, 91, 93) (safespottable)\"],\"rewards\":[\"2 Quest points\",\"3,875 Crafting XP\",\"Access to Shilo Village\",\"Ability to mine gem rocks in Shilo Village\"],\"sec\":[{\"n\":\"Exploring\",\"st\":[{\"t\":\"Talk to Mosol Rei east of Shilo Village in south Karamja to receive a wampum belt.\",\"s\":[\"Why do I need to run?\",\"Rashiliyia? Who is she?\",\"I'll go to see the Shaman.\",\"Yes, I'm sure and I'll take the Wampum belt to Trufitus.\"]},{\"t\":\"Show the wampum belt to Trufitus in Tai Bwo Wannai village.\",\"s\":[\"Mosol gave me something to show you.\",\"Mosol Rei said something about a legend?\",\"Why was it called Ah Za Rhoon?\",\"I am going to search for Ah Za Rhoon!\",\"Yes.\"],\"i\":[\"Wampum belt\"]},{\"t\":\"Use a spade on the ground in south east Karamja.\",\"i\":[\"Spade\"]},{\"t\":\"Use a lit torch or candle on the fissure.\",\"s\":[\"Yes\"],\"i\":[\"Lit torch or candle\"]},{\"t\":\"Use a rope on the fissure.\",\"i\":[\"Rope\"]},{\"t\":\"Right-click search the fissure.\",\"s\":[\"Yes, I'll give it a go!\"]},{\"t\":\"Search the nearby cave-in to go deeper in the caverns.\",\"s\":[\"Yes, I'll wriggle through.\"]},{\"t\":\"Search the loose rocks to the north for a tattered scroll.\",\"s\":[\"Yes, I'll carefully move the rocks to see what's behind them.\"]},{\"t\":\"Search the old sacks to the east for a crumpled scroll.\"},{\"t\":\"Right-click search the gallows in the north east corner for a corpse.\",\"s\":[\"Yes, I may find something else on the corpse.\"]},{\"t\":\"Bury Zadimus's corpse in the middle of Tai Bwo Wannai.\",\"i\":[\"Zadimus corpse\"]},{\"t\":\"Read the tattered scroll.\",\"s\":[\"Yes please.\"],\"i\":[\"Tattered scroll\"]},{\"t\":\"Read the crumpled scroll.\",\"s\":[\"Yes please.\"],\"i\":[\"Crumpled scroll\"]}],\"i\":[\"Spade\",\"Lit torch or candle\",\"Rope\",\"Chisel\"]},{\"n\":\"Free Rashiliyia\",\"st\":[{\"t\":\"Right-click search the rocks on Cairn Isle.\",\"s\":[\"Yes please, I can think of nothing nicer!\"]},{\"t\":\"Right-click search the tomb dolmen to the south.\"},{\"t\":\"Use a chisel on the pommel.\",\"i\":[\"Chisel\",\"Sword pommel\"]},{\"t\":\"Use bronze wire on the beads.\",\"i\":[\"Bronze wire\",\"Bone beads\"]},{\"t\":\"Search the palm trees in the north east of Karamja. Come equipped for a boss fight.\",\"i\":[\"Beads of the dead\",\"Bone shard\",\"Chisel\",\"Bones (3)\",\"Combat gear\",\"Crumble undead spell for final boss\",\"Food\"]},{\"t\":\"Right-click search the carved doors behind the palm trees.\",\"i\":[\"Combat gear\"]},{\"t\":\"Use a chisel on the bone shard.\",\"i\":[\"Chisel\",\"Bone shard\"]},{\"t\":\"Use the bone key on the doors behind the palm trees.\",\"i\":[\"Bone key\"]},{\"t\":\"Enter the doors behind the palm trees.\",\"i\":[\"Beads of the dead\",\"Bones (3)\",\"Combat gear\"]},{\"t\":\"Equip the beads of the dead, then make your way through the gate, down the rocks, then to the south west corner. Use bones on the door there.\",\"i\":[\"Beads of the dead\",\"Bones (3)\"]},{\"t\":\"Search the tomb dolmen, ready to fight.\"},{\"t\":\"Defeat Nazastarool's 3 forms. You can safe spot them over the tomb dolmen. The Crumble Undead spell is very strong against them.\"},{\"t\":\"Pickup Rashiliyia's corpse.\",\"i\":[\"Rashiliyia corpse\"]},{\"t\":\"Right-click search the rocks on Cairn Isle to enter the caverns again.\",\"s\":[\"Yes please, I can think of nothing nicer!\"],\"i\":[\"Rashiliyia corpse\"]},{\"t\":\"Use Rashiliyia's corpse on the dolmen to the south.\",\"i\":[\"Rashiliyia corpse\"]}],\"i\":[\"Chisel\",\"Bronze wire\",\"Bones (3)\"],\"r\":[\"Combat gear\",\"Food\",\"Crumble undead spell for final boss\",\"Prayer potions\"],\"c\":1,\"e\":[\"Nazastarool 3 times (levels 68, 91, 93) (safespottable)\"]}]}"
        "Sins of the Father" -> "{\"n\":\"Sins of the Father\",\"items\":[\"Combat gear + food\",\"Vyrewatch outfit or 1950 coins\",\"Ivandis flail\",\"Any axe\",\"Ruby\",\"Runes or tablet for Enchant Ruby\",\"Knife\",\"Chisel\"],\"rec\":[\"Any pickaxe\",\"Antipoison\",\"Drakan's medallion\",\"Morytania legs 3/4\"],\"enemies\":[\"Kroy (level 133)\",\"Vampyre juveniles (level 122 and 119)\",\"Nail beasts (level 143 and 67)\",\"Mutated bloodveld (level 123)\",\"Damien Leucurte (level 204)\",\"Vanstrom Klause (level 413)\"],\"rewards\":[\"2 Quest points\",\"6 x 15,000 Experience Tomes (Any skill above 60)\",\"A Blisterwood Flail\",\"Access to Darkmeyer and the Daeyalt Essence Mine\",\"Darkmeyer teleport via Drakan's Medallion.\"],\"sec\":[{\"n\":\"Investigating Slepe\",\"st\":[{\"t\":\"Talk to Veliaf in Slepe.\",\"s\":[\"Yes.\"]},{\"t\":\"Go to the church and talk Hameln the Jester about how his friend fell ill.\",\"s\":[\"I'd better get going.\",\"Do you know how he fell ill?\"]},{\"t\":\"Go to The Rat & Bat pub south east of the church and speak to Carl.\",\"s\":[\"Where do you get your Bloody Bracers from?\"]},{\"t\":\"Inspect the barrel south of the Rat & Bat Pub.\"},{\"t\":\"Follow Carl, hiding behind objects when he turns around.\"},{\"t\":\"Kill Kroy. Dodge the potion he sometimes throws to avoid damage and your attack rate being reduced.\"},{\"t\":\"Destroy both the Lab tables.\"},{\"t\":\"Return to Veliaf in Slepe.\",\"s\":[\"Fair enough, so what now?\"]}],\"i\":[\"Combat gear + food\"],\"c\":1,\"e\":[\"Kroy (level 133)\"]},{\"n\":\"Helping the Myreque\",\"st\":[{\"t\":\"Talk to Veliaf in Paterdomus.\",\"s\":[\"I see. So that's why you want to keep him safe, Veliaf?\"]},{\"t\":\"Speak to Ivan Strom south of Fenkenstrain's Castle.\"},{\"t\":\"Listen to the meeting.\"}]},{\"n\":\"Escorting Ivan\",\"st\":[{\"t\":\"Speak to Ivan Strom outside the east entrance of Paterdomus.\",\"s\":[\"I'm ready.\"]},{\"t\":\"Search the nearby backpack for a knife.\"},{\"t\":\"Cut 3 vines from the nearby tree.\",\"i\":[\"Knife\"]},{\"t\":\"Combine the vines together.\",\"i\":[\"Short vine (3)\"]},{\"t\":\"Use the long vine on the nearby branch.\",\"i\":[\"Long vine\"]},{\"t\":\"Swing on the vine.\"},{\"t\":\"Continue the trek.\",\"s\":[\"Yes.\"]},{\"t\":\"Kill the nail beasts.\"},{\"t\":\"Kill the nearby zombie for an axe.\",\"i\":[\"Any axe\"]},{\"t\":\"Chop the nearby dead trees for 3 logs.\",\"i\":[\"Any axe\"]},{\"t\":\"Repair the bridge.\",\"i\":[\"Any axe\",\"Logs (3)\"]},{\"t\":\"Cross the bridge.\"},{\"t\":\"Kill the juvinates with the Ivandis Flail. Try to attack the one near Ivan before it can attack him.\",\"i\":[\"Ivandis flail\"]}],\"i\":[\"Combat gear + food\",\"Ivandis flail\"],\"c\":1,\"e\":[\"Nail beasts (level 143 and 67)\"]},{\"n\":\"Learning of the Icyene\",\"st\":[{\"t\":\"Finish speaking to Ivan Strom.\"},{\"t\":\"Talk to Veliaf at the boat house in the south of Burgh de Rott.\"},{\"t\":\"Get into the boat to the Icyene Graveyard.\",\"s\":[\"Icyene Graveyard.\"]},{\"t\":\"Finish talking to Veliaf and Safalaan.\",\"s\":[\"Icyene Graveyard.\"]},{\"t\":\"Talk with Vanescula Drakan.\",\"s\":[\"Icyene Graveyard.\"]},{\"t\":\"Open the mausoleum's door.\"},{\"t\":\"Speak to Verdita Sefalatis in the Icyene Graveyard.\"},{\"t\":\"Speak to Kael Forshaw in the Icyene Graveyard. If you already have, open the quest journal to re-sync.\"},{\"t\":\"Speak to Radigad Ponfit in the Icyene Graveyard.\"},{\"t\":\"Speak to Polmafi Ferdygris in the Icyene Graveyard.\"},{\"t\":\"Speak to Ivan Strom in the Icyene Graveyard.\"},{\"t\":\"Speak to Veliaf Hurtz in the Icyene Graveyard.\"},{\"t\":\"Speak to Vanescula in the Icyene Graveyard.\",\"s\":[\"Icyene Graveyard.\"]}]},{\"n\":\"Investigating the lab\",\"st\":[{\"t\":\"Enter the Meiyerditch lab. The fastest way here is to have a Vyrewatch take you to the mines, mine 15 Daeyalt Ore, then leave.\",\"s\":[\"Meiyerditch.\"]},{\"t\":\"Speak to Safalaan at the Lab.\",\"s\":[\"Shall we get going then?\",\"Let's go.\"]},{\"t\":\"Defeat the Mutated Bloodveld (lvl-123).\"},{\"t\":\"Finish speaking with Safalaan in the Lab.\"},{\"t\":\"Search the bookshelf in the room west of Safalaan in the Lab.\",\"s\":[\"I'll be back soon.\"]},{\"t\":\"Go show Safalaan the Haemalchemy book 2 you found.\",\"s\":[\"Sure. Here you go.\"],\"i\":[\"Haemalchemy volume 2\"]}],\"i\":[\"Combat gear + food\",\"Any pickaxe\"],\"c\":1,\"e\":[\"Mutated bloodveld (level 123)\"]},{\"n\":\"Making a disguise\",\"st\":[{\"t\":\"Speak to Vanescula in the Icyene Graveyard. Take the boat south of Burgh de Rott to get there.\",\"s\":[\"Okay. I'll see you soon.\",\"Icyene Graveyard.\"]},{\"t\":\"Bring a Vyrewatch disguise to Polmafi in the Meiyerditch hideout in Old Man Ral's basement.\",\"s\":[\"Here you go.\"],\"i\":[\"Vyrewatch top\",\"Vyrewatch legs\",\"Vyrewatch shoes\"]},{\"t\":\"Return to Vanescula in the Icyene Graveyard with the Vyre noble outfit.\",\"s\":[\"Icyene Graveyard.\"],\"i\":[\"Vyre noble top unscented\",\"Vyre noble legs unscented\",\"Vyre noble shoes unscented\"]},{\"t\":\"Talk to Veliaf outside the church in Slepe.\",\"s\":[\"Slepe.\",\"Let's do this.\"],\"i\":[\"Vyre noble top unscented\",\"Vyre noble legs unscented\",\"Vyre noble shoes unscented\",\"Ivandis flail\"]},{\"t\":\"Kill Damien Leucurte (lvl-204). He can poison you. Stomp out any of the fires he spawns.\",\"s\":[\"Slepe.\",\"Let's do this.\"],\"i\":[\"Vyre noble top unscented\",\"Vyre noble legs unscented\",\"Vyre noble shoes unscented\",\"Ivandis flail\"]},{\"t\":\"Talk to Veliaf in Slepe.\"}],\"i\":[\"Combat gear + food\",\"Vyrewatch outfit or 1950 coins\",\"Ivandis flail\",\"Antipoison\"],\"c\":1,\"e\":[\"Damien Leucurte (level 204)\"]},{\"n\":\"Infiltrating Darkmeyer\",\"st\":[{\"t\":\"Go to Darkmeyer. You can take the boat to Meiyerditch, talk to a Vyrewatch to be sent to the mines, get out and you'll be right next to the entrance. If you're wearing the outfit you won't need to mine anything.\",\"s\":[\"Meiyerditch.\",\"Send me to the mines.\"],\"i\":[\"Vyre noble top\",\"Vyre noble legs\",\"Vyre noble shoes\"]},{\"t\":\"Speak to Desmodus Lasiurus outside the Arboretum in Darkmeyer.\",\"i\":[\"Vyre noble top\",\"Vyre noble legs\",\"Vyre noble shoes\"]},{\"t\":\"Speak to Mordan Mikazsi in lower Darkmeyer.\",\"i\":[\"Vyre noble top\",\"Vyre noble legs\",\"Vyre noble shoes\"]},{\"t\":\"Speak to Maria Gadderanks in the jail north of the Arboretum in Darkmeyer.\",\"i\":[\"Vyre noble top\",\"Vyre noble legs\",\"Vyre noble shoes\"]},{\"t\":\"Search the shelves in the Arboretum in Darkmeyer. Read the Old Note you get.\",\"i\":[\"Vyre noble top\",\"Vyre noble legs\",\"Vyre noble shoes\"]},{\"t\":\"Set the valves in the rooms to the values calculated from the note.\"},{\"t\":\"Gather 8 logs from the Blisterwood tree.\",\"i\":[\"Vyre noble top\",\"Vyre noble legs\",\"Vyre noble shoes\",\"Blisterwood logs (8)\",\"Any axe\"]},{\"t\":\"Return to Vanescula in the Icyene Graveyard with the 8 Blisterwood logs.\",\"s\":[\"Icyene Graveyard.\"],\"i\":[\"Blisterwood logs (8)\"]}],\"i\":[\"Any axe\"]},{\"n\":\"Creating a weapon\",\"st\":[{\"t\":\"Go speak to Vertida in Old Man Ral's basement with the 8 Blisterwood logs.\",\"s\":[\"Meiyerditch.\",\"Here you go.\"],\"i\":[\"Blisterwood logs (8)\"]},{\"t\":\"Speak to Vertida Sefalatis.\"},{\"t\":\"Search the nearby crate for a silver sickle.\"},{\"t\":\"Use a ruby on the sickle.\",\"s\":[\"Yes.\"],\"i\":[\"Ruby\",\"Silver sickle (b)\",\"Chisel\"]},{\"t\":\"Cast enchant ruby on the sickle.\",\"i\":[\"Runes or tablet for Enchant Ruby\",\"Ruby sickle\"]},{\"t\":\"Use a blisterwood log on the enchanted sickle.\",\"s\":[\"Yes.\"],\"i\":[\"Blisterwood log\",\"Enchanted ruby sickle (b)\",\"Knife\"]},{\"t\":\"Use the flail on the blisterwood sickle.\",\"s\":[\"Yes.\"],\"i\":[\"Ivandis flail\",\"Blisterwood sickle\"]}],\"i\":[\"Blisterwood logs (8)\",\"Chisel\",\"Knife\",\"Ruby\",\"Ivandis flail\",\"Runes or tablet for Enchant Ruby\"]},{\"n\":\"Taking on Drakan\",\"st\":[{\"t\":\"Return to Vanescula in the Icyene Graveyard with the Blisterwood Flail.\",\"s\":[\"Icyene Graveyard.\"],\"i\":[\"Blisterwood flail\"]},{\"t\":\"Speak to Safalaan north of the Icyene Graveyard.\",\"s\":[\"Icyene Graveyard.\"],\"i\":[\"Blisterwood flail\"]},{\"t\":\"Speak to Vanescula in the Icyene Graveyard.\",\"s\":[\"Icyene Graveyard.\"],\"i\":[\"Blisterwood flail\"]},{\"t\":\"Fight Vanstrom Klause. Protect from Magic. He has various special attacks indicated by what he says:\",\"i\":[\"Blisterwood flail\"]},{\"t\":\"Speak to Veliaf in the Myreque Hideout to complete the quest.\"}],\"i\":[\"Combat gear + food\",\"Anything to range the bloodveld during bossfight\",\"Blisterwood flail\"],\"c\":1,\"e\":[\"Vanstrom Klause (level 413)\"]}]}"
        "Skippy and the Mogres" -> "{\"n\":\"Skippy and the Mogres\",\"items\":[\"Bucket of water\",\"Nettle tea\",\"Bucket of milk\",\"Chocolate dust\",\"Snape grass\"],\"rec\":[],\"enemies\":[],\"rewards\":[\"Ability to kill Mogres\",\"Ability to receive Mogres as a Slayer task\"],\"sec\":[{\"n\":\"Help Skippy\",\"st\":[{\"t\":\"Right-click 'sober-up' on Skippy south west of Port Sarim.\",\"s\":[\"Throw the water!\"],\"i\":[\"Bucket of water\"]},{\"t\":\"Talk to Skippy.\",\"i\":[\"Nettle tea\"]},{\"t\":\"Use some chocolate dust on a bucket of milk.\",\"i\":[\"Chocolate dust\",\"Bucket of milk\"]},{\"t\":\"Use some snape grass on the chocolatey milk.\",\"i\":[\"Snape grass\",\"Chocolatey milk\"]},{\"t\":\"Use the hangover cure on Skippy.\",\"i\":[\"Hangover cure\"]}],\"i\":[\"Bucket of water\",\"Nettle tea\",\"Bucket of milk\",\"Chocolate dust\",\"Snape grass\"],\"c\":0}]}"
        "Sleeping Giants" -> "{\"n\":\"Sleeping Giants\",\"items\":[\"Oak Logs\",\"Wool\",\"Nails\",\"Hammer\",\"Chisel\"],\"rec\":[\"Ice Gloves\",\"Al Kharid Teleport\"],\"enemies\":[],\"rewards\":[\"1 Quest point\",\"6,000 Smithing XP\",\"Access to the Giants' Foundry\"],\"sec\":[{\"n\":\"Starting out\",\"st\":[{\"t\":\"Go to the Desert Plateau east of Al Kharid to start the quest. Minigame teleport to Giant's Foundry.\",\"i\":[\"Oak Logs\",\"Wool\",\"Nails\",\"Chisel\",\"Ice Gloves\"]},{\"t\":\"Attempt to Strike the Hill Giant at the entrance of the cave to start the quest.\",\"s\":[\"Yes.\"]},{\"t\":\"Speak to Kovac.\"},{\"t\":\"Enter the Giants' Foundry.\"},{\"t\":\"Fix the Broken polishing wheel.\",\"s\":[\"Yes.\"],\"i\":[\"Oak Logs\",\"Nails\",\"Hammer\"]},{\"t\":\"Fix the Broken grindstone.\",\"s\":[\"Yes.\"],\"i\":[\"Chisel\"]},{\"t\":\"Fix the Broken trip hammer.\",\"s\":[\"Yes.\"],\"i\":[\"Oak Logs\",\"Nails\",\"Hammer\"]},{\"t\":\"Speak to Kovac to continue.\"}],\"i\":[\"Oak Logs\",\"Wool\",\"Nails\",\"Hammer\",\"Chisel\"],\"c\":0},{\"n\":\"Creating the sword\",\"st\":[{\"t\":\"Speak to Kovac for a commission.\"},{\"t\":\"Take some bars & weapons from the Crate.\",\"s\":[\"Yes.\"]},{\"t\":\"Fill the Crucible with items & bars until it is full.\"},{\"t\":\"Speak to Kovac about the mould.\"},{\"t\":\"Set the Mould.\"},{\"t\":\"Select the mould for the forte, blade and tip.\"},{\"t\":\"Speak to Kovac about pouring the metal.\"},{\"t\":\"Pour the full Crucible into the mould.\"},{\"t\":\"Pick up the sword from the mould with a bucket of water or ice gloves equipped.\",\"i\":[\"Ice Gloves\",\"Bucket of Water\"]},{\"t\":\"Use the trip hammer while the heat bar is in the red, and re-heat it in the lava whenever it's close to yellow.\"},{\"t\":\"Grindstone the preform whilst in the yellow heat section.\"},{\"t\":\"Use the polishing wheel whilst in the green heat range, heating it in the lava when needed.\"},{\"t\":\"Give the finished sword to Kovac to complete the quest.\"}],\"i\":[\"Ice Gloves\",\"Bucket\"],\"c\":0}]}"
        "Song of the Elves" -> "{\"n\":\"Song of the Elves\",\"items\":[\"Steel full helm\",\"Steel platebody\",\"Steel platelegs\",\"Red dye\",\"Purple dye\",\"Silk\",\"Full mourners' outfit\",\"Runite bar\",\"Limestone brick (8)\",\"Tinderbox\",\"Rope\",\"Nature rune\",\"Irit leaf or a flower\",\"Adamant chainbody\",\"Wine of Zamorak or Zamorak brew\",\"Cabbage\",\"Black knife or black dagger\",\"Cadantine seed\",\"Seed dibber\",\"Vial of water\",\"Pestle and mortar\",\"Hammer\",\"Saw\",\"Any pickaxe\",\"Any axe\",\"Spade\"],\"rec\":[\"Teleport crystal\",\"Iorwerth camp teleport\",\"Games necklace\",\"Combat gear, food and potions\",\"Magic combat gear, food and potions\",\"Saradomin brews\",\"Super restores\",\"or more Stamina potions (6)\"],\"enemies\":[\"Many Mourners, Paladins and Knights of Ardougne\",\"Arianwyn (level 182)\",\"Essyllt (level 236)\",\"Fragment of Seren (level 494)\"],\"rewards\":[\"4 Quest points\",\"40,000 Agility XP\",\"40,000 Construction XP\",\"40,000 Farming XP\",\"40,000 Herblore XP\",\"40,000 Hunter XP\",\"40,000 Mining XP\",\"40,000 Smithing XP\",\"40,000 Woodcutting XP\",\"Access to Prifddinas\",\"Ability to fight Zalcano\",\"Access to The Gauntlet\",\"Access to Trahaearn Mine\",\"Access to Iorwerth Dungeon\",\"Ability to respawn at Prifddinas\",\"Ability to move POH to Prifddinas\",\"Prifddinas Teleport added to Crystal Teleport Seed\",\"Ability to make Divine Potions\",\"Ability to make Crystal Tools, Weapons and Armor\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Talk to Edmond in East Ardougne.\",\"s\":[\"Yes.\"]},{\"t\":\"Talk to King Lathas in East Ardougne castle.\"},{\"t\":\"Return to Edmond in East Ardougne.\",\"s\":[\"How do I get this disguise?\"]},{\"t\":\"Talk to Alrena in East Ardougne.\",\"s\":[\"Yes.\"],\"i\":[\"Purple dye\",\"Silk\"]},{\"t\":\"Use red dye on a steel full helm.\",\"i\":[\"Red dye\",\"Steel full helm\"]},{\"t\":\"Add the tabard to a steel platebody.\",\"i\":[\"Ardougne knight tabard\",\"Steel platebody\"]},{\"t\":\"Enter the basement of East Ardougne castle.\",\"i\":[\"Ardougne knight helm\",\"Ardougne knight platebody\",\"Steel platelegs\"]},{\"t\":\"Talk to Elena in the cell.\"},{\"t\":\"Leave the prison.\"},{\"t\":\"Search the cabinet in Elena's house.\",\"s\":[\"The thick clear liquid.\"]},{\"t\":\"Return to Elena with the clear liquid.\",\"s\":[\"Yes.\"],\"i\":[\"Clear liquid\"]}],\"i\":[\"Steel full helm\",\"Steel platebody\",\"Steel platelegs\",\"Red dye\",\"Purple dye\",\"Silk\",\"Full mourners' outfit\",\"Tinderbox\"]},{\"n\":\"Inciting the citizens\",\"st\":[{\"t\":\"Search the bed in the house west of the Mourner base.\",\"s\":[\"Climb through it.\"]},{\"t\":\"Talk to Elena in the hideout.\",\"s\":[\"It's not good, but it might be our only option.\",\"It's all in a day's work.\",\"I am.\"]},{\"t\":\"Leave the hideout.\"},{\"t\":\"Use a tinderbox on the grain in the West Ardougne council building.\",\"i\":[\"Tinderbox\",\"Gas mask\",\"Mourner top\",\"Mourner trousers\",\"Mourner boots\",\"Mourner gloves\",\"Mourner cloak\"]},{\"t\":\"Talk to the priest in West Ardougne.\",\"i\":[\"Gas mask\",\"Mourner top\",\"Mourner trousers\",\"Mourner boots\",\"Mourner gloves\",\"Mourner cloak\"]},{\"t\":\"Use a tinderbox on the grain in the West Ardougne church.\",\"i\":[\"Tinderbox\",\"Gas mask\",\"Mourner top\",\"Mourner trousers\",\"Mourner boots\",\"Mourner gloves\",\"Mourner cloak\"]},{\"t\":\"Talk to Nurse Sarah in West Ardougne.\",\"i\":[\"Gas mask\",\"Mourner top\",\"Mourner trousers\",\"Mourner boots\",\"Mourner gloves\",\"Mourner cloak\"]},{\"t\":\"Use a tinderbox on the grain outside the West Ardougne general store.\",\"i\":[\"Tinderbox\",\"Gas mask\",\"Mourner top\",\"Mourner trousers\",\"Mourner boots\",\"Mourner gloves\",\"Mourner cloak\"]},{\"t\":\"Talk to Chadwell in the West Ardougne general store.\",\"s\":[\"I'm here to tell you about some new taxes.\"],\"i\":[\"Gas mask\",\"Mourner top\",\"Mourner trousers\",\"Mourner boots\",\"Mourner glov