        "The Corsair Curse" -> "{\"n\":\"The Corsair Curse\",\"items\":[\"Combat gear + food to defeat Ithoi (level 34), who uses magic\"],\"rec\":[],\"enemies\":[\"Ithoi the Navigator (level 34)\"],\"rewards\":[\"2 Quest points\",\"Access to Yusuf's Bank in the Corsair Cove.\"],\"sec\":[{\"n\":\"Travel to the cove\",\"st\":[{\"t\":\"Talk to Captain Tock north of Port Sarim.\",\"s\":[\"What kind of help do you need?\",\"Sure, I'll try to help with your curse.\"]},{\"t\":\"Talk to Captain Tock west of Rimmington.\",\"s\":[\"Okay, I'm ready go to Corsair Cove.\"]}],\"i\":[\"Combat gear + food to defeat Ithoi (level 34), who uses magic\"],\"c\":1},{\"n\":\"Solve the curse\",\"st\":[{\"t\":\"Talk to Ithoi in the south western hut.\",\"s\":[\"I hear you've been cursed.\"]},{\"t\":\"Talk to Gnocci in the north west hut.\",\"s\":[\"I hear you've been cursed.\"]},{\"t\":\"Talk to Arsen in the central hut.\",\"s\":[\"I hear you've been cursed.\"]},{\"t\":\"Talk to Colin in the central hut.\",\"s\":[\"I hear you've been cursed.\"]},{\"t\":\"Pick up the tinderbox next to Gnocci.\",\"i\":[\"Tinderbox\"]},{\"t\":\"Take the spade in the south of the Corsair Cove.\"},{\"t\":\"Talk to Captain Tock on the ship.\",\"s\":[\"Arsen says he gave you a sacred ogre relic.\",\"About that sacred ogre relic...\"]},{\"t\":\"Talk to Chief Tess.\",\"s\":[\"I've come to return what Arsen stole.\"]},{\"t\":\"Dig next to the tree south west of the Cove.\",\"s\":[\"Search for the possessed doll and face the consequences.\"]},{\"t\":\"Go look through Ithoi's telescope.\"}]},{\"n\":\"Discover betrayal\",\"st\":[{\"t\":\"Talk to Captain Tock on the ship.\",\"s\":[\"I've ruled out all the Corsairs' theories...\",\"So what do I do now?\"]},{\"t\":\"Talk to Gnocci in the north west hut.\",\"s\":[\"I hear it happened straight after dinner.\"]},{\"t\":\"Talk to Arsen in the central hut.\",\"s\":[\"I hear Ithoi cooked the meal you ate that night.\"]},{\"t\":\"Talk to Ithoi.\",\"s\":[\"I bet I can prove you're well enough to get up.\",\"I know you've faked the curse.\",\"I hear you cooked the meal they ate before getting sick.\",\"Maybe because the Captain's thinking of firing you.\"]},{\"t\":\"Use your tinderbox on the driftwood under Ithoi's hut.\",\"i\":[\"Tinderbox\"]}]},{\"n\":\"Deal with Ithoi\",\"st\":[{\"t\":\"Kill Ithoi (level 35).\"},{\"t\":\"Talk to Captain Tock on the ship to finish the quest.\",\"s\":[\"I've killed Ithoi for poisoning your crew.\"]}]}]}"
        "The Curse of Arrav" -> "{\"n\":\"The Curse of Arrav\",\"items\":[\"Dwellberries (3)\",\"Ring of life\",\"Any pickaxe\",\"Any crossbow\",\"Mith grapple\",\"Insulated boots\"],\"rec\":[\"Stamina potion\",\"Prayer potion\",\"Anti-venom\",\"Crush or ranged combat gear to fight the Golem guard\",\"Ranged or melee combat gear for killing Arrav\",\"Food\",\"Fairy Ring [DLQ]\",\"Trollheim Teleport\",\"Lumberyard teleport\"],\"enemies\":[\"Golem guard (lvl 141)\",\"Arrav (lvl 339)\"],\"rewards\":[\"2 Quest points\",\"40,000 Mining XP\",\"40,000 Thieving XP\",\"40,000 Agility XP\",\"Access to Zemouregal's Fort\"],\"sec\":[{\"n\":\"Tomb Raiding\",\"st\":[{\"t\":\"Talk to Elias south of Ruins of Uzer to start the quest.\",\"s\":[\"Yes.\"]},{\"t\":\"Enter the tomb south-west of Elias.\",\"i\":[\"Dwellberries (3)\",\"Ring of life\",\"Crush or ranged combat gear to fight the Golem guard\"]},{\"t\":\"Get the first Mastaba key from the skeleton in the cave south of the entrance.\"},{\"t\":\"Get the second Mastaba key from the skeleton east of the entrance.\"},{\"t\":\"Pull the lever to the south-east.\",\"s\":[\"Yes.\"],\"i\":[\"Mastaba Key\"]},{\"t\":\"Pull the lever to the north-east.\",\"s\":[\"Yes.\"],\"i\":[\"Mastaba Key\"]},{\"t\":\"Open the imposing doors, ready to fight the Golem guard.\"},{\"t\":\"Fight the Golem guard. It is weak to crush style weapons. Use Protect from Melee to avoid damage from his attacks. When the screen shakes, step away from him to avoid taking damage.\"},{\"t\":\"Climb the stairs down the tomb basement.\"},{\"t\":\"Search the shelves to the west for an oil-filled canopic jar.\"},{\"t\":\"Inspect the murals in the room to the south.\",\"i\":[\"Oil-filled canopic jar\"]},{\"t\":\"Put the Dwellberries in the Canopic jar.\",\"i\":[\"Oil-filled canopic jar\",\"Dwellberries (3)\",\"Ring of life\"]},{\"t\":\"Put the Ring of life in the Canopic jar.\",\"i\":[\"Canopic jar (oil and berries)\",\"Ring of life\"]},{\"t\":\"Return to Elias south of Ruins of Uzer, either by walking out of the tomb or using the fairy ring.\",\"i\":[\"Canopic jar (full)\"]}],\"i\":[\"Dwellberries (3)\",\"Ring of life\",\"Crush or ranged combat gear to fight the Golem guard\"],\"tr\":[\"Fairy Ring [DLQ]\"],\"r\":[\"Stamina potion\",\"Prayer potion\",\"Food\"],\"c\":1,\"e\":[\"Golem guard (lvl 141)\"]},{\"n\":\"Fort Invasion\",\"st\":[{\"t\":\"Enter the cave next to Trollheim. You can use a Trollheim teleport tablet or the GWD Ghommal's Hilt teleport to get close.\",\"i\":[\"Any pickaxe\"]},{\"t\":\"Continue through the Trollheim cave, exiting at the Crevasse to the north-west. Use Protect from Melee to avoid taking damage from the Ice Trolls.\",\"i\":[\"Any pickaxe\"]},{\"t\":\"Enter the Trollweiss cave to the east.\",\"i\":[\"Any pickaxe\"]},{\"t\":\"Climb up the stairs in the room with the red tile floor and talk to Arrav.\"},{\"t\":\"Talk to Arrav.\"},{\"t\":\"Enter the room to your east and search the tapestry for something to help you with your heist.\"},{\"t\":\"Search the tapestry in the south of the room.\"},{\"t\":\"Return to Elias south of Ruins of Uzer and ask him for help interpreting the plans.\",\"i\":[\"Base plans\",\"Base key\"]}],\"i\":[\"Any pickaxe\"],\"tr\":[\"Fairy Ring [DLQ]\",\"Trollheim Teleport\"],\"r\":[\"Stamina potion\"],\"c\":1,\"e\":[\"Arrav (lvl 339)\"]},{\"n\":\"Hearty Heist\",\"st\":[{\"t\":\"Head to Zemouregal's base east of Varrock's sawmill and talk to Elias.\",\"s\":[\"Ready when you are.\"],\"i\":[\"Any crossbow\",\"Mith grapple\",\"Ranged or melee combat gear for killing Arrav\",\"Insulated boots\",\"Canopic jar (full)\",\"Base key\"]},{\"t\":\"Enter Zemouregal's base east of Varrock's sawmill.\",\"i\":[\"Any crossbow\",\"Mith grapple\",\"Ranged or melee combat gear for killing Arrav\",\"Insulated boots\",\"Canopic jar (full)\",\"Base key\"]},{\"t\":\"Make your way to the back of Zemouregal's base. Protect from Melee against the zombies to avoid most damage.\"},{\"t\":\"Enter the storage room to the south-east.\"},{\"t\":\"Search the table for some decoder strips.\"},{\"t\":\"Open the chest for the code key.\"},{\"t\":\"Step through through the metal doors.\",\"i\":[\"Canopic jar (full)\",\"Any crossbow\",\"Mith grapple\"]},{\"t\":\"Grapple across the pipe\",\"i\":[\"Canopic jar (full)\",\"Any crossbow\",\"Mith grapple\"]},{\"t\":\"Attempt to take Arrav's heart from the pedestal, ready for a fight with Arrav. Kill zombies as they appear (ranged weapons are handy here). Avoid the venom pools they spawn. Use Protect from Melee to avoid some of the incoming damage. When Arrav throws an axe towards you, step to the side or behind him.\",\"i\":[\"Canopic jar (full)\",\"Ranged or melee combat gear for killing Arrav\"]},{\"t\":\"Fight Arrav. Kill zombies as they appear (ranged weapons are handy here). Avoid the venom pools they spawn. Use Protect from Melee to avoid some of the incoming damage. When Arrav throws an axe towards you, step to the side or behind him.\",\"i\":[\"Canopic jar (full)\"]},{\"t\":\"Talk to Elias to finish the quest.\"}],\"i\":[\"Base plans\",\"Base key\",\"Any crossbow\",\"Mith grapple\",\"Ranged or melee combat gear for killing Arrav\",\"Insulated boots\",\"Canopic jar (full)\"],\"tr\":[\"Lumberyard teleport\"],\"r\":[\"Stamina potion\",\"Prayer potion\",\"Anti-venom\",\"Food\"],\"c\":1,\"e\":[\"Arrav (lvl 339)\"]}]}"
        "The Depths of Despair" -> "{\"n\":\"The Depths of Despair\",\"items\":[],\"rec\":[\"Skills necklace\",\"Xeric's Talisman\",\"Food (if low level)\",\"Super Energy or Stamina potions\",\"Access to Fairy Rings\"],\"enemies\":[\"Sand Snake (level 36)\"],\"rewards\":[\"1 Quest point\",\"1,500 Agility XP\",\"4000 x Coins\",\"A Kharedst's Memoirs page\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Talk to Lord Kandur Hosidius in the house west of the vinery.\",\"s\":[\"Anything I can help you with?\",\"Yes.\"]},{\"t\":\"Speak to Chef Olivia in Lord Kandur's kitchen.\"}]},{\"n\":\"The Envoy to Varlamore\",\"st\":[{\"t\":\"Speak to Galana in the Arceuus Library.\"},{\"t\":\"Find the Varlamore Envoy. Ask Galana for the approximate location if you can't find it.\",\"i\":[\"Varlamore Envoy\"]},{\"t\":\"Read the Varlamore Envoy.\",\"i\":[\"Varlamore Envoy\"]}]},{\"n\":\"The Crabclaw Caves\",\"st\":[{\"t\":\"Enter the Crabclaw Caves.\"},{\"t\":\"Enter the crevice. Kill a sandcrab for the easy diary while you're here.\"},{\"t\":\"Cross the stepping stones.\"},{\"t\":\"Climb the rocks.\"},{\"t\":\"Climb down the tunnel at the end.\"},{\"t\":\"Speak to Artur Hosidius.\"},{\"t\":\"Kill the Sand Snake.\"},{\"t\":\"Search the chest.\"}],\"i\":[\"Food (if low level)\",\"A Weapon\"],\"c\":1,\"e\":[\"Sand Snake (level 36)\"]},{\"n\":\"Finishing up\",\"st\":[{\"t\":\"Return to Lord Kandur Hosidius and talk to him.\"}]}]}"
        "The Dig Site" -> "{\"n\":\"The Dig Site\",\"items\":[\"Pestle and mortar\",\"Vial\",\"Tinderbox\",\"Cup of tea\",\"Rope (2)\",\"Opal\",\"Charcoal\"],\"rec\":[\"Digsite teleports (2)\",\"Varrock teleports (2)\"],\"enemies\":[],\"rewards\":[\"2 Quest points\",\"15,300 Mining XP\",\"2,000 Herblore XP\",\"2 x Gold Bars\",\"Ability to clean specimens in the Varrock Museum\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Talk to an Examiner in the Exam Centre south east of Varrock.\",\"s\":[\"Can I take an exam?\",\"Yes.\"]},{\"t\":\"Talk to Curator Haig in the Varrock Museum.\",\"i\":[\"Unstamped letter\"]},{\"t\":\"Return to an Examiner in the Exam Centre south east of Varrock.\",\"i\":[\"Sealed letter\"]},{\"t\":\"Search the bushes north of the Exam Centre for a teddy.\"},{\"t\":\"Pick up the tray in the south east of the dig site.\",\"i\":[\"Panning tray\"]},{\"t\":\"Talk to the Panning Guide nearby.\",\"i\":[\"Cup of tea\"]},{\"t\":\"Pan in the river for a special cup.\",\"i\":[\"Panning tray\"]},{\"t\":\"Pickpocket workmen until you get an animal skull and a specimen brush.\"},{\"t\":\"Talk to the female student in the north west of the Digsite twice.\",\"i\":[\"Teddy\"]},{\"t\":\"Talk to the female student in the north west of the Digsite.\"},{\"t\":\"Talk to the student in an orange shirt in the north east of the Digsite twice.\",\"i\":[\"Special cup\"]},{\"t\":\"Talk to the student in an orange shirt in the north east of the Digsite.\"},{\"t\":\"Talk to the student in a green shirt in the south of the Digsite twice.\",\"i\":[\"Animal skull\"]},{\"t\":\"Talk to the student in a green shirt in the south of the Digsite.\"},{\"t\":\"Talk to an Examiner in the Exam Centre to take the first test.\",\"s\":[\"Yes, I certainly am.\",\"The study of the earth, its contents and history.\",\"All that have passed the appropriate Earth Sciences exam.\",\"Gloves and boots to be worn at all times; proper tools must be used.\"]}],\"i\":[\"Cup of tea\"],\"c\":0},{\"n\":\"Exam 2\",\"st\":[{\"t\":\"Talk to the female student in the north west of the Digsite.\"},{\"t\":\"Talk to the student in an orange shirt in the north east of the Digsite.\"},{\"t\":\"Talk to the student in a green shirt in the south of the Digsite.\"},{\"t\":\"Talk to an Examiner in the Exam Centre to take the second test.\",\"s\":[\"I am ready for the next exam.\",\"Samples taken in rough form; kept only in sealed containers.\",\"Finds must be carefully handled, and gloves worn.\",\"Always handle with care; strike cleanly on its cleaving point.\"]}],\"c\":0},{\"n\":\"Exam 3\",\"st\":[{\"t\":\"Talk to the female student in the north west of the Digsite.\",\"i\":[\"Opal\"]},{\"t\":\"Talk to the female student again.\",\"i\":[\"Opal\"]},{\"t\":\"Talk to the student in an orange shirt in the north east of the Digsite.\"},{\"t\":\"Talk to the student in a green shirt in the south of the Digsite.\"},{\"t\":\"Talk to an Examiner in the Exam Centre to take the third test.\",\"s\":[\"I am ready for the last exam...\",\"Samples cleaned, and carried only in specimen jars.\",\"Brush carefully and slowly using short strokes.\",\"Handle bones very carefully and keep them away from other samples.\"]}],\"i\":[\"Opal\"],\"c\":0},{\"n\":\"Discovery\",\"st\":[{\"t\":\"Search the cupboard on the south wall of the west room of the Exam Centre for a specimen jar.\"},{\"t\":\"Dig in the north east dig spot in the Digsite until you get a talisman.\",\"i\":[\"Trowel\",\"Specimen jar\",\"Specimen brush\"]},{\"t\":\"Talk to the Archaeological expert in the Exam Centre.\",\"i\":[\"Ancient talisman\"]},{\"t\":\"Use the invitation on any workman.\",\"s\":[\"I lost the letter you gave me.\"],\"i\":[\"Invitation letter\"]}],\"i\":[\"Trowel\",\"Specimen brush\"],\"c\":0},{\"n\":\"Digging deeper\",\"st\":[{\"t\":\"Use a rope on the west winch.\",\"i\":[\"Rope\"]},{\"t\":\"Climb down the west winch.\"},{\"t\":\"Pick up some arcenia root.\",\"i\":[\"Arcenia root\"]},{\"t\":\"Search the bricks to the south.\"},{\"t\":\"Climb back to the surface.\"},{\"t\":\"Use a rope on the north east winch.\",\"i\":[\"Rope\"]},{\"t\":\"Climb down the north east winch.\"},{\"t\":\"Talk to Doug Deeping.\",\"s\":[\"How could I move a large pile of rocks?\"]},{\"t\":\"Leave Doug's cave.\"},{\"t\":\"Use the key on the chest in the tent in the south of the Digsite.\",\"i\":[\"Chest key\"]},{\"t\":\"Search the chest.\"},{\"t\":\"Use a trowel on the barrel west of the chest's tent.\",\"i\":[\"Trowel\"]},{\"t\":\"Use a vial on the barrel west of the chest's tent.\",\"i\":[\"Vial\"]},{\"t\":\"(DO NOT LEFT CLICK) Right-click use the liquid on the Archaeological expert in the Exam Centre.\",\"i\":[\"Unidentified liquid\"]},{\"t\":\"Use the powder on the Archaeological expert in the Exam Centre.\",\"i\":[\"Chemical powder\"]},{\"t\":\"Mix the nitroglycerin and ammonium nitrate together.\",\"i\":[\"Nitroglycerin\",\"Ammonium nitrate\"]},{\"t\":\"Grind charcoal with a pestle and mortar.\",\"i\":[\"Pestle and mortar\",\"Charcoal\"]},{\"t\":\"Add the ground charcoal to the vial.\",\"i\":[\"Ground charcoal\",\"Mixed chemicals\"]},{\"t\":\"Add arcenia root to the vial.\",\"i\":[\"Arcenia root\",\"Mixed chemicals\"]},{\"t\":\"Climb down the rope on the west winch.\",\"i\":[\"Chemical compound\",\"Tinderbox\"]},{\"t\":\"Use the compound on the bricks to the south.\",\"i\":[\"Chemical compound\"]},{\"t\":\"Use a tinderbox on the bricks to the south.\",\"i\":[\"Tinderbox\"]},{\"t\":\"Take the stone tablet in the south room.\"},{\"t\":\"Use the tablet on the Archaeological expert in the Exam Centre to complete the quest.\",\"i\":[\"Stone tablet\"]}],\"i\":[\"Rope (2)\",\"Trowel\",\"Pestle and mortar\",\"Vial\",\"Tinderbox\",\"Charcoal\"],\"c\":0}]}"
        "The Eyes of Glouphrie" -> "{\"n\":\"The Eyes of Glouphrie\",\"items\":[\"Bucket of sap\",\"Mud rune\",\"Maple logs\",\"Oak logs\",\"Hammer\",\"Saw\",\"Pestle and mortar\"],\"rec\":[],\"enemies\":[\"Evil creature (x6)\"],\"rewards\":[\"2 Quest points\",\"12,000 Magic XP\",\"2,500 Woodcutting XP\",\"6,000 Runecraft XP\",\"250 Construction XP\",\"A Crystal Saw Seed\"],\"sec\":[{\"n\":\"Learning\",\"st\":[{\"t\":\"Go talk to Brimstail in his cave in west Tree Gnome Stronghold.\"},{\"t\":\"Inspect the singing bowl in the west room.\"},{\"t\":\"Attempt to unlock oaknock's machine in the north of the cave.\"},{\"t\":\"Talk to Brimstail again.\",\"s\":[\"I've had a look in the other room now.\",\"Of course, I'd love to!\"]},{\"t\":\"Go talk to Hazelmere in his hut east of Yanille (Fairy Ring CLS).\"},{\"t\":\"Talk to Brimstail.\",\"s\":[\"I've visited Hazelmere, he told me all sorts of interesting things.\"]},{\"t\":\"Use the pestle and mortar on some mud runes.\",\"i\":[\"Pestle and mortar\",\"Mud rune\"]},{\"t\":\"Use the ground mud runes on the bucket of sap.\",\"i\":[\"Ground mud runes\",\"Bucket of sap\"]},{\"t\":\"Use the magic glue on oaknock's machine in the north of the cave.\",\"i\":[\"Magic glue\",\"Oak logs\",\"Maple logs\",\"Saw\",\"Hammer\"]},{\"t\":\"Talk to Brimstail for more disks.\",\"s\":[\"I can't work out what to do with these discs!\"]},{\"t\":\"Unlock the machine.\"}],\"i\":[\"Bucket of sap\",\"Mud rune\",\"Maple logs\",\"Oak logs\",\"Hammer\",\"Saw\",\"Pestle and mortar\"]},{\"n\":\"Kill the spies\",\"st\":[{\"t\":\"Talk to Brimstail again.\",\"s\":[\"Phew! I've got that machine working now. What do I need to do now?\"]},{\"t\":\"Kill the evil creature next to Brimstail.\"},{\"t\":\"Kill the evil creature next to the Stronghold's entrance.\"},{\"t\":\"Kill the evil creature next to the Stronghold's Spirit Tree.\"},{\"t\":\"Kill the evil creature in the north west of the Stronghold.\"},{\"t\":\"Kill the evil creature at the top of the Grand Tree.\"},{\"t\":\"Kill the evil creature next to Narnode.\"},{\"t\":\"Talk to King Narnode to finish the quest.\"}],\"c\":1,\"e\":[\"Evil creature (x6)\"]}]}"
        "The Feud" -> "{\"n\":\"The Feud\",\"items\":[\"Coins (800)\",\"Leather or Graceful Gloves\",\"Combat Gear bring Range or Mage Gear if safe spotting.\"],\"rec\":[\"Ring of dueling\",\"Pollnivneach teleport\"],\"enemies\":[\"Bandit Champion (level 70) - Safespottable\",\"Tough Guy (level 75) - Safespottable\"],\"rewards\":[\"1 Quest point\",\"15,000 Thieving XP\",\"500 x Coins\",\"Oak Blackjack\",\"Desert Disguise\",\"Willow Blackjack\",\"An Adamant Scimitar\",\"Ability to blackjack.\",\"Access to the Rogue Trader minigame\"],\"sec\":[{\"n\":\"Starting out\",\"st\":[{\"t\":\"Talk to Ali Morrisane in Al Kharid to start the quest.\",\"s\":[\"Are you really the greatest salesman in the world?\",\"I'd like to help you, but...\",\"Yes.\"]}],\"i\":[\"Coins\"]},{\"n\":\"Pollnivneach\",\"st\":[{\"t\":\"Buy a Kharidian Headpiece and a Fake Beard to create a disguise.\",\"s\":[\"Okay.\"],\"i\":[\"Coins\"]},{\"t\":\"Create a disguise by using the Kharidian Headpiece on the Fake Beard.\",\"i\":[\"Kharidian Headpiece\",\"Fake Beard\"]},{\"t\":\"Go through Shantay Pass.\",\"i\":[\"Shantay Pass\"]},{\"t\":\"Talk to the rug merchant and travel to Pollnivneach via magic carpet.\",\"s\":[\"Pollnivneach\"],\"i\":[\"Coins\"]},{\"t\":\"Buy 3 beers from the bartender and use them on Drunken Ali to get him to explain where his son is. Talk with him between beers\",\"i\":[\"Beer (3)\"]}],\"i\":[\"Coins\"]},{\"n\":\"Find the beef between the two factions\",\"st\":[{\"t\":\"Talk to a Menaphite Thug to figure out how their dispute started with the bandits.\"},{\"t\":\"Talk to a bandit to figure out their issues with the Menaphites.\"},{\"t\":\"Talk to Ali the Camel Man to try and get two camels to solve the dispute\",\"s\":[\"Are those camels around the side for sale?\",\"What price do you want for both of them?\",\"Would 500 gold coins for the pair of them do?\"]},{\"t\":\"Tell the bandits that the Menaphites have agreed to return the camel.\"},{\"t\":\"Tell the Menaphites that the bandits have agreed to return the camel.\"}],\"i\":[\"Coins\"]},{\"n\":\"First job\",\"st\":[{\"t\":\"Talk to Ali the Operator to get a job from him.\",\"s\":[\"Yes, of course, those bandits should be taught a lesson.\"]},{\"t\":\"Pickpocket a villager.\"},{\"t\":\"Lure a villager then talk to a street urchin and get them to distract a villager, once he has them distracted pickpocket them from behind.\"},{\"t\":\"Lure a villager to secluded place or an empty building, knock them out and then pickpocket them.\"}],\"i\":[\"Coins\"]},{\"n\":\"Second job\",\"st\":[{\"t\":\"Talk to Ali the Operator to get the second job.\"},{\"t\":\"Hide behind the cactus\",\"i\":[\"Leather or Graceful Gloves\",\"Desert Disguise\"]},{\"t\":\"Open the door.\",\"i\":[\"Keys\"]},{\"t\":\"Go up the stairs.\"},{\"t\":\"Search the painting to reveal the safe. Enter the code 1, 1, 2, 3, 5, 8.\"},{\"t\":\"Give Ali the Operator the jewels to get your final task from him.\"}],\"i\":[\"Desert Disguise\",\"Leather or Graceful Gloves\"]},{\"n\":\"Rising up\",\"st\":[{\"t\":\"Talk to a Menaphite member to find the traitor.\"},{\"t\":\"Talk to Ali and tell him you have found the traitor.\"},{\"t\":\"Talk to Ali the Barman to find out where Traitorous Ali is.\",\"s\":[\"No thanks I'm ok.\"]},{\"t\":\"Talk to Ali the Hag to ask her to make some poison for you.\"},{\"t\":\"Use coins on the snake charmer's money pot to get a snake charm and a snake basket.\",\"i\":[\"Coins\"]},{\"t\":\"Use the Snake Charm on a snake to capture it.\",\"i\":[\"Snake Charm\",\"Snake Basket\"]},{\"t\":\"Give the snake to Ali the Hag.\",\"i\":[\"Snake Basket (Full)\"]},{\"t\":\"Talk to Ali the Kebab Salesman to get a special sauce to use.\",\"s\":[\"Would you sell me that bottle of special kebab sauce?\",\"No thanks, I'm good.\"]},{\"t\":\"Use the Red Hot Sauce on the Trough and wait for a Camel to poop out the dung. Only pickup brown/Ugthanki dung, if you plan to do \\\"My Arm's Big Adventure\\\" or \\\"Forgettable Tale of a Drunken Dwarf\\\" then you may want to grab four more Ugthanki dung.\",\"i\":[\"Red Hot Sauce\"]},{\"t\":\"Talk to Ali the Hag and give her the dung.\",\"i\":[\"Dung\"]},{\"t\":\"Use the poison on the beer glass to kill Traitorous Ali.\",\"i\":[\"Hag's Poison\"]},{\"t\":\"Talk to Ali the Operator and tell him he is dead.\"}],\"i\":[\"Coins\"]},{\"n\":\"Finishing off\",\"st\":[{\"t\":\"Talk to the Menaphite Leader and prepare for a fight against a tough guy. You can safespot him inside the tent by using a chair.\"},{\"t\":\"Talk to a villager and they will be angry you broke the balance of power.\"},{\"t\":\"Talk to the Bandit Leader and be prepared to fight a Bandit Champion. You can safe spot him with the stool.\"},{\"t\":\"Talk to a villager and they will be angry still.\"},{\"t\":\"Talk to Ali the Mayor and get your due congratulations.\"},{\"t\":\"Talk to Ali Morrisane in Al Kharid to finish the quest.\"}],\"i\":[\"Combat Gear bring Range or Mage Gear if safe spotting.\"],\"c\":1,\"e\":[\"Bandit Champion (level 70) - Safespottable\",\"Tough Guy (level 75) - Safespottable\"]}]}"
        "The Final Dawn" -> "{\"n\":\"The Final Dawn\",\"items\":[\"Any type of bone or raw meat\",\"Melee Combat gear\"],\"rec\":[\"Ranged/Magic Combat gear\",\"Food\",\"Prayer potions (3)\",\"Pendant of ates\",\"Quetzal whistle\",\"Civitas illa fortis teleport\"],\"enemies\":[\"Emissary Enforcer (lvl-196)\",\"Chimalli (lvl-160) and Lucius (lvl-160)\",\"Multiple waves of Twilight Emissaries (lvl-70 to lvl-90)\",\"Ennius Tullus (lvl-306)\",\"Augur Metzli (lvl-396)\"],\"rewards\":[\"3 Quest points\",\"55,000 Thieving XP\",\"25,000 Fletching XP\",\"25,000 Runecraft XP\",\"55,000 Experience Lamps (Combat Skills)\",\"Arkan blade\",\"The Arkan Blade\",\"Access to Mokhaiotl\",\"Access to Crypt of Tonali\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Talk to Servius in the Sunrise Palace in Civitas illa Fortis to start the quest.\",\"s\":[\"Yes.\"]},{\"t\":\"Search the chest in the south of the Tower of Ascension south of Salvager Overlook for some emissary robes.\"},{\"t\":\"Enter the temple south-east of Salvager Overlook.\",\"i\":[\"Emissary robes\"]},{\"t\":\"Go down the stairs in the temple. The passphrase is 'Final' and 'Dawn'.\",\"s\":[\"Final.\",\"Dawn.\"],\"i\":[\"Emissary robes\",\"Combat weapon\",\"Food\"]},{\"t\":\"Enter the far eastern room. Avoid the patrolling guard.\"},{\"t\":\"Search the bed in the south room.\"},{\"t\":\"Open the drawers in the north room.\"},{\"t\":\"Open the drawers in the same room.\"},{\"t\":\"Use canvas piece on the painting in the east of the middle room of the eastern rooms.\",\"i\":[\"Canvas piece\"]},{\"t\":\"Enter the passage behind the painting.\",\"s\":[\"Enter the passage.\"]},{\"t\":\"Picklock the chest in the hidden room. Be ready for a fight afterwards.\"},{\"t\":\"Defeat the enforcer. You cannot use prayers, or teleport out. Step away each time he goes to attack, and step behind him or sideways if he says 'Traitor!' or 'Thief!'.\"},{\"t\":\"Pick up the emissary scroll.\",\"i\":[\"Emissary scroll\"]},{\"t\":\"Read the emissary scroll.\",\"i\":[\"Emissary scroll\"]}],\"i\":[\"Combat weapon\",\"Food\"],\"tr\":[\"Civitas illa fortis teleport\"],\"c\":1},{\"n\":\"The hideout\",\"st\":[{\"t\":\"Talk to the queen on the top floor of the Sunrise Palace.\"},{\"t\":\"Talk to Captain Vibia south of Civitas illa Fortis' west bank.\"},{\"t\":\"Inspect the window on the east side of the house north of Captain Vibia, and then enter it.\",\"s\":[\"Force open the window.\"],\"i\":[\"Any type of bone or raw meat\"]},{\"t\":\"Pet the dog to see the code for the door. Open the door using the code 'GUS'.\"},{\"t\":\"Pick up the sack of potatoes (3).\",\"i\":[\"Potatoes (?)\"]},{\"t\":\"Empty the sack of potatoes.\",\"i\":[\"Potatoes (?)\"]},{\"t\":\"Go upstairs.\"},{\"t\":\"Pick up the coin purse.\",\"i\":[\"Coin purse\"]},{\"t\":\"Go to the top floor.\",\"s\":[\"Climb up.\"]},{\"t\":\"Use the knife on the inspectable potted fan.\",\"i\":[\"Knife\"]},{\"t\":\"Use the empty coin purse on the plant pot in the north-west of the roof with sand in it.\",\"i\":[\"Empty coin purse\"]},{\"t\":\"Use the branch on the coin purse.\",\"i\":[\"Branch\",\"Sandy coin purse\"]},{\"t\":\"Search Janus.\"},{\"t\":\"Enter the basement in the hideout.\"},{\"t\":\"Talk to the queen in the hideout basement.\",\"s\":[\"Yes, let's go.\"]}],\"i\":[\"Any type of bone or raw meat\"]},{\"n\":\"The dwarves\",\"st\":[{\"t\":\"Enter Cam Torum.\"},{\"t\":\"Talk to Attala in Cam Torum's marketplace.\"},{\"t\":\"Talk to Servius in the house east of the bank in Cam Torum.\"},{\"t\":\"Go upstairs in the house.\"},{\"t\":\"Take the beer. Hop worlds if it's missing.\",\"i\":[\"Beer\"]},{\"t\":\"Go downstairs in the house.\"},{\"t\":\"Use the beer on Galna.\",\"i\":[\"Beer\"]},{\"t\":\"Enter the house's basement.\"},{\"t\":\"Search the south-west cabinet for wizard's mind bomb.\",\"s\":[\"More options...\",\"Wizard's mind bomb.\"]},{\"t\":\"Place wizard's mind bomb on the south-east barrel.\",\"i\":[\"Wizard's mind bomb\"]},{\"t\":\"Search the south-west cabinet for a beer.\",\"s\":[\"Beer.\"]},{\"t\":\"Place beer on the north barrel.\",\"i\":[\"Beer\"]},{\"t\":\"Search the south-west cabinet for steamforge brew.\",\"s\":[\"More options...\",\"Steamforge brew.\"]},{\"t\":\"Place steamforge brew on the south-west barrel.\",\"i\":[\"Steamforge brew\"]},{\"t\":\"Search the south-west cabinet for dwarven stout.\",\"s\":[\"Previous options...\",\"Dwarven stout.\"]},{\"t\":\"Place dwarven stout on the south barrel.\",\"i\":[\"Dwarven stout\"]},{\"t\":\"Drink a beer.\",\"i\":[\"Beer\"]},{\"t\":\"Place empty glass on the east barrel.\",\"i\":[\"Empty glass\"]},{\"t\":\"Inspect the fireplace.\",\"s\":[\"Pull it.\"]},{\"t\":\"Enter the hole in the south-east corner of the room.\"},{\"t\":\"Watch the cutscene with Ennius.\"},{\"t\":\"Go back through the hole into the Teumo's basement.\"},{\"t\":\"Talk to Servius in the house basement.\"}]},{\"n\":\"Ancient keys\",\"st\":[{\"t\":\"Enter the Neypotzli entrance in the far north of the cavern.\"},{\"t\":\"Talk to Eyatlalli.\"},{\"t\":\"Enter the north-east entrance to the streambound cavern.\"},{\"t\":\"Locate with the keystone fragment on the marked tile north of the cooking stove.\",\"i\":[\"Keystone fragment\"]},{\"t\":\"Enter the earthbound cavern via the north cave entrance.\",\"i\":[\"Keystone fragment\"]},{\"t\":\"Locate with the keystone fragment on the marked tile near where you trap lizards.\",\"i\":[\"Keystone fragment\"]},{\"t\":\"Enter the ancient prison via the large entrance in the south-west of the area.\",\"i\":[\"Keystone fragment\"]},{\"t\":\"Locate with the keystone fragment on the marked tile in the south-east room with a statue.\",\"i\":[\"Keystone fragment\"]},{\"t\":\"Touch the glowing symbol that appeared. Be ready for a fight.\",\"i\":[\"Melee Combat gear\"]},{\"t\":\"Defeat the cultists. Step into golden circle to avoid the mage's special. Avoid the arrow barrage from the ranger. When you defeat one of the cultists, the other will become enraged.\"},{\"t\":\"Talk to Attala.\"}],\"i\":[\"Melee Combat gear\",\"Food\",\"Prayer potions (3)\"],\"c\":1},{\"n\":\"Crypt of Tonali\",\"st\":[{\"t\":\"Talk to Servius in Tal Teklan in the Tlati Rainforest, in the north-west of Varlamore. The easiest way here is via quetzal.\",\"i\":[\"Melee Combat gear\",\"Food\",\"Prayer potions (3)\",\"Ranged/Magic Combat gear\"]},{\"t\":\"Enter the passageway in the tree south-east of Tal Teklan, into the Crypt of Tonali.\"},{\"t\":\"Defeat the attacking cultists.\"},{\"t\":\"Defeat Ennius. Protect from Melee. Stand on the circles to avoid damage when they appear. Avoid the lines of yellow star icons on the floor when they appear. When they reach 0 health, they'll gain some back and do more damage.\"},{\"t\":\"Climb down the stairs.\"},{\"t\":\"Step onto the red teleporter to the north-east.\"},{\"t\":\"Step onto the blue teleporter to the west.\"},{\"t\":\"Step on the red teleporter to the west.\"},{\"t\":\"Step onto the blue teleporter to the north-west.\"},{\"t\":\"Step on the red teleporter to the north.\"},{\"t\":\"Climb the rope up to the north-east.\"},{\"t\":\"Inspect the strange platform nearby to activate a shortcut lift from the surface.\"},{\"t\":\"Step on the red teleporter to the north-east of the lift.\"},{\"t\":\"Inspect the statue in the middle of the room.\"},{\"t\":\"Search the urns in the area for some essence.\"},{\"t\":\"Go back up to the main area.\"},{\"t\":\"Go through the blue teleport to the west.\"},{\"t\":\"Move-Itzla to the platform north of him by clicking on it to see which torches around the room light up.\"},{\"t\":\"Move-Itzla to the platform south of him by clicking on it to see which torches around the room light up.\"},{\"t\":\"Pull some tree roots.\"},{\"t\":\"Search the old tools for a knife blade. Avoid the lines of fire by having Itzla go on the north platform to remove dark flames, and the south one for light flames.\"},{\"t\":\"Fletch the roots into kindling.\",\"i\":[\"Ancient roots\"]},{\"t\":\"Have Itzla move between both the north and south platforms to see how many braziers are lit around the room total. Put that many into the statue.\",\"i\":[\"Root kindling\"]},{\"t\":\"Repeat the kindling burning matching the total braziers lit two more times.\"},{\"t\":\"Leave the moon puzzle room.\"}],\"i\":[\"Melee Combat gear\",\"Food\",\"Prayer potions (3)\"],\"c\":1},{\"n\":\"Doom\",\"st\":[{\"t\":\"Try to open the door to the north. Be ready for the final boss!\",\"i\":[\"Ranged/Magic Combat gear\"]},{\"t\":\"Approach Augur Metzli, ready for a fight.\"},{\"t\":\"Defeat Metzli. Start with Protect from Missiles. Use the gaps in the wave attacks to dodge the walls as they approach. If circles appear, stand where they appeared. Every time a teleporter appears to jump over a wave, the boss will switch attack styles alternating between mage and ranged. The boss will enter an enrage phase, it is much easier to range but melee is still possible. Attack the boss and then immediately click on the next teleporter to avoid taking damage.\"},{\"t\":\"Watch Metzli's cutscene.\"},{\"t\":\"Enter the entrance in the north of the area.\"},{\"t\":\"Inspect the ralos pillar south-west of the north door.\"},{\"t\":\"Inspect the ranul pillar south-east of the north door.\"},{\"t\":\"Inspect the entrance in the north of the area again.\"},{\"t\":\"Inspect the skeleton west of the north door.\"},{\"t\":\"Read the stone tablet.\",\"i\":[\"Stone tablet\"]},{\"t\":\"Talk to Prince Itzla Arkan to complete the quest!\"}],\"i\":[\"Ranged/Magic Combat gear\",\"Food\",\"Prayer potions (3)\"],\"c\":1,\"e\":[\"Augur Metzli (lvl-396)\"]}]}"
        "The Forsaken Tower" -> "{\"n\":\"The Forsaken Tower\",\"items\":[],\"rec\":[\"Games necklace for accessing Wintertodt\"],\"enemies\":[],\"rewards\":[\"1 Quest point\",\"500 Mining XP\",\"500 Smithing XP\",\"6000 x Coins\",\"A page for Kharedst's memoirs.\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Talk to Lady Vulcana Lovakengj in the south of Lovakengj.\",\"s\":[\"Yes.\",\"I'm looking for a quest.\",\"I'll get going.\"]},{\"t\":\"Talk to Undor at the entrance to Wintertodt. If you've never talked to Ignisia before, you'll need to talk to her first. She is just north east of Undor. You can teleport there using a Games Necklace, or run north through Arceuus.\",\"s\":[\"I've been sent to help you.\"]}],\"c\":0},{\"n\":\"To the Forsaken Tower\",\"st\":[{\"t\":\"Enter the Forsaken Tower, west of Lovakengj.\"},{\"t\":\"Inspect the display case in the Forsaken Tower.\"}],\"c\":0},{\"n\":\"Power puzzle\",\"st\":[{\"t\":\"Climb down the ladder into the tower's basement.\"},{\"t\":\"Search a crate in the north eastern cell for a generator crank\"},{\"t\":\"Inspect the steam generator in the south of the room\",\"s\":[\"Start the generator.\"],\"i\":[\"Generator crank\"]},{\"t\":\"Inspect the power grid.\",\"s\":[\"Yes.\"]},{\"t\":\"Solve the power puzzle.\"}],\"c\":0},{\"n\":\"Finishing off\",\"st\":[{\"t\":\"Get the hammer from the display case in the Forsaken Tower.\"},{\"t\":\"Return Dinh's Hammer to Undor at the entrance to Wintertodt.\",\"s\":[\"Let's talk about my quest.\",\"Yes.\"],\"i\":[\"Dinh's hammer\"]},{\"t\":\"Return to Lady Vulcana in south Lovakengj to finish the quest.\"}],\"c\":0}]}"
        "The Fremennik Exiles" -> "{\"n\":\"The Fremennik Exiles\",\"items\":[\"Combat gear\",\"Mirror shield\",\"2x kegs of beer or 650 coins\",\"Molten glass\",\"Astral runes (100)\",\"Pet rock\",\"Rune thrownaxe, or a friend to help enter Waterbirth Isle Dungeon\",\"Fishing rod\",\"Fremennik shield\",\"Ice gloves or smiths gloves(i)\",\"Hammer\",\"Glassblowing pipe\",\"Any pickaxe\",\"Seal of passage\"],\"rec\":[\"Food\",\"Rellekka teleports\",\"Restore potions\"],\"enemies\":[\"Basilisk Youngling (level 53)\",\"Basilisk (level 61)\",\"Monstrous Basilisk (level 135)\",\"Typhor (level 218)\",\"The Jormungand (level 363)\"],\"rewards\":[\"2 Quest points\",\"50,000 Slayer XP\",\"50,000 Crafting XP\",\"30,000 Runecraft XP\",\"V's Shield\",\"Access to the Isle of Stone\",\"Ability to kill Basilisk Knights as a slayer task\",\"Ability to craft and equip the Neitiznot faceguard.\"],\"sec\":[{\"n\":\"Investigating\",\"st\":[{\"t\":\"Buy 2 kegs of beer from Thora in Rellekka. She will be unavailable to trade later in the quest.\",\"i\":[\"Coins (650)\"]},{\"t\":\"Talk to Brundt in Rellekka's longhall.\",\"s\":[\"Ask for a quest.\",\"Yes.\"]},{\"t\":\"Talk to Freygerd in north Rellekka.\",\"i\":[\"Combat gear\",\"Mirror shield\"]},{\"t\":\"Search the sand pit near Freygerd, ready to fight a basilisk youngling.\",\"i\":[\"Combat gear\",\"Mirror shield\"]},{\"t\":\"Defeat the Basilisk Youngling.\",\"i\":[\"Combat gear\",\"Mirror shield\"]},{\"t\":\"Pick up the letter.\",\"i\":[\"Unsealed letter\"]},{\"t\":\"Read the letter.\",\"i\":[\"Unsealed letter\"]},{\"t\":\"Search the rockslide west of the sand pit.\"},{\"t\":\"Search the boxes south of Freygerd.\"},{\"t\":\"Return to Freygerd with the items you found.\",\"i\":[\"Unsealed letter\",\"Fang\",\"Venom gland\"]},{\"t\":\"Return to Brundt in Rellekka's longhall.\",\"s\":[\"Ask about the investigation.\",\"Ask about the Jormungand.\"]},{\"t\":\"Talk to Brundt south east of Rellekka, asking him all available questions.\"}],\"i\":[\"Combat gear\",\"Mirror shield\"],\"c\":1,\"e\":[\"Basilisk Youngling (level 53)\",\"Basilisk (level 61)\"]},{\"n\":\"A Fremennik Shield\",\"st\":[{\"t\":\"You can get a fremennik shield from dagannoths in Waterbirth Dungeon or Bardur in Waterbirth Dungeon for 150k, or for free with the Ring of Charos(a). You'll need a friend to get there, or a rune thrownaxe and a pet rock.\",\"i\":[\"Ring of Charos(a) or 150k coins\"]}],\"i\":[\"Ring of Charos(a) or 150k coins\",\"Pet rock\",\"Rune thrownaxe, or a friend to help enter Waterbirth Isle Dungeon\"]},{\"n\":\"Making Lunar Glass\",\"st\":[{\"t\":\"Talk to Baba Yaga in the chicken-legged house in the north of Lunar Isle's town.\",\"i\":[\"Seal of passage\",\"Molten glass\"]},{\"t\":\"Use the Lunar Altar to make some lunar glass.\",\"i\":[\"Molten glass (i)\",\"Astral runes (100)\"]}],\"i\":[\"Seal of passage\",\"Molten glass\",\"Astral runes (100)\"]},{\"n\":\"Making V's Sigil\",\"st\":[{\"t\":\"Enter the mine in the north east of Lunar Isle.\",\"i\":[\"Any pickaxe\"]},{\"t\":\"Mine 3 lunar ores from the stalagmites in the area.\",\"i\":[\"Any pickaxe\"]},{\"t\":\"Smelt the lunar ore into bars at any furnace.\",\"i\":[\"Lunar ore (3)\"]},{\"t\":\"Make the V sigil on any anvil.\",\"s\":[\"Yes.\"],\"i\":[\"Lunar bar (3)\"]},{\"t\":\"Talk to the Fossegrimen south west of Rellekka to enchant the sigil.\",\"s\":[\"Ask about V's Sigil.\"],\"i\":[\"V sigil\"]}],\"i\":[\"Any pickaxe\",\"Hammer\"]},{\"n\":\"Making a Polishing Rock\",\"st\":[{\"t\":\"Inspect the geyser north of the Mountain Camp.\",\"s\":[\"It's for the good of the Province!\"],\"i\":[\"Pet rock\"]},{\"t\":\"Talk to Peer the Seer south west of the Rellekka market.\"},{\"t\":\"Inspect the geyser again.\",\"i\":[\"Pet rock\",\"Ice gloves or smiths gloves(i)\",\"Fishing rod\"]},{\"t\":\"Retrieve your rock from the geyser.\",\"i\":[\"Ice gloves or smiths gloves(i)\",\"Fishing rod\"]}],\"i\":[\"Pet rock\",\"Ice gloves or smiths gloves(i)\",\"Fishing rod\"]},{\"n\":\"Forging the shield\",\"st\":[{\"t\":\"Use the shield parts together to make V's Shield.\",\"i\":[\"Fremennik shield\",\"Lunar glass\",\"Polishing rock\",\"V sigil (e)\",\"Glassblowing pipe\"]},{\"t\":\"Talk to Brundt south east of Rellekka with V's shield.\",\"i\":[\"V's shield\",\"Kegs of beer (2)\"]},{\"t\":\"Talk to Brundt with 2 kegs of beer.\",\"i\":[\"Kegs of beer (2)\"]}],\"i\":[\"Fremennik shield\",\"Lunar glass\",\"Polishing rock\",\"V sigil (e)\",\"Glassblowing pipe\",\"Kegs of beer (2)\"]},{\"n\":\"Defending Rellekka\",\"st\":[{\"t\":\"Return to Brundt in Rellekka's longhall.\",\"s\":[\"Ask about the Jormungand.\"],\"i\":[\"Combat gear\",\"Food\"]},{\"t\":\"Kill basilisks until you're told to stop.\",\"i\":[\"V's shield\",\"Combat gear\",\"Food\"]},{\"t\":\"Take the boat to the Isle of Stone.\"},{\"t\":\"Talk to Brundt outside the cave entrance.\"},{\"t\":\"Attempt to open the door and solve the puzzle. It's Mastermind, where a red tick means you have one of the correct runes in the wrong position, and a green tick means a correct rune in the correct position.\"},{\"t\":\"Enter the door, ready to fight.\",\"s\":[\"Yes.\"],\"i\":[\"Combat gear\",\"V's shield\"]},{\"t\":\"Fight Typhor, who attacks with both Melee and Magic. He is weak to crush.\",\"i\":[\"V's shield\"]},{\"t\":\"Defeat the Jormungand.\",\"i\":[\"V's shield\"]}],\"i\":[\"Combat gear\"],\"c\":1,\"e\":[\"Basilisk (level 61)\",\"Typhor (level 218)\",\"The Jormungand (level 363)\"]}]}"
        "The Fremennik Isles" -> "{\"n\":\"The Fremennik Isles\",\"items\":[],\"rec\":[],\"enemies\":[\"10 Ice Trolls (level 74-82)\",\"Ice Troll King (level 122)\"],\"rewards\":[\"1 Quest point\",\"5,000 Construction XP\",\"5,000 Crafting XP\",\"10,000 Woodcutting XP\",\"2 x 10,000 Exp. Lamp (Combat)\",\"Helm of Neitiznot\",\"Jester Outfit\",\"Around 20,000 coins in assorted rewards during quest\"],\"sec\":[{\"n\":\"Travel to Jatizso\",\"st\":[{\"t\":\"Talk to Mord Gunnars on a pier in north Rellekka.\"},{\"t\":\"Travel to Jatizso with Mord.\",\"s\":[\"Can you ferry me to Jatizso?\"]}],\"i\":[\"Raw tuna\",\"Mithril ore (6)\",\"Coal (7)\",\"Tin ore (8)\"]},{\"n\":\"Helping Gjuki\",\"st\":[{\"t\":\"Talk to King Gjuki Sorvott IV on Jatizso.\",\"i\":[\"Raw tuna\"]},{\"t\":\"Search the chest behind Gjuki's throne for a silly jester outfit.\",\"s\":[\"Take the jester's hat.\",\"Take the jester's top.\",\"Take the jester's tights.\",\"Take the jester's boots.\"]}]},{\"n\":\"Spy on Mawnis\",\"st\":[{\"t\":\"Talk to Slug Hemligssen wearing nothing but your Silly Jester outfit.\",\"s\":[\"Free stuff please.\",\"I am ready.\"],\"i\":[\"Silly jester hat\",\"Silly jester body\",\"Silly jester tights\",\"Silly jester boots\"]},{\"t\":\"Talk to Mawnis in Neitiznot to start spying on him.\",\"i\":[\"Silly jester hat\",\"Silly jester body\",\"Silly jester tights\",\"Silly jester boots\"]},{\"t\":\"Report back to Slug Hemligssen.\",\"s\":[\"Yes I have.\",\"They will be ready in two days.\",\"Seventeen militia have been trained.\",\"There are two bridges to repair.\"]}]},{\"n\":\"Collecting window tax\",\"st\":[{\"t\":\"Report back to King Gjuki Sorvott IV on Jatizso.\"},{\"t\":\"Collect 5000 coins from Keepa in north east Jatizso.\",\"s\":[\"But rules are rules. Pay up!\"]},{\"t\":\"Collect 5000 coins from Vanligga north of Gjuki's building.\",\"s\":[\"But, rules are rules. Pay up!\"]},{\"t\":\"Collect 6000 coins from Skuli in north west Jatizso.\",\"s\":[\"But, rules are rules. Pay up!\"]},{\"t\":\"Collect 8000 coins from Hring Hring in south west Jatizso.\",\"s\":[\"But rules are rules. Pay up!\"]}]},{\"n\":\"Collecting beard tax\",\"st\":[{\"t\":\"Collect tax from Hring Hring in south west Jatizso.\",\"s\":[\"But rules are rules. Pay up!\"]},{\"t\":\"Collect tax from Raum in south west Jatizso.\",\"s\":[\"But rules are rules. Pay up!\"]},{\"t\":\"Collect tax from Skuli in north west Jatizso.\",\"s\":[\"But rules are rules. Pay up!\"]},{\"t\":\"Collect tax from Keepa in north east Jatizso.\",\"s\":[\"But rules are rules. Pay up!\"]},{\"t\":\"Collect tax from Flossi in north east Jatizso.\",\"s\":[\"But rules are rules. Pay up!\"]},{\"t\":\"Report back to King Gjuki Sorvott IV on Jatizso.\"}]},{\"n\":\"Spy on Mawnis again\",\"st\":[{\"t\":\"Talk to Slug Hemligssen wearing nothing but your Silly Jester outfit.\",\"i\":[\"Silly jester hat\",\"Silly jester body\",\"Silly jester tights\",\"Silly jester boots\"]},{\"t\":\"Talk to Mawnis to start spying on him.\",\"i\":[\"Silly jester hat\",\"Silly jester body\",\"Silly jester tights\",\"Silly jester boots\"]},{\"t\":\"Report to Slug Hemligssen.\",\"s\":[\"Yes, I am.\",\"They are in a secluded bay, near Etceteria.\",\"They will be given some potions.\",\"I have been helping Neitiznot.\"]},{\"t\":\"Report back to King Gjuki Sorvott IV on Jatizso.\"},{\"t\":\"Take off your jester outfit, and talk to Mawnis.\",\"i\":[\"Royal decree\"]}]},{\"n\":\"Killing the king\",\"st\":[{\"t\":\"Enter the cave in the north east of the islands. Be prepared in your yak armour, Neitiznot shield, and a melee weapon.\",\"i\":[\"Yak-hide armour (top)\",\"Yak-hide armour (bottom)\",\"Neitiznot shield\",\"Melee gear\",\"Food + potions\"]},{\"t\":\"Cross the rope bridge. Be prepared to fight the Ice Troll King. Use the Protect from Magic prayer for the fight.\"},{\"t\":\"Kill the king. Use the Protect from Magic prayer for the fight.\"},{\"t\":\"Decapitate the king's head.\"},{\"t\":\"Talk to Mawnis with the Ice Troll King's head to complete the quest.\",\"i\":[\"Decapitated head\"]}],\"i\":[\"Neitiznot shield\",\"Melee gear\",\"Food + potions\"],\"c\":1,\"e\":[\"10 Ice Trolls (level 74-82)\",\"Ice Troll King (level 122)\"]}]}"
        "The Fremennik Trials" -> "{\"n\":\"The Fremennik Trials\",\"items\":[\"Coins (5250)\",\"Raw shark, manta ray or sea turtle\",\"Tinderbox\",\"Knife\",\"Any axe\"],\"rec\":[\"Combat gear + food\",\"Rings of recoil for Koschei\",\"Camelot teleport\",\"Teleports to Rellekka\"],\"enemies\":[\"Koschei the deathless\",\"Draugen (level 69)\"],\"rewards\":[\"3 Quest points\",\"2,812 Agility XP\",\"2,812 Attack XP\",\"2,812 Crafting XP\",\"2,812 Defence XP\",\"2,812 Fishing XP\",\"2,812 Fletching XP\",\"2,812 Hitpoints XP\",\"2,812 Strength XP\",\"2,812 Thieving XP\",\"2,812 Woodcutting XP\",\"Access to Miscellania, Etceteria, Neitiznot, Jatizso and the facilities of Rellekka.\",\"Ability to wear and purchase Fremmennik Helms\",\"Free travel to Waterbirth Island\"],\"sec\":[{\"n\":\"Talk to Brundt\",\"st\":[{\"t\":\"Talk to Brundt in Rellekka's longhall.\",\"s\":[\"Ask about anything else.\",\"Do you have any quests?\",\"Yes, I am interested.\",\"I want to become a Fremennik!\"]}],\"i\":[\"Coins (5250)\",\"Raw shark, manta ray or sea turtle\",\"Tinderbox\",\"Knife\",\"Any axe\",\"Combat gear + food\"],\"c\":1},{\"n\":\"Olaf's task\",\"st\":[{\"t\":\"Talk to Olaf the Bard north east of the longhall.\",\"s\":[\"Ask about becoming a Fremennik\",\"Yes\"]},{\"t\":\"Talk to Lalli to the south east of Rellekka.\",\"s\":[\"Other human?\"]},{\"t\":\"Return to Rellekka and talk to Askeladden for a pet rock.\",\"s\":[\"Ask about becoming a Fremennik\"]},{\"t\":\"Return to Lalli and use a onion, cabbage, potato, and pet rock on their stew. You can find the vegetables growing in the south east of Rellekka.\",\"i\":[\"Pet rock\",\"Cabbage\",\"Potato\",\"Onion\"]},{\"t\":\"Talk to Lalli for golden wool.\"},{\"t\":\"Go south east of Rellekka and cut a branch from the swaying tree\",\"i\":[\"Any axe\",\"Knife\"]},{\"t\":\"Use a knife on the branch to make an unstrung lyre\",\"i\":[\"Knife\",\"Branch\"]},{\"t\":\"Spin the golden fleece into wool using a spinning wheel. The closest wheel is in Seers' Village.\",\"i\":[\"Golden fleece\"]},{\"t\":\"Use the golden wool on your unstrung lyre.\",\"i\":[\"Unstrung lyre\",\"Golden wool\"]},{\"t\":\"Bring your lyre to the Strange Altar south west of Rellekka, and use either a raw shark, raw sea turtle or raw manta ray on it.\",\"i\":[\"Lyre\",\"Raw shark, manta ray or sea turtle\"]},{\"t\":\"Return to Rellekka and enter the longhall's stage to perform. Once on stage, play the enchanted lyre.\",\"i\":[\"Enchanted lyre\"]}],\"i\":[\"Any axe\",\"Knife\",\"Raw shark, manta ray or sea turtle\",\"Empty inventory slots for vegetables and a pet rock (4)\"]},{\"n\":\"Manni's task\",\"st\":[{\"t\":\"Talk to Manni the Reveller in the Rellekka longhall.\",\"s\":[\"Ask about becoming a Fremennik\",\"Yes\"]},{\"t\":\"Get some beer. There is beer tankard in the Rellekka longhall.\",\"i\":[\"Beer\"]},{\"t\":\"Give the Council workman on the bridge south of Rellekka going to Seer's Village a beer.\",\"s\":[\"Yes\"],\"i\":[\"Beer\"]},{\"t\":\"Buy some alcohol free beer from the Poison Salesman in the Seer's Village pub.\",\"s\":[\"Talk about the Fremennik Trials\",\"Yes\"],\"i\":[\"Coins (250)\"]},{\"t\":\"Return to Rellekka with the strange object, a tinderbox, and low alcohol beer.\",\"i\":[\"Strange object\",\"Tinderbox\",\"Low alcohol keg\"]},{\"t\":\"Use a tinderbox on the strange object then use it on the nearby pipe.\",\"i\":[\"Strange object\",\"Tinderbox\"]},{\"t\":\"Pick up a keg of beer in the longhall.\",\"i\":[\"Keg of beer\"]},{\"t\":\"Use the low alcohol beer on the keg of beer whilst in the longhall.\",\"i\":[\"Low alcohol keg\",\"Keg of beer\"]},{\"t\":\"Talk to Manni the Reveller to cheat in the competition.\",\"s\":[\"Ask about becoming a Fremennik\",\"Yes\"],\"i\":[\"Keg of beer\"]}],\"i\":[\"Tinderbox\",\"Coins (250)\"]},{\"n\":\"Sigli's task\",\"st\":[{\"t\":\"Talk to Sigli south of the longhall for a hunters' talisman.\",\"s\":[\"Ask about becoming a Fremennik\",\"What's a Draugen?\",\"Yes\"]},{\"t\":\"Use the hunter's talisman to hunt down the Draugen. It'll appear near one of the butterflies in the area.\"},{\"t\":\"Return the charged hunters' talisman to Sigli.\",\"i\":[\"Hunters' talisman\"]}],\"i\":[\"Combat gear + food\"],\"c\":1,\"e\":[\"Draugen (level 69)\"]},{\"n\":\"Sigmund's task\",\"st\":[{\"t\":\"Talk to Sigmund the Merchant in the Rellekka market.\",\"s\":[\"Yes\"]},{\"t\":\"Talk to the Sailor on the docks.\",\"s\":[\"Ask about the Merchant's trial\"]},{\"t\":\"Talk to Olaf the Bard east of the longhall.\",\"s\":[\"Ask about the Merchant's trial\"]},{\"t\":\"Talk to Ysra in her shop west of the market.\",\"s\":[\"Ask about the Merchant's trial\"]},{\"t\":\"Talk to Brundt in the longhall.\",\"s\":[\"Ask about the Merchant's trial\",\"Ask about anything else.\"]},{\"t\":\"Talk to Sigli south of the longhall.\",\"s\":[\"Ask about the Merchant's trial\"]},{\"t\":\"Talk to Skulgrimen north of the longhall.\",\"s\":[\"Ask about the Merchant's trial\"]},{\"t\":\"Talk to the Fisherman on the pier north of the market.\",\"s\":[\"Ask about the Merchant's trial\"]},{\"t\":\"Talk to Swensen the Navigator in his hut south west of the longhall.\",\"s\":[\"Ask about the Merchant's trial\"]},{\"t\":\"Talk to Peer the Seer south west of the market.\",\"s\":[\"Ask about the Merchant's trial\"]},{\"t\":\"Talk to Thorvald north of the longhall.\",\"s\":[\"Ask about the Merchant's trial\"]},{\"t\":\"Talk to Manni the Reveller in the longhall.\",\"s\":[\"Ask about the Merchant's trial\"]},{\"t\":\"Talk to Thora the Barkeep in the longhall.\",\"s\":[\"Ask about the Merchant's trial\"]},{\"t\":\"Talk to Askeladden south of the longhall.\",\"s\":[\"Ask about the Merchant's trial\",\"Yes\"]},{\"t\":\"Bring the promissory note to Thora the Barkeep in the longhall.\",\"s\":[\"Ask about the Merchant's trial\"],\"i\":[\"Promissory note\"]},{\"t\":\"Bring the cocktail to Manni the Reveller in the longhall.\",\"s\":[\"Ask about the Merchant's trial\"],\"i\":[\"Legendary cocktail\"]},{\"t\":\"Bring the champions token to Thorvald north of the longhall.\",\"s\":[\"Ask about the Merchant's trial\",\"Yes\"],\"i\":[\"Champions token\"]},{\"t\":\"Bring the warriors' contract to Peer the Seer south west of the market.\",\"s\":[\"Ask about the Merchant's trial\"],\"i\":[\"Warriors' contract\"]},{\"t\":\"Bring the weather forecast to Swensen the Navigator in his hut south west of the longhall.\",\"s\":[\"Ask about the Merchant's trial\"],\"i\":[\"Weather forecast\"]},{\"t\":\"Bring the sea fishing map to the Fisherman on the pier north of the market.\",\"s\":[\"Ask about the Merchant's trial\"],\"i\":[\"Sea fishing map\"]},{\"t\":\"Bring the unusual fish to Skulgrimen north of the longhall.\",\"s\":[\"Ask about the Merchant's trial\"],\"i\":[\"Unusual fish\"]},{\"t\":\"Bring the custom bow string to Sigli south of the longhall.\",\"s\":[\"Ask about the Merchant's trial\"],\"i\":[\"Custom bow string\"]},{\"t\":\"Bring the tracking map to Brundt in the longhall.\",\"s\":[\"Ask about the Merchant's trial\",\"Ask about anything else.\"],\"i\":[\"Tracking map\"]},{\"t\":\"Bring the fiscal statement to Ysra in her shop west of the market.\",\"s\":[\"Ask about the Merchant's trial\"],\"i\":[\"Fiscal statement\"]},{\"t\":\"Bring the sturdy boots to Olaf the Bard east of the longhall.\",\"s\":[\"Ask about the Merchant's trial\"],\"i\":[\"Sturdy boots\"]},{\"t\":\"Bring the ballad to the Sailor on the docks.\",\"s\":[\"Ask about the Merchant's trial\"],\"i\":[\"Fremennik ballad\"]},{\"t\":\"Finally, bring the exotic flower to Sigmund the Merchant in the Rellekka market.\",\"i\":[\"Exotic flower\"]}],\"i\":[\"Coins (5000)\"]},{\"n\":\"Thorvald's task\",\"st\":[{\"t\":\"Talk to Thorvald north of the longhall.\",\"s\":[\"Ask about becoming a Fremennik\"]},{\"t\":\"When you're ready to fight Koschei, go down the ladder.\",\"i\":[\"Nothing except for food, potions, and rings of recoil\",\"Optionally a Dramen branch + knife to make a dramen staff once inside Koschei's arena\"]},{\"t\":\"Fight Koschei the Deathless and 'kill' him at least 3 times. Dying to his fourth phase is a SAFE death.\"}],\"i\":[\"Nothing except for food, potions, and rings of recoil\",\"Optionally a Dramen branch + knife to make a dramen staff once inside Koschei's arena\"],\"c\":1,\"e\":[\"Koschei the deathless\"]},{\"n\":\"Swensen's task\",\"st\":[{\"t\":\"Talk to Swensen the Navigator in his hut south west of the longhall.\",\"s\":[\"Yes\",\"Ask about becoming a Fremennik\"]},{\"t\":\"Climb down Swensen's ladder.\"},{\"t\":\"Solve Swensen's challenge.\"}]},{\"n\":\"Peer's task\",\"st\":[{\"t\":\"Talk to Peer the Seer south west of the Rellekka market. You will need to bank all your items. Peer will offer to do this for you.\",\"s\":[\"Ask about becoming a Fremennik\",\"Yes\"]},{\"t\":\"Try to enter Peer the Seer's house after banking all your items. Peer the Seer will offer to bank everything for you.\",\"s\":[\"Read the riddle\"]},{\"t\":\"Enter the solution to Peer's door.\"},{\"t\":\"Solve Peer's challenge.\"}]},{\"n\":\"Finish off\",\"st\":[{\"t\":\"Talk to Brundt in Rellekka's longhall to finish the quest.\",\"s\":[\"Ask about anything else.\"]}]}]}"
        "The Garden of Death" -> "{\"n\":\"The Garden of Death\",\"items\":[\"Secateurs (Obtainable in quest)\"],\"rec\":[\"Xeric's talisman\",\"Kharedst's memoirs or book of the dead for teleports\",\"Fairy ring access for quick access to Molch Island (DJR)\",\"Antipoisons\"],\"enemies\":[],\"rewards\":[\"1 Quest point\",\"10,000 Farming XP\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Search the tent in the south east of the Kebos Lowlands.\",\"s\":[\"Yes.\"]},{\"t\":\"Read the journal\",\"i\":[\"Kasonde's journal\"]},{\"t\":\"Search the camping equipment for some secateurs.\"},{\"t\":\"Enter the nearby hole.\",\"i\":[\"Secateurs (Obtainable in quest)\"]},{\"t\":\"Search the north-west table.\"},{\"t\":\"Read the stone tablet.\",\"s\":[\"Yes.\"],\"i\":[\"Stone tablet\"]},{\"t\":\"Read the word translations.\",\"i\":[\"Word translations\"]},{\"t\":\"Click the 'Attempt Translation' button.\"},{\"t\":\"Work out various translation words and input them to the word translations.\",\"s\":[\"Yes.\"]},{\"t\":\"Leave the hole.\"}],\"i\":[\"Secateurs (Obtainable in quest)\"],\"c\":0},{\"n\":\"Investigating Molch\",\"st\":[{\"t\":\"Travel to Molch island via Boaty, located on the west/north/east sides of Lake Molch.\",\"s\":[\"Molch Island\"],\"i\":[\"Word translations\",\"Secateurs (Obtainable in quest)\"]},{\"t\":\"Enter the hole on Molch Island.\",\"i\":[\"Word translations\",\"Secateurs (Obtainable in quest)\"]},{\"t\":\"Inspect the vines to the south.\"},{\"t\":\"Cut the vines with secateurs.\",\"i\":[\"Secateurs (Obtainable in quest)\"]},{\"t\":\"Search the south west stone table.\"},{\"t\":\"Read the stone tablet, and take the note after closing the tablet's interface.\",\"s\":[\"Yes.\"],\"i\":[\"Stone tablet\"]},{\"t\":\"Read the word translations.\",\"i\":[\"Word translations\"]},{\"t\":\"Click the 'Attempt Translation' button.\"},{\"t\":\"Work out various translation words and input them to the word translations.\",\"s\":[\"Yes.\"]}],\"i\":[\"Secateurs (Obtainable in quest)\",\"Word translations\"],\"c\":0},{\"n\":\"Investigating Xeric's Shrine\",\"st\":[{\"t\":\"Leave the hole.\"},{\"t\":\"Travel via Boaty to Molch, and enter the hole near Xeric's Shrine.\",\"s\":[\"Molch\"],\"i\":[\"Word translations\"]},{\"t\":\"Enter the hole next to Xeric's Shrine.\",\"i\":[\"Word translations\"]},{\"t\":\"Search the south east stone table.\"},{\"t\":\"Read the stone tablet.\",\"s\":[\"Yes.\"],\"i\":[\"Stone tablet\"]},{\"t\":\"Read the word translations.\",\"i\":[\"Word translations\"]},{\"t\":\"Click the 'Attempt Translation' button.\"},{\"t\":\"Work out various translation words and input them to the word translations.\",\"s\":[\"Yes.\"]}],\"i\":[\"Word translations\"],\"c\":0},{\"n\":\"Investigating the Ruins of Morra\",\"st\":[{\"t\":\"Leave the hole.\"},{\"t\":\"Enter the hole in the Ruins of Morra, south west of Shayzien.\",\"i\":[\"Word translations\"]},{\"t\":\"Search the south stone table.\"},{\"t\":\"Read the stone tablet.\",\"s\":[\"Yes.\"],\"i\":[\"Stone tablet\"]},{\"t\":\"Read the word translations.\",\"i\":[\"Word translations\"]},{\"t\":\"Click the 'Attempt Translation' button.\"},{\"t\":\"Work out various translation words and input them to the word translations.\",\"s\":[\"Yes.\"]},{\"t\":\"Read the final stone tablet again.\",\"s\":[\"Yes.\"],\"i\":[\"Stone tablet\"]},{\"t\":\"Read the warning note.\",\"i\":[\"Warning note\"]}],\"c\":0}]}"
        "The General's Shadow" -> "{\"n\":\"The General's Shadow\",\"items\":[\"Coins (40)\",\"Ghostly hood\",\"Ghostly robe (top)\",\"Ghostly robe (bottom)\",\"Ghostly gloves\",\"Ghostly boots\",\"Ghostly cloak\",\"Ring of visibility\",\"Ghostspeak amulet\",\"Combat gear\"],\"rec\":[\"Teleports to Rellekka\",\"Necklace of Passage, or a teleport to Tree Gnome Stronghold\",\"Teleport to Al Kharid\",\"Teleport to Tai Bwo Wannai\",\"Teleport to Draynor Manor\",\"Teleport to Seer's Village\",\"Teleport to Fishing Guild\"],\"enemies\":[\"Bouncer (level 160, can't use prayer)\"],\"rewards\":[\"2,000 Slayer XP\",\"The Shadow Sword\"],\"sec\":[{\"n\":\"Proving your Sin\",\"st\":[{\"t\":\"Talk to General Khazard south east of Rellekka.\",\"s\":[\"I just have one of those faces.\",\"I'm a very trustworthy person.\"],\"i\":[\"Ghostly hood\",\"Ghostly robe (top)\",\"Ghostly robe (bottom)\",\"Ghostly cloak\",\"Ghostly boots\",\"Ghostly gloves\",\"Ring of visibility\",\"Ghostspeak amulet\"]},{\"t\":\"Talk to the Sin Seer in Seers' Village.\",\"s\":[\"Bribe\",\"Here's the money.\"],\"i\":[\"Coins (40)\"]},{\"t\":\"Return to General Khazard south east of Rellekka.\",\"i\":[\"Sin seer's note\",\"Ghostly robes\",\"Ring of visibility\",\"Ghostspeak amulet\"]}],\"i\":[\"Ghostly robes\",\"Ring of visibility\",\"Ghostspeak amulet\",\"Coins (40)\"]},{\"n\":\"Finding the Scouts\",\"st\":[{\"t\":\"Talk to the scout near The Outpost, south of the Tree Gnome Stronghold.\",\"i\":[\"Ghostly robes\",\"Ring of visibility\",\"Ghostspeak amulet\"]},{\"t\":\"Talk to the scout west of Draynor Manor.\",\"i\":[\"Ghostly robes\",\"Ring of visibility\",\"Ghostspeak amulet\"]},{\"t\":\"Talk to the scout south of the Shantay Pass.\",\"i\":[\"Ghostly robes\",\"Ring of visibility\",\"Ghostspeak amulet\"]},{\"t\":\"Talk to the scout south east of Tai Bwo Wannai.\",\"i\":[\"Ghostly robes\",\"Ring of visibility\",\"Ghostspeak amulet\"]},{\"t\":\"Return to General Khazard south east of Rellekka.\",\"i\":[\"Ghostly robes\",\"Ring of visibility\",\"Ghostspeak amulet\"]}],\"i\":[\"Ghostly robes\",\"Ring of visibility\",\"Ghostspeak amulet\"]},{\"n\":\"Defeat Bouncer\",\"st\":[{\"t\":\"Enter the cave south east of the Fishing Guild. Be prepared to fight Bouncer (level 160).\",\"i\":[\"Combat gear\",\"Severed leg\"]},{\"t\":\"Enter the crack in the north east of the caves.\",\"s\":[\"Yes\"],\"i\":[\"Combat gear\",\"Severed leg\"]},{\"t\":\"Kill Bouncer. You cannot use prayers.\",\"i\":[\"Combat gear\",\"Severed leg\"]}],\"i\":[\"Combat gear\",\"Severed leg\"],\"c\":1,\"e\":[\"Bouncer (level 160, can't use prayer)\"]}]}"
        "The Giant Dwarf" -> "{\"n\":\"The Giant Dwarf\",\"items\":[\"coins (2500)\",\"Logs\",\"Tinderbox\",\"Coal\",\"Iron bar\",\"Law rune\",\"Air rune\",\"Cut sapphires (3)\",\"Various ores and bars\",\"Redberry pie\"],\"rec\":[\"A house teleport if your house is in Rimmington and if you have no faster way to Mudskipper Point\",\"A Camelot/Rellekka teleport (for starting the quest)\",\"Access to fairy rings\",\"Some stamina potions (when collecting the ores)\",\"A ring of wealth/amulet of glory/Varrock teleport\",\"Clay (10)\",\"Copper ore (10)\",\"Tin ore (10)\",\"Iron ore (10)\",\"Coal (10)\",\"Silver ore (10)\",\"Gold ore (10)\",\"Mithril ore (10)\",\"Bronze bar (10)\",\"Iron bar (10)\",\"Silver bar (10)\",\"Gold bar (10)\",\"Steel bar (10)\",\"Mithril bar (10)\"],\"enemies\":[],\"rewards\":[\"2 Quest points\",\"2,500 Mining XP\",\"2,500 Smithing XP\",\"2,500 Crafting XP\",\"1,500 Magic XP\",\"1,500 Thieving XP\",\"1,500 Firemaking XP\"],\"sec\":[{\"n\":\"Starting out\",\"st\":[{\"t\":\"Speak to the Dwarven Boatman.\",\"s\":[\"That's a deal!\",\"Yes, I'm ready and don't mind it taking a few minutes.\",\"Yes.\"]},{\"t\":\"Finish speaking to Commander Veldaban.\",\"s\":[\"Yes, I will do this.\"]},{\"t\":\"Talk to Blasidar the sculptor in the east of Keldagrim.\",\"s\":[\"Yes, I will do this.\"]}],\"c\":0},{\"n\":\"Clothes fit for a king\",\"st\":[{\"t\":\"Talk to Vermundi west of Blasidar. If you already have, open the Quest Journal to re-sync.\",\"s\":[\"Yes, I'm looking for some special clothes.\"]},{\"t\":\"Talk to the Librarian.\",\"s\":[\"Do you know anything about King Alvis' clothes?\"]},{\"t\":\"Climb any bookcase to find a book on costumes.\"},{\"t\":\"Talk to Vermundi with the book on costumes.\",\"s\":[\"Yes, about those special clothes again...\"],\"i\":[\"Book on costumes\"]},{\"t\":\"Use your coal on the spinning machine light it with a tinderbox.\",\"i\":[\"Coal\",\"Logs\"]},{\"t\":\"Start the spinning machine with a tinderbox.\",\"i\":[\"Tinderbox\"]},{\"t\":\"Talk to Vermundi again and pay 200gp.\",\"s\":[\"Yes, about those special clothes again...\",\"I'll pay.\"],\"i\":[\"Coins (200)\"]}],\"i\":[\"Weight below 30 kg\",\"Logs\",\"Coal\",\"Tinderbox\",\"coins (2500)\",\"Free inventory slot\"],\"c\":0},{\"n\":\"Boots fit for a king\",\"st\":[{\"t\":\"Talk to Saro in West Keldagrim.\",\"s\":[\"Yes, I'm looking for a pair of special boots.\"]},{\"t\":\"Talk to Dromund.\"},{\"t\":\"Take the Left boot when Dromund isn't looking.\"},{\"t\":\"Take the Right boot from outside his window when he isn't looking using Telekinetic Grab.\",\"i\":[\"Law rune\",\"Air rune\"]}],\"i\":[\"Law rune\",\"Air rune\"],\"c\":0},{\"n\":\"An axe fit for a king\",\"st\":[{\"t\":\"Talk to Santiri.\",\"s\":[\"Yes, I'm looking for a particular battleaxe.\",\"Blasidar the sculptor needs it for his statue.\",\"Perhaps I can repair the axe?\"]},{\"t\":\"Use the 3 sapphires on the axe.\",\"i\":[\"Dwarven battleaxe\",\"Cut sapphires (3)\"]},{\"t\":\"Talk to the Librarian about Imcando Dwarves. If you already have and no option appears for this, go talk to Reldo in Varrock Castle.\",\"s\":[\"Can you help me find an Imcando dwarf?\"]},{\"t\":\"Talk to Reldo in Varrock Castle's library.\",\"s\":[\"Ask about Imcando dwarves.\"]},{\"t\":\"Talk to Thurgo at Mudskipper Point.\",\"s\":[\"Something else.\",\"Return to Keldagrim immediately.\"],\"i\":[\"Redberry pie\",\"Iron bar\",\"Dwarven battleaxe\"]}],\"i\":[\"Cut sapphires (3)\",\"Iron bar\",\"Redberry pie\"],\"c\":0},{\"n\":\"Halfway there\",\"st\":[{\"t\":\"Talk to Riki the sculptor's model to give him the clothes, axe and boots.\",\"s\":[\"Return to Keldagrim immediately.\"],\"i\":[\"Exquisite clothes\",\"Exquisite boots\",\"Dwarven battleaxe\"]},{\"t\":\"Talk to Blasidar the sculptor.\"}],\"i\":[\"Exquisite clothes\",\"Exquisite boots\",\"Dwarven battleaxe\"],\"c\":0},{\"n\":\"Joining the consortium\",\"st\":[{\"t\":\"Go to the upper floor of the market.\"},{\"t\":\"Keep talking to the same secretary and complete the tasks given. If you don't want to do one of the tasks, just talk to them again for a different one.\",\"s\":[\"Is there anything I can help you with?\",\"I'll take it.\",\"Do you have another task for me?\"]},{\"t\":\"Keep talking to the director of the same secretary and complete the tasks given. If you don't want to do one of the task, just talk to them again for a different one.\",\"s\":[\"Do you have any more tasks for me?\",\"I'll take it.\"]},{\"t\":\"Talk to the director to join the company.\",\"s\":[\"I'd like to officially join your company.\"]},{\"t\":\"Talk to the director after joining the company.\",\"s\":[\"Blasidar the sculptor has sent me.\",\"I would support you.\",\"Yes! Long live the Blue Opal!\"]},{\"t\":\"Talk to Commander Veldaban.\",\"s\":[\"I'm ready.\"]}],\"i\":[\"Various ores and bars\",\"Some stamina potions (when collecting the ores)\"],\"c\":0}]}"
        "The Golem" -> "{\"n\":\"The Golem\",\"items\":[\"Soft clay (4)\",\"Vial\",\"Pestle and mortar\",\"Papyrus\"],\"rec\":[\"Varrock teleport\",\"Digsite teleport\",\"Necklace of passage to Eagle's Eyrie\",\"Waterskins\"],\"enemies\":[],\"rewards\":[\"1 Quest point\",\"1,000 Thieving XP\",\"1,000 Crafting XP\",\"2 x Rubies (by using a chisel and hammer on the throne)\",\"2 x Emeralds (by using a chisel and hammer on the throne)\",\"2 x Sapphires (by using a chisel and hammer on the throne)\",\"Ability to take the Carpet ride from Shantay Pass to Uzer.\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Talk to the Golem in Uzer to start the quest.\",\"s\":[\"Yes.\",\"Eagle's Eyrie\"]},{\"t\":\"Use 4 soft clay on the Golem in Uzer.\",\"i\":[\"Soft clay (4)\"]},{\"t\":\"Pick up the letter on the floor in Uzer and read it.\",\"s\":[\"Eagle's Eyrie\"],\"i\":[\"Letter\"]},{\"t\":\"Enter the Uzer ruins. You can drop the Letter you just read.\"},{\"t\":\"Pick up the strange implement in the north west corner of the ruin.\",\"i\":[\"Strange implement\"]}],\"i\":[\"Soft clay (4)\"],\"c\":0},{\"n\":\"Finding the statuette\",\"st\":[{\"t\":\"Talk to Elissa in the north east of the Digsite.\",\"s\":[\"I found a letter in the desert with your name on.\"]},{\"t\":\"Search the bookcase in the south east corner of the Digsite Exam Centre.\"},{\"t\":\"Read Varmen's notes.\",\"i\":[\"Varmen's notes\"]},{\"t\":\"Talk to Curator Haig in the Varrock Museum. You can drop Varmen's notes.\",\"s\":[\"I'm looking for a statuette recovered from the city of Uzer.\"]},{\"t\":\"Pickpocket Curator Haig for the Display cabinet key.\"},{\"t\":\"Go to the first floor of the Varrock Museum and right-click open the golem statue's display case.\",\"i\":[\"Display cabinet key\"]},{\"t\":\"Right-click open the golem statue's display case.\",\"i\":[\"Display cabinet key\"]}],\"c\":0},{\"n\":\"Opening the portal\",\"st\":[{\"t\":\"Enter the Uzer ruins.\",\"s\":[\"Eagle's Eyrie\"],\"i\":[\"Statuette\",\"Pestle and mortar\",\"Vial\",\"Papyrus\"]},{\"t\":\"Use the statue on the empty alcove.\",\"i\":[\"Statuette\"]},{\"t\":\"Turn each of the statuettes to face the door.\"},{\"t\":\"Enter the portal.\"},{\"t\":\"Leave the throne room and return to the Golem.\"},{\"t\":\"Talk to the Golem in Uzer.\"},{\"t\":\"Pick up some black mushrooms.\"},{\"t\":\"Grind the mushrooms into a vial.\",\"i\":[\"Pestle and mortar\",\"Black mushroom\",\"Vial\"]},{\"t\":\"Steal a feather from the desert phoenix north of Uzer.\",\"s\":[\"Eagle's Eyrie\"]},{\"t\":\"Use the phoenix feather on the ink.\",\"i\":[\"Phoenix feather\",\"Black mushroom ink\"]},{\"t\":\"Use the phoenix quill on the papyrus.\",\"i\":[\"Phoenix quill pen\",\"Papyrus\"]},{\"t\":\"Use the strange implement on the Golem in Uzer.\",\"i\":[\"Strange implement\"]},{\"t\":\"Use the golem program on the Golem in Uzer.\",\"i\":[\"Golem program\"]}],\"i\":[\"Vial\",\"Pestle and mortar\",\"Papyrus\"],\"c\":0}]}"
        "The Grand Tree" -> "{\"n\":\"The Grand Tree\",\"items\":[\"Coins to enter the Stronghold if you didn't help Femi previously (1000)\"],\"rec\":[\"Combat gear. Safespotting is possible.\",\"Food\",\"Prayer potions\",\"Energy restoration\",\"Access to Fairy Rings\",\"Transport to the Grand Tree\"],\"enemies\":[\"Black demon (level 172) (can be safespotted)\"],\"rewards\":[\"5 Quest points\",\"18,400 Attack XP\",\"7,900 Agility XP\",\"2,150 Magic XP\",\"Ability to use the Spirit Tree in the Tree Gnome Stronghold.\"],\"sec\":[{\"n\":\"Getting started\",\"st\":[{\"t\":\"Talk to King Narnode Shareen in the Grand Tree(Make sure to have two empty inventory slots to start the quest).\",\"s\":[\"You seem worried, what's up?\",\"I'd be happy to help!\"]}]},{\"n\":\"Hazelmere\",\"st\":[{\"t\":\"Go up to Hazelmere, on the island east of Yanille. Fairy ring CLS or minigame teleport near Yanille.\",\"i\":[\"Translation Book\",\"Bark Sample\"]},{\"t\":\"Talk to Hazelmere.\",\"i\":[\"Translation Book\",\"Bark Sample\"]}],\"i\":[\"Bark Sample\",\"Translation Book\"]},{\"n\":\"Investigation\",\"st\":[{\"t\":\"Return to King Narnode in the Grand Tree.\",\"s\":[\"I think so!\",\"None of the above.\",\"A man came to me with the King's seal.\",\"I gave the man Daconia rocks.\",\"And Daconia rocks will kill the tree!\"]},{\"t\":\"Go up to Glough in the Tree Gnome Stronghold.\"},{\"t\":\"Talk to Glough.\"},{\"t\":\"Talk to King Narnode again in the Grand Tree.\"},{\"t\":\"Talk to Charlie on the top floor of the Grand Tree.\"},{\"t\":\"Return to Glough's house and search the cupboard for Glough's Journal.\"},{\"t\":\"Confront Glough about his journal.\"},{\"t\":\"Talk to Charlie.\"},{\"t\":\"Talk to King Narnode outside Charlie's cell.\"},{\"t\":\"Travel with the glider to escape.\",\"s\":[\"Take me to Karamja please!\"]}]},{\"n\":\"Karamja\",\"st\":[{\"t\":\"Enter the shipyard on Karamja.\",\"s\":[\"Glough sent me.\",\"Ka.\",\"Lu.\",\"Min.\"]},{\"t\":\"Get the Lumber order from the Foreman on the southern docks. You can either kill him or talk to him.\",\"s\":[\"Sadly his wife is no longer with us!\",\"He loves worm holes.\",\"Anita.\"]}],\"i\":[\"Coins to enter the Stronghold if you didn't help Femi previously (1000)\"]},{\"n\":\"Tuzo\",\"st\":[{\"t\":\"Talk to Anita in her house west of the Grand Tree.\"},{\"t\":\"Search the chest in Glough's house.\",\"i\":[\"Glough's key\"]},{\"t\":\"Take the invasion plans to King Narnode in the Grand Tree.\",\"i\":[\"Invasion plans\"]},{\"t\":\"Place the twigs to spell 'TUZO' in the watchtower in Glough's house. Return to King Narnode if you lost any.\",\"i\":[\"Twigs (T)\",\"Twigs (U)\",\"Twigs (Z)\",\"Twigs (O)\"]}]},{\"n\":\"Defeat the Black Demon\",\"st\":[{\"t\":\"Go down the trap door. Be prepared for the fight against a Black Demon (level 172).\"},{\"t\":\"Kill the black Demon. You can safespot from where Glough stands.\"},{\"t\":\"Talk to King Narnode deeper in the cave.\"},{\"t\":\"Search the roots under the Grand Tree until you find the Daconia stone. If you lose the rock, it will be in the same root again.\"},{\"t\":\"Give the Daconia stone to King Narnode under the Grand Tree.\",\"i\":[\"Daconia stone\"]}],\"i\":[\"Combat gear. Safespotting is possible.\",\"Food\",\"Prayer potions\"],\"c\":1,\"e\":[\"Black demon (level 172) (can be safespotted)\"]}]}"
        "The Great Brain Robbery" -> "{\"n\":\"The Great Brain Robbery\",\"items\":[\"Fishbowl helmet\",\"Diving apparatus\",\"10 Wooden cats, or 10 planks and 10 furs to make them\",\"Plank (8)\",\"Hammer\",\"Nails (200)\",\"Holy symbol\",\"Ring of Charos\",\"No pet following you or in your inventory\"],\"rec\":[\"Ectophial or Mos le'harmless teleport\",\"Monastery teleport\",\"Fenkenstrain's Castle teleport\",\"Watermelon seeds to plant on Harmony for Hard Morytania Diary (3)\",\"Combat gear for safespotting\",\"Food\",\"Prayer potion\"],\"enemies\":[\"Barrelchest (level 190, safespottable)\",\"4 Sorebones (level 57)\"],\"rewards\":[\"2 Quest points\",\"6,000 Prayer XP\",\"2,000 Crafting XP\",\"2,000 Construction XP\",\"Barrelchest Anchor\",\"5,000 Exp Reward Lamp (Any skill above 30)\",\"Prayer Book\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Talk to Brother Tranquility on Mos Le'Harmless.\",\"s\":[\"Yes.\",\"Yes, please.\"]},{\"t\":\"Pull the saradomin statue on Harmony, then enter it. Plant the watermelon seeds in the patch first if you brought them for the Hard Morytania Diary.\",\"i\":[\"Fishbowl helmet\",\"Diving apparatus\",\"Hammer\",\"Plank (4)\",\"Nails (100)\"]},{\"t\":\"Enter the water.\"},{\"t\":\"Repair the stairs to the east.\",\"i\":[\"Hammer\",\"Plank (4)\",\"Nails (100)\"]},{\"t\":\"Climb up the stairs to the east.\"},{\"t\":\"Climb up the ladder.\"},{\"t\":\"Peer through the nearby peephole.\"},{\"t\":\"Return to Brother Tranquility.\"}],\"i\":[\"Plank (4)\",\"Nails (100)\",\"Hammer\",\"Fishbowl helmet\",\"Diving apparatus\",\"Holy symbol\",\"No pet following you or in your inventory\"]},{\"n\":\"Protecting the windmill\",\"st\":[{\"t\":\"Search the south west bookcase in the Edgeville Monastery.\",\"s\":[\"Monastery\"],\"i\":[\"Holy symbol\"]},{\"t\":\"Read the prayer book.\",\"i\":[\"Prayer book\"]},{\"t\":\"Return to Harmony\"},{\"t\":\"Right-click recite the prayer book on Harmony.\",\"i\":[\"Prayer book\",\"Holy symbol\"]},{\"t\":\"Talk to Brother Tranquility again.\"}],\"i\":[\"Holy symbol\"]},{\"n\":\"Finding a Doctor\",\"st\":[{\"t\":\"Go up to the second floor of Fenkenstrain's Castle and talk to Dr. Fenkenstrain.\"},{\"t\":\"Talk to Rufus in Canifis' food store.\",\"s\":[\"Talk about the meat shipment\"],\"i\":[\"Ring of Charos\"]},{\"t\":\"Either buy 10 wooden cats from the G.E., or make them on a clockmaker's bench in your POH.\",\"s\":[\"Wooden cat\"],\"i\":[\"10 Wooden cats, or 10 planks and 10 furs to make them\"]},{\"t\":\"Return to Dr. Fenkenstrain and build the crate next to him.\",\"i\":[\"Ring of Charos\",\"Plank (4)\",\"Nails (100)\",\"Hammer\",\"Wooden cat (10)\",\"Crate part (6)\",\"Wolf whistle\"]},{\"t\":\"Add a bottom to the crate.\",\"i\":[\"Plank (4)\",\"Nails (100)\",\"Hammer\"]},{\"t\":\"Fill the crate next to Fenkenstrain with wooden cats.\",\"i\":[\"Wooden cat (10)\"]},{\"t\":\"Blow the wolf whistle.\",\"i\":[\"Wolf whistle\",\"Ring of Charos\"]},{\"t\":\"Return to Dr. Fenkenstrain and place the shipping order on the crate..\",\"i\":[\"Shipping order\"]}],\"i\":[\"Ring of Charos\",\"10 Wooden cats, or 10 planks and 10 furs to make them\",\"Plank (4)\",\"Nails (100)\",\"Hammer\"]},{\"n\":\"Saving the Monks\",\"st\":[{\"t\":\"Talk to Dr. Fenkenstrain in the Harmony Windmill basement.\"},{\"t\":\"Search the locker on the ship on the north of Harmony.\",\"i\":[\"Fishbowl helmet\",\"Diving apparatus\"]},{\"t\":\"Climb the ship's ladder.\"},{\"t\":\"Take a tinderbox.\",\"i\":[\"Tinderbox\"]},{\"t\":\"Take a keg.\",\"i\":[\"Keg\"]},{\"t\":\"Climb down the ship's ladder.\"},{\"t\":\"Use the keg on the church's door.\",\"i\":[\"Keg\"]},{\"t\":\"Use the fuse on the keg.\",\"i\":[\"Fuse\"]},{\"t\":\"Light the fuse.\",\"i\":[\"Tinderbox\"]},{\"t\":\"Kill sorebones in the church for items.\",\"i\":[\"Cranial clamp\",\"Brain tongs\"]},{\"t\":\"Return to Dr. Fenkenstrain in the Harmony Windmill basement.\",\"i\":[\"Hammer\",\"Cranial clamp\",\"Brain tongs\"]},{\"t\":\"Talk to Brother Tranquility on Harmony.\"}],\"i\":[\"Hammer\",\"Fishbowl helmet\",\"Diving apparatus\",\"Combat gear for safespotting\"],\"c\":1,\"e\":[\"4 Sorebones (level 57)\"]},{\"n\":\"Defeating a Barrelchest\",\"st\":[{\"t\":\"Enter the church, ready to fight Barrelchest. If after initially entering you leave then re-enter, the Barrelchest will get stuck and you can safespot it from the door.\",\"i\":[\"Fishbowl helmet\",\"Diving apparatus\",\"Combat gear for safespotting\"]},{\"t\":\"Confront Migor.\"},{\"t\":\"Defeat the barrelchest. You can safespot it from the door if you leave and re-enter the instance.\"},{\"t\":\"Talk to Brother Tranquility on Harmony to complete the quest.\"}],\"i\":[\"Fishbowl helmet\",\"Diving apparatus\",\"Combat gear for safespotting\"],\"c\":1,\"e\":[\"Barrelchest (level 190, safespottable)\"]}]}"
        "The Hand in the Sand" -> "{\"n\":\"The Hand in the Sand\",\"items\":[\"Beer or 2 gp\",\"Coins or more for boat travel (150)\",\"Vial (2)\",\"Redberries\",\"White berries\",\"Lantern lens\",\"Earth runes (5)\",\"Bucket of sand\"],\"rec\":[\"Teleports to Yanille, such as dueling ring or minigame teleport (3)\",\"Teleports to Brimhaven, or to near a boat to Brimhaven (2)\",\"Teleport to Port Sarim\"],\"enemies\":[],\"rewards\":[\"1 Quest point\",\"1,000 Thieving XP\",\"9,000 Crafting XP\",\"Daily sand from Bert in Yanille.\",\"Access to the Wizards Guild rune store.\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Talk to Bert in west Yanille.\",\"s\":[\"Eww a hand, in the sand! Why haven't you told the authorities?\",\"Sure, I'll give you a hand.\",\"Yes.\"]}],\"c\":0},{\"n\":\"Investigating\",\"st\":[{\"t\":\"Give the Guard Captain in the pub south of Bert a beer. You can buy one for 2gp from the pub.\",\"i\":[\"Beer\"]},{\"t\":\"Ring the bell outside the Wizards' Guild in Yanille. Talk to Zavistic Rarve when he appears.\",\"s\":[\"I have a rather sandy problem that I'd like to palm off on you.\"],\"i\":[\"Beer soaked hand\"]},{\"t\":\"Return to Bert in west Yanille.\"},{\"t\":\"Travel to Brimhaven, then enter Sandy's building south of the restaurant. Search Sandy's desk for Sandy's rota.\"},{\"t\":\"Pickpocket Sandy for some sand.\"}],\"i\":[\"Beer or 2 gp\"],\"c\":0},{\"n\":\"Making a truth serum\",\"st\":[{\"t\":\"Return to Bert in west Yanille with the rota and sand.\",\"i\":[\"Bert's rota\",\"Sandy's rota\"]},{\"t\":\"Ring the bell outside the Wizards' Guild in Yanille. Talk to Zavistic Rarve when he appears.\",\"s\":[\"I have a rather sandy problem that I'd like to palm off on you.\"],\"i\":[\"A magic scroll\"]},{\"t\":\"Talk to Zavistic Rarve again to get teleported to Port Sarim.\",\"s\":[\"Can you help me more?\",\"Yes, that would be great!\",\"I have a rather sandy problem that I'd like to palm off on you.\"],\"i\":[\"Vial\"]},{\"t\":\"Travel to Port Sarim, and talk to Betty in the magic shop.\",\"s\":[\"Talk to Betty about the Hand in the Sand.\"],\"i\":[\"Vial\"]},{\"t\":\"Use redberries on the bottled water.\",\"i\":[\"Bottled water\",\"Redberries\"]},{\"t\":\"Use whiteberries on the red bottled water\",\"i\":[\"Red dye\",\"White berries\"]},{\"t\":\"Use the pink dye on a lantern lens.\",\"i\":[\"Pink dye\",\"Lantern lens\"]},{\"t\":\"Talk to Betty with the pink lens.\",\"s\":[\"Talk to Betty about the Hand in the Sand.\"]},{\"t\":\"Stand in Betty's doorway and use the rose-tinted lens on the counter.\",\"i\":[\"Rose-tinted lens\"]},{\"t\":\"Talk to Betty again.\",\"s\":[\"Talk to Betty about the Hand in the Sand.\"],\"i\":[\"Truth serum\",\"Sand\"]}],\"i\":[\"Vial (2)\",\"Lantern lens\",\"Redberries\",\"White berries\"],\"c\":0},{\"n\":\"Uncover the truth\",\"st\":[{\"t\":\"Talk to Sandy in Brimhaven again with the truth serum. Select distractions until one works.\",\"i\":[\"Truth serum\"]},{\"t\":\"Use the truth serum on Sandy's coffee mug.\",\"i\":[\"Truth serum\"]},{\"t\":\"Activate the magical orb next to Sandy.\",\"i\":[\"Magical orb\"]},{\"t\":\"Ask Sandy all questions available with the Magical orb (a) in your inventory.\",\"s\":[\"Why is Bert's rota different from the original?\",\"Why doesn't Bert remember the change in his hours?\",\"What happened to the wizard?\"],\"i\":[\"Magical orb\"]}],\"i\":[\"Truth serum\",\"Magical orb\"],\"c\":0},{\"n\":\"Finishing off\",\"st\":[{\"t\":\"Return to the Wizards' Guild in Yanille and ring the bell outside. Talk to Zavistic Rarve when he appears.\",\"s\":[\"I have a rather sandy problem that I'd like to palm off on you.\"],\"i\":[\"Magical orb\",\"Earth runes (5)\",\"Bucket of sand\"]},{\"t\":\"Give Zavistic Rarve 5 earth runes and a bucket of sand.\",\"s\":[\"I have a rather sandy problem that I'd like to palm off on you.\"],\"i\":[\"Earth runes (5)\",\"Bucket of sand\"]},{\"t\":\"Travel to Entrana (bank all combat gear), and talk to Mazion at the sand pit.\"},{\"t\":\"Return to the Wizards' Guild in Yanille and ring the bell outside. Talk to Zavistic Rarve when he appears to finish the quest.\",\"s\":[\"I have a rather sandy problem that I'd like to palm off on you.\"],\"i\":[\"Wizard's head\"]}],\"i\":[\"Earth runes (5)\",\"Bucket of sand\"],\"tr\":[\"Teleport to Port Sarim\"],\"c\":0}]}"
        "The Heart of Darkness" -> "{\"n\":\"The Heart of Darkness\",\"items\":[\"Coins (30)\",\"Combat gear\",\"Food (10)\",\"Prayer potions (2)\"],\"rec\":[\"Quetzal feed (10)\",\"Limestone brick (3)\",\"Soft clay (4)\",\"Stamina potions\",\"Civitas illa fortis teleport\"],\"enemies\":[\"Several Emissary Brawlers (levels 74 and 86)\",\"Several Emissary Conjurers (level 71)\",\"Prince Itzla Arkan (level 167)\",\"Amoxliatl (level 263)\"],\"rewards\":[\"2 Quest points\",\"8,000 Mining XP\",\"8,000 Thieving XP\",\"8,000 Slayer XP\",\"8,000 Agility XP\",\"Access to Tapoyauik\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Talk to Prince Itzla Arkan at the Teomat. You can travel here using Renu the quetzal.\",\"s\":[\"Yes.\"]},{\"t\":\"Travel on Renu to the Quetzacalli Gorge.\"},{\"t\":\"Talk to the Bartender in the pub in the Gorge.\",\"s\":[\"I'd like to rent the basement room.\",\"I'll take it.\"],\"i\":[\"Coins (30)\"]},{\"t\":\"Rest in the bed in the south-eastern room of the pub.\"},{\"t\":\"Talk to Prince Itzla Arkan in the bedroom.\"},{\"t\":\"Talk to the shopkeeper east of the pub.\",\"s\":[\"I hear you can offer help to those in need.\"]},{\"t\":\"Return to Prince Itzla Arkan in the bedroom.\"}],\"i\":[\"Coins (30)\"],\"c\":1,\"e\":[\"Prince Itzla Arkan (level 167)\"]},{\"n\":\"The Tower\",\"st\":[{\"t\":\"Travel past the proudspire to the east to the Tower of Ascension. Talk to the prince there.\"},{\"t\":\"Before going to the tower, build the landing site in the north of the salvager overlook.\",\"i\":[\"Quetzal feed (10)\",\"Limestone brick (3)\",\"Soft clay (4)\"]},{\"t\":\"Talk to the prince at the Tower of Ascension to the south-east of the salvager overlook.\"},{\"t\":\"Talk to Felius outside the tower.\"},{\"t\":\"Talk to Caritta outside the tower.\"},{\"t\":\"Talk to Sergius outside the tower.\"},{\"t\":\"Talk to Nova outside the tower.\"},{\"t\":\"Talk to the prince at the Tower of Ascension to the south-east of the salvager overlook again.\",\"s\":[\"Could you remind me what Ximoua is?\"]},{\"t\":\"Talk to Forebearer Janus inside the tower.\"},{\"t\":\"Climb up the staircase in the tower to the first challenge.\"}],\"i\":[\"Combat gear\",\"Food (10)\"],\"tr\":[\"Quetzal feed (10)\"],\"r\":[\"Stamina potions\",\"Limestone brick (3)\",\"Soft clay (4)\"],\"c\":1},{\"n\":\"First Trial\",\"st\":[{\"t\":\"Pickpocket one of the emissary ascended.\"},{\"t\":\"Use the key to open the gate in the south-east corner of the room.\",\"i\":[\"Tower key\"]},{\"t\":\"Search the south-east chest for a book and some paper.\"}]},{\"n\":\"Second Trial\",\"st\":[{\"t\":\"Talk to Forebearer Janus, ready to fight.\",\"s\":[\"Yes! I'm ready.\"]},{\"t\":\"Defeat the waves of enemies. Use Protect from Melee. You can heal yourself and the prince using bandages from the chests in the area.\"},{\"t\":\"Talk to Forebearer Janus again to progress to the third trial.\",\"s\":[\"Yes.\",\"Proceed to the next trial.\"]}],\"i\":[\"Combat gear\"],\"c\":1},{\"n\":\"Third Trial\",\"st\":[{\"t\":\"Talk to the prince in the room.\"},{\"t\":\"Talk to Tenoch.\"},{\"t\":\"Talk to Silia.\"},{\"t\":\"Talk to Adrius.\"},{\"t\":\"Talk to Eleuia.\"},{\"t\":\"Talk to Janus to go to the final trial, ready for a fight.\",\"s\":[\"Yes.\"]}]},{\"n\":\"Final Trial\",\"st\":[{\"t\":\"Defeat the prince. Use Protect from Melee.\"},{\"t\":\"Talk to Janus to wrap up the final trial.\"}]},{\"n\":\"Cult\",\"st\":[{\"t\":\"Talk to Janus at the bottom of the tower.\"},{\"t\":\"Search the chest in the south of the tower for some emissary robes.\"},{\"t\":\"Talk to the prince to have him follow you.\"},{\"t\":\"Enter the temple to the east of the tower for a cutscene.\",\"i\":[\"Emissary robes\"]},{\"t\":\"Talk to the prince in the temple.\",\"i\":[\"Emissary robes\"]},{\"t\":\"Talk to Forebearer Fides in the temple.\",\"i\":[\"Emissary robes\"]}]},{\"n\":\"The Old Ones\",\"st\":[{\"t\":\"Go down the stairs south-east of the temple. Be equipped for a fight.\"},{\"t\":\"Take a pickaxe from the nearby barrel.\"},{\"t\":\"Mine the nearby rocks.\",\"i\":[\"Any pickaxe\"]},{\"t\":\"Pull the lever in the south-east of the area. Make sure to avoid the wall spikes.\"},{\"t\":\"Climb down the ledge east of the lever.\"},{\"t\":\"Climb across the ice ledge to the north. Avoid the floor spike traps on the way.\"},{\"t\":\"Pull the lever in the north-east room. Avoid the floor traps.\"},{\"t\":\"Jump over the frozen platforms to the north-west, and climb down the ledge there.\"},{\"t\":\"Pull the third lever in the north-west room.\"},{\"t\":\"Pull the final lever in the south-west, near the gate.\"},{\"t\":\"Pull the chain to unlock a shortcut.\"},{\"t\":\"Climb down the shortcut chain to the west of the entrance.\"},{\"t\":\"Inspect the air markings in the north-east of the area.\"},{\"t\":\"Inspect the earth markings in the south-east of the area.\"},{\"t\":\"Search the urn with an air symbol on it near to the earth markings in the south-east of the area.\"},{\"t\":\"Search the urn with an earth symbol on it near to the earth markings in the south-east of the area.\"},{\"t\":\"Inspect the water markings in the south-west of the area.\"},{\"t\":\"Inspect the fire markings in the north-west of the area.\"},{\"t\":\"Search the urn with an fire symbol on it near to the water markings in the south-west of the area.\"},{\"t\":\"Search the urn with an water symbol on it near to the water markings in the south-west of the area.\"},{\"t\":\"Fix the broken water statue in the west of the area.\",\"i\":[\"Water icon\"]},{\"t\":\"Fix the broken fire statue in the west of the area.\",\"i\":[\"Fire icon\"]},{\"t\":\"Fix the broken earth statue in the west of the area.\",\"i\":[\"Earth icon\"]},{\"t\":\"Fix the broken air statue in the west of the area.\",\"i\":[\"Air icon\"]},{\"t\":\"Enter the door to the west, ready for the boss.\"},{\"t\":\"Defeat Amoxliatl. Use Protect from Magic.\"},{\"t\":\"Talk to Servius, Teokan of Ralos in the palace in Civitas illa Fortis to complete the quest.\"}],\"i\":[\"Combat gear\"],\"tr\":[\"Civitas illa fortis teleport\"],\"r\":[\"Food (10)\",\"Prayer potions\"],\"c\":1,\"e\":[\"Amoxliatl (level 263)\"]}]}"
        "The Ides of Milk" -> "{\"n\":\"The Ides of Milk\",\"items\":[],\"rec\":[\"Combat gear\",\"Food\"],\"enemies\":[\"Bull (level 30)\"],\"rewards\":[\"1 Quest point\",\"Access to the cow boss\",\"Cow bell amulet and magic lamp (1,000 XP combat/Prayer) from Gillie Groats\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Speak to Cassius by the pond north-west of Lumbridge to start the quest.\",\"s\":[\"Yes.\"]}]},{\"n\":\"Investigation\",\"st\":[{\"t\":\"Speak to Gillie Groats at the cow field east of Lumbridge.\",\"s\":[\"Can you share what makes your cows so productive?\"]},{\"t\":\"Speak to Seth Groats at his farmhouse east of the River Lum.\"},{\"t\":\"Search the shelves in Seth's farmhouse for 'The groats principles'.\"}]},{\"n\":\"Milk tasting\",\"st\":[{\"t\":\"Return to Cassius with the book.\",\"i\":[\"The groats principles\"]},{\"t\":\"Drink the milk sample near Cassius.\",\"i\":[\"Milk sample\"]},{\"t\":\"Talk to Cassius after drinking the milk sample.\"}]},{\"n\":\"The Duke's opinion\",\"st\":[{\"t\":\"Speak to Duke Horacio on the first floor of Lumbridge Castle.\",\"i\":[\"Milk sample\"]},{\"t\":\"Speak to Gillie Groats at the cow field.\"},{\"t\":\"Drink the milk sample near Gillie.\",\"i\":[\"Milk sample\"]},{\"t\":\"Talk to Gillie Groats after drinking the milk sample.\"}]},{\"n\":\"The bull fight\",\"st\":[{\"t\":\"Open the bull pen gate in the north-east corner of the cow field to fight the Bull (level 30).\",\"s\":[\"Yes.\"],\"i\":[\"Combat gear\",\"Food\"]},{\"t\":\"Speak to Gillie Groats after defeating the Bull.\"}],\"i\":[\"Combat gear\",\"Food\"],\"c\":1,\"e\":[\"Bull (level 30)\"]},{\"n\":\"Finishing up\",\"st\":[{\"t\":\"Return to Cassius to complete the quest. You can then speak to Gillie Groats for a cow bell amulet and magic lamp (1,000 XP combat/Prayer).\"}]}]}"
        "The Knight's Sword" -> "{\"n\":\"The Knight's Sword\",\"items\":[\"Redberry pie\",\"Iron bar (2)\",\"Any pickaxe\"],\"rec\":[\"A teleport to Varrock\",\"Teleports to Falador (3)\",\"A teleport near Mudskipper Point, such as POH teleport or Fairy Ring to AIQ (2)\"],\"enemies\":[\"Able to survive attacks from Ice Warriors (level 57) and Ice Giants (level 53)\"],\"rewards\":[\"1 Quest point\",\"12,725 Smithing XP\",\"The ability to smelt Blurite ore.\",\"The ability to smith Blurite bars.\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Talk to the Squire in Falador Castle's courtyard.\",\"s\":[\"And how is life as a squire?\",\"I can make a new sword if you like...\",\"So would these dwarves make another one?\",\"Yes.\"]},{\"t\":\"Talk to Reldo in Varrock Castle's library.\",\"s\":[\"What do you know about the Imcando dwarves?\"]}]},{\"n\":\"Finding an Imcando\",\"st\":[{\"t\":\"Talk to Thurgo south of Port Sarim and give him a redberry pie.\",\"s\":[\"Would you like a redberry pie?\"],\"i\":[\"Redberry pie\"]},{\"t\":\"Talk to Thurgo again.\",\"s\":[\"Can you make a special sword for me?\"]}],\"i\":[\"Redberry pie\"]},{\"n\":\"Find the portrait\",\"st\":[{\"t\":\"Talk to the Squire in Falador Castle's courtyard.\"},{\"t\":\"Climb up the east ladder in Falador Castle.\"},{\"t\":\"Go up the staircase west of the ladder on the 1st floor.\"},{\"t\":\"Search the cupboard in the room south of the staircase. You'll need Sir Vyvin to be in the other room.\"},{\"t\":\"Bring Thurgo the portrait.\",\"s\":[\"About that sword...\"],\"i\":[\"Any pickaxe\",\"Iron bar (2)\",\"Portrait\"]}]},{\"n\":\"Making the sword\",\"st\":[{\"t\":\"Go down the ladder south of Port Sarim. Be prepared for ice giants and ice warriors to attack you.\",\"i\":[\"Any pickaxe\",\"Iron bar (2)\"]},{\"t\":\"Mine a blurite ore in the eastern cavern.\",\"i\":[\"Any pickaxe\"]},{\"t\":\"Return to Thurgo with a blurite ore and two iron bars.\",\"s\":[\"Can you make that replacement sword now?\"],\"i\":[\"Blurite ore\",\"Iron bar (2)\"]}],\"i\":[\"Any pickaxe\",\"Iron bar (2)\"]},{\"n\":\"Return the sword\",\"st\":[{\"t\":\"Return to the Squire with the sword to finish the quest.\",\"i\":[\"Blurite sword\"]}]}]}"
        "The Lost Tribe" -> "{\"n\":\"The Lost Tribe\",\"items\":[\"Any pickaxe\",\"A light source\"],\"rec\":[\"Lumbridge teleports (3)\",\"Varrock teleport\",\"Falador teleport\"],\"enemies\":[],\"rewards\":[\"1 Quest point\",\"3,000 Mining XP\",\"Ring of Life\",\"Access to the Dorgesh-Kaan mine.\",\"Access to Nardok's Bone Weapon Store\",\"2 new goblin emotes.\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Talk to Sigmund in Lumbridge Castle.\",\"s\":[\"Can you show me the way out of the mines?\"]},{\"t\":\"Talk to the Cook, Hans, Father Aereck, and Bob in Lumbridge until one tells you about seeing a goblin.\"},{\"t\":\"Talk to Duke Horacio in Lumbridge Castle.\",\"s\":[\"Hans says he saw something in the cellar\",\"Bob says he saw something in the cellar\",\"Father Aereck says he saw something in the cellar\",\"The cook says he saw something in the cellar\",\"Can you show me the way out of the mines?\"]}],\"c\":0},{\"n\":\"Investigating\",\"st\":[{\"t\":\"Use a pickaxe on the rubble in the Lumbridge Castle basement.\"},{\"t\":\"Enter the hole in Lumbridge Castle's basement.\"},{\"t\":\"Pick up the brooch on the floor.\",\"i\":[\"Brooch\"]},{\"t\":\"Show the brooch to Duke Horacio in Lumbridge Castle.\",\"s\":[\"Can you show me the way out of the mines?\"]}],\"i\":[\"Any pickaxe\",\"A light source\"],\"c\":0},{\"n\":\"Learning about goblins\",\"st\":[{\"t\":\"Search the north west bookcase in the Varrock Castle Library.\"},{\"t\":\"Read the entire goblin symbol book.\",\"i\":[\"Goblin symbol book\"]},{\"t\":\"Talk to the Goblin Generals in the Goblin Village.\",\"s\":[\"Have you ever heard of the Dorgeshuun?\",\"It doesn't really matter\",\"Well either way they refused to fight\",\"Well I found a brooch underground...\",\"Well why not show me both greetings?\"]}],\"c\":0},{\"n\":\"Making contact\",\"st\":[{\"t\":\"Travel through the tunnels under Lumbridge until you reach Mistag.\"},{\"t\":\"Perform the Goblin Bow emote next to Mistag and talk to him.\",\"i\":[\"A light source\"]},{\"t\":\"Talk to Duke Horacio in Lumbridge Castle. You can fast-travel with Mistag back to Lumbridge.\",\"s\":[\"I've made contact with the cave goblins...\",\"Can you show me the way out of the mines?\"]}],\"i\":[\"A light source\"],\"c\":0},{\"n\":\"Resolving tensions\",\"st\":[{\"t\":\"Pickpocket Sigmund for a key.\",\"s\":[\"Can you show me the way out of the mines?\"]},{\"t\":\"Open the chest in the room next to the Duke's room.\",\"s\":[\"Can you show me the way out of the mines?\"]},{\"t\":\"Enter the H.A.M lair west of Lumbridge and search a crate in its entrance for the silverware.\"},{\"t\":\"Take the silverware to Duke Horacio.\",\"s\":[\"I found the missing silverware in the HAM cave!\",\"Can you show me the way out of the mines?\"]},{\"t\":\"Travel through the tunnels until you reach Mistag, and give him the treaty.\",\"s\":[\"What was I doing again?\"]}],\"i\":[\"A light source\"],\"c\":0}]}"
        "The Queen of Thieves" -> "{\"n\":\"The Queen of Thieves\",\"items\":[\"Stew\"],\"rec\":[],\"enemies\":[],\"rewards\":[\"1 Quest point\",\"2,000 Thieving XP\",\"2000 x Coins\",\"A page for Kharedst's Memoirs\",\"Access to The Warrens.\"],\"sec\":[{\"n\":\"Investigation\",\"st\":[{\"t\":\"Speak to Tomas Lawry in Port Piscarilius.\",\"s\":[\"I'm looking for a quest.\",\"What are you investigating?\",\"Yes.\"]},{\"t\":\"Speak to the poor looking woman.\"},{\"t\":\"Speak to Robert O'Reilly, and give him the bowl of stew.\",\"s\":[\"Okay.\"],\"i\":[\"Stew\"]}],\"i\":[\"Stew\"],\"c\":0},{\"n\":\"Gaining Trust\",\"st\":[{\"t\":\"Enter the Warrens.\"},{\"t\":\"Speak to Devan Rutter.\",\"s\":[\"Nope, sounds good to me.\"]},{\"t\":\"Exit the Warrens.\"},{\"t\":\"Murder Conrad King.\"},{\"t\":\"Tell Devan Rutter about the murder.\"}],\"c\":0},{\"n\":\"Exposing Hughes\",\"st\":[{\"t\":\"Enter the Warrens.\"},{\"t\":\"Talk to the Queen of Thieves.\"},{\"t\":\"Exit the Warrens.\"},{\"t\":\"Go up the stairs in Councillor Hughes' home in Kingstown.\"},{\"t\":\"Pick the locked chest.\"},{\"t\":\"Go downstairs.\"},{\"t\":\"Speak to Tomas Lawry in Port Piscarilius.\",\"s\":[\"Let's talk about my quest.\"],\"i\":[\"Letter\"]},{\"t\":\"Talk to Lady Shauna Piscarilius.\"}],\"c\":0}]}"
        "The Red Reef" -> "{\"n\":\"The Red Reef\",\"items\":[\"Ranged/Mage combat gear to skip boat combat, or a boat with cannons to deal with pirates. An upgraded keel helps with survival. (Mithril is more than enough)\",\"Combat gear\"],\"rec\":[\"Food\",\"Prayer potions\",\"Boat repair kits (5)\"],\"enemies\":[\"2 pirate ships, or the crew on the ship with ranged combat gear\",\"6 pirates (lvl 52)\",\"Black Eye Bethel (lvl 191)\",\"Giant lobster (lvl 112)\"],\"rewards\":[\"2 Quest points\",\"15,000 Sailing XP\",\"5,000 Smithing XP\",\"Bosun's Workbench Schematic\",\"Access to the Great Conch sacred grove\"],\"sec\":[{\"n\":\"Finding Floopa\",\"st\":[{\"t\":\"Talk to Elder Raley at his home in The Great Conch to start the quest.\",\"s\":[\"Yes.\"]},{\"t\":\"Talk to Finn, south-east of Elder Raley's house, about Floopa's whereabouts.\"},{\"t\":\"Head to The Sacred Grove and talk to Elder Katt.\"},{\"t\":\"Enter The Sacred Grove and talk to Floopa.\"}]},{\"n\":\"Infiltrating the Red Reef\",\"st\":[{\"t\":\"Sail to Red Rock, north-west of The Great Conch.\"},{\"t\":\"Talk to the receptionist on Red Rock.\"},{\"t\":\"Familiarize yourself with the history of the Red Reef Trading Company by inspecting the display cases around the building.\"},{\"t\":\"Talk to Theodore Paxton.\"}]},{\"n\":\"Dealing with Black Eye Bethel\",\"st\":[{\"t\":\"Get ready for boat combat, then sail south towards Last Light and deal with Black Eye Bethel. Protect from Missiles to avoid most damage. Repair your ship. Combat is over when all boats are sunk or all pirates are killed.\",\"i\":[\"Ranged/Mage combat gear to skip boat combat, or a boat with cannons to deal with pirates. An upgraded keel helps with survival. (Mithril is more than enough)\",\"Combat gear to fight Black Eye Bethel\"]},{\"t\":\"Disembark at Last Light.\"},{\"t\":\"Kill all six pirates at Last Light.\"},{\"t\":\"Return to Theodore Paxton on Red Rock with the good news.\"}],\"i\":[\"Ranged/Mage combat gear to skip boat combat, or a boat with cannons to deal with pirates. An upgraded keel helps with survival. (Mithril is more than enough)\",\"Combat gear to fight Black Eye Bethel\"],\"r\":[\"Food\",\"Prayer potions\",\"Boat repair kits (5)\"],\"c\":1,\"e\":[\"6 pirates (lvl 52)\",\"Black Eye Bethel (lvl 191)\"]},{\"n\":\"Helping the Zenith\",\"st\":[{\"t\":\"Sail to and board the Zenith, east of Red Rock. If you don't see the Zenith there, try hopping to a different world.\",\"i\":[\"Any combat gear to fight a giant lobster\"]},{\"t\":\"Talk to Spencer Brentwood aboard the Zenith.\",\"i\":[\"Any combat gear to fight a giant lobster\"]},{\"t\":\"Talk to Spencer Brentwood again with the deep sea diving gear equipped to dive down to the bottom of the sea.\",\"s\":[\"Let's go.\"],\"i\":[\"Any combat gear to fight a giant lobster\",\"Deep sea helmet\",\"Deep sea apparatus\"]},{\"t\":\"Listen to Spencer Brentwood's instructions.\"},{\"t\":\"Head north and repair the Coral dredger, ready to fight a Giant lobster.\",\"i\":[\"Any combat gear to fight a giant lobster\"]},{\"t\":\"Kill the Giant lobster. Avoid the blue particles on the floor.\"},{\"t\":\"Repair the Coral dredger.\"},{\"t\":\"Talk to Spencer Brentwood near the eastern coral dredger.\"},{\"t\":\"Talk to Spencer Brentwood aboard the Zenith after repairing the coral dredgers.\"}],\"i\":[\"Any combat gear to fight a giant lobster\"],\"r\":[\"Food\"],\"c\":1,\"e\":[\"Giant lobster (lvl 112)\"]},{\"n\":\"Return to Floopa\",\"st\":[{\"t\":\"Return to Floopa at Elder Raley's house at The Great Conch.\"}]}]}"
        "The Restless Ghost" -> "{\"n\":\"The Restless Ghost\",\"items\":[],\"rec\":[\"Lumbridge teleports (2)\",\"Necklace of passage\"],\"enemies\":[\"A skeleton (level 13) you can run away from\"],\"rewards\":[\"1 Quest point\",\"1,125 Prayer XP\",\"Ghostspeak amulet\"],\"sec\":[{\"n\":\"Talk to Father Aereck\",\"st\":[{\"t\":\"Talk to Father Aereck in the Lumbridge Church.\",\"s\":[\"I'm looking for a quest!\",\"Yes.\"]}]},{\"n\":\"Get a ghostspeak amulet\",\"st\":[{\"t\":\"Talk to Father Urhney, west of the Lumbridge Swamp.\",\"s\":[\"Father Aereck sent me to talk to you.\",\"He's got a ghost haunting his graveyard.\"]}]},{\"n\":\"Talk to the ghost\",\"st\":[{\"t\":\"Open the coffin in the Lumbridge Graveyard to spawn the ghost.\",\"i\":[\"Ghostspeak amulet\"]},{\"t\":\"Search the coffin in the Lumbridge Graveyard to spawn the ghost.\",\"i\":[\"Ghostspeak amulet\"]},{\"t\":\"Speak to the Ghost that appears whilst wearing your Ghostspeak Amulet.\",\"s\":[\"Yep, now tell me what the problem is.\",\"Yep, clever aren't I?.\",\"Yes, ok. Do you know WHY you're a ghost?\",\"Yes, ok. Do you know why you're a ghost?\"],\"i\":[\"Ghostspeak amulet\"]}]},{\"n\":\"Return the ghost's skull\",\"st\":[{\"t\":\"Enter the Wizards' Tower basement, south of Draynor village.\"},{\"t\":\"Search the Altar. A skeleton (level 13) will appear and attack you, but you can just run away.\"},{\"t\":\"Leave the basement.\",\"i\":[\"Ghost's skull\"]},{\"t\":\"Open the ghost's coffin in the Lumbridge graveyard.\",\"i\":[\"Ghost's skull\"]},{\"t\":\"Search the coffin to put the skull back and finish the quest.\",\"i\":[\"Ghost's skull\"]}],\"c\":1,\"e\":[\"A skeleton (level 13) you can run away from\"]}]}"
        "The Ribbiting Tale of a Lily Pad Labour Dispute" -> "{\"n\":\"The Ribbiting Tale of a Lily Pad Labour Dispute\",\"items\":[\"Any axe\"],\"rec\":[],\"enemies\":[\"Cuthbert, Lord of Dread (level 1)\"],\"rewards\":[\"1 Quest point\",\"2,000 Woodcutting XP\",\"Access to a new Hardwood Farming Patch\"],\"sec\":[{\"n\":\"Toad-aly mad\",\"st\":[{\"t\":\"Talk to Marcellus near the Locus Oasis south of Civitas illa Fortis. AJP Fairy ring is fastest.\",\"s\":[\"Yes.\"]},{\"t\":\"Talk to the blue frogs in the north-east of the oasis.\"},{\"t\":\"Return to Marcellus.\"},{\"t\":\"Return to the blue frogs Sue and Gary in the north-east of the oasis.\"}],\"i\":[\"Any axe\"]},{\"n\":\"Rig-it\",\"st\":[{\"t\":\"Talk to the yellow frogs Jane and Dave to the south of Gary.\"},{\"t\":\"Chop down the orange tree next to the yellow frog.\",\"i\":[\"Any axe\"]},{\"t\":\"Sabotage the lily pad near to the yellow frogs.\"},{\"t\":\"Return to Sue and Gary in the north-east of the oasis.\"}]},{\"n\":\"Hopping to conclusions\",\"st\":[{\"t\":\"Return to Marcellus.\"},{\"t\":\"Go talk to Sue and Gary to discuss framing the flies.\"},{\"t\":\"Work out how to open the chest in Marcellus' house.\"},{\"t\":\"Plant the plushy in the capybara dung east of Marcellus, south of the orange tree.\"},{\"t\":\"Defeat Cuthbert, Lord of Dread.\"},{\"t\":\"Tell Marcellus about the plushy.\"},{\"t\":\"Talk to Sue and Gary to resolve the dispute!\"}],\"c\":1,\"e\":[\"Cuthbert, Lord of Dread (level 1)\"]}]}"
        "The Slug Menace" -> "{\"n\":\"The Slug Menace\",\"items\":[\"Commorb (can get another from Sir Tiffy)\",\"Swamp paste\",\"Rune/pure essence, 15 to be safe (5)\",\"Chisel\",\"Access to the Air, Water, Earth, Fire, and Mind runecrafting altars\"],\"rec\":[\"Teleport near Air Altar\",\"Teleport near Earth Altar\",\"Teleport near Fire Altar\",\"Teleport near Water Altar\",\"Teleport near Mind Altar\",\"Ardougne teleports (3)\",\"Necklace of Passage\"],\"enemies\":[\"Slug Prince (level 62) (can only be hurt by melee)\"],\"rewards\":[\"1 Quest point\",\"3,500 Runecraft XP\",\"3,500 Crafting XP\",\"3,500 Thieving XP\",\"Ability to purchase and equip Proselyte equipment.\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Talk to Sir Tiffy Cashien in Falador Park.\",\"s\":[\"Do you have any jobs for me yet?\"],\"i\":[\"Commorb (can get another from Sir Tiffy)\"]}],\"i\":[\"Commorb (can get another from Sir Tiffy)\"]},{\"n\":\"Investigating\",\"st\":[{\"t\":\"Talk to Col. O'Niall on the pier in Witchaven, east of Ardougne.\",\"s\":[\"Who are the important people in Witchaven?\",\"Nothing at the moment thanks.\"]},{\"t\":\"Talk to Brother Maledict in the church.\",\"s\":[\"That's enough for now.\"]},{\"t\":\"Talk to Mayor Hobb in north west Witchaven.\",\"s\":[\"I'm just looking around.\",\"Nothing at the moment thanks.\"]},{\"t\":\"Talk to Holgart north of Witchaven.\",\"s\":[\"Nothing at the moment thanks.\"]},{\"t\":\"Return to Col. O'Niall on the pier in Witchaven.\"},{\"t\":\"Enter the old ruin entrance west of Witchaven.\",\"s\":[\"That's enough for now.\"]},{\"t\":\"Push the wall just east of where you come down.\"},{\"t\":\"Follow the path until you reach an imposing door, and try opening it. After, try scanning with the commorb v2.\",\"i\":[\"Commorb v2\"]},{\"t\":\"Try scanning with the commorb.\",\"i\":[\"Commorb (can get another from Sir Tiffy)\"]},{\"t\":\"Pick up the dead sea slug next to the imposing door.\",\"i\":[\"Dead sea slug\"]}],\"i\":[\"Commorb v2\"]},{\"n\":\"Uncovering the truth\",\"st\":[{\"t\":\"Talk to Jorral north of West Ardougne.\",\"s\":[\"Translations\"],\"i\":[\"Door transcription\",\"Necklace of Passage\"]},{\"t\":\"Return to Col. O'Niall on the pier in Witchaven.\"},{\"t\":\"Talk to Brother Maledict in the church.\"},{\"t\":\"Search the study desk in the Mayor's house for a page.\"},{\"t\":\"Talk to Ezekial Lovecraft in the fishing shop in east Witchaven for a page.\"},{\"t\":\"Talk to Col. O'Niall on the pier in Witchaven for a page.\"},{\"t\":\"Use some swamp paste on one of the page fragments.\",\"i\":[\"Swamp paste\",\"Fragment 1\",\"Fragment 2\",\"Fragment 3\"]},{\"t\":\"Talk to Jeb north of Witchaven to travel to the Fishing Platform.\",\"i\":[\"Dead sea slug\"]},{\"t\":\"Talk to Bailey on the Fishing Platform.\",\"i\":[\"Dead sea slug\"]},{\"t\":\"Use the slug glue on one of the fragments.\",\"i\":[\"Sea slug glue\",\"Fragment 1\"]},{\"t\":\"Combine the fragments.\"},{\"t\":\"Right-click each page to turn rune/pure essence into empty runes. Take each empty rune and use it on its respective Runecrafting Altar. Bring extra essence (~10 extra) as it is possible to accidentally destroy the essence upon creation.\",\"i\":[\"Page 1\",\"Page 2\",\"Page 3\",\"Rune or Pure Essence\",\"Chisel\"]}],\"i\":[\"Door transcription\",\"Commorb v2\",\"Dead sea slug\",\"Swamp paste\",\"Chisel\",\"Rune/pure essence, 15 to be safe (5)\",\"Access to the Air, Water, Earth, Fire, and Mind runecrafting altars\"]},{\"n\":\"Facing the prince\",\"st\":[{\"t\":\"Prepare to fight the Slug Prince (level 62). Only melee can hurt it. Then, enter the old ruin entrance west of Witchaven.\",\"i\":[\"Melee weapon to fight the Slug Prince\",\"Air rune\",\"Water rune\",\"Earth rune\",\"Fire rune\",\"Mind rune\"]},{\"t\":\"Enter the wall just east of where you come down.\"},{\"t\":\"Use the runes on the imposing doors at the end of the path.\",\"i\":[\"Air rune\",\"Water rune\",\"Earth rune\",\"Fire rune\",\"Mind rune\"]},{