        "The Tourist Trap" -> "{\"n\":\"The Tourist Trap\",\"items\":[\"Desert shirt\",\"Desert robe\",\"Desert boots\",\"Bronze bars (3)\",\"Hammer\",\"Feather (50)\"],\"rec\":[\"Combat gear\",\"Waterskins\",\"Knife\",\"Any pickaxe\",\"Coins (100)\"],\"enemies\":[\"Mercenary Captain (level 47)\"],\"rewards\":[\"2 Quest points\",\"2 x 4,650 Exp. Lamps (Agility, Fletching, Smithing or Thieving)\",\"Ability to smith darts.\"],\"sec\":[{\"n\":\"Investigating the trap\",\"st\":[{\"t\":\"Talk to Irena south of the Shantay Pass.\",\"s\":[\"What's the matter?\",\"Is there a reward if I get her back?\",\"I'll look for your daughter.\",\"Okay Irena, calm down. I'll get your daughter back for you.\",\"Yes, I'll go on this quest!\"]},{\"t\":\"Talk to the Mercenary Captain outside the Desert Mining Camp. When he attacks you, kill him for a key.\",\"s\":[\"Wow! A real captain!\",\"I'd love to work for a tough guy like you!\",\"Can't I do something for a strong Captain like you?\",\"Sorry Sir, I don't think I can do that.\",\"It's a funny captain who can't fight his own battles!\"],\"i\":[\"Combat gear\"]},{\"t\":\"UNEQUIP ALL COMBAT GEAR and enter the camp.\",\"i\":[\"Desert shirt\",\"Desert robe\",\"Desert boots\",\"Metal key\"]},{\"t\":\"Talk to the Male Slave to the east to trade your desert robes for his slave robes.\",\"s\":[\"I've just arrived.\",\"Okay, you caught me out.\",\"Oh yes, that sounds interesting.\",\"What's that then?\",\"I can try to undo them for you.\",\"It's funny you should say that...\",\"Yeah, okay, let's give it a go.\",\"Yes, I'll trade.\"],\"i\":[\"Desert shirt\",\"Desert robe\",\"Desert boots\"]},{\"t\":\"Equip the slave clothes, and enter the mine door in the north east of the camp.\",\"i\":[\"Slave shirt\",\"Slave robe\",\"Slave boots\"]},{\"t\":\"Follow the cave around and talk to a guard guarding the deeper cave.\",\"s\":[\"I'd like to mine in a different area.\",\"Yes sir, you're quite right sir.\",\"Yes sir, we understand each other perfectly.\"],\"i\":[\"Slave shirt\",\"Slave robe\",\"Slave boots\"]}],\"i\":[\"Desert shirt\",\"Desert robe\",\"Desert boots\",\"Bronze bars (3)\",\"Hammer\",\"Feather (50)\"],\"c\":1,\"e\":[\"Mercenary Captain (level 47)\"]},{\"n\":\"Helping out\",\"st\":[{\"t\":\"Talk to Al Shabim in the Bedabin Camp.\",\"s\":[\"I am looking for a pineapple.\",\"Yes, I'm interested.\"]},{\"t\":\"UNEQUIP ALL COMBAT GEAR and enter the camp.\",\"i\":[\"Metal key\",\"Bedabin key\"]},{\"t\":\"Climb up the ladder in the building in the camp.\",\"i\":[\"Bedabin key\"]},{\"t\":\"Search the south west bookcase.\"},{\"t\":\"Talk to Captain Siad about sailing to distract him.\",\"s\":[\"I wanted to have a chat?\",\"You seem to have a lot of books!\",\"So, you're interested in sailing?\",\"I could tell by the cut of your jib.\"],\"i\":[\"Bedabin key\"]},{\"t\":\"Search the chest.\",\"s\":[\"I wanted to have a chat?\",\"You seem to have a lot of books!\",\"So, you're interested in sailing?\",\"I could tell by the cut of your jib.\"]},{\"t\":\"Return to Al Shabim in the Bedabin Camp with the plans.\",\"s\":[\"Yes, I'm very interested.\",\"Yes, I'm kind of curious.\"],\"i\":[\"Technical plans\",\"Bronze bar\",\"Hammer\",\"Feather (50)\"]},{\"t\":\"Enter the north tent and attempt to make a prototype dart tip on the anvil. Bring all 3 bars with you for this.\",\"s\":[\"Yes. I'd like to try.\"],\"i\":[\"Technical plans\",\"Bronze bar\",\"Hammer\",\"Feather (50)\"]},{\"t\":\"Add 10 feathers to the prototype dart tip.\",\"i\":[\"Prototype dart tip\",\"Feather (50)\"]},{\"t\":\"Bring the prototype dart to Al Shabim.\",\"i\":[\"Prototype dart\"]}],\"i\":[\"Bronze bars (3)\",\"Hammer\",\"Feather (50)\"]},{\"n\":\"Freeing Ana\",\"st\":[{\"t\":\"UNEQUIP ALL COMBAT GEAR and enter the camp.\",\"i\":[\"Metal key\",\"Tenti pineapple\",\"Slave shirt\",\"Slave robe\",\"Slave boots\"]},{\"t\":\"Equip the slave clothes, and enter the mine door in the north east of the camp.\",\"i\":[\"Slave shirt\",\"Slave robe\",\"Slave boots\",\"Tenti pineapple\"]},{\"t\":\"Follow the cave around and talk to a guard guarding the deeper cave.\",\"i\":[\"Slave shirt\",\"Slave robe\",\"Slave boots\",\"Tenti pineapple\"]},{\"t\":\"Enter the deeper mines.\"},{\"t\":\"Right-click search the barrel next to the mine cart for a barrel.\",\"s\":[\"Yeah, cool!\"]},{\"t\":\"Right-click search the mine cart to ride it to the next room.\",\"s\":[\"Yes, of course.\"],\"i\":[\"Barrel\"]},{\"t\":\"Follow the path west then north until you find Ana. Use the barrel on her.\",\"i\":[\"Barrel\"]},{\"t\":\"Use Ana on the mine cart you came in on.\",\"i\":[\"Ana in a barrel\"]},{\"t\":\"Return in the mine cart you came in on.\",\"s\":[\"Yes, of course.\"]},{\"t\":\"Right-click search the barrel next to the mine cart for Ana.\"},{\"t\":\"Right-click use the winch bucket to send Ana to the surface.\",\"s\":[\"Yes please.\",\"I said you were very gregarious!\"]},{\"t\":\"Return to the surface. If Ana was captured again, search the barrel next to the mine cart for her.\"},{\"t\":\"Right-click operate the winch in the south west of the camp.\"},{\"t\":\"Right-click search the barrel west of the winch. If it's empty, operate the winch again.\"},{\"t\":\"Use Ana on the cart in the middle of the camp.\",\"i\":[\"Ana in a barrel\"]},{\"t\":\"Talk to the Mine Cart Driver to escape. Once he's agreed to take you, right-click search the wooden cart to escape.\",\"s\":[\"Nice cart.\",\"One wagon wheel says to the other, 'I'll see you around'.\",\"'One good turn deserves another'\",\"Fired... no, shot perhaps!\",\"In for a penny in for a pound.\",\"Well, you see, it's like this...\",\"Prison riot in ten minutes, get your cart out of here!\",\"You can't leave me here, I'll get killed!\",\"Yes, I'll get on.\"]},{\"t\":\"Bring Ana to Irena south of the Shantay Pass.\",\"i\":[\"Ana in a barrel\"]},{\"t\":\"Talk to Ana outside the Shantay Pass.\"},{\"t\":\"Talk to Irena south of the Shantay Pass to finish the quest!\"}],\"i\":[\"Slave shirt\",\"Slave robe\",\"Slave boots\"]}]}"
        "Throne of Miscellania" -> "{\"n\":\"Throne of Miscellania\",\"items\":[\"Iron bar\",\"Logs\",\"Any non-silver ring you are willing to lose\",\"Flowers\",\"Any normal/oak/willow/maple/yew shortbow or longbow (if courting Astrid)\",\"Cake (if courting Brand)\",\"One of: \"],\"rec\":[\"Dramen staff if travelling via Fairy Ring CIP\",\"Potions/Items to restore run energy\"],\"enemies\":[],\"rewards\":[\"1 Quest point\",\"Ability to manage Miscellania.\",\"Ability to teleport to Miscellania with the Ring of Wealth.\"],\"sec\":[{\"n\":\"Talk to King Vargas\",\"st\":[{\"t\":\"Buy some flowers from the Flower Girl for 15gp.\",\"s\":[\"Yes, please.\"]},{\"t\":\"Talk to King Vargas. You can choose whether to get Brand's or Astrid's approval\",\"s\":[\"Yes.\",\"If I may be so bold...\"]}],\"i\":[\"Flowers\",\"Any normal/oak/willow/maple/yew shortbow or longbow (if courting Astrid)\",\"Cake (if courting Brand)\",\"Any non-silver ring you are willing to lose\",\"Iron bar\",\"Logs\",\"One of: \"],\"c\":0},{\"n\":\"Win over Astrid\",\"st\":[{\"t\":\"Go upstairs in the Miscellania castle.\"},{\"t\":\"Talk to Princess Astrid a few times.\",\"s\":[\"Archery is a noble art!\",\"He's been very helpful.\",\"Hahahaha!\"]},{\"t\":\"Use flowers on Astrid.\",\"s\":[\"Yes\"],\"i\":[\"Flowers\"]},{\"t\":\"Dance in Princess Astrid's room.\"},{\"t\":\"Keep talking to Princess Astrid.\",\"s\":[\"What happened next?\",\"That sounds like a good idea.\",\"I'm quite fond of it myself.\"]},{\"t\":\"Use any bow on Astrid.\",\"s\":[\"Yes\"],\"i\":[\"Any normal/oak/willow/maple/yew shortbow or longbow (if courting Astrid)\"]},{\"t\":\"Blow kiss emote next to Princess Astrid.\"},{\"t\":\"Use a ring on Astrid.\",\"s\":[\"Yes\"],\"i\":[\"Any non-silver ring you are willing to lose\"]}],\"c\":0},{\"n\":\"Win over Brand\",\"st\":[{\"t\":\"Go upstairs in the Miscellania castle.\"},{\"t\":\"Talk to Prince Brand a few times.\",\"s\":[\"Be still, my heart.\",\"You will be the greatest bard!\",\"They don't understand your poetry as I do.\"]},{\"t\":\"Use flowers on Prince Brand.\",\"s\":[\"Yes\"],\"i\":[\"Flowers\"]},{\"t\":\"Use the Clap emote next to Prince Brand\"},{\"t\":\"Talk to Prince Brand more.\",\"s\":[\"A much nobler pursuit, to be sure.\",\"How inspiring!\",\"How poetic.\"]},{\"t\":\"Give Prince Brand a cake.\",\"s\":[\"Yes\"],\"i\":[\"Cake (if courting Brand)\"]},{\"t\":\"Use the blow kiss emote next to Prince Brand\"},{\"t\":\"Use a ring on Prince Brand.\",\"s\":[\"Yes\"],\"i\":[\"Any non-silver ring you are willing to lose\"]}],\"c\":0},{\"n\":\"Establish peace\",\"st\":[{\"t\":\"Talk to Queen Sigrid in Etceteria castle.\"},{\"t\":\"Talk to King Vargas.\"},{\"t\":\"Talk to Queen Sigrid.\"},{\"t\":\"Talk to Prince Brand in Miscellania castle.\"},{\"t\":\"Talk to Advisor Ghrim.\",\"s\":[\"How do I make peace with Etceteria?\"]},{\"t\":\"Return to Queen Sigrid in Etceteria castle.\"},{\"t\":\"Return to King Vargas.\"},{\"t\":\"Talk to Derrik in the north of Miscellania.\",\"s\":[\"I have a slightly strange request...\"],\"i\":[\"Iron bar\"]},{\"t\":\"Use the giant nib on some logs. Cut a nearby evergreen if you don't have logs.\",\"i\":[\"Giant nib\",\"Logs\"]},{\"t\":\"Talk to King Vargas with the giant pen.\",\"i\":[\"Giant pen\"]}],\"c\":0},{\"n\":\"Get support\",\"st\":[{\"t\":\"Talk to King Vargas to finish the quest.\"}],\"i\":[\"One of: \"],\"c\":0}]}"
        "Tower of Life" -> "{\"n\":\"Tower of Life\",\"items\":[\"Beer\",\"Hammer\",\"Saw\"],\"rec\":[\"Raw swordfish (for diary task)\",\"Raw chicken (for diary task)\"],\"enemies\":[],\"rewards\":[\"2 Quest points\",\"1,000 Construction XP\",\"500 Crafting XP\",\"500 Thieving XP\",\"Access to Creature Creation.\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Talk to Effigy outside the Tower of Life.\",\"s\":[\"Sure, why not.\"]},{\"t\":\"Talk to Bonafido.\"}],\"i\":[\"Saw\",\"Hammer\",\"Beer\"],\"c\":0},{\"n\":\"Get the Builders' outfit\",\"st\":[{\"t\":\"Get the Hard Hat from 'Black-eye'.\"},{\"t\":\"Talk to 'No fingers'.\"},{\"t\":\"Pickpocket 'No fingers'.\"},{\"t\":\"Get a Beer for 'The Guns'.\",\"i\":[\"Beer\"]},{\"t\":\"Talk to 'The Guns'.\"},{\"t\":\"Search the bushes to the south for some Builder's Trousers.\"},{\"t\":\"Speak to Bonafido wearing the Builder's outfit.\",\"i\":[\"Hard Hat\",\"Builder's Shirt\",\"Builder's Trousers\",\"Builder's Boots\"]}],\"i\":[\"Beer\"],\"c\":0},{\"n\":\"Fix the tower\",\"st\":[{\"t\":\"Enter the tower.\",\"i\":[\"Hard Hat\",\"Builder's Shirt\",\"Builder's Trousers\",\"Builder's Boots\"]},{\"t\":\"Build the Pressure Machine.\",\"s\":[\"Yes\"],\"i\":[\"Saw\",\"Hammer\"]},{\"t\":\"Build the Pipe Machine.\",\"s\":[\"Yes\"]},{\"t\":\"Build the cage.\",\"s\":[\"Yes\"]}],\"i\":[\"Saw\",\"Hammer\"],\"c\":0},{\"n\":\"The Alchemists' Secret\",\"st\":[{\"t\":\"Go back and talk to Effigy.\"}],\"c\":0}]}"
        "Tree Gnome Village" -> "{\"n\":\"Tree Gnome Village\",\"items\":[\"Logs (6)\",\"Combat gear (magic is best)\"],\"rec\":[\"Food\"],\"enemies\":[\"Khazard Warlord (level 112)\"],\"rewards\":[\"2 Quest points\",\"11,450 Attack XP\",\"Gnome amulet\",\"Use of the Spirit Tree transportation method.\"],\"sec\":[{\"n\":\"Getting started\",\"st\":[{\"t\":\"Speak to King Bolren in the centre of the Tree Gnome Maze.\"}]},{\"n\":\"The three trackers\",\"st\":[{\"t\":\"Speak with Commander Montai, north-east of the maze entrance.\",\"s\":[\"Ok, I'll gather some wood.\"]},{\"t\":\"Speak with Commander Montai again to give him the wood.\",\"i\":[\"Logs (6)\"]},{\"t\":\"Speak with Commander Montai.\",\"s\":[\"I'll try my best.\"]},{\"t\":\"Talk to the first tracker gnome to the north-west of the battlefield for the height coordinate.\"},{\"t\":\"Talk to the second tracker gnome inside the jail for the y coordinate.\"},{\"t\":\"Talk to the third tracker gnome to the south-west of the jail.\"},{\"t\":\"Fire the ballista at the tower.\"}],\"i\":[\"Logs (6)\"]},{\"n\":\"Retrieving the orbs\",\"st\":[{\"t\":\"Enter the tower by the Crumbled wall and climb the ladder to retrieve the first orb from chest.\"},{\"t\":\"Return the Orb of protection to King Bolren in the centre of the Tree Gnome Maze.\",\"s\":[\"Yes please.\"],\"i\":[\"Orb of protection\"]},{\"t\":\"Talk to the Khazard warlord, south west of West Ardougne, ready to fight him.\"},{\"t\":\"Defeat the Khazard warlord and retrieve orbs.\"},{\"t\":\"Return the Orbs of protection to King Bolren in the centre of the Tree Gnome Maze.\",\"s\":[\"Yes please.\"],\"i\":[\"Orbs of protection\"]}],\"i\":[\"Combat gear (magic is best)\",\"Food\"],\"c\":1,\"e\":[\"Khazard Warlord (level 112)\"]}]}"
        "Tribal Totem" -> "{\"n\":\"Tribal Totem\",\"items\":[],\"rec\":[\"Coins or more for boat trips (90)\",\"Amulet of glory\",\"Ardougne teleport\",\"Brimhaven teleports (2)\"],\"enemies\":[],\"rewards\":[\"1 Quest point\",\"1,775 Thieving XP\",\"5 x Swordfish\"],\"sec\":[{\"n\":\"Retrieving the totem\",\"st\":[{\"t\":\"Talk to Kangai Mau in the Brimhaven food store.\",\"s\":[\"I'm in search of adventure!\",\"Ok, I will get it back.\",\"Yes.\"]},{\"t\":\"Travel to the GPDT depot in Ardougne and investigate the most northeastern crate for a label.\"},{\"t\":\"Use the label on the highlighted crate.\",\"i\":[\"Address label\"]},{\"t\":\"Talk to a nearby GPDT employee.\",\"s\":[\"So, when are you going to deliver this crate?\"]},{\"t\":\"Talk to Wizard Cromperty in north east Ardougne.\",\"s\":[\"Chat.\",\"So what have you invented?\",\"Can I be teleported please?\",\"Yes, that sounds good. Teleport me!\"]},{\"t\":\"Work out and enter the password for the door to the west.\"},{\"t\":\"FIRST Right-click 'Investigate' the stairs to disable a trap, then climb the stairs.\"},{\"t\":\"Open the chest on the top floor and search it for the totem.\"},{\"t\":\"Return to Kangai Mau in Brimhaven.\",\"i\":[\"Totem\"]}],\"c\":0}]}"
        "Troll Romance" -> "{\"n\":\"Troll Romance\",\"items\":[\"Iron bar\",\"Maple/yew logs\",\"Rope\",\"Cake tin\",\"Swamp tar\",\"Bucket of wax\",\"Combat gear, food, and potions\",\"Climbing boots\"],\"rec\":[\"Games necklace\"],\"enemies\":[\"Arrg (level 113) can be safe spotted. Please check the wiki for instructions to setup a safe spot.\"],\"rewards\":[\"2 Quest points\",\"8,000 Agility XP\",\"4,000 Strength XP\",\"Diamond\",\"2 x Rubies\",\"4 x Emeralds\",\"A Sled\",\"Sledding route from Trollweiss Mountain.\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Talk to Ug in the south west room of the Troll Stronghold's first floor.\",\"s\":[\"Awww, you poor troll. What seems to be the problem?\",\"Don't worry now, I'll see what I can do.\"]},{\"t\":\"Talk to Aga north of Ug.\",\"s\":[\"So... how's your... um... love life?\"]}],\"i\":[\"Climbing boots\"]},{\"n\":\"Make a sled\",\"st\":[{\"t\":\"Talk to Tenzing west of Burthorpe.\",\"s\":[\"Do you know where I can find Trollweiss?\",\"What would I need to make such a sled?\"]},{\"t\":\"Talk to Dunstan in north east Burthorpe.\",\"s\":[\"Talk about a quest.\",\"I need a sled!!\",\"No.\"],\"i\":[\"Iron bar\",\"Maple/yew logs\",\"Rope\"]},{\"t\":\"Talk to Dunstan again.\",\"s\":[\"Talk about a quest.\"],\"i\":[\"Iron bar\",\"Maple/yew logs\",\"Rope\"]},{\"t\":\"Use some swamp tar on a bucket of wax.\",\"i\":[\"Swamp tar\",\"Bucket of wax\",\"Cake tin\"]},{\"t\":\"Use the wax on the sled.\",\"i\":[\"Wax\",\"Sled\"]}],\"i\":[\"Maple/yew logs\",\"Iron bar\",\"Rope\",\"Swamp tar\",\"Bucket of wax\",\"Cake tin\"]},{\"n\":\"Get flowers\",\"st\":[{\"t\":\"Enter the cave north of Trollheim. There are high leveled ice trolls in here, so Protect from Melee and be careful!\",\"i\":[\"Sled\"]},{\"t\":\"Leave the cave via the north crevice.\"},{\"t\":\"Equip the sled.\",\"i\":[\"Sled\"]},{\"t\":\"Sled to the south.\",\"i\":[\"Sled\"]},{\"t\":\"Pick a rare flower.\"}],\"i\":[\"Sled\"]},{\"n\":\"Fighting for Aga\",\"st\":[{\"t\":\"Return to Ug with the trollweiss flowers.\",\"i\":[\"Trollweiss\"]},{\"t\":\"Challenge Arrg to a fight. Please check the wiki for instructions to setup a safe spot.\",\"s\":[\"I am here to kill you!\"],\"i\":[\"Combat gear, food, and potions\"]},{\"t\":\"Kill Arrg.\"},{\"t\":\"Talk to Ug in the south west room to finish the quest.\"}],\"i\":[\"Trollweiss\",\"Combat gear, food, and potions\"],\"c\":1,\"e\":[\"Arrg (level 113) can be safe spotted. Please check the wiki for instructions to setup a safe spot.\"]}]}"
        "Troll Stronghold" -> "{\"n\":\"Troll Stronghold\",\"items\":[\"Climbing boots or 12 coins\"],\"rec\":[\"Games necklace\",\"Food + prayer potions\",\"Mage or ranged gear for safe spotting\"],\"enemies\":[\"Dad (level 101) (safespottable)\",\"Troll General (level 113) (safespottable)\"],\"rewards\":[\"1 Quest point\",\"Law Talisman\",\"Ability to make Law Runes\",\"Access to Trollheim and the Troll Stronghold\",\"Access to the God Wars Dungeon\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Talk to Denulth in Burthorpe.\",\"s\":[\"How goes your fight with the trolls?\",\"Is there anything I can do to help?\",\"I'll get Godric back!\"]}]},{\"n\":\"Reach the Stronghold\",\"st\":[{\"t\":\"Follow the path west of Burthorpe, then go along the path going south.\"},{\"t\":\"Climb over the stile north of Tenzing.\"},{\"t\":\"Follow the path until you reach some rocks. Climb over them.\",\"i\":[\"Climbing boots\"]},{\"t\":\"Follow the path from here east until you enter the arena.\"},{\"t\":\"Fight Dad until he gives up. You can safe spot him from the gate you entered through.\",\"s\":[\"I accept your challenge!\"]},{\"t\":\"Leave the arena and continue through the cave to the north.\",\"s\":[\"I'll be going now.\"]},{\"t\":\"Enter the cave entrance.\"},{\"t\":\"Leave through cave's north exit.\"},{\"t\":\"Follow the path around Trollheim until you reach the Stronghold's entrance. Be wary of thrower trolls on the path, you'll want to use Protect from Ranged.\"}],\"i\":[\"Climbing boots or 12 coins\",\"Mage or ranged gear for safe spotting\",\"Food + prayer potions\"]},{\"n\":\"Free the prisoners\",\"st\":[{\"t\":\"Enter the west rooms and kill any of the Troll Generals for a prison key.\"},{\"t\":\"Climb down the north staircase.\"},{\"t\":\"Enter the prison door.\"},{\"t\":\"Climb down the stairs to the prison.\"},{\"t\":\"Pickpocket or kill Berry for a cell key.\"},{\"t\":\"Unlock Eadgar's cell.\"},{\"t\":\"Pickpocket or kill Twig for a cell key.\"},{\"t\":\"Unlock Godric's cell.\"}],\"c\":1,\"e\":[\"Troll General (level 113) (safespottable)\"]},{\"n\":\"Finish off\",\"st\":[{\"t\":\"Talk to Dunstan in north east Burthorpe to finish the quest.\"}]}]}"
        "Troubled Tortugans" -> "{\"n\":\"Troubled Tortugans\",\"items\":[\"Any axe\",\"Hammer\",\"Saw\",\"Combat gear\",\"Food\",\"Prayer restore\"],\"rec\":[],\"enemies\":[\"Gryphon (lvl 95)\",\"Shellbane gryphon (lvl 235)\"],\"rewards\":[\"1 Quest point\",\"10,000 Sailing XP\",\"8,000 Slayer XP\",\"Access to the Great Conch\"],\"sec\":[{\"n\":\"Find the stranded Tortugan\",\"st\":[{\"t\":\"Talk to the Injured Tortugan on the small island north-west of The Great Conch to start the quest.\",\"s\":[\"Yes.\"]},{\"t\":\"Help the Injured Tortugan with her wounds.\",\"i\":[\"Makeshift bandages\"]},{\"t\":\"Talk to the Injured Tortugan again.\"}]},{\"n\":\"The Great Conch\",\"st\":[{\"t\":\"Sail to the docks at the southern edge of The Great Conch with Floopa.\"},{\"t\":\"Talk to Elder Korel at the docks of The Great Conch.\"},{\"t\":\"Head into The Summer Shore to the north and talk to Elder Raley in the south-east building.\"}]},{\"n\":\"Making repairs\",\"st\":[{\"t\":\"Talk to Elder Raley after completing the town repairs.\"}]},{\"n\":\"Tracking the Gryphon\",\"st\":[{\"t\":\"Inspect the monument in the middle of town to pick up the Gryphon's trail.\",\"i\":[\"Any axe\",\"Combat gear\",\"Food\",\"Prayer restore\"]},{\"t\":\"Follow the Gryphon tracks west of town and inspect the red plant.\",\"i\":[\"Any axe\",\"Combat gear\",\"Food\",\"Prayer restore\"]},{\"t\":\"Follow the Gryphon tracks north and inspect the rockslide.\",\"i\":[\"Any axe\",\"Combat gear\",\"Food\",\"Prayer restore\"]},{\"t\":\"Follow the Gryphon tracks north up the hill and inspect the plant on the east side.\",\"i\":[\"Any axe\",\"Combat gear\",\"Food\",\"Prayer restore\"]},{\"t\":\"Follow the Gryphon tracks east and inspect the plant to reveal the final set of tracks.\",\"i\":[\"Any axe\",\"Combat gear\",\"Food\",\"Prayer restore\"]},{\"t\":\"Follow the Gryphon tracks east and unblock the cave entrance.\",\"i\":[\"Any axe\",\"Combat gear\",\"Food\",\"Prayer restore\"]},{\"t\":\"Enter the Gryphon's cave, prepared for a fight.\",\"s\":[\"Yes.\"],\"i\":[\"Combat gear\",\"Food\",\"Prayer restore\"]},{\"t\":\"Defeat the Gryphon. It hits with melee, and does a special attack if your worn weight is less than 40kg.\",\"i\":[\"Combat gear\",\"Food\",\"Prayer restore\"]},{\"t\":\"Return to Elder Raley with news about the Gryphon's defeat.\"}],\"i\":[\"Any axe\",\"Combat gear\",\"Food\",\"Prayer restore\"],\"c\":1,\"e\":[\"Gryphon (lvl 95)\"]},{\"n\":\"Attack on the Little Pearl\",\"st\":[{\"t\":\"Get a Tortugan shield from Elder Blunn.\"},{\"t\":\"Sail to Little Pearl island, south-east of The Great Conch, to confront the Shellbane gryphon.\",\"i\":[\"Combat gear\",\"Food\",\"Prayer restore\",\"Tortugan shield\"]},{\"t\":\"Defeat the Shellbane gryphon. Have your worn weight be at least 40kg to avoid some damage. Protect from ranged if you're ranging it, and protect from melee when in melee range. Avoid tornadoes. Move when it spits a slow blob at you.\",\"i\":[\"Combat gear\",\"Food\",\"Prayer restore\",\"Tortugan shield\"]},{\"t\":\"Talk to Elder Korel after defeating the Shellbane gryphon.\"},{\"t\":\"Return to Elder Raley at The Great Conch to complete the quest.\"}],\"c\":1,\"e\":[\"Gryphon (lvl 95)\",\"Shellbane gryphon (lvl 235)\"]}]}"
        "Twilight's Promise" -> "{\"n\":\"Twilight's Promise\",\"items\":[\"Two combat styles\"],\"rec\":[\"Stamina potions (3)\"],\"enemies\":[\"Knight of Varlamore (level 81)\",\"8 Cultists (level 34)\"],\"rewards\":[\"1 Quest point\",\"3,000 Thieving XP\",\"Ability to use the Civitas illa Fortis Teleport spell\",\"Ability to use the Quetzal Transport System\"],\"sec\":[{\"n\":\"Cryptic\",\"st\":[{\"t\":\"Talk to Regulus Cento outside Varrock's East Gate to travel to Varlamore.\",\"s\":[\"Let's do it!\"]},{\"t\":\"Talk to Ennius Tullus just west of where you arrived, next to the fountain.\",\"s\":[\"Yes.\"]},{\"t\":\"Talk to Metzli in the temple in the south of the city.\",\"s\":[\"I'm meant to be meeting Prince Itzla here.\"]},{\"t\":\"Enter the temple's crypt.\",\"s\":[\"I'd better head down there.\"]},{\"t\":\"Talk to Prince Itzla Arkan in the north room.\"},{\"t\":\"Leave the crypt.\"},{\"t\":\"Return to Ennius Tullus, who is now in the palace.\"}]},{\"n\":\"Knights - Bazaar\",\"st\":[{\"t\":\"Talk to the Knight of Varlamore in the bazaar south of the palace.\",\"i\":[\"Varlamore crest\"]},{\"t\":\"Pickpocket the citizen in turquoise robes in the bazaar.\"},{\"t\":\"Return the amulet to the knight in the bazaar.\",\"i\":[\"Stolen amulet\"]}],\"i\":[\"Varlamore crest\"],\"c\":1,\"e\":[\"Knight of Varlamore (level 81)\"]},{\"n\":\"Knights - Cothon\",\"st\":[{\"t\":\"Talk to the Knight of Varlamore on the south western part of the Fortis Cothon (docks) in the east of the city.\",\"i\":[\"Varlamore crest\"]},{\"t\":\"Search the crate in the north-east of the Cothon, next to two barrels of fish.\"},{\"t\":\"Return to the Knight of Varlamore on the south part of the Fortis Cothon.\"}],\"i\":[\"Varlamore crest\"],\"c\":1,\"e\":[\"Knight of Varlamore (level 81)\"]},{\"n\":\"Knights - Pub\",\"st\":[{\"t\":\"Talk to the Knights of Varlamore in the pub OUTSIDE the walls of the city to the south.\",\"i\":[\"Varlamore crest\"]},{\"t\":\"Lead the knight to the fountain to the east. Whenever they stop following you, talk to them again.\"},{\"t\":\"Talk to the sobered knight at the fountain.\"}],\"i\":[\"Varlamore crest\"]},{\"n\":\"Knights - Colosseum\",\"st\":[{\"t\":\"Enter the Colosseum in the east of the city.\",\"i\":[\"Varlamore crest\",\"Two combat styles\"]},{\"t\":\"Talk to the Knight of Varlamore in the north training room, ready to fight.\",\"s\":[\"I'm ready. Let's do this.\"],\"i\":[\"Varlamore crest\",\"Two combat styles\"]},{\"t\":\"Defeat the knight, swapping combat styles to bypass his prayers.\",\"i\":[\"Two combat styles\"]},{\"t\":\"Talk to the Knight of Varlamore in the northern training room once more.\"}],\"i\":[\"Varlamore crest\",\"Two combat styles\"],\"c\":1,\"e\":[\"Knight of Varlamore (level 81)\"]},{\"n\":\"Cost of Betrayal\",\"st\":[{\"t\":\"Return to Ennius Tullus in the palace.\"},{\"t\":\"Go to the top floor of the Kualti Headquarters, just west of the palace.\"},{\"t\":\"Search the chest in the south-east room on the south wall.\"},{\"t\":\"Read the incriminating letter.\",\"i\":[\"Incriminating letter\"]},{\"t\":\"Return to Ennius and Furia in the palace.\"}]},{\"n\":\"The Twilight Emissaries\",\"st\":[{\"t\":\"TALK to Regulus Cento south-east of the palace.\",\"s\":[\"I was told to ask you about getting to the Teomat.\"]},{\"t\":\"Feed Renu the feed.\",\"s\":[\"I was told to ask you about getting to the Teomat.\"],\"i\":[\"Quetzel feed\"]},{\"t\":\"Travel with Renu to Teomat.\"},{\"t\":\"Talk to Prince Itzla Arkan in the temple, near the altar.\"},{\"t\":\"Talk to Metzli in the northern building of the Teomat.\"},{\"t\":\"Defeat the cultists.\"},{\"t\":\"Talk to Prince Itzla Arkan in Teomat, near the altar, to finish the quest.\"}],\"c\":1,\"e\":[\"8 Cultists (level 34)\"]}]}"
        "Underground Pass" -> "{\"n\":\"Underground Pass\",\"items\":[\"Rope, multiple in case you fail an agility check\",\"Bow (not crossbow)\",\"Arrows (metal, unpoisoned)\",\"Spade\",\"Plank\",\"Bucket\",\"Tinderbox\",\"Combat Equipment\"],\"rec\":[\"Food\",\"Stamina Potions\",\"Coins (to buy food, 75 ea) (750)\",\"Agility Potions\",\"Telegrab Runes\"],\"enemies\":[\"3 Demons (level 91, safespottable)\",\"3 Paladins (level 62, safespottable)\",\"Kalrag (level 89)\",\"Disciple of Iban (level 13)\"],\"rewards\":[\"5 Quest points\",\"3,000 Agility XP\",\"3,000 Attack XP\",\"Iban's Staff\"],\"sec\":[{\"n\":\"Starting out\",\"st\":[{\"t\":\"Talk to King Lathas.\",\"s\":[\"I am. What's our plan?\",\"I'm ready.\",\"Yes.\"]},{\"t\":\"Talk to Koftik outside the West Ardougne cave.\",\"s\":[\"I'll take my chances.\"]}]},{\"n\":\"The Underground Pass\",\"st\":[{\"t\":\"Talk to Koftik inside the cave.\"},{\"t\":\"Wield a lit arrow and shoot the guide-rope.\",\"i\":[\"Bow (not crossbow)\",\"Lit Arrow\"]},{\"t\":\"Swing across the pit with a rope.\",\"i\":[\"Rope\"]},{\"t\":\"Cross the grid by trial and error. Keep health above 15, and remember the path for Regicide.\"},{\"t\":\"Either disable or walk past the traps.\"},{\"t\":\"Take the first orb of light.\"},{\"t\":\"Take the second orb of light north west of the well.\"},{\"t\":\"Take the third orb of light west of the well. Remember to use a plank on the flat rocks to cross them.\"},{\"t\":\"Search the flat rock to remove the trap and take the fourth orb to the south west of the well.\",\"s\":[\"Yes, I'll give it a go.\"]},{\"t\":\"Return to the furnace to the east, and use the orbs on it.\"},{\"t\":\"Climb down the well.\"}],\"i\":[\"Rope, multiple in case you fail an agility check\",\"Bow (not crossbow)\",\"Arrows (metal, unpoisoned)\",\"Spade\",\"Plank\",\"Bucket\",\"Tinderbox\",\"Combat Equipment\"],\"c\":1},{\"n\":\"Descending Deeper\",\"st\":[{\"t\":\"Navigate the maze, or use the shortcut to the south with 50 Thieving.\"},{\"t\":\"Search the unicorn cage.\"},{\"t\":\"Use the railing on the boulder.\",\"i\":[\"Railing\"]}]},{\"n\":\"Cold-blooded Killing\",\"st\":[{\"t\":\"Search the cage again.\"},{\"t\":\"Travel through the tunnel to find some knights.\"},{\"t\":\"Kill Sir Jerro and take his badge. Optionally: talk to one of the knights first to receive food and potions.\",\"i\":[\"Badge (Sir Jerro)\"]},{\"t\":\"Kill Sir Harry and take his badge.\",\"i\":[\"Badge (Sir Harry)\"]},{\"t\":\"Kill Sir Carl and take his badge.\",\"i\":[\"Badge (Sir Carl)\"]},{\"t\":\"Use the badges and unicorn horn on the well.\",\"i\":[\"Badge (Sir Jerro)\"]},{\"t\":\"Open the door at the end of the path.\"}]},{\"n\":\"The Witch Kardia\",\"st\":[{\"t\":\"Talk to Niloof.\"},{\"t\":\"Talk to Klank to obtain his gauntlets. If you've done so before, you may need to pay 5,000gp for them.\"},{\"t\":\"Start from the south east corner of the bridges, and go northwest along them and retrieve the witch's cat.\"},{\"t\":\"Use the cat on the witch's door in the south east corner of the area to distract her.\",\"i\":[\"Witch's Cat\"]},{\"t\":\"Search the chest in the witch's house. You'll need 4 empty inventory slots.\"}]},{\"n\":\"Imbuing the Doll\",\"st\":[{\"t\":\"From the south east corner of the area, head west then south along the pathways. Kill Holthion and pick up his amulet.\",\"i\":[\"Amulet of Holthion\"]},{\"t\":\"Kill Doomion and pick up his amulet.\",\"i\":[\"Amulet of Doomion\"]},{\"t\":\"Kill Othainian and pick up his amulet.\",\"i\":[\"Amulet of Othanian\"]},{\"t\":\"Search the chest north of Doomion.\"},{\"t\":\"Return to the dwarf encampment on the lower level.\"},{\"t\":\"Use a bucket on the brew barrel in the dwarf encampment on the south west.\",\"i\":[\"Bucket\"]},{\"t\":\"Use the bucket of brew on the tomb in the south east corner of the area.\",\"i\":[\"Dwarf brew\"]},{\"t\":\"Light the tomb with a tinderbox.\",\"i\":[\"Tinderbox\"]},{\"t\":\"Kill Kalrag the spider. Protect From Melee can keep you safe in this fight.\",\"i\":[\"Doll of Iban\"]},{\"t\":\"Search the marked cage in the north west of the area while wearing Klank's gauntlets.\",\"i\":[\"Klank's gauntlets\"]}],\"c\":1,\"e\":[\"Kalrag (level 89)\"]},{\"n\":\"Entering the Temple\",\"st\":[{\"t\":\"Travel along the pathways from the north west corner of the area to the middle. Kill a disciple of Iban and take their robes.\",\"i\":[\"Doll of Iban\"]},{\"t\":\"Enter the Temple of Iban wearing monk robes. Prepare to use Iban's doll on the well, as Iban can deal lots of damage quickly.\",\"i\":[\"Zamorak monk top\",\"Zamorak monk bottom\"]},{\"t\":\"Right-click USE the doll on the well. Standing north of the well can prevent Iban from hitting.\",\"i\":[\"Doll of Iban\"]}],\"c\":1,\"e\":[\"Disciple of Iban (level 13)\"]},{\"n\":\"Foggy Memories\",\"st\":[{\"t\":\"Talk to Koftik.\"},{\"t\":\"Return to King Lathas to finish the quest.\"}]}]}"
        "Vale Totems" -> "{\"n\":\"Vale Totems\",\"items\":[\"Knife\",\"Oak log\",\"Oak shield/longbow/shortbow (4)\"],\"rec\":[],\"enemies\":[],\"rewards\":[\"Unlocks the Auburnvale fletching minigame\"],\"sec\":[{\"n\":\"Repair the totem\",\"st\":[{\"t\":\"Talk to Ranulph in the west part of Auburnvale to start the quest.\",\"s\":[\"Yes.\"]},{\"t\":\"Build the totem site.\",\"i\":[\"Knife\",\"Oak log\"]},{\"t\":\"Talk to Isadora to learn about carving.\"},{\"t\":\"Carve spirit animals you see into the totem.\"},{\"t\":\"Return to Isadora after carving the spirit animals into the totem.\"},{\"t\":\"Decorate the totem with four decorative items (shield, longbow, or shortbow) of the same wood type you used to build/carve the totem.\",\"i\":[\"Oak shield/longbow/shortbow (4)\"]},{\"t\":\"Return to Isadora to talk after decorating the totem.\"},{\"t\":\"Claim the offering the Ent left next to your totem.\"},{\"t\":\"Return to Isadora to finish the quest.\"}],\"i\":[\"Knife\",\"Oak log\",\"Oak shield/longbow/shortbow (4)\"],\"c\":0}]}"
        "Vampyre Slayer" -> "{\"n\":\"Vampyre Slayer\",\"items\":[\"Hammer\",\"A beer, or 2 coins to buy one\",\"Combat gear + food to defeat Count Draynor\"],\"rec\":[\"Teleport to Varrock\",\"Draynor manor teleport\",\"Garlic\"],\"enemies\":[\"Count Draynor (level 34)\"],\"rewards\":[\"3 Quest points\",\"4,825 Attack XP\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Talk to Morgan in the north of Draynor Village.\",\"s\":[\"Yes.\"]}]},{\"n\":\"Get garlic\",\"st\":[{\"t\":\"Get garlic from the cupboard upstairs in Morgan's house. You can tick off this section in the sidebar to skip the garlic acquisition.\"}]},{\"n\":\"Get a stake\",\"st\":[{\"t\":\"Talk to Dr. Harlow in the Blue Moon Inn in Varrock.\",\"s\":[\"Morgan needs your help!\"],\"i\":[\"A beer, or 2 coins to buy one\"]},{\"t\":\"Buy a beer from the bartender in the Blue Moon Inn in Varrock.\",\"s\":[\"A glass of your finest ale please.\"],\"i\":[\"Coins (2)\"]},{\"t\":\"Talk to Dr. Harlow again with a beer.\",\"s\":[\"Yes. Here you go.\"],\"i\":[\"Beer\"]}],\"i\":[\"A beer, or 2 coins to buy one\"]},{\"n\":\"Kill Count Draynor\",\"st\":[{\"t\":\"Prepare to fight Count Draynor (level 34), and enter Draynor Manor.\"},{\"t\":\"Enter Draynor Manor's basement.\"},{\"t\":\"Open the coffin and kill Count Draynor.\"}],\"i\":[\"Hammer\",\"Stake\",\"Combat gear + food to defeat Count Draynor\"],\"r\":[\"Garlic\"],\"c\":1,\"e\":[\"Count Draynor (level 34)\"]}]}"
        "Wanted!" -> "{\"n\":\"Wanted!\",\"items\":[\"20 Rune or Pure Essence (UNNOTED)\",\"A light source\",\"A rope\",\"Combat gear\",\"A law rune, an enchanted gem and some molten glass OR 10k gp\"],\"rec\":[\"Amulet of glory\",\"Ring of Dueling\",\"A teleport to Falador\",\"A teleport to Varrock\",\"A teleport to Canifis\",\"A spiny helmet or slayer helm\"],\"enemies\":[\"Black Knight (level 33)\",\"Solus Dellagar (similar strength)\"],\"rewards\":[\"1 Quest point\",\"5,000 Slayer XP\",\"Access to the White Knight's Armory\"],\"sec\":[{\"n\":\"Getting started\",\"st\":[{\"t\":\"Talk to Sir Tiffy Cashien in Falador Park.\",\"s\":[\"Do you have any jobs for me yet?\",\"Yes, I'm interested.\",\"How will all that help?\"]},{\"t\":\"Go tell Sir Amik Varze in the White Knights' Castle you wish to join the White Knights, BUT refuse to be a Squire.\"},{\"t\":\"Return to Sir Tiffy Cashien in Falador Park.\"},{\"t\":\"Go back to Sir Amik Varze in the White Knights' Castle.\"},{\"t\":\"Report back to Sir Tiffy Cashien in Falador Park.\"},{\"t\":\"Get a Commorb from Sir Tiffy Cashien in Falador Park.\"},{\"t\":\"Right-click the Commorb and select 'contact' to contact Savant.\",\"s\":[\"Current Assignment\"],\"i\":[\"Commorb\"]}],\"i\":[\"A law rune, an enchanted gem and some molten glass OR 10k gp\"]},{\"n\":\"Daquarius\",\"st\":[{\"t\":\"Talk to Lord Daquarius in Taverley Dungeon.\",\"i\":[\"Commorb\"]},{\"t\":\"Kill a Black Knight near Daquarius.\",\"i\":[\"Combat gear\"]},{\"t\":\"Talk to Lord Daquarius in Taverley Dungeon again.\"}],\"i\":[\"Combat gear\",\"Commorb\"],\"c\":1,\"e\":[\"Black Knight (level 33)\"]},{\"n\":\"Mage of Zamorak\",\"st\":[{\"t\":\"Talk to the Mage of Zamorak in south east Varrock.\",\"s\":[\"Solus Dellagar\"],\"i\":[\"Commorb\"]},{\"t\":\"Bring the 20 rune or pure essence to the Mage of Zamorak in Varrock.\",\"s\":[\"Solus Dellagar\"],\"i\":[\"Commorb\",\"20 Rune or Pure Essence (UNNOTED)\"]}],\"i\":[\"20 Rune or Pure Essence (UNNOTED)\",\"Commorb\"]},{\"n\":\"The Hunt for Solus\",\"st\":[{\"t\":\"Go to Canifis, and scan with your Commorb there until you find Solus.\",\"i\":[\"Commorb\"]},{\"t\":\"Hunt down Solus Dellagar across Gielinor.\"}],\"i\":[\"A light source\",\"A rope\",\"A spiny helmet or slayer helm\",\"Commorb\"],\"c\":1,\"e\":[\"Solus Dellagar (similar strength)\"]},{\"n\":\"Final battle\",\"st\":[{\"t\":\"Go to the Rune Essence mine by talking to any of the NPCs that can teleport you there.\",\"i\":[\"Commorb\",\"Combat gear\"]},{\"t\":\"Kill Solus Dellagar.\",\"i\":[\"Combat gear\"]},{\"t\":\"Show Solus' Hat to Sir Amik Varze in Falador.\",\"s\":[\"Current Assignment\"],\"i\":[\"Commorb\"]}],\"i\":[\"Combat gear\",\"Commorb\"],\"c\":1,\"e\":[\"Solus Dellagar (similar strength)\"]}]}"
        "Watchtower" -> "{\"n\":\"Watchtower\",\"items\":[\"Coins (20)\",\"Gold bar\",\"Death rune\",\"Any pickaxe\",\"Dragon bones\",\"Rope (2)\",\"Guam potion (unf)\",\"A light source\",\"Pestle and mortar\",\"Bat bones\",\"Jangerberries\"],\"rec\":[\"Shields/potions that mitigate dragon's fire\"],\"enemies\":[\"Gorad (level 68)\",\"Able to survive blue dragons, ogres, and greater demons attacking you\"],\"rewards\":[\"4 Quest points\",\"15,250 Magic XP\",\"5000 x Coins\",\"Ability to use the Watchtower Teleport\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Go to the top floor of the Watchtower north of Yanille and talk to the Watchtower Wizard.\",\"s\":[\"What's the matter?\",\"So how come the spell doesn't work?\",\"Can I be of help?\"]}]},{\"n\":\"Investigate\",\"st\":[{\"t\":\"Search the bushes north of the Watchtower.\"},{\"t\":\"Return to the Watchtower Wizard with the fingernails.\",\"s\":[\"What do you suggest I do?\",\"So what do I do?\"],\"i\":[\"Fingernails\"]},{\"t\":\"Talk to Og north west of Yanille.\",\"s\":[\"I seek entrance to the city of ogres.\"]},{\"t\":\"Use your rope on a branch to swing to the island west of Yanille.\",\"i\":[\"Rope\"]},{\"t\":\"Talk to Grew on the island west of Yanille.\",\"s\":[\"Don't eat me; I can help you.\"]},{\"t\":\"Leave Grew's island.\"},{\"t\":\"Enter the hole south of Gu'Tanoth.\"},{\"t\":\"Kill Gorad and pick up his tooth.\"},{\"t\":\"Talk to Toban on the island east of Gu'Tanoth.\",\"s\":[\"I seek entrance to the city of ogres.\",\"I could do something for you...\"]},{\"t\":\"Give Toban some dragon bones on the island east of Gu'Tanoth.\",\"i\":[\"Dragon bones\"]},{\"t\":\"Open the chest on the island east of Gu'Tanoth using Toban's Key.\",\"i\":[\"Toban's key\"]},{\"t\":\"Return to Og with his stolen gold north west of Yanille.\",\"i\":[\"Toban's gold\"]},{\"t\":\"Return to Grew with Gorad's teeth on the island west of Yanille.\",\"i\":[\"Rope\"]},{\"t\":\"Return to the Watchtower Wizard with the relic pieces.\",\"i\":[\"Relic part 1\",\"Relic part 2\",\"Relic part 3\"]}],\"i\":[\"Dragon bones\",\"Rope (2)\"],\"c\":1,\"e\":[\"Gorad (level 68)\"]},{\"n\":\"Enter Gu'Tanoth\",\"st\":[{\"t\":\"Talk to the Ogre Guard at the entrance of Gu'Tanoth and give them the ogre relic.\",\"i\":[\"Ogre relic\"]},{\"t\":\"Steal a rock cake from Gu'Tanoth's market.\"},{\"t\":\"Talk to an Ogre Guard next to the battlement.\",\"s\":[\"But I am a friend to ogres...\"]},{\"t\":\"Attempt to cross the battlement again with a rock cake.\",\"i\":[\"Rock cake\"]},{\"t\":\"Jump over the broken bridge.\",\"s\":[\"Okay, I'll pay it.\"],\"i\":[\"Coins (20)\"]},{\"t\":\"Talk to the City Guard.\",\"s\":[\"I seek passage into the skavid caves.\"]},{\"t\":\"Talk to the City Guard again.\",\"i\":[\"Death rune\"]}],\"i\":[\"Ogre relic\",\"Coins (20)\",\"Death rune\",\"Gold bar\",\"A light source\"]},{\"n\":\"Learn the Skavid language\",\"st\":[{\"t\":\"Enter the skavid cave entrance in east Gu'Tanoth.\",\"i\":[\"Skavid map\",\"A light source\"]},{\"t\":\"Talk to the scared skavid.\",\"s\":[\"Okay, okay, I'm not going to hurt you.\"]},{\"t\":\"Talk to four other skavids in their caves.\",\"s\":[\"I'll be fine without a tinderbox.\"],\"i\":[\"Skavid map\",\"A light source\"]},{\"t\":\"Try to go through the gate to the south east cave of Gu'Tanoth. Give the guard a gold bar and go through.\",\"i\":[\"Gold bar\"]},{\"t\":\"Enter the mad skavid's cave.\",\"s\":[\"I'll be fine without a tinderbox.\"]},{\"t\":\"Pick up 2 cave nightshade. You can world hop to get a second one.\",\"i\":[\"Cave nightshade (2)\"]},{\"t\":\"Use a nightshade on an Enclave Guard in the Gu'Tanoth market.\",\"i\":[\"Cave nightshade\"]}],\"i\":[\"Gold bar\",\"A light source\",\"Skavid map\"],\"r\":[\"Shields/potions that mitigate dragon's fire\"]},{\"n\":\"Getting the other crystals\",\"st\":[{\"t\":\"Return to the Watchtower Wizard.\"},{\"t\":\"Use some jangerberries on a guam potion (unf)\",\"i\":[\"Guam potion (unf)\",\"Jangerberries\"]},{\"t\":\"Use a pestle and mortar on some bat bones.\",\"i\":[\"Pestle and mortar\",\"Bat bones\"]},{\"t\":\"Use the ground bat bones on the potion\",\"i\":[\"Ground bat bones\",\"Vial\"]},{\"t\":\"Return to the Watchtower Wizard with the potion.\",\"i\":[\"Potion\"]},{\"t\":\"Use a nightshade on an Enclave Guard in the Gu'Tanoth market to enter the enclave again.\",\"i\":[\"Cave nightshade\",\"Magic ogre potion\",\"Any pickaxe\"]},{\"t\":\"Use the magic ogre potion on all the ogre shamans.\",\"i\":[\"Magic ogre potion\"]},{\"t\":\"Mine the Rock of Dalgorth in the enclave.\",\"i\":[\"Any pickaxe\"]},{\"t\":\"Return to the Watchtower Wizard with the crystals.\",\"i\":[\"Crystal\"]},{\"t\":\"Use the crystals on the pillars.\",\"i\":[\"Crystal\"]},{\"t\":\"Pull the lever to finish the quest.\"}],\"i\":[\"Guam potion (unf)\",\"Jangerberries\",\"Pestle and mortar\",\"Bat bones\",\"Cave nightshade\",\"Any pickaxe\"]}]}"
        "Waterfall Quest" -> "{\"n\":\"Waterfall Quest\",\"items\":[\"Rope\",\"Air runes (6)\",\"Earth runes (6)\",\"Water runes (6)\"],\"rec\":[\"Games necklace\",\"Food\"],\"enemies\":[\"Able to survive enemies up to level 86 attacking you\"],\"rewards\":[\"1 Quest point\",\"13,750 Strength XP\",\"13,750 Attack XP\",\"2 x Diamonds\",\"2 x Gold Bars\",\"40 x Mithril Seeds\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Talk to Almera on top of Baxtorian Falls, south of Barbarian Outpost.\",\"s\":[\"Yes.\"]}],\"i\":[\"Rope\"]},{\"n\":\"Investigate\",\"st\":[{\"t\":\"Board the log raft west of Almera.\",\"i\":[\"Rope\"]},{\"t\":\"Talk to Hudon.\",\"i\":[\"Rope\"]},{\"t\":\"Use a rope on the rock to the south.\",\"i\":[\"Rope\"]},{\"t\":\"Use a rope on the dead tree.\",\"i\":[\"Rope\"]},{\"t\":\"Get in the barrel.\"},{\"t\":\"Go up the stairs in the house south of Almera's house.\"},{\"t\":\"Search the south east bookcase.\"},{\"t\":\"Read the book.\",\"i\":[\"Book on baxtorian\"]}],\"i\":[\"Rope\"]},{\"n\":\"Get Glarial's Pebble\",\"st\":[{\"t\":\"Go to the centre of the Tree Gnome Village and go down the ladder at the entrance.\"},{\"t\":\"Search the off-coloured crate in the east room.\"},{\"t\":\"Go through the gate in the west room.\",\"i\":[\"Key\"]},{\"t\":\"Talk to Golrie.\"}]},{\"n\":\"Loot Glarial's tomb\",\"st\":[{\"t\":\"Bank everything besides the pebble and some food. Then use Glarial's pebble on Glarial's Tombstone east of Baxtorian Falls.\",\"i\":[\"Glarial's pebble\"]},{\"t\":\"Search the chest in the western room for Glarial's amulet.\"},{\"t\":\"Search Glarial's Tomb in the south room for Glarial's urn.\"}]},{\"n\":\"Put Glarial to rest\",\"st\":[{\"t\":\"Leave Glarial's Tomb and get 6 air, water, and earth runes, a rope, glarial's amulet, glarial's urn, and some food.\",\"i\":[\"Air runes (6)\",\"Earth runes (6)\",\"Water runes (6)\",\"Glarial's amulet\",\"Glarial's urn\",\"Rope\"]},{\"t\":\"Board the log raft west of Almera.\"},{\"t\":\"Use a rope on the rock to the south.\",\"i\":[\"Rope\"]},{\"t\":\"Use a rope on the dead tree.\",\"i\":[\"Rope\"]},{\"t\":\"Equip Glarial's amulet.\",\"i\":[\"Glarial's amulet\"]},{\"t\":\"Enter the falls with Glarial's amulet equipped.\",\"i\":[\"Glarial's amulet\"]},{\"t\":\"Search the crate in the east room for a key.\"},{\"t\":\"Enter the west room with the key.\",\"i\":[\"Key\"]},{\"t\":\"Use 1 earth, water and air rune on each of the 6 pillars in the room. Afterwards, use Glarial's amulet on the statue of Glarial.\",\"i\":[\"Air rune\",\"Water rune\",\"Earth rune\"]},{\"t\":\"DO NOT LEFT-CLICK THE CHALICE! Use Glarial's urn on the Chalice to finish the quest.\",\"i\":[\"Glarial's urn\"]}],\"i\":[\"Rope\",\"Air runes (6)\",\"Earth runes (6)\",\"Water runes (6)\",\"Glarial's urn\",\"Glarial's amulet\"]}]}"
        "What Lies Below" -> "{\"n\":\"What Lies Below\",\"items\":[\"Bowl\",\"Chaos runes (15)\",\"Access to the Chaos Altar\"],\"rec\":[\"Chronicle for teleports to south of Varrock\"],\"enemies\":[\"5 outlaws (level 32)\",\"King Roald (level 47)\"],\"rewards\":[\"1 Quest point\",\"8,000 Runecraft XP\",\"2,000 Defence XP\",\"The Beacon Ring\",\"Access to a shortcut to the Chaos Altar\"],\"sec\":[{\"n\":\"Starting off\",\"st\":[{\"t\":\"Talk to Rat Burgiss south of Varrock.\",\"s\":[\"Yes.\",\"Shall I get them back for you?\",\"Of course! Tell me what you need me to do.\"]}]},{\"n\":\"Help Rat\",\"st\":[{\"t\":\"Go to the Bandits west of the Grand Exchange and kill 5 for intel. Put the intel into the folder Rat gave you.\",\"i\":[\"Folder\",\"Rat's paper (5)\"]},{\"t\":\"Return to Rat Burgiss south of Varrock.\",\"i\":[\"Full folder\"]}]},{\"n\":\"Help Surok\",\"st\":[{\"t\":\"Talk to Surok Magis in the Varrock Library.\",\"i\":[\"Letter to Surok\"]},{\"t\":\"Travel to the chaos altar with the wand and 15 chaos runes. You can either enter with a chaos talisman, or use the abyss.\",\"i\":[\"Wand\",\"Chaos runes (15)\",\"Access to the Chaos Altar\"]},{\"t\":\"Use the wand on the chaos altar.\",\"i\":[\"Wand\",\"Chaos runes (15)\"]},{\"t\":\"Return to Surok Magis in the Varrock Library with the wand and a bowl.\",\"s\":[\"I have the things you wanted!\"],\"i\":[\"Infused wand\",\"Bowl\"]}],\"i\":[\"Chaos runes (15)\",\"Access to the Chaos Altar\",\"Bowl\",\"Wand\"]},{\"n\":\"Defeat Surok\",\"st\":[{\"t\":\"Return to Rat Burgiss south of Varrock.\",\"s\":[\"Yes! I have a letter for you.\"],\"i\":[\"Surok's letter\"]},{\"t\":\"Talk to Zaff in the Varrock staff shop.\",\"s\":[\"Rat Burgiss sent me!\"]},{\"t\":\"Prepare to fight King Roald (level 47), then go talk to Surok Magis in the Varrock Library.\",\"s\":[\"Bring it on!\"],\"i\":[\"Beacon ring\"]},{\"t\":\"Fight King Roald. When he's at 1hp, right-click operate the beacon ring.\",\"i\":[\"Beacon ring\"]},{\"t\":\"Re